OPS_STOK_DISIPLIN_BEKLEYEN_GUN = 7

# İş günü başlangıç saati — bu saatten önce biten kapanışlar bir önceki iş gününe ait sayılır
_IS_GUNU_SINIRI_SAAT: int = max(0, min(12, int(os.getenv("EVVEL_IS_GUNU_SINIRI_SAAT", "6"))))

# Stok kayıp özet önbelleği — hub-ozet her çağrıldığında tam analiz çalıştırmamak için
_stok_kayip_cache: Dict[str, Any] = {"ts": 0.0, "anomali_sube": 0, "toplam_kayip": 0}
_STOK_KAYIP_CACHE_SURE = 600  # 10 dakika


def _siparis_gonderilmedi_kapat(cur: Any) -> int:
    """
    7 günü geçmiş bekleyen siparişleri 'gonderilmedi' olarak kapatır.
    hub-ozet her çağrıldığında çalışır (lazy kapatma).

    FIX #4: Kapanış sırasında tahsis edilmiş rezervleri de serbest bırakır.
    Aksi hâlde depo rezerv_adet sonsuza şişer (hayalet rezerv).

    Döner: kapatılan sipariş sayısı.
    """
    log = logging.getLogger(__name__)
    # Önce kapatılacak siparişleri ve kalemlerini çek
    cur.execute(
        """
        SELECT id, kalem_durumlari, hedef_depo_sube_id
        FROM siparis_talep
        WHERE durum = 'bekliyor'
          AND tarih < CURRENT_DATE - (%s * INTERVAL '1 day')
        """,
        (OPS_STOK_DISIPLIN_BEKLEYEN_GUN,),
    )
    kapanacaklar = [dict(r) for r in (cur.fetchall() or [])]

    for row in kapanacaklar:
        kd = row.get("kalem_durumlari") or {}
        depo_sube = (row.get("hedef_depo_sube_id") or "").strip() or None
        if not isinstance(kd, dict):
            continue
        kalemler = kd.get("kalemler") or []
        if not kalemler:
            continue
        for kalem in kalemler:
            kk        = str(kalem.get("kalem_kodu") or "").strip()
            tahsis_ad = int(kalem.get("tahsis_adet") or 0)
            if not kk or tahsis_ad <= 0:
                continue
            # Rezervi serbest bırak: önce depoda ara, yoksa merkez stok kartında
            try:
                if depo_sube:
                    cur.execute(
                        """
                        UPDATE sube_depo_stok
                        SET rezerve_adet = GREATEST(0, COALESCE(rezerve_adet, 0) - %s),
                            guncelleme   = NOW()
                        WHERE sube_id = %s AND kalem_kodu = %s
                        """,
                        (tahsis_ad, depo_sube, kk),
                    )
                else:
                    cur.execute(
                        """
                        UPDATE merkez_stok_kart
                        SET rezerve_adet = GREATEST(0, COALESCE(rezerve_adet, 0) - %s),
                            guncelleme   = NOW()
                        WHERE kalem_kodu = %s
                        """,
                        (tahsis_ad, kk),
                    )
            except Exception as _e:
                log.warning("gonderilmedi_kapat rezerv_serbest hata siparis=%s kalem=%s: %s",
                            row.get("id"), kk, _e)

    # Şimdi kapat
    cur.execute(
        """
        UPDATE siparis_talep
        SET durum          = 'gonderilmedi',
            gonderilmedi_ts = NOW()
        WHERE durum = 'bekliyor'
          AND tarih < CURRENT_DATE - (%s * INTERVAL '1 day')
        """,
        (OPS_STOK_DISIPLIN_BEKLEYEN_GUN,),
    )
    return cur.rowcount


def _stok_kayip_ozet_hizli() -> Dict[str, int]:
    """
    Son 30 günde açılış+kapanış eşleşmesi olan şubelerde stok sapmasını sayar.
    Formül: açılış + ekleme(URUN_STOK_EKLE/URUN_AC) - kapanış = tahmini tüketim.
    Pozitif fark → açıklanamayan kayıp.
    10 dakika önbellekte tutulur.
    """
    now = time.time()
    if now - _stok_kayip_cache["ts"] < _STOK_KAYIP_CACHE_SURE:
        return {"anomali_sube": int(_stok_kayip_cache["anomali_sube"]), "toplam_kayip": int(_stok_kayip_cache["toplam_kayip"])}

    anomali_subeler: set = set()
    toplam_kayip = 0
    try:
        with db() as (conn, cur):
            cur.execute("""
                SELECT sube_id, tarih, meta FROM sube_operasyon_event
                WHERE tip='KAPANIS' AND durum='tamamlandi'
                  AND tarih >= CURRENT_DATE - INTERVAL '30 days'
            """)
            kap_rows = [dict(r) for r in cur.fetchall()]
            cur.execute("""
                SELECT sube_id, tarih, meta FROM sube_operasyon_event
                WHERE tip='ACILIS' AND durum='tamamlandi'
                  AND tarih >= CURRENT_DATE - INTERVAL '30 days'
            """)
            ac_rows = [dict(r) for r in cur.fetchall()]
            # Gün içi eklemeler (URUN_STOK_EKLE + URUN_AC) — tam analizle aynı formül
            cur.execute("""
                SELECT sube_id, tarih, etiket, aciklama
                FROM operasyon_defter
                WHERE tarih >= CURRENT_DATE - INTERVAL '30 days'
                  AND etiket IN ('URUN_STOK_EKLE', 'URUN_AC')
            """)
            defter_rows = [dict(r) for r in cur.fetchall()]

        ac_map: Dict[tuple, Any] = {}
        for r in ac_rows:
            ac_map[(str(r["sube_id"]), str(r["tarih"]))] = r.get("meta")

        ek_map: Dict[tuple, Dict[str, int]] = {}
        for r in defter_rows:
            key = (str(r["sube_id"]), str(r["tarih"]))
            if key not in ek_map:
                ek_map[key] = {k: 0 for k in STOK_KEYS}
            prefix = "URUN_STOK_JSON:" if r.get("etiket") == "URUN_STOK_EKLE" else "URUN_AC_JSON:"
            d = _ops_parse_defter_delta(str(r.get("aciklama") or ""), prefix)
            for k in STOK_KEYS:
                ek_map[key][k] += int(d.get(k) or 0)

        for r in kap_rows:
            key = (str(r["sube_id"]), str(r["tarih"]))
            if key not in ac_map:
                continue
            kap_stok = _stok_map_from_meta(r.get("meta"), "kapanis_stok_sayim")
            ac_stok  = _stok_map_from_meta(ac_map[key], "acilis_stok_sayim")
            ek       = ek_map.get(key, {})
            for k in STOK_KEYS:
                # açılış + ekleme - kapanış = tüketim; pozitif = kayıp
                fark = int(ac_stok.get(k) or 0) + int(ek.get(k) or 0) - int(kap_stok.get(k) or 0)
                if fark > 0:
                    anomali_subeler.add(r["sube_id"])
                    toplam_kayip += fark
    except Exception:
        logger.exception("_stok_kayip_ozet_hizli hata")

    _stok_kayip_cache["ts"] = now
    _stok_kayip_cache["anomali_sube"] = len(anomali_subeler)
    _stok_kayip_cache["toplam_kayip"] = toplam_kayip
    return {"anomali_sube": len(anomali_subeler), "toplam_kayip": toplam_kayip}


class OpsGiderFisKontrolBody(BaseModel):
    gider_id: str
