def _depoda_var_miydi(cur: Any, sube_id: str, tarih: str) -> bool:
    """Basit sinyal kararı için: o gün stok hareketi/teslim var mı?"""
    cur.execute(
        """
        SELECT 1
        FROM operasyon_defter
        WHERE sube_id=%s AND tarih=%s::date
          AND etiket IN ('URUN_SEVK','URUN_AC','URUN_STOK_EKLE')
        LIMIT 1
        """,
        (sube_id, tarih),
    )
    return cur.fetchone() is not None


def _son_kapanis_event_row(cur: Any, sube_id: str, tarih: Any) -> Any:
    """Verilen gün için son tamamlanmış KAPANIS event (yalnızca meta sütunu)."""
    cur.execute(
        """
        SELECT meta
        FROM sube_operasyon_event
        WHERE sube_id=%s
          AND tarih=%s
          AND tip='KAPANIS' AND durum='tamamlandi'
        ORDER BY cevap_ts DESC NULLS LAST, id DESC
        LIMIT 1
        """,
        (sube_id, tarih),
    )
    return cur.fetchone()


def _davranis_uyarilari_siparis_talep(
    cur: Any, talep_id: str
) -> List[Dict[str, Any]]:
    """Aynı katalog siparişine bağlı kalıcı davranış (DAVRANIS) uyarı satırları."""
    tid = (talep_id or "").strip()
    if not tid:
        return []
    cur.execute(
        """
        SELECT kural, mesaj, puan
        FROM sube_operasyon_uyari
        WHERE siparis_talep_id=%s AND tip='DAVRANIS'
        ORDER BY puan DESC
        """,
        (tid,),
    )
    return [
        {"kural": r.get("kural"), "mesaj": r.get("mesaj"), "puan": int(r.get("puan") or 0)}
        for r in cur.fetchall()
    ]


def _enrich_kalemler_ve_davranis(
    cur: Any,
    *,
    sube_id: str,
    kalemler: List[Any],
    merkez_map: Any,
    hedef_depo_sube_id: Optional[str],
    talep_id: str,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    """
    Katalog sipariş satırı: stok zenginleştirme + aynı talep için davranış uyarıları.
    (Hub alarm, operasyon ekranları, sevkiyat önizleme aynı mantığı paylaşır.)
    """
    fl = enrich_siparis_kalemleri_stok_inplace(
        cur,
        sube_id,
        kalemler,
        merkez_map=merkez_map,
        hedef_depo_sube_id=hedef_depo_sube_id,
    )
    dvr = _davranis_uyarilari_siparis_talep(cur, talep_id)
    return fl, dvr


@router.get("/personel-takip")
def ops_personel_takip_liste(sube_id: Optional[str] = None):
    sid = (sube_id or "").strip() or None
    with db() as (conn, cur):
        qp: List[Any] = []
        q = """
            SELECT t.*, COALESCE(p.ad_soyad, u.ad, t.personel_id) AS personel_ad
            FROM personel_takip t
            LEFT JOIN personel p ON p.id = t.personel_id
            LEFT JOIN sube_panel_kullanici u ON u.id = t.personel_id
            WHERE TRUE
        """
        if sid:
            # sinyal tablosundan son 30 günde bu şubede sinyal var mı filtrele
            q += """
              AND EXISTS (
                SELECT 1 FROM personel_risk_sinyal s
                WHERE s.personel_id = t.personel_id
                  AND s.sube_id = %s
                  AND s.tarih >= (CURRENT_DATE - INTERVAL '30 day')
              )
            """
            qp.append(sid)
        q += " ORDER BY CASE t.takip_seviyesi WHEN 'kritik' THEN 0 WHEN 'uyari' THEN 1 ELSE 2 END, t.guncelleme DESC"
        cur.execute(q, tuple(qp))
        rows = []
        for r in cur.fetchall():
            d = dict(r)
            if d.get("takip_baslangic"):
                d["takip_baslangic"] = str(d["takip_baslangic"])
            if d.get("guncelleme"):
                d["guncelleme"] = str(d["guncelleme"])
            rows.append(d)
    return {"satirlar": rows}


@router.get("/sube-giris-bugun")
def ops_sube_giris_bugun(tarih: Optional[str] = None):
    """Bugün şube giriş takibi (cep canlı operasyon): kim girdi, planlanan vardiya saati
    (09-18), fiili giriş ve kaç dk geç. vardiya_atama (planlanan) ↔ gorev_yoklama (fiili)."""
    from datetime import date as _date
    try:
        hedef = str(_date.fromisoformat(tarih)) if tarih else str(is_gunu_tr())
    except Exception:
        hedef = str(is_gunu_tr())
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT gy.sube_id::text, s.ad AS sube_ad, gy.personel_id,
                   COALESCE(p.ad_soyad, gy.personel_id) AS personel_ad,
                   gy.vardiya_tip,
                   to_char((gy.giris_ts AT TIME ZONE 'Europe/Istanbul'), 'HH24:MI') AS giris_saat,
                   va.baslangic_saat, va.bitis_saat,
                   CASE WHEN va.baslangic_saat IS NOT NULL THEN
                     ROUND(EXTRACT(EPOCH FROM (
                       (gy.giris_ts AT TIME ZONE 'Europe/Istanbul')::time - va.baslangic_saat
                     ))/60.0)
                   END AS gecikme_dk
            FROM gorev_yoklama gy
            JOIN subeler s ON s.id = gy.sube_id
            LEFT JOIN personel p ON p.id::text = gy.personel_id
            LEFT JOIN LATERAL (
              SELECT va.baslangic_saat, va.bitis_saat
              FROM vardiya_atama va
              WHERE va.personel_id::text = gy.personel_id AND va.tarih = gy.tarih
                AND COALESCE(va.durum,'') <> 'iptal'
              ORDER BY ABS(EXTRACT(EPOCH FROM (va.baslangic_saat - (gy.giris_ts AT TIME ZONE 'Europe/Istanbul')::time))) ASC
              LIMIT 1
            ) va ON TRUE
            WHERE gy.tarih = %s
            ORDER BY s.ad, gy.giris_ts
            """,
            (hedef,),
        )
        rows = []
        for r in cur.fetchall():
            d = dict(r)
            d["baslangic_saat"] = str(d["baslangic_saat"])[:5] if d.get("baslangic_saat") else None
            d["bitis_saat"] = str(d["bitis_saat"])[:5] if d.get("bitis_saat") else None
            d["gecikme_dk"] = int(d["gecikme_dk"]) if d.get("gecikme_dk") is not None else None
            rows.append(d)

        # ŞUBE AÇILIŞ: planlanan açılış saati (subeler.acilis_saati) vs fiili açılış
        # event'i (ACILIS tamamlandi) → kaç dk geç. "TEMA 12:00 açılmalıydı, 12:02 açıldı".
        # Açılış PLANI = o şubeye o gün planlanan İLK vardiyanın başlangıç saati
        # (vardiya 11:00 ise açılış 11:00 beklenir). Ayrı subeler.acilis_saati config'ine
        # bağlı DEĞİL (kullanıcı kararı 2026-06-18). Fiili = ilk ACILIS event'i.
        cur.execute(
            """
            SELECT s.id::text AS sube_id, s.ad AS sube_ad,
                   plan.planlanan,
                   to_char(MIN(e.cevap_ts) AT TIME ZONE 'Europe/Istanbul', 'HH24:MI') AS fiili_saat,
                   CASE WHEN plan.planlanan IS NOT NULL AND MIN(e.cevap_ts) IS NOT NULL THEN
                     ROUND(EXTRACT(EPOCH FROM (
                       (MIN(e.cevap_ts) AT TIME ZONE 'Europe/Istanbul')::time - plan.planlanan
                     ))/60.0)
                   END AS gecikme_dk
            FROM subeler s
            LEFT JOIN LATERAL (
              SELECT MIN(va.baslangic_saat) AS planlanan
              FROM vardiya_atama va JOIN vardiya_slot sl ON sl.id = va.slot_id
              WHERE sl.sube_id = s.id AND va.tarih = %s AND COALESCE(va.durum,'') <> 'iptal'
            ) plan ON TRUE
            LEFT JOIN sube_operasyon_event e
              ON e.sube_id = s.id AND e.tip='ACILIS' AND e.durum='tamamlandi' AND e.tarih = %s
            WHERE s.aktif = TRUE
            GROUP BY s.id, s.ad, plan.planlanan
            ORDER BY s.ad
            """,
            (hedef, hedef),
        )
        acilislar = []
        for r in cur.fetchall():
            d = dict(r)
            d["planlanan"] = str(d["planlanan"])[:5] if d.get("planlanan") else None
            d["gecikme_dk"] = int(d["gecikme_dk"]) if d.get("gecikme_dk") is not None else None
            acilislar.append(d)

        # BEKLENEN AMA GİRMEYEN: vardiyası planlı (vardiya_atama) olduğu halde bugün HİÇ
        # QR girişi (gorev_yoklama) olmayan personel. dk_gecti>0 → vardiyası başladı, hâlâ yok.
        cur.execute(
            """
            SELECT sl.sube_id::text AS sube_id, s.ad AS sube_ad, va.personel_id,
                   COALESCE(p.ad_soyad, va.personel_id) AS personel_ad,
                   va.baslangic_saat, va.bitis_saat,
                   ROUND(EXTRACT(EPOCH FROM (
                     (NOW() AT TIME ZONE 'Europe/Istanbul')::time - va.baslangic_saat
                   ))/60.0) AS dk_gecti
            FROM vardiya_atama va
            JOIN vardiya_slot sl ON sl.id = va.slot_id
            JOIN subeler s ON s.id = sl.sube_id
            LEFT JOIN personel p ON p.id::text = va.personel_id
            WHERE va.tarih = %s AND COALESCE(va.durum,'') <> 'iptal'
              AND NOT EXISTS (
                SELECT 1 FROM gorev_yoklama gy
                WHERE gy.personel_id = va.personel_id AND gy.tarih = va.tarih
              )
            ORDER BY s.ad, va.baslangic_saat
            """,
            (hedef,),
        )
        beklenenler = []
        for r in cur.fetchall():
            d = dict(r)
            d["baslangic_saat"] = str(d["baslangic_saat"])[:5] if d.get("baslangic_saat") else None
            d["bitis_saat"] = str(d["bitis_saat"])[:5] if d.get("bitis_saat") else None
            d["dk_gecti"] = int(d["dk_gecti"]) if d.get("dk_gecti") is not None else None
            beklenenler.append(d)
    return {"tarih": hedef, "toplam": len(rows), "girisler": rows,
            "acilislar": acilislar, "beklenenler": beklenenler}


@router.get("/depo-stok-yedek")
def ops_depo_stok_yedek():
    """sube_depo_stok HAM dökümü — havuz mantığı kaldırılmadan ÖNCE tam veri yedeği.
    Hiçbir resolve/gruplama/filtre YOK: tablodaki HER satır (sube_id, kalem_kodu,
    kalem_adi, mevcut_adet) olduğu gibi döner. Veri kaybına karşı emniyet ağı."""
    with db() as (_, cur):
        cur.execute(
            """
            SELECT id::text AS id, sube_id::text AS sube_id, kalem_kodu, kalem_adi,
                   mevcut_adet, COALESCE(guncelleme::text,'') AS guncelleme
            FROM sube_depo_stok
            ORDER BY sube_id, kalem_kodu
            """
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    toplam = sum(int(r.get("mevcut_adet") or 0) for r in rows)
    return {
        "yedek_zamani": _now_iso() if "_now_iso" in globals() else None,
        "satir_sayisi": len(rows),
        "toplam_adet": toplam,
        "satirlar": rows,
    }


@router.get("/depo-stok")
def ops_depo_stok():
    """Tüm aktif (sezon açık) şubelerin depo stoğu — tek çağrıda matris. Telefon
    Depolar ekranı: şube seç / tüm şubeler karşılaştır, kategori gruplu, düşük stok."""
    with db() as (_, cur):
        cur.execute(
            "SELECT id::text, ad FROM subeler WHERE aktif=TRUE AND COALESCE(sezon_kapali,FALSE)=FALSE ORDER BY ad"
        )
        subeler = [dict(r) for r in (cur.fetchall() or [])]
        cur.execute(
            """
            SELECT ds.sube_id::text AS sube_id, ds.kalem_kodu, ds.kalem_adi,
                   ds.mevcut_adet, ds.min_stok,
                   COALESCE(k.ad, '') AS kategori,
                   COALESCE(k.sira, 999) AS kat_sira, COALESCE(u.sira, 999) AS u_sira
            FROM sube_depo_stok ds
            JOIN subeler s ON s.id = ds.sube_id AND s.aktif=TRUE AND COALESCE(s.sezon_kapali,FALSE)=FALSE
            LEFT JOIN siparis_urun u ON u.id::text = ds.kalem_kodu
            LEFT JOIN siparis_kategori k ON k.id = u.kategori_id
            """
        )
        agg: Dict[str, Any] = {}
        for r in (cur.fetchall() or []):
            d = dict(r)
            kk = str(d["kalem_kodu"])
            if kk not in agg:
                agg[kk] = {
                    "kalem_kodu": kk, "kalem_adi": d.get("kalem_adi") or kk,
                    "kategori": d.get("kategori") or "Diğer",
                    "min_stok": int(d.get("min_stok") or 0),
                    "kat_sira": int(d.get("kat_sira") or 999), "u_sira": int(d.get("u_sira") or 999),
                    "adetler": {}, "toplam": 0,
                }
            a = int(d.get("mevcut_adet") or 0)
            agg[kk]["adetler"][d["sube_id"]] = a
            agg[kk]["toplam"] += a
            if not agg[kk]["kalem_adi"]:
                agg[kk]["kalem_adi"] = d.get("kalem_adi") or kk
        kalemler = sorted(
            agg.values(),
            key=lambda x: (x["kat_sira"], (x["kategori"] or "").lower(), x["u_sira"], (x["kalem_adi"] or "").lower()),
        )
    return {"subeler": subeler, "toplam_kalem": len(kalemler), "kalemler": kalemler}


# ══════════════════════════════════════════════════════════════════════════════
# MERKEZ SİPARİŞ (İZOLE) — patron/cep'ten verilen sipariş. siparis_talep(MERKEZ) +
# toptanci_siparis(kaynak='merkez') oluşturur → şube teslim-al akışına düşer,
# "Merkez Siparişi" rozetiyle görünür. Kaldırmak istersek: bu endpoint + rozet sil.
# ══════════════════════════════════════════════════════════════════════════════
@router.post("/siparis/merkez-siparis-olustur")
def ops_merkez_siparis_olustur(body: dict = None):
    body = body or {}
    sube_id = str(body.get("sube_id") or "").strip()          # teslimat şubesi
    tedarikci_id = str(body.get("tedarikci_id") or "").strip()
    notu = str(body.get("not_aciklama") or "").strip() or None
    if not sube_id or not tedarikci_id:
        raise HTTPException(400, "sube_id (teslimat) ve tedarikci_id zorunlu")
    kalemler = []
    for k in (body.get("kalemler") or []):
        ad = str((k or {}).get("urun_ad") or "").strip()
        try:
            adet = max(0, int((k or {}).get("adet") or 0))
        except Exception:
            adet = 0
        if not ad or adet <= 0:
            continue
        kalemler.append({"urun_ad": ad, "adet": adet,
                         "kalem_kodu": (str((k or {}).get("kalem_kodu") or "").strip() or None)})
    if not kalemler:
        raise HTTPException(400, "En az bir geçerli kalem girilmeli")
    with db() as (conn, cur):
        cur.execute("SELECT id, ad, telefon FROM tedarikciler WHERE id=%s AND aktif=TRUE", (tedarikci_id,))
        tr = cur.fetchone()
        if not tr:
            raise HTTPException(404, "Tedarikçi bulunamadı veya pasif")
        ted = dict(tr)
        # 🚧 GUARD SİMETRİSİ (2026-08-09): teslim ucu sezon/kasa kilidi arıyordu
        # ama SİPARİŞ ucu aramıyordu. Sonuç: sezon kapalı Köyceğiz'e sipariş
        # açılabiliyor, sonra teslimde 403 alınıyordu — yolun yarısında kalan
        # hayalet kayıt. Aynı kural zincirin her halkasında geçerli olmalı.
        cur.execute("SELECT ad, COALESCE(aktif,TRUE) AS aktif, "
                    "COALESCE(sezon_kapali,FALSE) AS sezon_kapali "
                    "FROM subeler WHERE id=%s", (sube_id,))
        sr = cur.fetchone()
        if not sr:
            raise HTTPException(404, "Şube bulunamadı")
        _s = dict(sr)
        if not _s.get("aktif"):
            raise HTTPException(409, f"'{_s.get('ad')}' şubesi pasif — sipariş açılamaz.")
        if _s.get("sezon_kapali"):
            raise HTTPException(
                409,
                f"'{_s.get('ad')}' şubesi SEZON KAPALI. Sipariş açılırsa teslim "
                "alınamaz (teslim adımı kasa kilidi ister) ve yarım kayıt kalır. "
                "Önce şubeyi sezona açın.")
        sube_adi = _s.get("ad") or sube_id
        # V2: kanonik urun_id damgala (kaynakta çöz)
        for k in kalemler:
            k["urun_id"] = _kanonik_urun_id(cur, k.get("kalem_kodu"), k.get("urun_ad"))
        # 1) siparis_talep — MERKEZ kaynaklı, toptancıya yönlendirilmiş kabul edilir
        talep_id = str(uuid.uuid4())
        cur.execute(
            """
            INSERT INTO siparis_talep
                (id, sube_id, durum, personel_ad, not_aciklama, kalemler, sevkiyat_durumu)
            VALUES (%s,%s,'gonderildi','MERKEZ',%s,%s::jsonb,'toptanciya_yonlendirildi')
            """,
            (talep_id, sube_id, notu, json.dumps(kalemler, ensure_ascii=False)),
        )
        # 2) toptanci_siparis — kaynak='merkez'; şube teslim-bekleyene düşer
        ts_id = str(uuid.uuid4())
        cur.execute(
            """
            INSERT INTO toptanci_siparis
                (id, talep_id, sube_id, tedarikci_id, tedarikci_ad, tedarikci_tel,
                 kalemler, not_aciklama, durum, kaynak, olusturan_ad)
            VALUES (%s,%s,%s,%s,%s,%s,%s::jsonb,%s,'gonderildi','merkez','Patron (Cep)')
            """,
            (ts_id, talep_id, sube_id, tedarikci_id, ted.get("ad"), ted.get("telefon"),
             json.dumps(kalemler, ensure_ascii=False), notu),
        )
    return {"ok": True, "talep_id": talep_id, "ts_id": ts_id,
            "sube_adi": sube_adi, "tedarikci_ad": ted.get("ad")}


@router.get("/kasiyer-karne")
def ops_kasiyer_karne(gun: int = 30, sube_id: Optional[str] = None):
    """Kasiyer doğruluk karnesi — ÖZENSİZLİK ≠ ŞÜPHE ayrımıyla.
    personel_risk_sinyal'i kişi bazında özetler:
      - SAYIM_OZENSIZLIK → disiplin (düzeltilince fark 0; dürüst ama özensiz)
      - KASA_GERCEK_ACIK → onaylanmış kayıp (şüphe)
      - ACILIS/KAPANIS_KASA_FARK → henüz çözülmemiş ham kasa farkı
    Profil: 🟢 temiz / 🟠 disiplin / 🟡 izle / 🔴 incele."""
    gun_sayi = max(1, min(365, int(gun or 30)))
    sid = (sube_id or "").strip() or None
    with db() as (conn, cur):
        # ⚠️ TEMBEL KOLON GARANTİSİ: `kisi_id` personel_kimlik modülü tarafından
        # lazy oluşturuluyor. O modül hiç çağrılmamışsa kolon YOK olur ve
        # aşağıdaki sorgu PATLAR — okuyanın, okuduğu kolonu garanti etmesi
        # gerekir (bu dosyadaki `_alim_kaynagi_kolonu` deseninin aynısı).
        try:
            cur.execute("ALTER TABLE personel ADD COLUMN IF NOT EXISTS kisi_id TEXT")
        except Exception:  # noqa: BLE001 — kolon zaten varsa ya da yetki yoksa akış sürsün
            pass
        q = """
            -- 👤 KİŞİ BAZINDA TOPLA (2026-08-26) — çıkıp geri gelen personel
            -- Sahip: "çıktı geri girdi." Böyle bir personelin `personel`
            -- tablosunda İKİ satırı olur ve sinyaller ikisine dağılır; risk
            -- profili İKİYE BÖLÜNÜR, aktif kişi olduğundan temiz görünür.
            -- ⚠️ GEÇMİŞ KAYIT TAŞINMADI: bir denetim sistemi kendi denetim
            -- satırlarını "rapor düzgün görünsün" diye yeniden yazmaz
            -- (ev kuralı: GERİ-ALMA ≠ SİLME · damga bulguyu silmez).
            -- Satır NE OLDUĞU konusunda doğru; yanlış olan HANGİ KİŞİ satırına
            -- asıldığı — ve onu artık `kisi_id` cevaplıyor. KAYIT DEĞİL OKUMA
            -- düzeltilir: hem geçmişe hem geleceğe çalışır, veri göçü gerekmez.
            SELECT COALESCE(p.kisi_id, s.personel_id) AS personel_id,
                   COALESCE(p.ad_soyad, u.ad, s.personel_id) AS personel_ad,
                   COUNT(*) FILTER (WHERE s.sinyal_turu='SAYIM_OZENSIZLIK') AS ozensizlik,
                   COUNT(*) FILTER (WHERE s.sinyal_turu='KASA_GERCEK_ACIK') AS gercek_acik,
                   COUNT(*) FILTER (WHERE s.sinyal_turu IN ('ACILIS_KASA_FARK','KAPANIS_KASA_FARK')) AS ham_kasa_fark,
                   COUNT(*) AS toplam_sinyal,
                   COALESCE(SUM(s.agirlik),0) AS toplam_agirlik,
                   MAX(s.tarih) AS son_sinyal
            FROM personel_risk_sinyal s
            LEFT JOIN personel p ON p.id = s.personel_id
            LEFT JOIN sube_panel_kullanici u ON u.id = s.personel_id
            WHERE s.tarih >= (CURRENT_DATE - (%s * INTERVAL '1 day'))
        """
        qp: List[Any] = [gun_sayi]
        if sid:
            q += " AND s.sube_id = %s"
            qp.append(sid)
        q += " GROUP BY COALESCE(p.kisi_id, s.personel_id), personel_ad ORDER BY gercek_acik DESC, ham_kasa_fark DESC, ozensizlik DESC"
        cur.execute(q, tuple(qp))
        karne = []
        for r in cur.fetchall():
            d = dict(r)
            ozen = int(d.get("ozensizlik") or 0)
            gercek = int(d.get("gercek_acik") or 0)
            ham = int(d.get("ham_kasa_fark") or 0)
            # Şüphe skoru: gerçek açık ağır, çözülmemiş ham fark orta; özensizlik şüpheye GİRMEZ
            suphe_skor = gercek * 10 + ham * 3
            if gercek >= 1 or suphe_skor >= 15:
                profil = "incele"; profil_emoji = "🔴"; profil_metin = "İncele (gerçek açık / yoğun fark)"
            elif ham >= 3:
                profil = "izle"; profil_emoji = "🟡"; profil_metin = "İzle (çözülmemiş kasa farkları)"
            elif ozen >= 3:
                profil = "disiplin"; profil_emoji = "🟠"; profil_metin = "Disiplin (özensiz ama dürüst — kayıp yok)"
            else:
                profil = "temiz"; profil_emoji = "🟢"; profil_metin = "Temiz"
            d["ozensizlik"] = ozen
            d["gercek_acik"] = gercek
            d["ham_kasa_fark"] = ham
            d["toplam_sinyal"] = int(d.get("toplam_sinyal") or 0)
            d["toplam_agirlik"] = int(d.get("toplam_agirlik") or 0)
            d["suphe_skor"] = suphe_skor
            d["profil"] = profil
            d["profil_emoji"] = profil_emoji
            d["profil_metin"] = profil_metin
            d["son_sinyal"] = str(d["son_sinyal"]) if d.get("son_sinyal") else None
            karne.append(d)
    return {"gun": gun_sayi, "sube_id": sid, "toplam_kasiyer": len(karne), "karne": karne}


@router.get("/personel-risk-sinyal")
def ops_personel_risk_sinyal(personel_id: str, gun: int = 30):
    pid = (personel_id or "").strip()
    if not pid:
        raise HTTPException(400, "personel_id zorunlu")
    gun_sayi = max(1, min(365, int(gun or 30)))
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT id, personel_id, sube_id, tarih, sinyal_turu, agirlik, aciklama, referans_id, olusturma
            FROM personel_risk_sinyal
            WHERE personel_id=%s
              AND tarih >= (CURRENT_DATE - (%s * INTERVAL '1 day'))
            ORDER BY tarih DESC, olusturma DESC
            LIMIT 500
            """,
            (pid, gun_sayi),
        )
        rows = []
        for r in cur.fetchall():
            d = dict(r)
            if d.get("tarih"):
                d["tarih"] = str(d["tarih"])
            if d.get("olusturma"):
                d["olusturma"] = str(d["olusturma"])
            d["agirlik"] = int(d.get("agirlik") or 0)
            rows.append(d)
        cur.execute("SELECT * FROM personel_takip WHERE personel_id=%s", (pid,))
        takip = cur.fetchone()
        takip_d = dict(takip) if takip else None
        if takip_d:
            if takip_d.get("takip_baslangic"):
                takip_d["takip_baslangic"] = str(takip_d["takip_baslangic"])
            if takip_d.get("guncelleme"):
                takip_d["guncelleme"] = str(takip_d["guncelleme"])
    return {"personel_id": pid, "gun_sayi": gun_sayi, "takip": takip_d, "satirlar": rows}

_YM_RE = re.compile(r"^\d{4}-\d{2}$")


class GuvenlikAlarmIslemBody(BaseModel):
    personel_id: Optional[str] = None
    notu: Optional[str] = None
    sustur_dk: int = 120


class KasaUyumsuzlukCozBody(BaseModel):
    notu: Optional[str] = None
    personel_id: Optional[str] = None
    personel_ad: Optional[str] = None
    # Düzeltilmiş fark tutarı — sonradan yapılan hesaplamalar bu tutara göre işler.
    # None bırakılırsa orijinal fark_tl geçerli olur.
    duzeltilen_fark_tl: Optional[float] = None


class KasaKaynakDuzeltmeBody(BaseModel):
    """Kasa farkının KAYNAĞINI düzeltir, sonra recalc tetiklenir."""
    sebep: str  # ciro_yanlis | acilis_yanlis | gider_eksik | devir_yanlis | gercek_acik
    notu: Optional[str] = None
    personel_id: Optional[str] = None
    personel_ad: Optional[str] = None
    # Sebebe göre payload:
    #   ciro_yanlis: { yeni_nakit, yeni_pos?, yeni_online? }
    #   acilis_yanlis: { yeni_acilis_kasa }
    #   gider_eksik: { kategori, tutar, aciklama? }
    #   devir_yanlis: { yeni_teslim?, yeni_devir? }
    #   gercek_acik: {} (kaynak değişmez, sadece audit + okundu)
    payload: Dict[str, Any] = {}
    onay_pin: Optional[str] = None  # İşletme onayı (Merve Karabacak PIN) — mali kayıt değiştirir


def _coerce_year_month(ym: Optional[str]) -> str:
    v = (ym or "").strip()
    if not v:
        return bugun_tr().strftime("%Y-%m")
    if not _YM_RE.match(v):
        return bugun_tr().strftime("%Y-%m")
    return v


def _guvenlik_alarm_limitleri() -> Dict[str, int]:
    try:
        pencere = int((os.environ.get("EVVEL_GUV_ALARM_DK") or "15").strip())
    except ValueError:
        pencere = 15
    try:
        pin_kilit_esik = int((os.environ.get("EVVEL_GUV_ALARM_PIN_KILIT") or "2").strip())
    except ValueError:
        pin_kilit_esik = 2
    try:
        pin_hatali_esik = int((os.environ.get("EVVEL_GUV_ALARM_PIN_HATALI") or "8").strip())
    except ValueError:
        pin_hatali_esik = 8
    return {
        "pencere_dk": max(5, min(pencere, 240)),
        "pin_kilit_esik": max(1, min(pin_kilit_esik, 50)),
        "pin_hatali_esik": max(1, min(pin_hatali_esik, 200)),
    }


def _sube_guvenlik_alarm_ozet(cur: Any, sube_id: str, lim: Dict[str, int]) -> Dict[str, Any]:
    cur.execute(
        """
        SELECT
          COUNT(*) FILTER (WHERE tip='PIN_KILIT')::int AS pin_kilit_adet,
          COUNT(*) FILTER (WHERE tip='PIN_HATALI')::int AS pin_hatali_adet,
          COUNT(*) FILTER (WHERE tip='PIN_KILITTE_DENEME')::int AS pin_kilitte_deneme_adet,
          MAX(olay_ts) AS son_olay_ts
        FROM operasyon_guvenlik_olay
        WHERE sube_id=%s
          AND olay_ts >= NOW() - (%s * INTERVAL '1 minute')
        """,
        (sube_id, lim["pencere_dk"]),
    )
    r = dict(cur.fetchone() or {})
    pin_kilit = int(r.get("pin_kilit_adet") or 0)
    pin_hatali = int(r.get("pin_hatali_adet") or 0)
    pin_kilitte_deneme = int(r.get("pin_kilitte_deneme_adet") or 0)
    alarm = pin_kilit >= lim["pin_kilit_esik"] or pin_hatali >= lim["pin_hatali_esik"]
    seviye = "kritik" if pin_kilit >= lim["pin_kilit_esik"] else ("uyari" if alarm else "normal")
    mesaj = None
    if pin_kilit >= lim["pin_kilit_esik"]:
        mesaj = f"PIN_KILIT son {lim['pencere_dk']} dk: {pin_kilit} (eşik {lim['pin_kilit_esik']})"
    elif pin_hatali >= lim["pin_hatali_esik"]:
        mesaj = f"PIN_HATALI son {lim['pencere_dk']} dk: {pin_hatali} (eşik {lim['pin_hatali_esik']})"
    out = {
        "pencere_dk": lim["pencere_dk"],
        "pin_kilit_adet": pin_kilit,
        "pin_hatali_adet": pin_hatali,
        "pin_kilitte_deneme_adet": pin_kilitte_deneme,
        "alarm": alarm,
        "seviye": seviye,
        "mesaj": mesaj,
    }
    if r.get("son_olay_ts"):
        out["son_olay_ts"] = str(r["son_olay_ts"])
    return out


def _alarm_durum_get(cur: Any, sube_id: str) -> Optional[Dict[str, Any]]:
    cur.execute(
        """
        SELECT sube_id, durum, islem_ts, islem_personel_id, islem_notu, sustur_bitis_ts
        FROM operasyon_guvenlik_alarm_durum
        WHERE sube_id=%s
        """,
        (sube_id,),
    )
    row = cur.fetchone()
    if not row:
        return None
    d = dict(row)
    if d.get("durum") == "susturuldu" and d.get("sustur_bitis_ts"):
        # Süresi dolan susturma, otomatik pasife düşer.
        cur.execute(
            """
            DELETE FROM operasyon_guvenlik_alarm_durum
            WHERE sube_id=%s
              AND durum='susturuldu'
              AND sustur_bitis_ts IS NOT NULL
              AND sustur_bitis_ts <= NOW()
            """,
            (sube_id,),
        )
        if cur.rowcount:
            return None
    if d.get("islem_ts"):
        d["islem_ts"] = str(d["islem_ts"])
    if d.get("sustur_bitis_ts"):
        d["sustur_bitis_ts"] = str(d["sustur_bitis_ts"])
    return d


def _ozet_events(events: List[dict]) -> Dict[str, Any]:
    by_tip: Dict[str, List[dict]] = {}
    for e in events:
        t = e.get("tip") or ""
        by_tip.setdefault(t, []).append(e)

    def _durum_list(tip: str) -> List[str]:
        return [x.get("durum") or "" for x in by_tip.get(tip, [])]

    def _any_tamam(tip: str) -> bool:
        return any(x.get("durum") == "tamamlandi" for x in by_tip.get(tip, []))

    def _any_gecikti(tip: str) -> bool:
        return any(x.get("durum") == "gecikti" for x in by_tip.get(tip, []))

    alarm_toplam = sum(int(e.get("alarm_sayisi") or 0) for e in events)
    return {
        "acilis_tamam": _any_tamam("ACILIS"),
        "acilis_gecikti": _any_gecikti("ACILIS"),
        "kontrol_bekleyen": sum(1 for x in by_tip.get("KONTROL", []) if x.get("durum") in ("bekliyor", "gecikti")),
        "kontrol_gecikti": _any_gecikti("KONTROL"),
        "kapanis_tamam": _any_tamam("KAPANIS"),
        "kapanis_gecikti": _any_gecikti("KAPANIS"),
        "cikis_acik": any(x.get("durum") in ("bekliyor", "gecikti") for x in by_tip.get("CIKIS", [])),
        "alarm_sayisi_toplam": alarm_toplam,
        "tip_durumlar": {k: _durum_list(k) for k in ("ACILIS", "KONTROL", "CIKIS", "KAPANIS")},
    }


def _kart_uret(cur, sube_row: dict, guvenlik_lim: Dict[str, int]) -> Dict[str, Any]:
    sid = sube_row["id"]
    sube = dict(sube_row)
    # ensure=False: dashboard salt-okuma poll'üdür; günlük event satırı oluşturma
    # scheduler(02:30)+startup tarafından garanti edilir. Dinamik durum sync'leri (gecikti
    # geçişi vb.) yine çalışır. Bu, her 25 sn'lik poll'de koşulsuz yazmayı kaldırır.
    operasyon = build_panel_operasyon_blob(cur, sid, sube, ensure=False)
    events = operasyon.get("events") or []
    ozet = _ozet_events(events)

    ciro_girildi = _bugun_ciro_var_mi(cur, sid)
    sube_acik = _bugun_sube_acildi_mi(cur, sid)
    kasa_acik = _bugun_kasa_acildi_mi(cur, sid)
    taslak_row   = _bugun_ciro_taslak_bekliyor(cur, sid)
    taslak_bek   = taslak_row is not None
    # Gecikmiş taslak: bekliyor + olusturma > 6 saat önce → operatör uyarısı.
    taslak_gecikti = False
    if taslak_row and taslak_row.get("olusturma"):
        try:
            _ol = str(taslak_row["olusturma"]).strip().replace("Z", "+00:00")
            _ol_dt = datetime.fromisoformat(_ol)
            if _ol_dt.tzinfo is not None:
                _ol_dt = _ol_dt.astimezone().replace(tzinfo=None)
            taslak_gecikti = (dt_now_tr_naive() - _ol_dt).total_seconds() > 6 * 3600
        except Exception:
            pass
    cur.execute(
        """
        SELECT COALESCE(SUM(toplam), 0) AS toplam
        FROM ciro
        WHERE sube_id=%s
          AND tarih=CURRENT_DATE
          AND durum='aktif'
        """,
        (sid,),
    )
    bugun_ciro_tutar = float((cur.fetchone() or {}).get("toplam") or 0)

    # 7 günlük ciro trendi — hub kart sparkline için.
    # generate_series boş günleri 0 ile doldurur; her zaman tam 7 satır döner.
    # Birden fazla şube cirosunun aynı güne düşmesi (edge case) SUM ile toplanır.
    cur.execute(
        """
        SELECT
            gs.dt::text          AS tarih,
            COALESCE(SUM(c.toplam), 0)::float AS ciro
        FROM (
            SELECT generate_series(
                CURRENT_DATE - INTERVAL '6 days',
                CURRENT_DATE,
                INTERVAL '1 day'
            )::date AS dt
        ) gs
        LEFT JOIN ciro c
               ON c.tarih::date = gs.dt
              AND c.sube_id = %s
              AND c.durum = 'aktif'
        GROUP BY gs.dt
        ORDER BY gs.dt ASC
        """,
        (sid,),
    )
    ciro_trend = [
        {"tarih": r["tarih"], "ciro": float(r["ciro"] or 0)}
        for r in cur.fetchall()
    ]

    kritik = bool(operasyon.get("aktif_kritik"))
    geciken = kritik or bool(operasyon.get("aktif_suphe")) or any(
        e.get("durum") == "gecikti" for e in events
    )

    cur.execute(
        """
        SELECT u.id, u.tip, u.seviye, u.fark_tl, u.beklenen_tl, u.gercek_tl,
               u.mesaj, u.okundu, u.olusturma,
               u.kalem_kodu, COALESCE(ds.kalem_adi, '') AS kalem_adi
        FROM sube_operasyon_uyari u
        LEFT JOIN sube_depo_stok ds ON ds.sube_id = u.sube_id AND ds.kalem_kodu = u.kalem_kodu
        WHERE u.sube_id=%s AND u.tarih=CURRENT_DATE
        ORDER BY u.olusturma DESC
        LIMIT 12
        """,
        (sid,),
    )
    uyarilar: List[dict] = []
    fark_tl: Optional[float] = None
    for r in cur.fetchall():
        d = dict(r)
        if d.get("olusturma"):
            d["olusturma"] = str(d["olusturma"])
        if d.get("fark_tl") is not None:
            d["fark_tl"] = float(d["fark_tl"])
            if fark_tl is None and abs(float(d["fark_tl"])) > 0.01:
                fark_tl = float(d["fark_tl"])
        if d.get("beklenen_tl") is not None:
            d["beklenen_tl"] = float(d["beklenen_tl"])
        if d.get("gercek_tl") is not None:
            d["gercek_tl"] = float(d["gercek_tl"])
        # DAVRANIS uyarılarında eski format düzelt: ürün adı mesaja ekle
        if d.get("tip") == "DAVRANIS" and d.get("kalem_adi"):
            mesaj = str(d.get("mesaj") or "")
            kalem_adi = str(d["kalem_adi"])
            # Eski format: "... — {"mevcut": X, ...}" — ürün adı yoksa ekle
            if kalem_adi and kalem_adi not in mesaj:
                # JSON kuyruğunu temizle, ürün adını ekle
                import re as _re
                mesaj_temiz = _re.sub(r"\s*—\s*\{.*\}$", "", mesaj).strip()
                # detay'dan mevcut/min_stok al
                detay_raw = d.get("detay") or "{}"
                try:
                    detay_obj = json.loads(detay_raw) if isinstance(detay_raw, str) else (detay_raw or {})
                except Exception:
                    detay_obj = {}
                mevcut  = detay_obj.get("mevcut")
                min_stok = detay_obj.get("min_stok")
                ekler = [kalem_adi]
                if mevcut is not None:
                    ekler.append(f"mevcut: {mevcut}")
                if min_stok is not None:
                    ekler.append(f"min: {min_stok}")
                d["mesaj"] = mesaj_temiz + " — " + " · ".join(str(e) for e in ekler)
        uyarilar.append(d)

    virt = build_virtual_merkez_uyarilari(cur, sid, dt_now_tr_naive())
    # Sanal liste DB'ye yazıldıktan sonra aynı ID ikinci kez DB'den de gelebilir; dedup yap.
    _db_ids = {u["id"] for u in uyarilar if u.get("id")}
    virt_yeni = [v for v in virt if not (v.get("id") and v["id"] in _db_ids)]
    uyarilar = virt_yeni + uyarilar

    fark_var = any(
        (u.get("fark_tl") is not None and abs(float(u["fark_tl"])) > 0.01)
        or (u.get("seviye") in ("uyari", "kritik"))
        for u in uyarilar
    )

    vd_gerek = vardiya_devri_bugun_baslamis_mi(cur, sid)
    vd_ok = vardiya_devri_tamamlandi_mi(cur, sid)
    vardiya_devri_durum = "Tamamlandı" if vd_ok else ("Devam ediyor" if vd_gerek else "—")

    now_naive = dt_now_tr_naive()

    def _event_ts_to_dt(raw: Any) -> Optional[datetime]:
        if raw is None:
            return None
        if isinstance(raw, datetime):
            dtv = raw
        else:
            s = str(raw).strip()
            if not s:
                return None
            s = s.replace("Z", "+00:00")
            try:
                dtv = datetime.fromisoformat(s)
            except Exception:
                try:
                    dtv = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
                except Exception:
                    return None
        if dtv.tzinfo is not None:
            return dtv.astimezone().replace(tzinfo=None)
        return dtv

    def _json_dict_or_empty(raw: Any) -> Dict[str, Any]:
        if isinstance(raw, dict):
            return raw
        if isinstance(raw, str):
            txt = raw.strip()
            if not txt:
                return {}
            try:
                obj = json.loads(txt)
            except Exception:
                return {}
            return obj if isinstance(obj, dict) else {}
        return {}

    acilis_gercek_dt: Optional[datetime] = None
    for e in events:
        if e.get("tip") != "ACILIS" or e.get("durum") != "tamamlandi":
            continue
        dtv = _event_ts_to_dt(e.get("cevap_ts"))
        if not dtv:
            continue
        if acilis_gercek_dt is None or dtv > acilis_gercek_dt:
            acilis_gercek_dt = dtv

    kontrol_gecikme_dk = 0
    for e in events:
        if e.get("tip") != "KONTROL" or e.get("durum") != "gecikti":
            continue
        son_teslim_dt = _event_ts_to_dt(e.get("son_teslim_ts"))
        if not son_teslim_dt:
            continue
        dk = int((now_naive - son_teslim_dt).total_seconds() // 60)
        kontrol_gecikme_dk = max(kontrol_gecikme_dk, max(0, dk))
    cur.execute(
        """
        SELECT MAX(EXTRACT(EPOCH FROM (NOW() - son_teslim_ts)) / 60.0) AS gecikme_dk
        FROM sube_operasyon_event
        WHERE sube_id=%s
          AND tarih=CURRENT_DATE
          AND tip='KONTROL'
          AND durum='gecikti'
          AND son_teslim_ts IS NOT NULL
        """,
        (sid,),
    )
    gecikme_row = cur.fetchone() or {}
    try:
        kontrol_gecikme_dk = max(0, int(gecikme_row.get("gecikme_dk") or 0))
    except (TypeError, ValueError):
        kontrol_gecikme_dk = 0
    cur.execute(
        """
        SELECT COUNT(*) AS adet
        FROM siparis_talep
        WHERE sube_id=%s AND tarih=CURRENT_DATE AND durum='bekliyor'
        """,
        (sid,),
    )
    sip_bek = int((cur.fetchone() or {}).get("adet") or 0)
    cur.execute(
        """
        SELECT COUNT(*) AS adet
        FROM siparis_ozel_talep
        WHERE sube_id=%s AND tarih=CURRENT_DATE AND durum='bekliyor'
        """,
        (sid,),
    )
    sip_ozel_bek = int((cur.fetchone() or {}).get("adet") or 0)
    cur.execute(
        """
        SELECT COUNT(*) AS adet
        FROM siparis_talep
        WHERE hedef_depo_sube_id=%s
          AND sevkiyat_durumu IN ('depoda_hazirlaniyor', 'kismi_hazirlandi')
          AND tarih >= (CURRENT_DATE - INTERVAL '7 day')
        """,
        (sid,),
    )
    sevkiyat_bek = int((cur.fetchone() or {}).get("adet") or 0)
    cur.execute(
        """
        SELECT COUNT(*) AS adet
        FROM onay_kuyrugu
        WHERE kaynak_tablo='anlik_giderler' AND durum='bekliyor'
          AND kaynak_id IN (
            SELECT id FROM anlik_giderler WHERE sube=%s AND tarih=CURRENT_DATE
          )
        """,
        (sid,),
    )
    gider_bek = int((cur.fetchone() or {}).get("adet") or 0)
    cur.execute(
        """
        SELECT COUNT(*) AS adet
        FROM sube_merkez_not
        WHERE sube_id=%s AND DATE(olusturma)=CURRENT_DATE
        """,
        (sid,),
    )
    not_adet = int((cur.fetchone() or {}).get("adet") or 0)

    satis_tahmini_toplam = 0
    satis_tahmini_kalemler: Dict[str, int] = {}
    teorik = teorik_stok_bugun(cur, sid)
    kap_row = _son_kapanis_event_row(cur, sid, bugun_tr())
    if teorik is not None and kap_row:
        gercek = stok_from_event_meta((kap_row or {}).get("meta"), "kapanis_stok_sayim")
        for k in STOK_KEYS:
            diff = int(teorik.get(k) or 0) - int(gercek.get(k) or 0)
            if diff > 0:
                satis_tahmini_kalemler[k] = diff
                satis_tahmini_toplam += diff

    cur.execute(
        """
        INSERT INTO sube_operasyon_ozet (
            sube_id, tarih, acilis_gercek_ts, kontrol_gecikme_dk,
            vardiya_devri_durum, satis_tahmini_toplam, satis_tahmini_kalemler, guncelleme
        )
        VALUES (%s, CURRENT_DATE, %s, %s, %s, %s, %s::jsonb, NOW())
        ON CONFLICT (sube_id, tarih) DO UPDATE SET
            acilis_gercek_ts = EXCLUDED.acilis_gercek_ts,
            kontrol_gecikme_dk = EXCLUDED.kontrol_gecikme_dk,
            vardiya_devri_durum = EXCLUDED.vardiya_devri_durum,
            satis_tahmini_toplam = EXCLUDED.satis_tahmini_toplam,
            satis_tahmini_kalemler = EXCLUDED.satis_tahmini_kalemler,
            guncelleme = NOW()
        """,
        (
            sid,
            acilis_gercek_dt,
            kontrol_gecikme_dk,
            vardiya_devri_durum,
            satis_tahmini_toplam,
            json.dumps(satis_tahmini_kalemler, ensure_ascii=False),
        ),
    )

    readback_cols = (
        "satis_tahmini_toplam",
        "satis_tahmini_kalemler",
        "satis_tahmin_toplam",
        "satis_tahmin_json",
        "teorik_stok_json",
        "kapanis_stok_json",
    )
    cur.execute(
        """
        SELECT column_name
        FROM information_schema.columns
        WHERE table_schema='public'
          AND table_name='sube_operasyon_ozet'
          AND column_name = ANY(%s)
        """,
        (list(readback_cols),),
    )
    mevcut_kolonlar = {str((r or {}).get("column_name") or "") for r in cur.fetchall()}
    secilecek = [c for c in readback_cols if c in mevcut_kolonlar]
    ozet_row: Dict[str, Any] = {}
    if secilecek:
        cur.execute(
            f"""
            SELECT {", ".join(secilecek)}
            FROM sube_operasyon_ozet
            WHERE sube_id=%s AND tarih=CURRENT_DATE
            LIMIT 1
            """,
            (sid,),
        )
        ozet_row = dict(cur.fetchone() or {})

    rb_satis_tahmini_toplam = int(ozet_row.get("satis_tahmini_toplam") or 0)
    rb_satis_tahmini_kalemler = _json_dict_or_empty(ozet_row.get("satis_tahmini_kalemler"))
    legacy_toplam = int(ozet_row.get("satis_tahmin_toplam") or 0)
    legacy_json = _json_dict_or_empty(ozet_row.get("satis_tahmin_json"))
    # Eski kolonlar varsa yeni kolonları beslemek için fallback olarak kullan.
    if rb_satis_tahmini_toplam <= 0 and legacy_toplam > 0:
        rb_satis_tahmini_toplam = legacy_toplam
    if not rb_satis_tahmini_kalemler and legacy_json:
        rb_satis_tahmini_kalemler = legacy_json
    teorik_stok_json = _json_dict_or_empty(ozet_row.get("teorik_stok_json"))
    kapanis_stok_json = _json_dict_or_empty(ozet_row.get("kapanis_stok_json"))
    # Geriye uyumluluk alanları yeni kolonlardan türetilir.
    satis_tahmin_toplam = rb_satis_tahmini_toplam
    satis_tahmin_json = rb_satis_tahmini_kalemler

    # ── Teorik/Gerçek Satış Verimliliği ─────────────────────────
    # 14 günlük ortalama (ciro ÷ tüketim_birimi) × bugünkü birim = teorik beklenen ciro
    satis_verimlilik: Dict[str, Any] = {
        "teorik_ciro": None,
        "gercek_ciro": bugun_ciro_tutar,
        "yuzde": None,
        "tl_per_birim_ort": None,
        "yeterli_veri": False,
    }
    try:
        cur.execute(
            """
            SELECT
                COALESCE(AVG(c.toplam / NULLIF(o.satis_tahmini_toplam, 0)), 0) AS tl_per_birim,
                COUNT(*) AS gun_sayisi
            FROM ciro c
            JOIN sube_operasyon_ozet o
                ON o.sube_id = c.sube_id AND o.tarih = c.tarih
            WHERE c.sube_id = %s
              AND c.durum = 'aktif'
              AND c.tarih >= CURRENT_DATE - INTERVAL '14 days'
              AND c.tarih  < CURRENT_DATE
              AND o.satis_tahmini_toplam > 0
              AND c.toplam > 0
            """,
            (sid,),
        )
        _sv = cur.fetchone() or {}
        _tpb = float(_sv.get("tl_per_birim") or 0)
        _gun = int(_sv.get("gun_sayisi") or 0)
        if _tpb > 0 and _gun >= 3:
            _teorik = round(_tpb * rb_satis_tahmini_toplam, 2)
            _yuzde = round(bugun_ciro_tutar / _teorik * 100, 1) if _teorik > 0 else None
            satis_verimlilik = {
                "teorik_ciro": _teorik,
                "gercek_ciro": bugun_ciro_tutar,
                "yuzde": _yuzde,
                "tl_per_birim_ort": round(_tpb, 2),
                "yeterli_veri": True,
            }
    except Exception:
        pass

    cur.execute(
        """
        SELECT personel_ad, bildirim_saati, olay_ts
        FROM operasyon_defter
        WHERE sube_id=%s
          AND tarih=CURRENT_DATE
          AND etiket='ACILIS_TAMAM'
        ORDER BY olay_ts DESC
        LIMIT 1
        """,
        (sid,),
    )
    acilis_row = dict(cur.fetchone() or {})
    acilis_personel_ad = (acilis_row.get("personel_ad") or "").strip() or None
    bildirim_saati = (acilis_row.get("bildirim_saati") or "").strip()
    acilis_saat = bildirim_saati or None
    if not acilis_saat:
        acilis_olay_ts = _event_ts_to_dt(acilis_row.get("olay_ts"))
        if acilis_olay_ts:
            acilis_saat = acilis_olay_ts.strftime("%H:%M:%S")

    guvenlik = _sube_guvenlik_alarm_ozet(cur, sid, guvenlik_lim)
    alarm_durum = _alarm_durum_get(cur, sid)
    guvenlik["alarm_durum"] = alarm_durum
    sustur_aktif = bool(alarm_durum and alarm_durum.get("durum") == "susturuldu")
    guvenlik["alarm_goster"] = bool(guvenlik.get("alarm")) and not sustur_aktif

    # ── Bugünkü beklenen açılış: vardiya atamasındaki en erken slot ──────────
    beklenen_acilis_saati: Optional[str] = None
    beklenen_acilis_personel: str = ""
    # NOT: _kart_uret tek transaction'da şube döngüsünde çağrılıyor. Burada tam rollback
    # YAPILMAZ — önceki şubelerin senkronize event'lerini siler. Bunun yerine SAVEPOINT:
    # sadece bu sorgu geri alınır, transaction'ın geri kalanı korunur.
    try:
        cur.execute("SAVEPOINT sp_bek_acilis")
        cur.execute(
            """
            WITH en_erken AS (
                SELECT MIN(va.baslangic_saat) AS bek_saat
                FROM vardiya_atama va
                JOIN vardiya_slot vs ON vs.id = va.slot_id
                WHERE vs.sube_id = %s
                  AND va.tarih  = CURRENT_DATE
                  AND va.durum != 'iptal'
            )
            SELECT
                TO_CHAR(ee.bek_saat, 'HH24:MI')                    AS beklenen_saat,
                STRING_AGG(DISTINCT p.ad_soyad, ', ')               AS personel_listesi
            FROM en_erken ee
            JOIN vardiya_atama va
                ON va.baslangic_saat = ee.bek_saat
            JOIN vardiya_slot vs ON vs.id = va.slot_id
            JOIN personel p      ON p.id  = va.personel_id
            WHERE vs.sube_id = %s
              AND va.tarih  = CURRENT_DATE
              AND va.durum != 'iptal'
            GROUP BY ee.bek_saat
            """,
            (sid, sid),
        )
        va_row = cur.fetchone()
        if va_row:
            _s = str(va_row.get("beklenen_saat") or "").strip()
            if _s:
                beklenen_acilis_saati = _s
            beklened_pers = str(va_row.get("personel_listesi") or "").strip()
            beklenen_acilis_personel = beklened_pers
        cur.execute("RELEASE SAVEPOINT sp_bek_acilis")
    except Exception:
        try:
            cur.execute("ROLLBACK TO SAVEPOINT sp_bek_acilis")
        except Exception:
            pass

    # ── ŞU AN VARDİYADA OLAN PERSONEL — kartta "kim var" göstergesi ──
    # LOCALTIME (session TZ=İstanbul) slotun başlangıç/bitiş aralığındaysa o kişi vardiyada.
    # Gece vardiyası (bitiş ertesi gün): now >= başlangıç VEYA now < bitiş.
    vardiya_su_an: List[Dict[str, Any]] = []
    try:
        cur.execute("SAVEPOINT sp_vardiya_suan")
        cur.execute(
            """
            SELECT DISTINCT p.ad_soyad AS ad,
                   to_char(va.baslangic_saat, 'HH24:MI') AS bas,
                   to_char(va.bitis_saat, 'HH24:MI')     AS bit
            FROM vardiya_atama va
            JOIN vardiya_slot vs ON vs.id = va.slot_id
            JOIN personel p      ON p.id  = va.personel_id
            WHERE vs.sube_id = %s
              AND va.tarih = CURRENT_DATE
              AND va.durum != 'iptal'
              AND (
                    (NOT va.gece_vardiyasi AND LOCALTIME >= va.baslangic_saat AND LOCALTIME < va.bitis_saat)
                 OR (va.gece_vardiyasi AND (LOCALTIME >= va.baslangic_saat OR LOCALTIME < va.bitis_saat))
              )
            ORDER BY bas
            """,
            (sid,),
        )
        vardiya_su_an = [
            {"ad": str(r.get("ad") or "").strip(), "bas": r.get("bas"), "bit": r.get("bit")}
            for r in (cur.fetchall() or [])
        ]
        cur.execute("RELEASE SAVEPOINT sp_vardiya_suan")
    except Exception:
        try:
            cur.execute("ROLLBACK TO SAVEPOINT sp_vardiya_suan")
        except Exception:
            pass

    return {
        "vardiya_su_an": vardiya_su_an,
        "sube_id": sid,
        "sube_adi": sube.get("ad"),
        "kasa_acik": kasa_acik,
        "sube_acik": sube_acik,
        "ciro_girildi": ciro_girildi,
        "ciro_taslak_bekliyor": taslak_bek,
        "ciro_taslak_gecikti": taslak_gecikti,  # 6h+ bekliyorsa True — sarı uyarı
        "bugun_ciro_tutar": bugun_ciro_tutar,
        "ciro_trend": ciro_trend,          # 7 günlük [{tarih, ciro}] — sparkline
        "operasyon": operasyon,
        "ozet": ozet,
        "uyarilar": uyarilar,
        "guvenlik": guvenlik,
        "vardiya_devri_basladi": vd_gerek,
        "vardiya_devri_tamam": vd_ok,
        "vardiya_devri_durum": vardiya_devri_durum,
        "acilis_gercek_ts": acilis_gercek_dt.isoformat() if acilis_gercek_dt else None,
        "kontrol_gecikme_dk": kontrol_gecikme_dk,
        "siparis_bekleyen": sip_bek,
        "siparis_ozel_bekleyen": sip_ozel_bek,
        "sevkiyat_bekleyen": sevkiyat_bek,
        "anlik_gider_bekleyen": gider_bek,
        "gunluk_not_adet": not_adet,
        "satis_tahmini_toplam": rb_satis_tahmini_toplam,
        "satis_tahmini_kalemler": rb_satis_tahmini_kalemler,
        "satis_tahmin_toplam": satis_tahmin_toplam,
        "satis_tahmin_json": satis_tahmin_json,
        "teorik_stok_json": teorik_stok_json,
        "kapanis_stok_json": kapanis_stok_json,
        "satis_verimlilik": satis_verimlilik,
        "acilis_personel_ad": acilis_personel_ad,
        "acilis_saat": acilis_saat,
        "beklenen_acilis_saati": beklenen_acilis_saati,
        "beklenen_acilis_personel": beklenen_acilis_personel,
        "bayraklar": {
            "kritik": kritik,
            "geciken": geciken,
            "fark_var": fark_var,
            "fark_tl": fark_tl,
            "guvenlik_alarm": bool(guvenlik.get("alarm_goster")),
            "siparis_bekleyen": (sip_bek + sip_ozel_bek) > 0,
            "taslak_gecikti": taslak_gecikti,
            "teknik_hata": False,
        },
    }


@router.get("/dashboard")
def ops_dashboard(
    filtre: Optional[str] = Query(
        "all",
        description="all | kritik | geciken | fark | guvenlik | stok",
    ),
):
    """
    Tüm aktif şubeler için operasyon + günlük durum kartları.
    """
    f = (filtre or "all").strip().lower()
    if f not in ("all", "kritik", "geciken", "fark", "guvenlik", "stok"):
        f = "all"

    with db() as (conn, cur):
        cur.execute("SELECT * FROM subeler WHERE aktif=TRUE ORDER BY ad")
        subeler = cur.fetchall()
        guvenlik_lim = _guvenlik_alarm_limitleri()
        kartlar: List[dict] = []
        hatalar: List[dict] = []
        for s in subeler:
            sdict = dict(s)
            try:
                kartlar.append(_kart_uret(cur, sdict, guvenlik_lim))
            except Exception as e:
                sid = str(sdict.get("id") or "")
                sad = sdict.get("ad")
                logger.exception("ops_dashboard kart üretim hatası: sube_id=%s", sid)
                hatalar.append({"sube_id": sid, "sube_adi": sad, "hata": str(e)})
                kartlar.append(
                    {
                        "sube_id": sid,
                        "sube_adi": sad,
                        "kasa_acik": False,
                        "sube_acik": False,
                        "ciro_girildi": False,
                        "ciro_taslak_bekliyor": False,
                        "ciro_taslak_gecikti": False,
                        "operasyon": {"events": []},
                        "ozet": {},
                        "uyarilar": [
                            {
                                "tip": "OPS_DASHBOARD_HATA",
                                "seviye": "kritik",
                                "mesaj": f"Şube kartı üretilemedi: {e}",
                            }
                        ],
                        "guvenlik": {},
                        "vardiya_devri_basladi": False,
                        "vardiya_devri_tamam": False,
                        "vardiya_devri_durum": "—",
                        "kontrol_gecikme_dk": 0,
                        "siparis_bekleyen": 0,
                        "siparis_ozel_bekleyen": 0,
                        "anlik_gider_bekleyen": 0,
                        "gunluk_not_adet": 0,
                        "satis_tahmini_toplam": 0,
                        "satis_tahmini_kalemler": {},
                        "satis_tahmin_toplam": 0,
                        "satis_tahmin_json": {},
                        "teorik_stok_json": {},
                        "kapanis_stok_json": {},
                        # NOT: kritik/geciken FALSE — bu bir OPERASYON sorunu değil, TEKNİK
                        # kart üretim hatası. Sahte "şube kritik!" alarmı basmamak için ayrı
                        # bayrak (teknik_hata) kullanılır; operatör alarmı ile karışmaz.
                        "bayraklar": {
                            "kritik": False,
                            "geciken": False,
                            "fark_var": False,
                            "fark_tl": None,
                            "guvenlik_alarm": False,
                            "siparis_bekleyen": False,
                            "teknik_hata": True,
                        },
                    }
                )

        try:
            cur.execute(
                """
                SELECT
                    t.sube_id::text AS sube_id,
                    COALESCE(s.ad, t.sube_id::text) AS sube_adi,
                    t.kalemler_json,
                    t.not_aciklama,
                    t.personel_id,
                    t.guncelleme
                FROM urun_ac_taslak t
                LEFT JOIN subeler s ON s.id = t.sube_id
                WHERE t.guncelleme >= CURRENT_DATE
                  AND jsonb_typeof(COALESCE(t.kalemler_json, '[]'::jsonb)) = 'array'
                  AND jsonb_array_length(COALESCE(t.kalemler_json, '[]'::jsonb)) > 0
                ORDER BY t.guncelleme DESC
                """
            )
            _taslak_rows = cur.fetchall() or []
            yarim_urun_ac_oturumlar = []
            for row in _taslak_rows:
                kalemler = row.get("kalemler_json") or []
                if isinstance(kalemler, str):
                    try:
                        import json as _j; kalemler = _j.loads(kalemler)
                    except Exception:
                        kalemler = []
                toplam_adet = sum(max(0, int(k.get("adet") or 0)) for k in kalemler if isinstance(k, dict))
                guncelleme = row.get("guncelleme")
                yarim_urun_ac_oturumlar.append({
                    "sube_id":     str(row.get("sube_id") or ""),
                    "sube_adi":    str(row.get("sube_adi") or ""),
                    "adet":        toplam_adet,
                    "kalem_sayisi": len([k for k in kalemler if isinstance(k, dict) and int(k.get("adet") or 0) > 0]),
                    "kalemler":    [
                        {"urun_ad": str(k.get("urun_ad") or k.get("kalem_kodu") or "?"), "adet": max(0, int(k.get("adet") or 0))}
                        for k in kalemler if isinstance(k, dict) and int(k.get("adet") or 0) > 0
                    ],
                    "not_aciklama": str(row.get("not_aciklama") or ""),
                    "personel_id":  str(row.get("personel_id") or ""),
                    "guncelleme":   str(guncelleme) if guncelleme else "",
                })
        except Exception:
            yarim_urun_ac_oturumlar = []

    if f == "kritik":
        kartlar = [k for k in kartlar if k["bayraklar"]["kritik"]]
    elif f == "geciken":
        kartlar = [k for k in kartlar if k["bayraklar"]["geciken"]]
    elif f == "fark":
        kartlar = [k for k in kartlar if k["bayraklar"]["fark_var"]]
    elif f == "guvenlik":
        kartlar = [k for k in kartlar if k["bayraklar"]["guvenlik_alarm"]]
    elif f == "stok":
        def _stok_es(k):
            for u in k.get("uyarilar") or []:
                t = (u.get("tip") or "")
                # STOK_* (devir/gün-içi/alarm) + karşılıksız açma + KONTROL gecikmesi
                if t.startswith("STOK_") or t == "URUN_AC_UYUMSUZLUK" or t == "KONTROL_CEVAP_GECIKME":
                    return True
            return False

        kartlar = [k for k in kartlar if _stok_es(k)]

    # Dashboard üst blokları (kasa devir / kapanış özeti / kasa uyum) aynı iş günü etiketiyle hizalı
    ig_dash = is_gunu_tr()

    # Bugünkü kasa devri kayıtları
    kasa_devir_listesi = []
    try:
        with db() as (_, cur2):
            cur2.execute("""
                SELECT
                    k.sube_id::text,
                    COALESCE(s.ad, k.sube_id::text) AS sube_adi,
                    k.nakit, k.pos, k.online, k.teslim, k.devir,
                    k.durum,
                    k.kapanisci_onay_ts AS sabah_ts,
                    p1.ad_soyad AS sabahci_adi,
                    p2.ad_soyad AS aksamci_adi,
                    k.sabahci_personel_id,
                    k.aksamci_personel_id,
                    k.meta
                FROM kapanis_kayit k
                LEFT JOIN subeler s ON s.id = k.sube_id
                LEFT JOIN personel p1 ON p1.id::text = k.sabahci_personel_id::text
                LEFT JOIN personel p2 ON p2.id::text = k.aksamci_personel_id::text
                WHERE k.tarih = %s
                  AND k.olay = 'vardiya_sabah_aksam_devri'
                ORDER BY k.kapanisci_onay_ts DESC
            """, (ig_dash,))
            for row in (cur2.fetchall() or []):
                sabah_ts = row.get("sabah_ts")
                # Devir stok sayımını meta'dan çıkar
                meta_raw = row.get("meta") or {}
                if isinstance(meta_raw, str):
                    try:
                        import json as _j; meta_raw = _j.loads(meta_raw)
                    except Exception:
                        meta_raw = {}
                devir_stok = meta_raw.get("vardiya_devir_stok_sayim") or {}
                devir_stok_liste = [
                    {"key": k, "label": STOK_LABEL_TR.get(k, k), "adet": int(v)}
                    for k, v in devir_stok.items() if int(v or 0) > 0
                ]
                kasa_devir_listesi.append({
                    "sube_id":             str(row.get("sube_id") or ""),
                    "sube_adi":            str(row.get("sube_adi") or ""),
                    "kasadaki_nakit":      float(row.get("teslim") or 0),
                    "durum":               str(row.get("durum") or ""),
                    "sabah_ts":            str(sabah_ts) if sabah_ts else "",
                    "sabahci_adi":         str(row.get("sabahci_adi") or ""),
                    "aksamci_adi":         str(row.get("aksamci_adi") or ""),
                    "sabahci_personel_id": str(row.get("sabahci_personel_id") or ""),
                    "aksamci_personel_id": str(row.get("aksamci_personel_id") or ""),
                    "devir_stok":          devir_stok_liste,
                })
    except Exception:
        kasa_devir_listesi = []

    # İş gününe göre tamamlanan KAPANIS (gece 02:00 öncesi takvim «ertesi gün» olsa bile önceki iş günü)
    kapanis_ozet_listesi = []
    try:
        with db() as (_, cur3):
            cur3.execute(
                """
                SELECT
                    e.sube_id::text,
                    COALESCE(s.ad, e.sube_id::text) AS sube_adi,
                    e.olay_ts,
                    e.kasa_sayim,
                    e.teslim,
                    e.devir,
                    p.ad_soyad AS personel_adi,
                    e.personel_id
                FROM sube_operasyon_event e
                LEFT JOIN subeler s ON s.id = e.sube_id
                LEFT JOIN personel p ON p.id::text = e.personel_id::text
                WHERE e.tip = 'KAPANIS'
                  AND e.durum = 'tamamlandi'
                  AND e.tarih = %s
                ORDER BY e.olay_ts DESC
                """,
                (ig_dash,),
            )
            for row in (cur3.fetchall() or []):
                ts = row.get("olay_ts")
                kapanis_ozet_listesi.append({
                    "sube_id":      str(row.get("sube_id") or ""),
                    "sube_adi":     str(row.get("sube_adi") or ""),
                    "olay_ts":      str(ts) if ts else "",
                    "kasa_sayim":   float(row.get("kasa_sayim") or 0),
                    "teslim":       float(row.get("teslim") or 0),
                    "devir":        float(row.get("devir") or 0),
                    "personel_adi": str(row.get("personel_adi") or ""),
                })
    except Exception:
        kapanis_ozet_listesi = []

    # Kasa teslim (ara + gün_sonu): tabloda `olusturma` var; eski `olusturulma_ts` hatalıydı → sorgu çöküp liste boş kalıyordu.
    # Tarih aralığı iş günü sonu (`is_gunu_tr`) ile hizalı, son 14 gün (merkezde son işlemler görünsün).
    kasa_teslim_bugun_listesi: list = []
    try:
        gun_son = is_gunu_tr()
        gun_bas = gun_son - timedelta(days=13)
        with db() as (_, cur_kt):
            cur_kt.execute(
                """
                SELECT
                    kt.sube_id::text,
                    COALESCE(s.ad, kt.sube_id::text) AS sube_adi,
                    kt.tarih,
                    kt.teslim_turu,
                    kt.tutar,
                    kt.teslim_eden_ad,
                    kt.teslim_alan_ad,
                    kt.aciklama,
                    kt.olusturma
                FROM kasa_teslim kt
                LEFT JOIN subeler s ON s.id = kt.sube_id
                WHERE kt.tarih >= %s AND kt.tarih <= %s
                ORDER BY kt.tarih DESC, kt.olusturma DESC NULLS LAST
                LIMIT 200
                """,
                (gun_bas, gun_son),
            )
            for row in (cur_kt.fetchall() or []):
                ts = row.get("olusturma")
                tr = row.get("tarih")
                kasa_teslim_bugun_listesi.append(
                    {
                        "sube_id": str(row.get("sube_id") or ""),
                        "sube_adi": str(row.get("sube_adi") or ""),
                        "tarih": str(tr) if tr else "",
                        "teslim_turu": str(row.get("teslim_turu") or ""),
                        "tutar": float(row.get("tutar") or 0),
                        "teslim_eden_ad": str(row.get("teslim_eden_ad") or ""),
                        "teslim_alan_ad": str(row.get("teslim_alan_ad") or ""),
                        "aciklama": str(row.get("aciklama") or ""),
                        "ts": str(ts) if ts else "",
                    }
                )
    except Exception:
        logger.exception("ops_dashboard kasa_teslim listesi okunamadı")
        kasa_teslim_bugun_listesi = []

    # Kasa uyumsuzluk: dünün deviri ile bugünün açılış sayımı karşılaştır
    # |fark| > 50 eşiği: zincir standardı (±50₺ tolerans bandı içi normal)
    kasa_uyumsuzluk_listesi: list = []
    try:
        with db() as (_, cur_ku):
            cur_ku.execute("""
                SELECT
                    a.sube_id::text,
                    COALESCE(s.ad, a.sube_id::text) AS sube_adi,
                    a.kasa_sayim AS acilis_kasa,
                    COALESCE(
                        k.devir,
                        GREATEST(0, COALESCE(k.kasa_sayim, 0) - COALESCE(k.teslim, 0))
                    )::float AS dun_devir,
                    (a.kasa_sayim - COALESCE(
                        k.devir,
                        GREATEST(0, COALESCE(k.kasa_sayim, 0) - COALESCE(k.teslim, 0))
                    ))::float AS fark,
                    -- Son 7 günde kaç kez fark oluştu (kronik takip)
                    (
                        SELECT COUNT(*) FROM sube_operasyon_uyari u7
                        WHERE u7.sube_id = a.sube_id
                          AND u7.tip = 'ACILIS_KASA_FARK'
                          AND u7.tarih >= CURRENT_DATE - INTERVAL '7 days'
                    ) AS son_7g_fark_adet,
                    (
                        SELECT COALESCE(SUM(ABS(u7.fark_tl)), 0) FROM sube_operasyon_uyari u7
                        WHERE u7.sube_id = a.sube_id
                          AND u7.tip = 'ACILIS_KASA_FARK'
                          AND u7.tarih >= CURRENT_DATE - INTERVAL '7 days'
                    ) AS son_7g_fark_toplam
                FROM sube_operasyon_event a
                LEFT JOIN subeler s ON s.id = a.sube_id
                LEFT JOIN sube_operasyon_event k
                    ON k.sube_id = a.sube_id
                    AND k.tip = 'KAPANIS'
                    AND k.durum = 'tamamlandi'
                    AND k.tarih = (a.tarih - INTERVAL '1 day')::date
                WHERE a.tip = 'ACILIS'
                  AND a.durum = 'tamamlandi'
                  AND a.tarih = %s
                  AND ABS(a.kasa_sayim - COALESCE(
                        k.devir,
                        GREATEST(0, COALESCE(k.kasa_sayim, 0) - COALESCE(k.teslim, 0))
                    )) > 50
            """, (ig_dash,))
            for row in (cur_ku.fetchall() or []):
                fark_val = float(row.get("fark") or 0)
                fark_abs = abs(fark_val)
                if fark_abs >= 200:
                    sev_ku = "kritik"
                elif fark_abs >= 50:
                    sev_ku = "uyari"
                else:
                    sev_ku = "normal"
                kasa_uyumsuzluk_listesi.append({
                    "sube_id":    str(row.get("sube_id") or ""),
                    "sube_adi":   str(row.get("sube_adi") or ""),
                    "acilis_kasa": float(row.get("acilis_kasa") or 0),
                    "dun_devir":   float(row.get("dun_devir") or 0),
                    "fark":        fark_val,
                    "seviye":      sev_ku,
                    "son_7g_fark_adet":   int(row.get("son_7g_fark_adet") or 0),
                    "son_7g_fark_toplam": float(row.get("son_7g_fark_toplam") or 0),
                })
    except Exception:
        kasa_uyumsuzluk_listesi = []

    return {
        "tarih": str(bugun_tr()),
        "filtre": f,
        "sube_sayisi": len(kartlar),
        "satis_tahmin_toplam": sum(int(k.get("satis_tahmin_toplam") or 0) for k in kartlar),
        "guvenlik_alarmli_sube_sayisi": sum(1 for k in kartlar if k["bayraklar"].get("guvenlik_alarm")),
        "kartlar": kartlar,
        "hatalar": hatalar,
        "yarim_urun_ac_oturumlar": yarim_urun_ac_oturumlar,
        "yarim_urun_ac_oturum_sayisi": sum(int(x.get("adet") or 0) for x in yarim_urun_ac_oturumlar),
        "kasa_devir_listesi": kasa_devir_listesi,
        "kapanis_ozet_listesi": kapanis_ozet_listesi,
        "kasa_teslim_bugun_listesi": kasa_teslim_bugun_listesi,
        "kasa_uyumsuzluk_listesi": kasa_uyumsuzluk_listesi,
        "guvenlik_alarm_limitleri": _guvenlik_alarm_limitleri(),
        "tolerans": {
            "normal_tl": 50,
            "uyari_tl": 200,
            "aciklama": "Açılış kasa farkı: |fark|≤50 normal, <200 uyarı, ≥200 kritik.",
        },
    }


class KapanisGunDuzeltBody(BaseModel):
    sube_id: str
    yanlis_tarih: str   # event'in yanlış yazıldığı gün (YYYY-MM-DD)
    dogru_tarih: str    # cevap_ts'nin gerçek günü (YYYY-MM-DD)


@router.post("/kapanis-gun-duzelt")
def kapanis_gun_duzelt(body: KapanisGunDuzeltBody):
    """Yanlış güne düşmüş TAMAMLANMIŞ KAPANIS event'ini doğru güne taşır.

    GÜVENLİK: yalnızca event'in cevap_ts'si (TR) gerçekten `dogru_tarih`'e aitse
    taşır — yani kapanış fiziksel olarak o gün yapılmışsa. (Köyceğiz: 14'e yazılmış
    ama cevap_ts=15 → 15'e taşınır.) Doğru günde duran bayat bekliyor/gecikti
    KAPANIS placeholder'ı önce temizlenir. Rapor cache her iki gün için yenilenir.
    """
    sid = (body.sube_id or "").strip()
    yt = (body.yanlis_tarih or "").strip()
    dt_ = (body.dogru_tarih or "").strip()
    if not sid or not yt or not dt_:
        raise HTTPException(400, "sube_id, yanlis_tarih, dogru_tarih zorunlu")
    ev_id = None
    silinen = 0
    taslak_tasinan = 0
    ciro_tasinan = 0
    with db() as (conn, cur):
        # 1. Yanlış günde, cevap_ts'si DOĞRU güne ait tamamlanmış KAPANIS bul (kanıt)
        cur.execute(
            """
            SELECT id FROM sube_operasyon_event
            WHERE sube_id=%s AND tarih=%s::date AND tip='KAPANIS' AND durum='tamamlandi'
              AND (cevap_ts AT TIME ZONE 'Europe/Istanbul')::date = %s::date
            ORDER BY cevap_ts DESC NULLS LAST LIMIT 1
            """,
            (sid, yt, dt_),
        )
        row = cur.fetchone()
        if row:
            ev_id = dict(row)["id"]
            # Doğru günde duran bayat bekliyor/gecikti KAPANIS placeholder'ı sil
            cur.execute(
                """
                DELETE FROM sube_operasyon_event
                WHERE sube_id=%s AND tarih=%s::date AND tip='KAPANIS' AND sira_no=0
                  AND durum IN ('bekliyor','gecikti')
                """,
                (sid, dt_),
            )
            silinen = cur.rowcount
            cur.execute(
                "UPDATE sube_operasyon_event SET tarih=%s::date WHERE id=%s",
                (dt_, ev_id),
            )
            audit(cur, "sube_operasyon_event", ev_id, "KAPANIS_GUN_DUZELT")

        # 2. ciro_taslak — kapanışla aynı anda oluşan taslak da yanlış güne yazılmış
        #    olabilir. olusturma'sı doğru güne ait olan taslakları taşı (güvenlik).
        try:
            cur.execute("SAVEPOINT sp_taslak")
            cur.execute(
                """
                UPDATE ciro_taslak SET tarih=%s::date
                WHERE sube_id=%s AND tarih=%s::date
                  AND olusturma::date = %s::date
                """,
                (dt_, sid, yt, dt_),
            )
            taslak_tasinan = cur.rowcount
            cur.execute("RELEASE SAVEPOINT sp_taslak")
        except Exception:
            taslak_tasinan = 0
            try:
                cur.execute("ROLLBACK TO SAVEPOINT sp_taslak")
                cur.execute("RELEASE SAVEPOINT sp_taslak")
            except Exception:
                pass

        # 3. ciro (aktif/onaylı) — aynı mantık (genelde yok ama güvenlik için)
        try:
            cur.execute("SAVEPOINT sp_ciro")
            cur.execute(
                """
                UPDATE ciro SET tarih=%s::date
                WHERE sube_id=%s AND tarih=%s::date
                  AND olusturma::date = %s::date
                """,
                (dt_, sid, yt, dt_),
            )
            ciro_tasinan = cur.rowcount
            cur.execute("RELEASE SAVEPOINT sp_ciro")
        except Exception:
            ciro_tasinan = 0
            try:
                cur.execute("ROLLBACK TO SAVEPOINT sp_ciro")
                cur.execute("RELEASE SAVEPOINT sp_ciro")
            except Exception:
                pass

        if ev_id is None and taslak_tasinan == 0 and ciro_tasinan == 0:
            raise HTTPException(
                404,
                "Taşınacak kayıt bulunamadı (cevap_ts/olusturma dogru_tarih'e ait değil).",
            )

        # 4. Rapor cache her iki gün için yenile (best-effort)
        try:
            from rapor_cache import gunluk_ozet_yenile
            from datetime import date as _date
            gunluk_ozet_yenile(cur, sid, _date.fromisoformat(yt), kaynak='kapanis_gun_duzelt')
            gunluk_ozet_yenile(cur, sid, _date.fromisoformat(dt_), kaynak='kapanis_gun_duzelt')
        except Exception:
            pass
        conn.commit()
    return {
        "tasindi": True, "event_id": ev_id,
        "silinen_placeholder": silinen,
        "ciro_taslak_tasinan": taslak_tasinan,
        "ciro_tasinan": ciro_tasinan,
        "yanlis_tarih": yt, "dogru_tarih": dt_,
    }


@router.get("/kapanis-takip")
def kapanis_takip(tarih: Optional[str] = None):
    """
    Günlük kapanış takip: tüm aktif şubeler, kapanış + açılış durumu + ciro (nakit/pos/online).
    Onaylandi taslak bekliyor'a göre önceliklidir (aynı gün içinde).
    Tarih verilmezse varsayılan: iş günü (gece 02:00'e kadar önceki takvim günü) — tr_saat.is_gunu_tr.

    Ciro sütunları: kapanış varsa meta.x_rapor (şubenin X girişi); yoksa ciro/taslak.
    Online=nakit+POS çift kaydı tespit edilirse online=0 sayılır (toplam çift sayılmaz).

    Nakit denge (Δ): sabah_kasa + X_nakit − teslim − devir − ara_teslim − nakit anlık gider (aktif+onay_bekliyor).
    ≈0 beklenir; + kasa açığı, − kasa fazlası.

    Kapanış tutarları: aynı iş gününde birden fazla tamamlanmış KAPANIS kaydı olabilir (ör. vardiya ara adımı
    ile son operasyon kapanışı). MAX(teslim)/MAX(devir) karışımı yapılmaz; şube bazında ``cevap_ts`` en yeni
    olan tek satır kullanılır (_son_kapanis_event_row ile uyumlu).
    """
    from datetime import date as _date
    try:
        hedef = str(_date.fromisoformat(tarih)) if tarih else str(is_gunu_tr())
    except Exception:
        hedef = str(is_gunu_tr())

    with db() as (conn, cur):
        cur.execute("SELECT id::text, ad FROM subeler WHERE aktif=TRUE ORDER BY ad")
        subeler = [dict(r) for r in (cur.fetchall() or [])]

        # Kapanış eventleri — şube başına tek satır: en son tamamlanan (ara devir + son kapanış karışmaz)
        cur.execute(
            """
            SELECT DISTINCT ON (e.sube_id)
                   e.sube_id::text,
                   e.cevap_ts AT TIME ZONE 'Europe/Istanbul' AS kapanis_ts,
                   e.kasa_sayim,
                   e.devir,
                   e.teslim,
                   e.personel_ad,
                   e.snap_nakit,
                   e.snap_pos,
                   e.snap_online,
                   e.meta
            FROM sube_operasyon_event e
            WHERE e.tip = 'KAPANIS' AND e.durum = 'tamamlandi'
              AND e.tarih = %s
            ORDER BY e.sube_id, e.cevap_ts DESC NULLS LAST, e.id DESC
            """,
            (hedef,),
        )
        kapanis_map = {r["sube_id"]: dict(r) for r in (cur.fetchall() or [])}

        # Açılış — şube başına tek satır: o gün ilk tamamlanan ACILIS (MIN/MAX karışımı yok)
        cur.execute(
            """
            SELECT DISTINCT ON (e.sube_id)
                   e.sube_id::text,
                   e.cevap_ts AT TIME ZONE 'Europe/Istanbul' AS acilis_ts,
                   e.kasa_sayim AS acilis_kasa,
                   e.personel_ad
            FROM sube_operasyon_event e
            WHERE e.tip = 'ACILIS' AND e.durum = 'tamamlandi'
              AND e.tarih = %s
            ORDER BY e.sube_id, e.cevap_ts ASC NULLS LAST, e.id ASC
            """,
            (hedef,),
        )
        acilis_map = {r["sube_id"]: dict(r) for r in (cur.fetchall() or [])}

        # Nakit anlık giderler (aktif + merkez onayı bekleyen — gün içi görünürlük)
        cur.execute(
            """
            SELECT sube::text AS sube_id, COALESCE(SUM(tutar), 0)::float AS gider_nakit
            FROM anlik_giderler
            WHERE tarih = %s::date
              AND LOWER(COALESCE(NULLIF(TRIM(odeme_yontemi), ''), 'nakit')) = 'nakit'
              AND durum IN ('aktif', 'onay_bekliyor')
            GROUP BY sube
            """,
            (hedef,),
        )
        gider_map = {str(r["sube_id"]): float(r["gider_nakit"] or 0) for r in (cur.fetchall() or [])}

        # Gün içi ara kasa teslimleri (müdüre — kapanış formülünde düşülür)
        cur.execute(
            """
            SELECT sube_id::text, COALESCE(SUM(tutar), 0)::float AS ara_toplam
            FROM kasa_teslim
            WHERE tarih = %s::date AND teslim_turu = 'ara'
            GROUP BY sube_id
            """,
            (hedef,),
        )
        ara_teslim_map = {
            str(r["sube_id"]): float(r["ara_toplam"] or 0) for r in (cur.fetchall() or [])
        }

        # Ciro taslakları: onaylandi > bekliyor, en son olusturma
        cur.execute(
            """
            SELECT DISTINCT ON (t.sube_id)
                   t.sube_id::text, t.nakit, t.pos, t.online,
                   t.durum, t.olusturma, t.gonderen_ad
            FROM ciro_taslak t
            WHERE t.tarih = %s AND t.durum IN ('bekliyor', 'onaylandi')
            ORDER BY t.sube_id,
                     CASE t.durum WHEN 'onaylandi' THEN 0 ELSE 1 END,
                     t.olusturma DESC
            """,
            (hedef,),
        )
        taslak_map: dict = {}
        for r in (cur.fetchall() or []):
            taslak_map[str(r["sube_id"])] = dict(r)

        # Onaylı ciro — nakit/pos/online kesin tutar
        cur.execute(
            """
            SELECT c.sube_id::text,
                   c.toplam,
                   c.nakit, c.pos, c.online
            FROM ciro c
            WHERE c.tarih = %s AND c.durum = 'aktif'
            """,
            (hedef,),
        )
        ciro_map = {}
        for r in (cur.fetchall() or []):
            ciro_map[str(r["sube_id"])] = {
                "toplam": float(r["toplam"] or 0),
                "nakit":  float(r.get("nakit") or 0),
                "pos":    float(r.get("pos") or 0),
                "online": float(r.get("online") or 0),
            }

    satirlar = []
    for s in subeler:
        sid = s["id"]
        kap  = kapanis_map.get(sid, {})
        acil = acilis_map.get(sid, {})
        tas  = taslak_map.get(sid, {})
        ciro = ciro_map.get(sid)

        if ciro:
            ciro_tutar = float(ciro.get("toplam") or 0)
            nakit = float(ciro.get("nakit") or 0)
            pos = float(ciro.get("pos") or 0)
            online = float(ciro.get("online") or 0)
            ciro_kaynak = "ciro"
        else:
            ciro_tutar = 0.0
            nakit = float(tas.get("nakit") or 0)
            pos = float(tas.get("pos") or 0)
            online = float(tas.get("online") or 0)
            ciro_kaynak = "taslak" if tas else ""

        kts  = kap.get("kapanis_ts")
        ats  = acil.get("acilis_ts")
        tts  = tas.get("olusturma")

        sabah_kasa = float(acil.get("acilis_kasa") or 0) if acil else 0.0
        teslim_kasa = float(kap.get("teslim") or 0) if kap else 0.0
        devir_kalan = float(kap.get("devir") or 0) if kap else 0.0
        ara_teslim = float(ara_teslim_map.get(sid, 0.0) or 0.0)
        gider_nakit = float(gider_map.get(sid, 0.0) or 0.0)

        # Ciro sütunları: önce kapanış X (panel girişi); yoksa onaylı ciro / taslak
        xr_kap = _kapanis_x_rapor_from_event(kap if kap else None)
        if bool(kap) and xr_kap.get("nakit") is not None:
            nakit = float(xr_kap.get("nakit") or 0)
            pos = float(xr_kap.get("pos") or 0)
            online = float(xr_kap.get("online") or 0)
            ciro_kaynak = "kapanis_x"
        nakit, pos, online, ciro_tutar, online_cift_kayit = _ciro_kalemleri_sanitize(
            nakit, pos, online
        )

        nakit_delta_icin = float(nakit)

        nakit_denkleme_tam = bool(acil) and bool(kap)
        nakit_denkleme_kismi = False
        nakit_kasa_fark = None
        if nakit_denkleme_tam:
            nakit_kasa_fark = round(
                sabah_kasa + nakit_delta_icin - teslim_kasa - devir_kalan - gider_nakit - ara_teslim,
                2,
            )
        elif bool(acil) and (gider_nakit > 0.001 or nakit_delta_icin > 0.001 or ara_teslim > 0.001):
            nakit_kasa_fark = round(
                sabah_kasa + nakit_delta_icin - gider_nakit - ara_teslim,
                2,
            )
            nakit_denkleme_kismi = True

        satirlar.append({
            "sube_id":         sid,
            "sube_adi":        s["ad"],
            # Açılış
            "acildi":          bool(acil),
            "acilis_ts":       str(ats) if ats else "",
            "sabah_kasa_tl":   sabah_kasa,
            # Kapanış
            "kapanis_tamam":   bool(kap),
            "kapanis_ts":      str(kts) if kts else "",
            "kasa_sayim":      float(kap.get("kasa_sayim") or 0),
            "devir":           devir_kalan,
            "teslim_kasa_tl":  teslim_kasa,
            # 🔵 EVV-OPS3-B (2026-08-13): teslim_kasa 0'ı hem "gerçek 0 teslim" hem "teslim
            # kaydı YOK" için üretiyordu → ekran 0 TL'yi "bekliyor/—" gösteriyordu. Bu bayrak
            # teslim'in AÇIKÇA girildiğini söyler: 0 gerçekse frontend '0 ₺' (temiz) gösterir.
            "teslim_var":      (kap.get("teslim") is not None) if kap else False,
            "ara_teslim_tl":   ara_teslim,
            "kapanis_personel": str(kap.get("personel_ad") or ""),
            # Ciro taslak
            "taslak_var":      bool(tas),
            "taslak_durum":    str(tas.get("durum") or ""),
            "taslak_ts":       str(tts) if tts else "",
            "gonderen_ad":     str(tas.get("gonderen_ad") or ""),
            # Tutarlar
            "nakit":           nakit,
            "pos":             pos,
            "online":          online,
            "ciro_kaynak":     ciro_kaynak,
            "online_cift_kayit": online_cift_kayit,
            "ciro_onaylandi":  bool(ciro),
            "ciro_tutar":      ciro_tutar,
            "anlik_gider_nakit_tl": gider_nakit,
            "nakit_denkleme_tam": nakit_denkleme_tam,
            "nakit_denkleme_kismi": nakit_denkleme_kismi,
            "nakit_kasa_fark_tl": nakit_kasa_fark,
        })

    return {
        "tarih":                hedef,
        "is_gunu_tr":           str(is_gunu_tr()),
        "takvim_tr":            str(bugun_tr()),
        "kapanis_son_teslim_saat": int(KAPANIS_SON_TESLIM_ERTESI_GUN_SAAT),
        "satirlar":             satirlar,
        "sube_sayisi":          len(satirlar),
        "kapanis_yapan_adet":   sum(1 for r in satirlar if r["kapanis_tamam"]),
        "ciro_onaylanan_adet":  sum(1 for r in satirlar if r["ciro_onaylandi"]),
        "taslak_bekleyen_adet": sum(1 for r in satirlar if r["taslak_var"] and r["taslak_durum"] == "bekliyor"),
        "eksik_kapanis_adet":   sum(1 for r in satirlar if not r["kapanis_tamam"]),
        "eksik_ciro_adet":      sum(1 for r in satirlar if not r["ciro_onaylandi"] and not r["taslak_var"]),
    }


@router.get("/acilis-kasa-takip")
def acilis_kasa_takip(tarih: Optional[str] = None):
    """
    Şube panelinden gelen açılış kasası — günlük merkez takip.
    Kaynak: sube_operasyon_event ACILIS (kasa_sayim) + dün KAPANIS devir karşılaştırması.
    """
    import json as _json
    from datetime import date as _date, timedelta
    from operasyon_kurallar import tolerans_seviyesi

    try:
        hedef = str(_date.fromisoformat(tarih)) if tarih else str(is_gunu_tr())
    except Exception:
        hedef = str(is_gunu_tr())

    dunku = str(_date.fromisoformat(hedef) - timedelta(days=1))

    with db() as (_, cur):
        cur.execute("SELECT id::text, ad FROM subeler WHERE aktif=TRUE ORDER BY ad")
        subeler = [dict(r) for r in (cur.fetchall() or [])]

        cur.execute(
            """
            SELECT DISTINCT ON (e.sube_id)
                   e.sube_id::text,
                   e.durum,
                   e.cevap_ts AT TIME ZONE 'Europe/Istanbul' AS acilis_ts,
                   e.personel_saat,
                   e.kasa_sayim AS acilis_kasa,
                   e.personel_id::text,
                   e.personel_ad,
                   e.meta,
                   e.sistem_slot_ts AT TIME ZONE 'Europe/Istanbul' AS sistem_slot_ts
            FROM sube_operasyon_event e
            WHERE e.tip = 'ACILIS' AND e.tarih = %s
            ORDER BY e.sube_id,
                     CASE e.durum WHEN 'tamamlandi' THEN 0 ELSE 1 END,
                     e.cevap_ts DESC NULLS LAST, e.id DESC
            """,
            (hedef,),
        )
        acilis_map = {r["sube_id"]: dict(r) for r in (cur.fetchall() or [])}

        cur.execute(
            """
            SELECT DISTINCT ON (e.sube_id)
                   e.sube_id::text,
                   COALESCE(
                       e.devir,
                       GREATEST(0, COALESCE(e.kasa_sayim, 0) - COALESCE(e.teslim, 0))
                   ) AS beklenen_devir,
                   e.personel_ad AS kapanis_personel_ad
            FROM sube_operasyon_event e
            WHERE e.tip = 'KAPANIS' AND e.durum = 'tamamlandi'
              AND e.tarih = %s
            ORDER BY e.sube_id, e.cevap_ts DESC NULLS LAST, e.id DESC
            """,
            (dunku,),
        )
        kap_map = {r["sube_id"]: dict(r) for r in (cur.fetchall() or [])}

        cur.execute(
            """
            SELECT u.id::text, u.sube_id::text, u.fark_tl, u.beklenen_tl, u.gercek_tl,
                   u.seviye, u.okundu, u.acilis_personel_ad, u.kapanis_personel_ad
            FROM sube_operasyon_uyari u
            WHERE u.tip = 'ACILIS_KASA_FARK' AND u.tarih = %s
            """,
            (hedef,),
        )
        uyum_map = {str(r["sube_id"]): dict(r) for r in (cur.fetchall() or [])}

    satirlar = []
    for s in subeler:
        sid = s["id"]
        acil = acilis_map.get(sid, {})
        kap = kap_map.get(sid, {})
        uyum = uyum_map.get(sid)

        durum = str(acil.get("durum") or "").strip().lower()
        tamam = durum == "tamamlandi"
        ats = acil.get("acilis_ts")

        bek = kap.get("beklenen_devir")
        if bek is not None:
            bek = float(bek)
        elif uyum and uyum.get("beklenen_tl") is not None:
            bek = float(uyum["beklenen_tl"])

        acilis_kasa = float(acil.get("acilis_kasa") or 0) if tamam else None
        if acilis_kasa is None and uyum and uyum.get("gercek_tl") is not None:
            acilis_kasa = float(uyum["gercek_tl"])

        fark = None
        fark_seviye = None
        if acilis_kasa is not None and bek is not None:
            fark = round(acilis_kasa - bek, 2)
            fark_seviye = tolerans_seviyesi(fark)
        elif uyum and uyum.get("fark_tl") is not None:
            fark = round(float(uyum["fark_tl"]), 2)
            fark_seviye = str(uyum.get("seviye") or tolerans_seviyesi(fark))

        panel_acilis = False
        meta_raw = acil.get("meta")
        if meta_raw:
            try:
                meta = _json.loads(meta_raw) if isinstance(meta_raw, str) else meta_raw
                panel_acilis = bool(meta.get("panel_acilis_tr_ts") or meta.get("acilis_stok_sayim"))
            except Exception:
                panel_acilis = False

        satirlar.append({
            "sube_id": sid,
            "sube_adi": s["ad"],
            "acilis_durum": durum or ("yok" if not acil else "bekliyor"),
            "acilis_tamam": tamam,
            "acilis_ts": str(ats) if ats else "",
            "personel_saat": str(acil.get("personel_saat") or ""),
            "personel_ad": str(acil.get("personel_ad") or (uyum or {}).get("acilis_personel_ad") or ""),
            "panel_acilis": panel_acilis,
            "acilis_kasa_tl": acilis_kasa,
            "beklenen_devir_tl": bek,
            "dunku_kapanis_tarih": dunku,
            "dunku_kapanis_personel": str(
                kap.get("kapanis_personel_ad") or (uyum or {}).get("kapanis_personel_ad") or ""
            ),
            "fark_tl": fark,
            "fark_seviye": fark_seviye,
            "uyumsuzluk_id": str(uyum["id"]) if uyum else None,
            "uyumsuzluk_cozuldu": bool(uyum.get("okundu")) if uyum else False,
            "uyumsuzluk_bekliyor": bool(uyum and not uyum.get("okundu")),
        })

    satirlar.sort(
        key=lambda r: (
            0 if not r["acilis_tamam"] else (1 if r.get("uyumsuzluk_bekliyor") else 2),
            -abs(float(r.get("fark_tl") or 0)),
            (r.get("sube_adi") or "").lower(),
        )
    )

    acilis_yapan = sum(1 for r in satirlar if r["acilis_tamam"])
    fark_uyari = sum(
        1 for r in satirlar
        if r.get("fark_seviye") in ("uyari", "kritik") and abs(float(r.get("fark_tl") or 0)) > 0.01
    )

    return {
        "tarih": hedef,
        "is_gunu_tr": str(is_gunu_tr()),
        "takvim_tr": str(bugun_tr()),
        "dunku_kapanis_tarih": dunku,
        "satirlar": satirlar,
        "sube_sayisi": len(satirlar),
        "acilis_yapan_adet": acilis_yapan,
        "acilis_bekleyen_adet": len(satirlar) - acilis_yapan,
        "fark_uyari_adet": fark_uyari,
        "uyumsuzluk_bekleyen_adet": sum(1 for r in satirlar if r.get("uyumsuzluk_bekliyor")),
    }


@router.get("/haftalik-karsilastirma")
def ops_haftalik_karsilastirma():
    """
    Son 7 gün (bu hafta) vs önceki 7 gün: şube bazında ciro karşılaştırması + sıralama.
    generate_series ile boş günler 0 olarak doldurulur — her zaman 14 satır/şube.
    """
    from collections import defaultdict

    with db() as (conn, cur):
        cur.execute(
            """
            SELECT
                s.id::text   AS sube_id,
                s.ad         AS sube_adi,
                gs.dt::text  AS tarih,
                COALESCE(SUM(c.toplam), 0)::float AS ciro
            FROM subeler s
            CROSS JOIN (
                SELECT generate_series(
                    CURRENT_DATE - INTERVAL '13 days',
                    CURRENT_DATE,
                    INTERVAL '1 day'
                )::date AS dt
            ) gs
            LEFT JOIN ciro c
                   ON c.tarih::date = gs.dt
                  AND c.sube_id = s.id
                  AND c.durum = 'aktif'
            WHERE s.aktif = TRUE
            GROUP BY s.id, s.ad, gs.dt
            ORDER BY s.ad, gs.dt ASC
            """
        )
        rows = cur.fetchall()

    branch_days: dict = defaultdict(lambda: {"sube_id": None, "sube_adi": None, "gunler": []})
    for r in rows:
        sid = str(r["sube_id"])
        bd = branch_days[sid]
        bd["sube_id"] = sid
        bd["sube_adi"] = r["sube_adi"]
        bd["gunler"].append({"tarih": r["tarih"], "ciro": float(r["ciro"])})

    result: List[dict] = []
    for sid, bd in branch_days.items():
        gunler = bd["gunler"]  # 14 gün ASC sıralı
        prev7 = gunler[:7]     # 14 gün önce — 8 gün önce
        this7 = gunler[7:]     # 7 gün önce — bugün
        prev_total = round(sum(g["ciro"] for g in prev7), 2)
        this_total = round(sum(g["ciro"] for g in this7), 2)
        degisim_pct = round((this_total - prev_total) / prev_total * 100, 1) if prev_total > 0 else None
        result.append({
            "sube_id":      sid,
            "sube_adi":     bd["sube_adi"],
            "bu_hafta":     this_total,
            "gecen_hafta":  prev_total,
            "degisim_pct":  degisim_pct,
            "trend":        this7,   # son 7 gün sparkline [{tarih, ciro}]
        })

    result.sort(key=lambda x: x["bu_hafta"], reverse=True)
    for i, r in enumerate(result):
        r["sira"] = i + 1

    # Tüm şubelerin günlük toplamı (genel sağlık sparkline)
    daily_map: dict = defaultdict(float)
    for bd in branch_days.values():
        for g in bd["gunler"][7:]:  # sadece son 7 gün
            daily_map[g["tarih"]] += g["ciro"]
    genel_trend = sorted(
        [{"tarih": t, "ciro": round(c, 2)} for t, c in daily_map.items()],
        key=lambda x: x["tarih"],
    )

    toplam_bu_hafta    = round(sum(r["bu_hafta"]   for r in result), 2)
    toplam_gecen_hafta = round(sum(r["gecen_hafta"] for r in result), 2)
    genel_degisim_pct  = round(
        (toplam_bu_hafta - toplam_gecen_hafta) / toplam_gecen_hafta * 100, 1
    ) if toplam_gecen_hafta > 0 else None

    return {
        "subeler":             result,
        "genel_trend":         genel_trend,
        "toplam_bu_hafta":     toplam_bu_hafta,
        "toplam_gecen_hafta":  toplam_gecen_hafta,
        "genel_degisim_pct":   genel_degisim_pct,
    }


@router.get("/kontrol-ozet")
def ops_kontrol_ozet(
    sube_id: Optional[str] = None,
    sadece_alarmlar: bool = False,
    kategori: Optional[str] = None,
):
    """
    Merkezi kontrol motoru.
    Tüm kontrolleri tek endpoint'te döner.
    """
    bugun = str(bugun_tr())
    sid = (sube_id or "").strip() or None
    kat = (kategori or "").strip().upper() or None
    if sid:
        with db() as (conn, cur):
            cur.execute(
                "SELECT * FROM subeler WHERE id=%s AND aktif=TRUE",
                (sid,),
            )
            sube = cur.fetchone()
            if not sube:
                raise HTTPException(404, "Şube bulunamadı")
            ozet = sube_kontrol_calistir(cur, sid, dict(sube), kategori=kat)
        return {"tarih": bugun, **ozet}

    sonuclar = tum_subeler_kontrol(sadece_alarmlar=sadece_alarmlar, kategori=kat)
    return {
        "tarih": bugun,
        "sube_sayisi": len(sonuclar),
        "kritik_toplam": sum(s["kritik_adet"] for s in sonuclar),
        "uyari_toplam": sum(s["uyari_adet"] for s in sonuclar),
        "temiz_sube": sum(1 for s in sonuclar if s["temiz"]),
        "subeler": sonuclar,
    }


@router.get("/motor-analitik-olay")
def ops_motor_analitik_olay(olay_tipi: Optional[str] = None, limit: int = 80):
    """Motor analitik append-only akışı (merkez incelemesi)."""
    lim = max(1, min(int(limit or 80), 300))
    ot = (olay_tipi or "").strip()
    with db() as (conn, cur):
        if ot:
            cur.execute(
                """
                SELECT id, olay_tipi, sube_id, tutar_yok_bilgi, payload_json, hesap_surumu, kaynak, olusturma
                FROM motor_analitik_olay
                WHERE olay_tipi = %s
                ORDER BY olusturma DESC
                LIMIT %s
                """,
                (ot, lim),
            )
        else:
            cur.execute(
                """
                SELECT id, olay_tipi, sube_id, tutar_yok_bilgi, payload_json, hesap_surumu, kaynak, olusturma
                FROM motor_analitik_olay
                ORDER BY olusturma DESC
                LIMIT %s
                """,
                (lim,),
            )
        satirlar = []
        for r in cur.fetchall():
            d = dict(r)
            if d.get("olusturma"):
                d["olusturma"] = str(d["olusturma"])
            satirlar.append(d)
    return {"satirlar": satirlar}


@router.get("/gider-fis-bekleyen")
def ops_gider_fis_bekleyen(gun: int = 14, sube_id: Optional[str] = None):
    gun_sayi = max(1, min(60, int(gun or 14)))
    sid = (sube_id or "").strip() or None
    with db() as (conn, cur):
        qp: List[Any] = [gun_sayi]
        q = """
            SELECT
                g.id, g.tarih, g.kategori, g.tutar, g.aciklama, g.sube,
                s.ad AS sube_adi,
                g.personel_id,
                COALESCE(p.ad_soyad, u.ad, g.personel_id) AS personel_ad,
                COALESCE(g.fis_gonderildi, FALSE) AS fis_gonderildi,
                COALESCE(NULLIF(TRIM(g.fis_kontrol_durumu), ''), 'bekliyor') AS fis_kontrol_durumu,
                g.fis_kontrol_tarihi,
                g.fis_kontrol_notu,
                g.olusturma,
                (CURRENT_DATE - g.tarih)::int AS gecikme_gun
            FROM anlik_giderler g
            LEFT JOIN subeler s ON s.id = g.sube
            LEFT JOIN personel p ON p.id = g.personel_id
            LEFT JOIN sube_panel_kullanici u ON u.id = g.personel_id
            WHERE g.tarih >= (CURRENT_DATE - (%s * INTERVAL '1 day'))
              AND COALESCE(NULLIF(TRIM(g.fis_kontrol_durumu), ''), 'bekliyor') = 'bekliyor'
              AND COALESCE(g.fis_gonderildi, FALSE) = FALSE
        """
        if sid:
            q += " AND g.sube=%s"
            qp.append(sid)
        q += " ORDER BY g.tarih ASC, g.olusturma ASC NULLS LAST, g.id LIMIT 400"
        cur.execute(q, tuple(qp))
        rows: List[Dict[str, Any]] = []
        for r in cur.fetchall():
            d = dict(r)
            if d.get("tarih"):
                d["tarih"] = str(d["tarih"])
            if d.get("olusturma"):
                d["olusturma"] = str(d["olusturma"])
            if d.get("tutar") is not None:
                d["tutar"] = float(d["tutar"])
            d["fis_gonderildi"] = bool(d.get("fis_gonderildi"))
            if d.get("fis_kontrol_tarihi"):
                d["fis_kontrol_tarihi"] = str(d["fis_kontrol_tarihi"])
            gecikme = int(d.get("gecikme_gun") or 0)
            d["gecikme_gun"] = gecikme
            d["oncelik"] = "kritik" if gecikme >= 5 else ("uyari" if gecikme >= 2 else "normal")
            rows.append(d)
        # Şube bazlı özet
        from collections import defaultdict as _dd
        ozet: Dict[str, Any] = _dd(lambda: {"sube_adi": "", "toplam": 0, "kritik": 0, "tutar_toplam": 0.0})
        for r in rows:
            sk = r.get("sube") or ""
            ozet[sk]["sube_adi"] = r.get("sube_adi") or sk
            ozet[sk]["toplam"] += 1
            if r.get("oncelik") == "kritik":
                ozet[sk]["kritik"] += 1
            ozet[sk]["tutar_toplam"] = round(ozet[sk]["tutar_toplam"] + float(r.get("tutar") or 0), 2)
    return {
        "gun_sayi": gun_sayi,
        "sube_id": sid,
        "satirlar": rows,
        "sube_ozet": [{"sube_id": k, **v} for k, v in ozet.items()],
        "toplam": len(rows),
        "kritik_adet": sum(1 for r in rows if r.get("oncelik") == "kritik"),
    }


@router.post("/gider-fis-kontrol")
def ops_gider_fis_kontrol(body: OpsGiderFisKontrolBody):
    gid = (body.gider_id or "").strip()
    durum = (body.durum or "").strip().lower()
    notu = (body.notu or "").strip() or None
    if not gid:
        raise HTTPException(400, "gider_id zorunlu")
    if durum not in ("geldi", "gelmedi", "muaf"):
        raise HTTPException(400, "durum: geldi | gelmedi | muaf")
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT id, sube, tarih, kategori, tutar, personel_id, fis_gonderildi, fis_kontrol_durumu
            FROM anlik_giderler
            WHERE id=%s
            FOR UPDATE
            """,
            (gid,),
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Gider bulunamadı")
        g = dict(row)
        cur.execute(
            """
            UPDATE anlik_giderler
            SET fis_kontrol_durumu=%s,
                fis_kontrol_tarihi=NOW(),
                fis_kontrol_notu=%s
            WHERE id=%s
            """,
            (durum, notu, gid),
        )
        audit(cur, "anlik_giderler", gid, f"OPS_FIS_KONTROL_{durum.upper()}")

        if durum == "gelmedi":
            sid = str(g.get("sube") or "")
            pid = str(g.get("personel_id") or "").strip()
            tg = str(g.get("tarih") or bugun_tr())
            depoda_var = _depoda_var_miydi(cur, sid, tg) if sid else False
            sinyal_turu = "DEPODA_VAR_FIS_YOK" if depoda_var else "FIS_EKSIK_DUSUK_RISK"
            agirlik = 10 if depoda_var else 4
            acik = (
                f"Fiş gelmedi — gider={gid} kategori={g.get('kategori')} tutar={float(g.get('tutar') or 0):.0f} TL"
                + (" (depoda hareket var)" if depoda_var else "")
            )
            cur.execute(
                """
                INSERT INTO personel_risk_sinyal
                    (id, personel_id, sube_id, tarih, sinyal_turu, agirlik, aciklama, referans_id)
                VALUES (%s, %s, %s, %s::date, %s, %s, %s, %s)
                """,
                (str(uuid.uuid4()), pid or "—", sid or None, tg, sinyal_turu, int(agirlik), (acik + (f" · not={notu}" if notu else ""))[:1800], gid),
            )
            if pid:
                kontrol_personel_risk_profili(cur, pid, gun=30)
    return {"success": True, "gider_id": gid, "durum": durum}


@router.get("/defter")
def ops_defter(
    sube_id: Optional[str] = None,
    limit: int = 300,
    year_month: Optional[str] = None,
    gun: Optional[str] = None,
    zincir_dogrula: bool = False,
):
    lim = max(10, min(800, int(limit)))
    ym = _coerce_year_month(year_month)
    gun_v = (gun or "").strip()
    zincir_ozet: Optional[Dict[str, Any]] = None
    with db() as (conn, cur):
        if sube_id:
            cur.execute(
                """
                SELECT d.id, d.sube_id, s.ad AS sube_adi, d.tarih, d.olay_ts, d.etiket, d.aciklama, d.ref_event_id,
                       d.personel_id, d.personel_ad, d.bildirim_saati, d.imza_hmac,
                       d.defter_onceki_id, d.defter_zincir_hmac
                FROM operasyon_defter d
                LEFT JOIN subeler s ON s.id = d.sube_id
                WHERE d.sube_id=%s
                  AND to_char(d.tarih, 'YYYY-MM') = %s
                  AND (NULLIF(%s, '') IS NULL OR d.tarih = NULLIF(%s, '')::date)
                ORDER BY d.olay_ts DESC
                LIMIT %s
                """,
                (sube_id, ym, gun_v, gun_v, lim),
            )
        else:
            cur.execute(
                """
                SELECT d.id, d.sube_id, s.ad AS sube_adi, d.tarih, d.olay_ts, d.etiket, d.aciklama, d.ref_event_id,
                       d.personel_id, d.personel_ad, d.bildirim_saati, d.imza_hmac,
                       d.defter_onceki_id, d.defter_zincir_hmac
                FROM operasyon_defter d
                JOIN subeler s ON s.id = d.sube_id
                WHERE to_char(d.tarih, 'YYYY-MM') = %s
                  AND (NULLIF(%s, '') IS NULL OR d.tarih = NULLIF(%s, '')::date)
                ORDER BY d.olay_ts DESC
                LIMIT %s
                """,
                (ym, gun_v, gun_v, lim),
            )
        rows = [dict(x) for x in cur.fetchall()]
        for d in rows:
            d["imza_gecerli"] = operasyon_defter_satir_imza_gecerli(d)
            if d.get("olay_ts"):
                d["olay_ts"] = str(d["olay_ts"])
            if d.get("tarih"):
                d["tarih"] = str(d["tarih"])

        if zincir_dogrula and sube_id:
            cur.execute(
                """
                SELECT id, imza_hmac, defter_zincir_hmac, olay_ts
                FROM operasyon_defter
                WHERE sube_id=%s
                  AND to_char(tarih, 'YYYY-MM') = %s
                  AND (NULLIF(%s, '') IS NULL OR tarih = NULLIF(%s, '')::date)
                ORDER BY olay_ts ASC NULLS LAST, id ASC
                """,
                (sube_id, ym, gun_v, gun_v),
            )
            chrono = [dict(x) for x in cur.fetchall()]
            zincir_ozet = operasyon_defter_zincir_satirlari_dogrula(chrono)

    out: Dict[str, Any] = {
        "satirlar": rows,
        "limit": lim,
        "year_month": ym,
        "gun": gun_v or None,
    }
    if zincir_dogrula:
        out["zincir_dogrula"] = zincir_ozet
    return out


@router.get("/defter-guvenlik-ozet")
def ops_defter_guvenlik_ozet(year_month: Optional[str] = None):
    """
    Şube bazlı: seçilen ayda defter satır sayısı, imzasız / imza geçersiz sayıları,
    kronolojik zincir doğrulaması (Faz 2).
    """
    ym = _coerce_year_month(year_month)
    with db() as (conn, cur):
        cur.execute("SELECT id, ad FROM subeler WHERE aktif=TRUE ORDER BY ad")
        subeler = cur.fetchall()
        sube_map = {str(s["id"]): s.get("ad") for s in subeler}

        # Tek sorguda tüm şubelerin o ayki defter satırları — N+1 önleme
        cur.execute(
            """
            SELECT id, sube_id, tarih, olay_ts, etiket, aciklama, ref_event_id,
                   personel_id, personel_ad, bildirim_saati, imza_hmac,
                   defter_onceki_id, defter_zincir_hmac
            FROM operasyon_defter
            WHERE to_char(tarih, 'YYYY-MM') = %s
            ORDER BY sube_id, olay_ts ASC NULLS LAST, id ASC
            """,
            (ym,),
        )
        tum_satirlar: Dict[str, List[dict]] = {sid: [] for sid in sube_map}
        for row in cur.fetchall():
            sid = str(row["sube_id"])
            if sid in tum_satirlar:
                tum_satirlar[sid].append(dict(row))

        sube_satirlar: List[dict] = []
        for sid, sube_adi in sube_map.items():
            rows = tum_satirlar.get(sid, [])
            imzasiz = sum(1 for r in rows if not (str(r.get("imza_hmac") or "").strip()))
            imza_gecersiz = 0
            for r in rows:
                v = operasyon_defter_satir_imza_gecerli(r)
                if v is False:
                    imza_gecersiz += 1
            zincir = (
                operasyon_defter_zincir_satirlari_dogrula(rows)
                if rows
                else {"gecerli": True, "incelenen_zincir_satir": 0}
            )
            sube_satirlar.append(
                {
                    "sube_id": sid,
                    "sube_adi": sube_adi,
                    "ay_satir": len(rows),
                    "imzasiz_satir": imzasiz,
                    "imza_gecersiz_satir": imza_gecersiz,
                    "zincir_ay": zincir,
                }
            )
    return {"year_month": ym, "subeler": sube_satirlar}


