@router.get("/guvenlik-ozet")
def ops_guvenlik_ozet(
    sube_id: Optional[str] = None,
    year_month: Optional[str] = None,
    gun: Optional[str] = None,
):
    """Faz 5: güvenlik olaylarını tip bazında özetler."""
    ym = _coerce_year_month(year_month)
    gun_v = (gun or "").strip()
    sube_v = (sube_id or "").strip()
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT tip, COUNT(*)::int AS adet, MAX(olay_ts) AS son_olay_ts
            FROM operasyon_guvenlik_olay
            WHERE to_char(olay_ts::date, 'YYYY-MM') = %s
              AND (NULLIF(%s, '') IS NULL OR olay_ts::date = NULLIF(%s, '')::date)
              AND (NULLIF(%s, '') IS NULL OR sube_id = NULLIF(%s, ''))
            GROUP BY tip
            ORDER BY adet DESC, tip
            """,
            (ym, gun_v, gun_v, sube_v, sube_v),
        )
        tipler = [dict(x) for x in cur.fetchall()]
    toplam = 0
    for t in tipler:
        t["adet"] = int(t.get("adet") or 0)
        toplam += t["adet"]
        if t.get("son_olay_ts"):
            t["son_olay_ts"] = str(t["son_olay_ts"])
    return {
        "year_month": ym,
        "gun": gun_v or None,
        "sube_id": sube_v or None,
        "toplam_olay": toplam,
        "tipler": tipler,
    }


@router.get("/guvenlik-alarmlar")
def ops_guvenlik_alarmlar():
    """
    Faz 6: aktif şube güvenlik alarmları (kısa pencere + eşik).
    Eşikler env:
      EVVEL_GUV_ALARM_DK (varsayılan 15)
      EVVEL_GUV_ALARM_PIN_KILIT (varsayılan 2)
      EVVEL_GUV_ALARM_PIN_HATALI (varsayılan 8)
    """
    lim = _guvenlik_alarm_limitleri()
    with db() as (conn, cur):
        cur.execute("SELECT id, ad FROM subeler WHERE aktif=TRUE ORDER BY ad")
        subeler = [dict(x) for x in cur.fetchall()]

        # Süresi dolan susturmaları toplu temizle
        cur.execute(
            """
            DELETE FROM operasyon_guvenlik_alarm_durum
            WHERE durum='susturuldu'
              AND sustur_bitis_ts IS NOT NULL
              AND sustur_bitis_ts <= NOW()
            """
        )

        # Tek sorguda tüm şubelerin alarm istatistikleri — N+1 önleme
        cur.execute(
            """
            SELECT
              sube_id,
              COUNT(*) FILTER (WHERE tip='PIN_KILIT')::int      AS pin_kilit_adet,
              COUNT(*) FILTER (WHERE tip='PIN_HATALI')::int     AS pin_hatali_adet,
              COUNT(*) FILTER (WHERE tip='PIN_KILITTE_DENEME')::int AS pin_kilitte_deneme_adet,
              MAX(olay_ts) AS son_olay_ts
            FROM operasyon_guvenlik_olay
            WHERE olay_ts >= NOW() - (%s * INTERVAL '1 minute')
            GROUP BY sube_id
            """,
            (lim["pencere_dk"],),
        )
        alarm_istatistik: Dict[str, dict] = {
            str(r["sube_id"]): dict(r) for r in cur.fetchall()
        }

        # Tek sorguda tüm alarm durum kayıtları
        cur.execute(
            """
            SELECT sube_id, durum, islem_ts, islem_personel_id, islem_notu, sustur_bitis_ts
            FROM operasyon_guvenlik_alarm_durum
            """
        )
        alarm_durum_map: Dict[str, dict] = {
            str(r["sube_id"]): dict(r) for r in cur.fetchall()
        }

        alarmlar: List[dict] = []
        for s in subeler:
            sid = str(s["id"])
            ist = alarm_istatistik.get(sid, {})
            pin_kilit = int(ist.get("pin_kilit_adet") or 0)
            pin_hatali = int(ist.get("pin_hatali_adet") or 0)
            pin_kilitte_deneme = int(ist.get("pin_kilitte_deneme_adet") or 0)
            alarm = pin_kilit >= lim["pin_kilit_esik"] or pin_hatali >= lim["pin_hatali_esik"]
            if not alarm:
                continue
            seviye = "kritik" if pin_kilit >= lim["pin_kilit_esik"] else "uyari"
            mesaj = None
            if pin_kilit >= lim["pin_kilit_esik"]:
                mesaj = f"PIN_KILIT son {lim['pencere_dk']} dk: {pin_kilit} (eşik {lim['pin_kilit_esik']})"
            elif pin_hatali >= lim["pin_hatali_esik"]:
                mesaj = f"PIN_HATALI son {lim['pencere_dk']} dk: {pin_hatali} (eşik {lim['pin_hatali_esik']})"
            ozet = {
                "pencere_dk": lim["pencere_dk"],
                "pin_kilit_adet": pin_kilit,
                "pin_hatali_adet": pin_hatali,
                "pin_kilitte_deneme_adet": pin_kilitte_deneme,
                "alarm": alarm,
                "seviye": seviye,
                "mesaj": mesaj,
            }
            if ist.get("son_olay_ts"):
                ozet["son_olay_ts"] = str(ist["son_olay_ts"])
            alarm_durum = alarm_durum_map.get(sid)
            sustur_aktif = bool(alarm_durum and alarm_durum.get("durum") == "susturuldu")
            alarmlar.append(
                {
                    "sube_id": sid,
                    "sube_adi": s.get("ad"),
                    "seviye": seviye,
                    "mesaj": mesaj,
                    "alarm_durum": alarm_durum,
                    "susturuldu": sustur_aktif,
                    "detay": ozet,
                }
            )
    aktif_alarmlar = [a for a in alarmlar if not a.get("susturuldu")]
    return {
        "limitler": lim,
        "alarm_sayisi": len(aktif_alarmlar),
        "toplam_alarm_kaydi": len(alarmlar),
        "alarmlar": alarmlar,
    }


@router.post("/guvenlik-alarmlar/{sube_id}/okundu")
def ops_guvenlik_alarm_okundu(sube_id: str, body: GuvenlikAlarmIslemBody = GuvenlikAlarmIslemBody()):
    with db() as (conn, cur):
        _sube_getir(cur, sube_id)
        cur.execute(
            """
            INSERT INTO operasyon_guvenlik_alarm_durum
                (sube_id, durum, islem_ts, islem_personel_id, islem_notu, sustur_bitis_ts)
            VALUES (%s, 'okundu', NOW(), %s, %s, NULL)
            ON CONFLICT (sube_id) DO UPDATE SET
                durum='okundu',
                islem_ts=NOW(),
                islem_personel_id=EXCLUDED.islem_personel_id,
                islem_notu=EXCLUDED.islem_notu,
                sustur_bitis_ts=NULL
            """,
            (
                sube_id,
                (body.personel_id or "").strip() or None,
                (body.notu or "").strip()[:300] or None,
            ),
        )
        durum = _alarm_durum_get(cur, sube_id)
    return {"success": True, "sube_id": sube_id, "alarm_durum": durum}


@router.post("/guvenlik-alarmlar/{sube_id}/sustur")
def ops_guvenlik_alarm_sustur(sube_id: str, body: GuvenlikAlarmIslemBody = GuvenlikAlarmIslemBody()):
    sustur_dk = max(5, min(int(body.sustur_dk or 120), 24 * 60))
    with db() as (conn, cur):
        _sube_getir(cur, sube_id)
        cur.execute(
            """
            INSERT INTO operasyon_guvenlik_alarm_durum
                (sube_id, durum, islem_ts, islem_personel_id, islem_notu, sustur_bitis_ts)
            VALUES (%s, 'susturuldu', NOW(), %s, %s, NOW() + (%s * INTERVAL '1 minute'))
            ON CONFLICT (sube_id) DO UPDATE SET
                durum='susturuldu',
                islem_ts=NOW(),
                islem_personel_id=EXCLUDED.islem_personel_id,
                islem_notu=EXCLUDED.islem_notu,
                sustur_bitis_ts=EXCLUDED.sustur_bitis_ts
            """,
            (
                sube_id,
                (body.personel_id or "").strip() or None,
                (body.notu or "").strip()[:300] or None,
                sustur_dk,
            ),
        )
        durum = _alarm_durum_get(cur, sube_id)
    return {"success": True, "sube_id": sube_id, "sustur_dk": sustur_dk, "alarm_durum": durum}


@router.get("/defter-export")
def ops_defter_export(
    year_month: Optional[str] = None,
    sube_id: Optional[str] = None,
    gun: Optional[str] = None,
):
    """Seçilen dönem için operasyon defteri CSV (UTF-8, Excel uyumu için BOM)."""
    ym = _coerce_year_month(year_month)
    gun_v = (gun or "").strip()
    max_rows = 25000
    with db() as (conn, cur):
        if sube_id:
            cur.execute(
                """
                SELECT id, sube_id, tarih, olay_ts, etiket, aciklama, ref_event_id,
                       personel_id, personel_ad, bildirim_saati, imza_hmac,
                       defter_onceki_id, defter_zincir_hmac
                FROM operasyon_defter
                WHERE sube_id=%s
                  AND to_char(tarih, 'YYYY-MM') = %s
                  AND (NULLIF(%s, '') IS NULL OR tarih = NULLIF(%s, '')::date)
                ORDER BY olay_ts ASC NULLS LAST, id ASC
                LIMIT %s
                """,
                (sube_id, ym, gun_v, gun_v, max_rows),
            )
        else:
            cur.execute(
                """
                SELECT id, sube_id, tarih, olay_ts, etiket, aciklama, ref_event_id,
                       personel_id, personel_ad, bildirim_saati, imza_hmac,
                       defter_onceki_id, defter_zincir_hmac
                FROM operasyon_defter
                WHERE to_char(tarih, 'YYYY-MM') = %s
                  AND (NULLIF(%s, '') IS NULL OR tarih = NULLIF(%s, '')::date)
                ORDER BY olay_ts ASC NULLS LAST, id ASC
                LIMIT %s
                """,
                (ym, gun_v, gun_v, max_rows),
            )
        raw_rows = [dict(x) for x in cur.fetchall()]

    buf = io.StringIO()
    buf.write("\ufeff")
    w = csv.writer(buf)
    w.writerow(
        [
            "id",
            "sube_id",
            "tarih",
            "olay_ts",
            "etiket",
            "aciklama",
            "ref_event_id",
            "personel_id",
            "personel_ad",
            "bildirim_saati",
            "imza_hmac",
            "imza_gecerli",
            "defter_onceki_id",
            "defter_zincir_hmac",
        ]
    )
    for r in raw_rows:
        ig = operasyon_defter_satir_imza_gecerli(r)
        ig_s = "" if ig is None else ("evet" if ig else "hayir")
        w.writerow(
            [
                r.get("id"),
                r.get("sube_id"),
                str(r.get("tarih") or ""),
                str(r.get("olay_ts") or ""),
                r.get("etiket"),
                (r.get("aciklama") or "").replace("\r\n", " ").replace("\n", " "),
                r.get("ref_event_id"),
                r.get("personel_id"),
                r.get("personel_ad"),
                r.get("bildirim_saati"),
                r.get("imza_hmac"),
                ig_s,
                r.get("defter_onceki_id"),
                r.get("defter_zincir_hmac"),
            ]
        )

    base = f"operasyon_defter_{ym.replace('-', '')}"
    if gun_v:
        base += f"_{gun_v}"
    if sube_id:
        base += "_sube"
    fname = quote(f"{base}.csv", safe="")
    return Response(
        content=buf.getvalue(),
        media_type="text/csv; charset=utf-8",
        headers={
            "Content-Disposition": f"attachment; filename*=UTF-8''{fname}",
        },
    )


@router.get("/sayimlar")
def ops_sayimlar(
    sube_id: Optional[str] = None,
    limit: int = 300,
    year_month: Optional[str] = None,
    gun: Optional[str] = None,
):
    lim = max(10, min(800, int(limit)))
    ym = _coerce_year_month(year_month)
    gun_v = (gun or "").strip()
    with db() as (conn, cur):
        if sube_id:
            cur.execute(
                """
                SELECT e.id AS event_id, e.sube_id, s.ad AS sube_adi,
                       e.tarih, e.cevap_ts, e.meta,
                       d.personel_id, d.personel_ad, d.bildirim_saati
                FROM sube_operasyon_event e
                JOIN subeler s ON s.id = e.sube_id
                LEFT JOIN LATERAL (
                    SELECT x.personel_id, x.personel_ad, x.bildirim_saati
                    FROM operasyon_defter x
                    WHERE x.ref_event_id = e.id
                      AND x.etiket = 'ACILIS_TAMAM'
                    ORDER BY x.olay_ts DESC
                    LIMIT 1
                ) d ON TRUE
                WHERE e.tip='ACILIS'
                  AND e.durum='tamamlandi'
                  AND e.sube_id=%s
                  AND to_char(e.tarih, 'YYYY-MM') = %s
                  AND (NULLIF(%s, '') IS NULL OR e.tarih = NULLIF(%s, '')::date)
                ORDER BY e.cevap_ts DESC NULLS LAST
                LIMIT %s
                """,
                (sube_id, ym, gun_v, gun_v, lim),
            )
        else:
            cur.execute(
                """
                SELECT e.id AS event_id, e.sube_id, s.ad AS sube_adi,
                       e.tarih, e.cevap_ts, e.meta,
                       d.personel_id, d.personel_ad, d.bildirim_saati
                FROM sube_operasyon_event e
                JOIN subeler s ON s.id = e.sube_id
                LEFT JOIN LATERAL (
                    SELECT x.personel_id, x.personel_ad, x.bildirim_saati
                    FROM operasyon_defter x
                    WHERE x.ref_event_id = e.id
                      AND x.etiket = 'ACILIS_TAMAM'
                    ORDER BY x.olay_ts DESC
                    LIMIT 1
                ) d ON TRUE
                WHERE e.tip='ACILIS'
                  AND e.durum='tamamlandi'
                  AND to_char(e.tarih, 'YYYY-MM') = %s
                  AND (NULLIF(%s, '') IS NULL OR e.tarih = NULLIF(%s, '')::date)
                ORDER BY e.cevap_ts DESC NULLS LAST
                LIMIT %s
                """,
                (ym, gun_v, gun_v, lim),
            )

        rows: List[dict] = []
        for r in cur.fetchall():
            d = dict(r)
            if d.get("tarih"):
                d["tarih"] = str(d["tarih"])
            if d.get("cevap_ts"):
                d["cevap_ts"] = str(d["cevap_ts"])
            d["stok_sayim"] = _stok_map_from_meta(d.get("meta"), "acilis_stok_sayim", _BAR_KEYS)
            d.pop("meta", None)
            rows.append(d)
    return {"satirlar": rows, "limit": lim, "year_month": ym, "gun": gun_v or None}


# ── Bar Günlük Özet ───────────────────────────────────────────────────────────
# Gün içi: satılan = açılış + ürün_aç - bugün_kapanış (negatif = aynı gün stoğu tutmaz).
# Devir: önceki_gün_kapanış_stoğu vs bugün_açılış_stoğu — tutmazsa devir_uyumsuz_kalemleri.
# ─────────────────────────────────────────────────────────────────────────────

_BAR_KEYS = [
    "bardak_kucuk", "bardak_buyuk", "bardak_plastik", "karton_bardak",
    "su_adet", "sut_litre", "redbull_adet", "soda_adet", "cookie_adet", "pasta_adet",
    "surup_adet", "kahve_paket", "kapak_adet", "pecete_paket", "diger_sarf",
    *PASTA_KEYS,
]


def _stok_map_from_meta(meta_raw: Any, alan: str, keys: Optional[List[str]] = None) -> Dict[str, int]:
    """
    Event meta içindeki stok bloklarını tek bir normalizasyonla okur.
    `stok_from_event_meta` ile (legacy fallback dahil) parse eder, istenen anahtarlara indirger.
    """
    src_keys = keys or list(STOK_KEYS)
    base = stok_from_event_meta(meta_raw, alan)
    return {k: max(0, int(base.get(k) or 0)) for k in src_keys}


def _bar_stok_from_meta(meta_raw: Any, alan: str) -> Dict[str, int]:
    """meta JSONB'den belirli alanı (acilis_stok_sayim / kapanis_stok_sayim) okur."""
    return _stok_map_from_meta(meta_raw, alan, _BAR_KEYS)


def _event_meta_dict(meta_raw: Any) -> Dict[str, Any]:
    if meta_raw is None or meta_raw == "":
        return {}
    if isinstance(meta_raw, dict):
        return meta_raw
    if isinstance(meta_raw, str):
        try:
            parsed = json.loads(meta_raw)
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            return {}
    return {}


def _online_nakit_pos_cift(nakit: float, pos: float, online: float) -> bool:
    """Online alanına yanlışlıkla nakit+POS toplamı yazılmış mı (çift sayım)."""
    n, p, o = float(nakit or 0), float(pos or 0), float(online or 0)
    if o <= 0.001 or n <= 0.001 or p <= 0.001:
        return False
    # Tolerans 50 kuruştan 1 kuruşa indirildi — eskiden 49 kuruşa kadar kasiyer hile/hata
    # yapabiliyordu. Banka para mutabakatı standardı: < 0.01₺ (kuruş hassasiyeti).
    return abs(o - (n + p)) < 0.01


def _ciro_kalemleri_sanitize(
    nakit: float, pos: float, online: float
) -> tuple[float, float, float, float, bool]:
    """Panelde online yokken merkez/OCR hatası: online=nakit+pos ise sıfırla."""
    n, p, o = float(nakit or 0), float(pos or 0), float(online or 0)
    if _online_nakit_pos_cift(n, p, o):
        return n, p, 0.0, round(n + p, 2), True
    return n, p, o, round(n + p + o, 2), False


def _kapanis_x_rapor_from_event(kap: Optional[dict]) -> Dict[str, Optional[float]]:
    """Kapanış anında kaydedilen X nakit/POS/online (meta.x_rapor veya snap_*)."""
    if not kap:
        return {"nakit": None, "pos": None, "online": None}
    meta = _event_meta_dict(kap.get("meta"))
    xr = meta.get("x_rapor") if isinstance(meta.get("x_rapor"), dict) else {}
    out: Dict[str, Optional[float]] = {}
    for key, snap_key in (
        ("nakit", "snap_nakit"),
        ("pos", "snap_pos"),
        ("online", "snap_online"),
    ):
        val = None
        if isinstance(xr, dict) and key in xr and xr.get(key) is not None:
            val = float(xr.get(key) or 0)
        elif kap.get(snap_key) is not None:
            val = float(kap.get(snap_key) or 0)
        out[key] = val
    return out


def _bar_prev_calendar_iso(tarih_str: str) -> str:
    """ACILIS tarihi için bir önceki takvim günü (YYYY-MM-DD)."""
    d = date.fromisoformat(str(tarih_str)[:10])
    return (d - timedelta(days=1)).isoformat()


def _urun_ac_delta_parse(aciklama: str) -> Dict[str, int]:
    """operasyon_defter URUN_AC satırındaki delta ve kalemler JSON'unu ayrıştırır."""
    if not aciklama:
        return {}
    raw = aciklama
    # "URUN_AC_JSON:{...}" veya doğrudan JSON
    if raw.startswith("URUN_AC_JSON:"):
        raw = raw[len("URUN_AC_JSON:"):]
    if " | " in raw:
        raw = raw.split(" | ", 1)[0].strip()
    try:
        obj = json.loads(raw)
    except Exception:
        return {}
    if not isinstance(obj, dict):
        return {}
    delta = obj.get("delta") or {}
    if not isinstance(delta, dict):
        delta = {}
    kalemler = obj.get("kalemler") or []
    if not isinstance(kalemler, list):
        kalemler = []
    # Şube paneli aynı açılışı hem `delta` hem `kalemler` ile gönderir; toplamda çift sayım yapılmaz.
    s_map: Dict[str, int] = {k: 0 for k in _BAR_KEYS}
    for item in kalemler:
        if not isinstance(item, dict):
            continue
        urun_ad = str(item.get("urun_ad") or "").strip()
        try:
            adet = max(0, int(item.get("adet") or 0))
        except (TypeError, ValueError):
            adet = 0
        if not urun_ad or adet <= 0:
            continue
        stok_key = _stok_key_from_urun_ad(urun_ad)
        if stok_key and stok_key in _BAR_KEYS:
            s_map[stok_key] += adet
    result: Dict[str, int] = {}
    for k in _BAR_KEYS:
        try:
            dv = max(0, int(delta.get(k) or 0))
        except (TypeError, ValueError):
            dv = 0
        sv = int(s_map.get(k) or 0)
        merged = max(dv, sv)
        if merged > 0:
            result[k] = merged
    return result


def _urun_ac_kalem_idler(aciklama: str) -> List[Tuple[str, int]]:
    """URUN_AC kalemler[] dizisinden (urun_id, adet) çiftlerini çıkarır — HAVUZ FİLTRESİ YOK.
    Maliyet motorunun 'ne açıldıysa onu maliyetle' (peçete/kahve türü/özel şurup dahil)
    kod-bağımsız hesabı için. urun_id → siparis_urun.depo_stok_kalem_kodu → fiyat zinciri."""
    raw = (aciklama or "")
    if raw.startswith("URUN_AC_JSON:"):
        raw = raw[len("URUN_AC_JSON:"):]
    if " | " in raw:
        raw = raw.split(" | ", 1)[0].strip()
    try:
        obj = json.loads(raw)
    except Exception:
        return []
    if not isinstance(obj, dict):
        return []
    kalemler = obj.get("kalemler") or []
    if not isinstance(kalemler, list):
        return []
    out: List[Tuple[str, int]] = []
    for it in kalemler:
        if not isinstance(it, dict):
            continue
        uid = str(it.get("urun_id") or "").strip()
        try:
            adet = max(0, int(it.get("adet") or 0))
        except (TypeError, ValueError):
            adet = 0
        if uid and adet > 0:
            out.append((uid, adet))
    return out


def _urun_ac_payload_parse(aciklama: str) -> Dict[str, Any]:
    """
    URUN_AC satırındaki JSON payload'ını güvenli parse eder.
    Not metni varsa (' | ...') JSON kısmını ayırır.
    """
    s = (aciklama or "").strip()
    if not s:
        return {}
    if s.startswith("URUN_AC_JSON:"):
        s = s[len("URUN_AC_JSON:") :]
    if " | " in s:
        s = s.split(" | ", 1)[0].strip()
    try:
        obj = json.loads(s)
    except Exception:
        return {}
    return obj if isinstance(obj, dict) else {}


@router.get("/gec-acilan-subeler")
def ops_gec_acilan_subeler(
    tarih: Optional[str] = Query(None, description="YYYY-MM-DD"),
    limit: int = Query(200, ge=1, le=500),
):
    """
    Seçilen günde plan saatine göre geç açılan şubeleri döner.
    Referans saat: vardiya ataması varsa MIN(başlangıç), yoksa operasyon sistem_slot_ts.
    Yanıtta ``gecikme_seviye``: ≤15 dk → uyarı, >15 dk → kritik (iş kuralı).
    Ek olarak: o gün için ACILIS satırı var ama henüz tamamlanmamış (cevap yok / bekliyor-gecikti vb.)
    şubeler `acilmayan_subeler` listesinde döner.
    `plan_kayitsiz_subeler`: aktif ve vardiya/operasyon takibi açık şubelerden o gün için hiç ACILIS
    event satırı oluşmamış olanlar (şube paneli / motor henüz çalışmamış).
    """
    hedef_tarih = (tarih or str(bugun_tr())).strip()
    try:
        hedef_tarih = str(datetime.strptime(hedef_tarih, "%Y-%m-%d").date())
    except ValueError:
        raise HTTPException(400, "tarih formatı YYYY-MM-DD olmalı")

    with db() as (conn, cur):
        # ── Geç açılan: vardiya planı baz alınır, yoksa sistem_slot_ts fallback ──
        cur.execute(
            """
            SELECT
                e.id           AS event_id,
                e.sube_id,
                COALESCE(s.ad, e.sube_id::text)           AS sube_adi,
                e.tarih,
                e.cevap_ts,
                -- Planlanan: vardiya min saat (time) → string
                CASE
                    WHEN va.bek_saat IS NOT NULL
                        THEN TO_CHAR(va.bek_saat, 'HH24:MI')
                    WHEN e.sistem_slot_ts IS NOT NULL
                        THEN TO_CHAR(e.sistem_slot_ts AT TIME ZONE 'Europe/Istanbul', 'HH24:MI')
                    ELSE NULL
                END AS planlanan_saat,
                -- Gecikme: vardiya saati varsa ona göre, yoksa sistem_slot_ts'e göre
                CASE
                    WHEN va.bek_saat IS NOT NULL THEN
                        ROUND(EXTRACT(EPOCH FROM
                            (e.cevap_ts AT TIME ZONE 'Europe/Istanbul'
                             - (e.tarih::date + va.bek_saat))
                        ) / 60.0, 2)
                    WHEN e.sistem_slot_ts IS NOT NULL THEN
                        ROUND(EXTRACT(EPOCH FROM (e.cevap_ts - e.sistem_slot_ts)) / 60.0, 2)
                    ELSE 0.0
                END AS gecikme_dk,
                va.bek_personel,
                x.personel_id,
                x.personel_ad,
                (va.bek_saat IS NOT NULL) AS vardiya_planli
            FROM sube_operasyon_event e
            LEFT JOIN subeler s ON s.id = e.sube_id
            LEFT JOIN LATERAL (
                SELECT
                    MIN(va2.baslangic_saat)                AS bek_saat,
                    STRING_AGG(DISTINCT p2.ad_soyad, ', ') AS bek_personel
                FROM vardiya_atama va2
                JOIN vardiya_slot vs2 ON vs2.id = va2.slot_id
                JOIN personel p2      ON p2.id  = va2.personel_id
                WHERE vs2.sube_id = e.sube_id
                  AND va2.tarih   = e.tarih
                  AND va2.durum  != 'iptal'
            ) va ON TRUE
            LEFT JOIN LATERAL (
                SELECT
                    d.personel_id,
                    COALESCE(NULLIF(TRIM(d.personel_ad), ''), p.ad_soyad, d.personel_id) AS personel_ad
                FROM operasyon_defter d
                LEFT JOIN personel p ON p.id = d.personel_id
                WHERE d.ref_event_id = e.id
                ORDER BY d.olay_ts DESC NULLS LAST, d.id DESC
                LIMIT 1
            ) x ON TRUE
            WHERE e.tip = 'ACILIS'
              AND e.tarih = %s::date
              AND e.cevap_ts IS NOT NULL
              AND (
                CASE
                    WHEN va.bek_saat IS NOT NULL THEN
                        EXTRACT(EPOCH FROM
                            (e.cevap_ts AT TIME ZONE 'Europe/Istanbul'
                             - (e.tarih::date + va.bek_saat))
                        ) > 0
                    WHEN e.sistem_slot_ts IS NOT NULL THEN
                        EXTRACT(EPOCH FROM (e.cevap_ts - e.sistem_slot_ts)) > 0
                    ELSE FALSE
                END
              )
            ORDER BY gecikme_dk DESC, sube_adi ASC
            LIMIT %s
            """,
            (hedef_tarih, limit),
        )
        rows = cur.fetchall() or []

        # ── Henüz açılmamış: ACILIS var ama tamamlanmamış ──
        cur.execute(
            """
            SELECT
                e.sube_id,
                COALESCE(s.ad, e.sube_id::text) AS sube_adi,
                e.durum,
                va.bek_saat,
                va.bek_personel
            FROM sube_operasyon_event e
            LEFT JOIN subeler s ON s.id = e.sube_id
            LEFT JOIN LATERAL (
                SELECT
                    MIN(va2.baslangic_saat)                AS bek_saat,
                    STRING_AGG(DISTINCT p2.ad_soyad, ', ') AS bek_personel
                FROM vardiya_atama va2
                JOIN vardiya_slot vs2 ON vs2.id = va2.slot_id
                JOIN personel p2      ON p2.id  = va2.personel_id
                WHERE vs2.sube_id = e.sube_id
                  AND va2.tarih   = e.tarih
                  AND va2.durum  != 'iptal'
            ) va ON TRUE
            WHERE e.tip = 'ACILIS'
              AND e.tarih = %s::date
              AND e.sira_no = 0
              AND e.sistem_slot_ts IS NOT NULL
              AND NOT (e.durum = 'tamamlandi' AND e.cevap_ts IS NOT NULL)
            ORDER BY sube_adi ASC
            """,
            (hedef_tarih,),
        )
        acilmayan_rows = cur.fetchall() or []

        # ── Plansız şubeler: ACILIS event'i hiç oluşmamış ──
        cur.execute(
            """
            SELECT
                s.id  AS sube_id,
                s.ad  AS sube_adi,
                COALESCE(
                    TO_CHAR(va.bek_saat, 'HH24:MI'),
                    NULLIF(TRIM(s.acilis_saati), ''),
                    '09:00'
                ) AS plan_acilis_saati,
                va.bek_personel
            FROM subeler s
            LEFT JOIN LATERAL (
                SELECT
                    MIN(va2.baslangic_saat)                AS bek_saat,
                    STRING_AGG(DISTINCT p2.ad_soyad, ', ') AS bek_personel
                FROM vardiya_atama va2
                JOIN vardiya_slot vs2 ON vs2.id = va2.slot_id
                JOIN personel p2      ON p2.id  = va2.personel_id
                WHERE vs2.sube_id = s.id
                  AND va2.tarih   = %s::date
                  AND va2.durum  != 'iptal'
            ) va ON TRUE
            WHERE s.aktif = TRUE
              AND s.vardiya_yazilsin = TRUE
              AND NOT EXISTS (
                SELECT 1 FROM sube_operasyon_event e
                WHERE e.sube_id = s.id
                  AND e.tarih = %s::date
                  AND e.tip = 'ACILIS'
                  AND e.sira_no = 0
              )
            ORDER BY s.ad ASC
            """,
            (hedef_tarih, hedef_tarih),
        )
        plan_yoks_rows = cur.fetchall() or []

    def _fmt_time(v) -> Optional[str]:
        """time / datetime → 'HH:MM' ya da None."""
        if v is None:
            return None
        if hasattr(v, "strftime"):
            return v.strftime("%H:%M")
        s = str(v).strip()[:5]
        return s if len(s) == 5 else None

    _GEC_UYARI_ESIK_DK = 15.0  # İş kuralı: bu dakikaya kadar «uyarı», üstü «kritik» (vardiya slotlu/slotsuz aynı eşik)

    kayitlar: List[Dict[str, Any]] = []
    for r in rows:
        gercek_ts = r.get("cevap_ts")
        try:
            gecikme = float(r.get("gecikme_dk") or 0.0)
        except (TypeError, ValueError):
            gecikme = 0.0
        gecikme = round(max(0.0, gecikme), 2)
        vardiya_planli = bool(r.get("vardiya_planli"))
        seviye = "kritik" if gecikme > _GEC_UYARI_ESIK_DK else "uyari"
        kayitlar.append(
            {
                "event_id":         r.get("event_id"),
                "sube_id":          str(r.get("sube_id") or ""),
                "sube_adi":         str(r.get("sube_adi") or ""),
                "tarih":            str(r.get("tarih") or hedef_tarih),
                "planlanan_saat":   str(r.get("planlanan_saat") or ""),
                "acilis_saat":      gercek_ts.strftime("%H:%M") if hasattr(gercek_ts, "strftime") else None,
                "gecikme_dk":       gecikme,
                "gecikme_seviye":   seviye,
                "vardiya_planli":   vardiya_planli,
                "beklened_personel": str(r.get("bek_personel") or ""),
                "personel_id":      r.get("personel_id"),
                "personel_ad":      str(r.get("personel_ad") or ""),
            }
        )

    acilmayan_subeler: List[Dict[str, Any]] = []
    for ar in acilmayan_rows or []:
        acilmayan_subeler.append(
            {
                "sube_id":           str(ar.get("sube_id") or ""),
                "sube_adi":          str(ar.get("sube_adi") or ""),
                "durum":             str(ar.get("durum") or ""),
                "beklenen_saat":     _fmt_time(ar.get("bek_saat")) or "",
                "beklened_personel": str(ar.get("bek_personel") or ""),
            }
        )

    plan_kayitsiz_subeler: List[Dict[str, Any]] = []
    for pr in plan_yoks_rows or []:
        plan_kayitsiz_subeler.append(
            {
                "sube_id":           str(pr.get("sube_id") or ""),
                "sube_adi":          str(pr.get("sube_adi") or ""),
                "plan_acilis_saati": str(pr.get("plan_acilis_saati") or "09:00"),
                "beklened_personel": str(pr.get("bek_personel") or ""),
            }
        )

    return {
        "tarih": hedef_tarih,
        "toplam": len(kayitlar),
        "kayitlar": kayitlar,
        "gecikme_uyari_esik_dk": _GEC_UYARI_ESIK_DK,
        "acilmayan_subeler": acilmayan_subeler,
        "acilmayan_toplam": len(acilmayan_subeler),
        "plan_kayitsiz_subeler": plan_kayitsiz_subeler,
        "plan_kayitsiz_toplam": len(plan_kayitsiz_subeler),
    }


@router.get("/gec-kalan-personel")
def ops_gec_kalan_personel(
    year_month: Optional[str] = Query(None, description="YYYY-MM"),
    gecikme_dk: int = Query(5, ge=1, le=120),
    kritik_dk: int = Query(15, ge=5, le=240),
    limit: int = Query(300, ge=1, le=1000),
):
    """
    Aylık personel bazlı geç açılış özeti.
    Gecikme dakikası «Geç Açılan Şubeler» ile aynı referansı kullanır:
    vardiya planı varsa (MIN başlangıç) o saat; yoksa operasyon sistem_slot_ts.
    """
    ym = _coerce_year_month(year_month)
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT
                e.id AS event_id,
                e.sube_id,
                COALESCE(s.ad, e.sube_id) AS sube_adi,
                e.tarih,
                e.sistem_slot_ts,
                e.cevap_ts,
                CASE
                    WHEN va.bek_saat IS NOT NULL THEN
                        ROUND(EXTRACT(EPOCH FROM
                            (e.cevap_ts AT TIME ZONE 'Europe/Istanbul'
                             - (e.tarih::date + va.bek_saat))
                        ) / 60.0, 2)
                    WHEN e.sistem_slot_ts IS NOT NULL THEN
                        ROUND(EXTRACT(EPOCH FROM (e.cevap_ts - e.sistem_slot_ts)) / 60.0, 2)
                    ELSE NULL
                END AS gecikme_dk,
                CASE
                    WHEN va.bek_saat IS NOT NULL THEN TO_CHAR(va.bek_saat, 'HH24:MI')
                    WHEN e.sistem_slot_ts IS NOT NULL THEN
                        TO_CHAR(e.sistem_slot_ts AT TIME ZONE 'Europe/Istanbul', 'HH24:MI')
                    ELSE NULL
                END AS planlanan_saat_str,
                x.personel_id,
                x.personel_ad
            FROM sube_operasyon_event e
            LEFT JOIN subeler s ON s.id = e.sube_id
            LEFT JOIN LATERAL (
                SELECT
                    MIN(va2.baslangic_saat)                AS bek_saat,
                    STRING_AGG(DISTINCT p2.ad_soyad, ', ') AS bek_personel
                FROM vardiya_atama va2
                JOIN vardiya_slot vs2 ON vs2.id = va2.slot_id
                JOIN personel p2      ON p2.id  = va2.personel_id
                WHERE vs2.sube_id = e.sube_id
                  AND va2.tarih   = e.tarih
                  AND va2.durum  != 'iptal'
            ) va ON TRUE
            LEFT JOIN LATERAL (
                SELECT
                    d.personel_id,
                    COALESCE(NULLIF(TRIM(d.personel_ad), ''), p.ad_soyad, d.personel_id) AS personel_ad
                FROM operasyon_defter d
                LEFT JOIN personel p ON p.id = d.personel_id
                WHERE d.ref_event_id = e.id
                ORDER BY d.olay_ts DESC NULLS LAST, d.id DESC
                LIMIT 1
            ) x ON TRUE
            WHERE e.tip = 'ACILIS'
              AND to_char(e.tarih, 'YYYY-MM') = %s
              AND e.cevap_ts IS NOT NULL
              AND (
                CASE
                    WHEN va.bek_saat IS NOT NULL THEN
                        EXTRACT(EPOCH FROM
                            (e.cevap_ts AT TIME ZONE 'Europe/Istanbul'
                             - (e.tarih::date + va.bek_saat))
                        ) >= (%s * 60)
                    WHEN e.sistem_slot_ts IS NOT NULL THEN
                        EXTRACT(EPOCH FROM (e.cevap_ts - e.sistem_slot_ts)) >= (%s * 60)
                    ELSE FALSE
                END
              )
            ORDER BY e.tarih DESC, sube_adi ASC
            LIMIT %s
            """,
            (ym, gecikme_dk, gecikme_dk, limit),
        )
        rows = cur.fetchall() or []

    personel_map: Dict[str, Dict[str, Any]] = {}
    toplam_gecikme = 0
    for r in rows:
        pid = str(r.get("personel_id") or "").strip()
        pad = str(r.get("personel_ad") or "").strip()
        if not pid and not pad:
            pid = "anon"
            pad = "Bilinmiyor"
        elif not pad:
            pad = pid
        pkey = f"{pid}::{pad}"
        try:
            gecikme = float(r.get("gecikme_dk") or 0.0)
        except (TypeError, ValueError):
            gecikme = 0.0
        gecikme = round(max(0.0, gecikme), 2)
        gercek_ts = r.get("cevap_ts")
        plan_saat = str(r.get("planlanan_saat_str") or "").strip() or None
        agg = personel_map.setdefault(
            pkey,
            {
                "personel_id": pid or None,
                "personel_ad": pad,
                "gecikme_adet": 0,
                "toplam_gecikme_dk": 0.0,
                "max_gecikme_dk": 0.0,
                "detaylar": [],
            },
        )
        agg["gecikme_adet"] += 1
        agg["toplam_gecikme_dk"] += gecikme
        if gecikme > float(agg["max_gecikme_dk"]):
            agg["max_gecikme_dk"] = gecikme
        agg["detaylar"].append(
            {
                "event_id": r.get("event_id"),
                "tarih": str(r.get("tarih") or ""),
                "sube_id": r.get("sube_id"),
                "sube_adi": r.get("sube_adi"),
                "planlanan_saat": plan_saat,
                "acilis_saat": gercek_ts.strftime("%H:%M") if gercek_ts else None,
                "gecikme_dk": gecikme,
            }
        )
        toplam_gecikme += 1

    satirlar: List[Dict[str, Any]] = []
    for v in personel_map.values():
        adet = int(v["gecikme_adet"])
        toplam_gecikme_dk = round(float(v["toplam_gecikme_dk"]), 2)
        ort = round(toplam_gecikme_dk / float(max(1, adet)), 2)
        detaylar = sorted(v["detaylar"], key=lambda x: (x.get("tarih") or "", x.get("sube_adi") or ""), reverse=True)
        kritik_gecikme_adet = sum(1 for d in detaylar if float(d.get("gecikme_dk") or 0.0) >= float(kritik_dk))
        # Skor: toplam gecikme yükü + kritik tekrar bonusu (kritik dakika üstü olaylar daha ağır).
        skor = round(toplam_gecikme_dk + (kritik_gecikme_adet * float(kritik_dk)), 2)
        satirlar.append(
            {
                "personel_id": v["personel_id"],
                "personel_ad": v["personel_ad"],
                "gecikme_adet": adet,
                "toplam_gecikme_dk": toplam_gecikme_dk,
                "ortalama_gecikme_dk": ort,
                "max_gecikme_dk": round(float(v["max_gecikme_dk"]), 2),
                "kritik": kritik_gecikme_adet > 0,
                "kritik_gecikme_adet": kritik_gecikme_adet,
                "skor": skor,
                "detaylar": detaylar,
            }
        )

    satirlar.sort(
        key=lambda x: (
            float(x.get("skor") or 0.0),
            float(x.get("toplam_gecikme_dk") or 0.0),
            int(x.get("gecikme_adet") or 0),
            float(x.get("max_gecikme_dk") or 0.0),
            str(x.get("personel_ad") or ""),
        ),
        reverse=True,
    )
    kritik_adet = sum(1 for x in satirlar if bool(x.get("kritik")))
    return {
        "year_month": ym,
        "gecikme_dk": int(gecikme_dk),
        "kritik_dk": int(kritik_dk),
        "toplam_personel": len(satirlar),
        "gecikme_toplam_adet": int(toplam_gecikme),
        "kritik_personel_sayisi": int(kritik_adet),
        "satirlar": satirlar,
    }


@router.get("/bar-ozet")
def ops_bar_ozet(
    sube_id: Optional[str] = None,
    year_month: Optional[str] = None,
    gun: Optional[str] = None,
    limit: int = Query(60, ge=1, le=365),
    kapanis_fallback: bool = Query(
        True,
        description=(
            "False: gün sonu stok yalnızca tamamlanmış KAPANIS eventinden; "
            "vardiya devir yedekleri kullanılmaz (Kullanılan Ürünler için)."
        ),
    ),
    evo_yenile: bool = Query(
        False,
        description="True: Evo hs_rapor token önbelleğini temizleyip Grup_Pasta verisini yeniden çeker.",
    ),
):
    """
    Günlük bar özeti:
    - Gün içi: Açılış + Ürün Aç − Kapanış = Satılan (negatif = aynı gün stoğu tutmaz).
    - Günler arası devir: Bir önceki gün kapanış stoğu ile bugün açılış stoğu kalem kalem
      karşılaştırılır (bardak/su/… tutmuyorsa `devir_uyumsuz_kalemleri`).
    Her şube+tarih (ACILIS günü) için tek satır döner.
    """
    lim = max(1, min(365, int(limit)))
    ym = _coerce_year_month(year_month)
    gun_v = (gun or "").strip()

    with db() as (conn, cur):
        # ── 1. ACILIS eventleri ────────────────────────────────────────────
        acilis_params: list = [ym, gun_v, gun_v]
        acilis_sube_filter = ""
        if sube_id:
            acilis_sube_filter = "AND e.sube_id = %s"
            acilis_params.append(sube_id)
        acilis_params.append(lim)

        cur.execute(
            f"""
            SELECT DISTINCT ON (e.sube_id, e.tarih)
                   e.sube_id, s.ad AS sube_adi, e.tarih,
                   e.cevap_ts AS acilis_ts, e.meta AS acilis_meta
            FROM sube_operasyon_event e
            JOIN subeler s ON s.id = e.sube_id
            WHERE e.tip='ACILIS' AND e.durum='tamamlandi'
              AND to_char(e.tarih, 'YYYY-MM') = %s
              AND (NULLIF(%s, '') IS NULL OR e.tarih = NULLIF(%s, '')::date)
              {acilis_sube_filter}
            ORDER BY e.sube_id, e.tarih, e.cevap_ts ASC NULLS LAST, e.id ASC
            LIMIT %s
            """,
            acilis_params,
        )
        acilis_rows = {(str(r["sube_id"]), str(r["tarih"])): dict(r) for r in cur.fetchall()}

        if not acilis_rows:
            return {"satirlar": [], "year_month": ym, "gun": gun_v or None}

        # ── 2. KAPANIS eventleri — aynı dönem ─────────────────────────────
        kap_params: list = [ym, gun_v, gun_v]
        kap_sube_filter = ""
        if sube_id:
            kap_sube_filter = "AND e.sube_id = %s"
            kap_params.append(sube_id)

        cur.execute(
            f"""
            SELECT DISTINCT ON (e.sube_id, e.tarih)
                   e.sube_id, e.tarih, e.meta AS kapanis_meta
            FROM sube_operasyon_event e
            WHERE e.tip='KAPANIS' AND e.durum='tamamlandi'
              AND to_char(e.tarih, 'YYYY-MM') = %s
              AND (NULLIF(%s, '') IS NULL OR e.tarih = NULLIF(%s, '')::date)
              {kap_sube_filter}
            ORDER BY e.sube_id, e.tarih, e.cevap_ts DESC NULLS LAST, e.id DESC
            """,
            kap_params,
        )
        kapanis_map: Dict[tuple, Dict[str, int]] = {}
        # Kapanış stoğu nereden geldi? "kapanis"=gerçek KAPANIS eventi (kesin),
        # "devir"=vardiya devri yedeği (geçici), "ozet"=operasyon özeti (geçici).
        # Frontend "geçici" etiketini bu kaynağa göre gösterir.
        kapanis_kaynak_map: Dict[tuple, str] = {}
        for r in cur.fetchall():
            key = (str(r["sube_id"]), str(r["tarih"]))
            kapanis_map[key] = _bar_stok_from_meta(r["kapanis_meta"], "kapanis_stok_sayim")
            kapanis_kaynak_map[key] = "kapanis"

        # ── 2b/2c. Yedek kapanış stoğu — yalnızca kapanis_fallback=True (devir ≠ gerçek kapanış) ──
        if kapanis_fallback:
            kap_fb_params: list = [ym, gun_v, gun_v]
            kap_fb_sube_filter = ""
            if sube_id:
                kap_fb_sube_filter = "AND k.sube_id = %s"
                kap_fb_params.append(sube_id)
            try:
                cur.execute("SAVEPOINT sp_kapanis_kayit_fb")
                cur.execute(
                    f"""
                    SELECT k.sube_id::text, k.tarih::text, k.meta
                    FROM kapanis_kayit k
                    WHERE k.olay = 'vardiya_sabah_aksam_devri'
                      AND k.durum = 'tamamlandi'
                      AND to_char(k.tarih, 'YYYY-MM') = %s
                      AND (NULLIF(%s, '') IS NULL OR k.tarih = NULLIF(%s, '')::date)
                      {kap_fb_sube_filter}
                    """,
                    kap_fb_params,
                )
                for r in cur.fetchall():
                    key = (str(r["sube_id"]), str(r["tarih"]))
                    if key in kapanis_map:
                        continue
                    meta_raw = r.get("meta") or {}
                    if isinstance(meta_raw, str):
                        try:
                            import json as _jfb; meta_raw = _jfb.loads(meta_raw)
                        except Exception:
                            meta_raw = {}
                    devir_stok = meta_raw.get("vardiya_devir_stok_sayim") or {}
                    if devir_stok:
                        kapanis_map[key] = {k: max(0, int(devir_stok.get(k) or 0)) for k in _BAR_KEYS}
                        kapanis_kaynak_map[key] = "devir"
                cur.execute("RELEASE SAVEPOINT sp_kapanis_kayit_fb")
            except Exception:
                cur.execute("ROLLBACK TO SAVEPOINT sp_kapanis_kayit_fb")

            kap_ozet_params: list = [ym, gun_v, gun_v]
            kap_ozet_sube_filter = ""
            if sube_id:
                kap_ozet_sube_filter = "AND o.sube_id = %s"
                kap_ozet_params.append(sube_id)
            try:
                cur.execute("SAVEPOINT sp_ozet_kapanis_stok")
                cur.execute(
                    f"""
                    SELECT o.sube_id::text, o.tarih::text, o.kapanis_stok_json
                    FROM sube_operasyon_ozet o
                    WHERE to_char(o.tarih, 'YYYY-MM') = %s
                      AND (NULLIF(%s, '') IS NULL OR o.tarih = NULLIF(%s, '')::date)
                      AND o.kapanis_stok_json IS NOT NULL
                      {kap_ozet_sube_filter}
                    """,
                    kap_ozet_params,
                )
                for r in cur.fetchall():
                    key = (str(r["sube_id"]), str(r["tarih"]))
                    if key in kapanis_map:
                        continue
                    raw = r.get("kapanis_stok_json") or {}
                    if isinstance(raw, str):
                        try:
                            import json as _joz; raw = _joz.loads(raw)
                        except Exception:
                            raw = {}
                    if raw:
                        kapanis_map[key] = {k: max(0, int(raw.get(k) or 0)) for k in _BAR_KEYS}
                        kapanis_kaynak_map[key] = "ozet"
                cur.execute("RELEASE SAVEPOINT sp_ozet_kapanis_stok")
            except Exception:
                cur.execute("ROLLBACK TO SAVEPOINT sp_ozet_kapanis_stok")

        # ── 3. URUN_AC gün toplamları ──────────────────────────────────────
        urun_params: list = [ym, gun_v, gun_v]
        urun_sube_filter = ""
        if sube_id:
            urun_sube_filter = "AND sube_id = %s"
            urun_params.append(sube_id)

        cur.execute(
            f"""
            SELECT sube_id, tarih::text AS tarih, aciklama
            FROM operasyon_defter
            WHERE etiket='URUN_AC'
              AND to_char(tarih, 'YYYY-MM') = %s
              AND (NULLIF(%s, '') IS NULL OR tarih = NULLIF(%s,'')::date)
              {urun_sube_filter}
            """,
            urun_params,
        )
        urun_ac_map: Dict[tuple, Dict[str, int]] = {}
        for r in cur.fetchall():
            key = (str(r["sube_id"]), str(r["tarih"]))
            delta = _urun_ac_delta_parse(r["aciklama"] or "")
            existing = urun_ac_map.setdefault(key, {k: 0 for k in _BAR_KEYS})
            for k, v in delta.items():
                existing[k] = existing.get(k, 0) + v

        # ── 3b. Önceki gün kapanış — devir: dün gece sayım = bugün sabah sayım ──
        prev_pair_seen: set = set()
        prev_pairs: List[Tuple[str, str]] = []
        for sid_i, tarih_str_i in acilis_rows.keys():
            pk = (sid_i, _bar_prev_calendar_iso(tarih_str_i))
            if pk not in prev_pair_seen:
                prev_pair_seen.add(pk)
                prev_pairs.append(pk)

        kapanis_dun_map: Dict[Tuple[str, str], Dict[str, int]] = {}
        kapanis_dun_ts_map: Dict[Tuple[str, str], Any] = {}
        if prev_pairs:
            sid_list = [p[0] for p in prev_pairs]
            tarih_list = [date.fromisoformat(p[1]) for p in prev_pairs]
            cur.execute(
                """
                SELECT DISTINCT ON (e.sube_id, e.tarih)
                       e.sube_id, e.tarih::text, e.meta AS kapanis_meta, e.cevap_ts AS kapanis_ts
                FROM sube_operasyon_event e
                INNER JOIN (
                    SELECT * FROM unnest(%s::text[], %s::date[]) AS j(sube_id, tarih)
                ) q ON e.sube_id = q.sube_id AND e.tarih = q.tarih
                WHERE e.tip = 'KAPANIS' AND e.durum = 'tamamlandi'
                ORDER BY e.sube_id, e.tarih, e.cevap_ts DESC NULLS LAST, e.id DESC
                """,
                (sid_list, tarih_list),
            )
            for r in cur.fetchall() or []:
                kk = (str(r["sube_id"]), str(r["tarih"]))
                kapanis_dun_map[kk] = _bar_stok_from_meta(r.get("kapanis_meta"), "kapanis_stok_sayim")
                kapanis_dun_ts_map[kk] = r.get("kapanis_ts")

            # Fallback: KAPANIS eventi olmayan önceki günler için vardiya devri
            missing_dun = [p for p in prev_pairs if p not in kapanis_dun_map]
            if missing_dun:
                d_sid_list  = [p[0] for p in missing_dun]
                d_tar_list  = [date.fromisoformat(p[1]) for p in missing_dun]
                try:
                    cur.execute("SAVEPOINT sp_kapanis_kayit_dun")
                    cur.execute(
                        """
                        SELECT k.sube_id::text, k.tarih::text, k.meta
                        FROM kapanis_kayit k
                        INNER JOIN (
                            SELECT * FROM unnest(%s::text[], %s::date[]) AS j(sube_id, tarih)
                        ) q ON k.sube_id = q.sube_id AND k.tarih = q.tarih
                        WHERE k.olay = 'vardiya_sabah_aksam_devri' AND k.durum = 'tamamlandi'
                        """,
                        (d_sid_list, d_tar_list),
                    )
                    for r in cur.fetchall() or []:
                        kk = (str(r["sube_id"]), str(r["tarih"]))
                        if kk in kapanis_dun_map:
                            continue
                        meta_raw = r.get("meta") or {}
                        if isinstance(meta_raw, str):
                            try:
                                import json as _jd; meta_raw = _jd.loads(meta_raw)
                            except Exception:
                                meta_raw = {}
                        devir_stok = meta_raw.get("vardiya_devir_stok_sayim") or {}
                        if devir_stok:
                            kapanis_dun_map[kk] = {k: max(0, int(devir_stok.get(k) or 0)) for k in _BAR_KEYS}
                    cur.execute("RELEASE SAVEPOINT sp_kapanis_kayit_dun")
                except Exception:
                    cur.execute("ROLLBACK TO SAVEPOINT sp_kapanis_kayit_dun")

        # ── 4. Birleştir ───────────────────────────────────────────────────
        from stok_bar_uyum import GUN_ICI_DENETIM_KEYS

        satirlar: List[Dict[str, Any]] = []
        for (sid, tarih_str), ac_row in acilis_rows.items():
            key = (sid, tarih_str)
            acilis  = _bar_stok_from_meta(ac_row.get("acilis_meta"), "acilis_stok_sayim")
            kapanis = kapanis_map.get(key, {})
            urun_ac = urun_ac_map.get(key, {k: 0 for k in _BAR_KEYS})

            satilan:  Dict[str, int] = {}
            fark_var: bool = False
            urun_ac_eksik_var: bool = False
            for k in _BAR_KEYS:
                a = acilis.get(k, 0)
                u = urun_ac.get(k, 0)
                kap = kapanis.get(k, 0)
                sat = a + u - kap
                satilan[k] = sat
                if sat < 0 and k in GUN_ICI_DENETIM_KEYS:
                    fark_var = True
                    urun_ac_eksik_var = True

            prev_key = (sid, _bar_prev_calendar_iso(tarih_str))
            dun_blk = kapanis_dun_map.get(prev_key)
            onceki_kapanis_yok = dun_blk is None
            # KÖPRÜ ÜRÜN AÇ: dün kapanış → bugün açılış arasında depodan bara açılan ürün.
            # Beklenen açılış = dün kapanış + köprü. Böylece meşru "ürün aç" devir farkı sayılmaz;
            # ürün aç kaydı YOKKEN açılış fazlaysa (manipülasyon/hata) doğru şekilde işaretlenir.
            kopru = {}
            if dun_blk is not None:
                try:
                    from stok_bar_uyum import bridging_urun_ac_bar_map as _bridge
                    kopru = _bridge(cur, sid, kapanis_dun_ts_map.get(prev_key), ac_row.get("acilis_ts"))
                except Exception:
                    kopru = {}
            devir_uyumsuz_kalemleri: List[str] = []
            devir_farklari: Dict[str, Dict[str, int]] = {}
            if dun_blk is not None:
                for k2 in _BAR_KEYS:
                    # Pasta TOPLAM (pasta_adet) üzerinden takip edilir — 33 ayrı çeşit
                    # devirde kıyaslanmaz (çeşitler günlük taze; gürültü yapar).
                    if k2.startswith("pasta_") and k2 != "pasta_adet":
                        continue
                    vd = int(dun_blk.get(k2, 0) or 0)
                    va = int(acilis.get(k2, 0) or 0)
                    kb = int(kopru.get(k2, 0) or 0)
                    beklenen = vd + kb  # dün kapanış + köprü ürün aç
                    if va != beklenen:
                        devir_uyumsuz_kalemleri.append(k2)
                        devir_farklari[k2] = {
                            "dun_kapanis": vd,
                            "kopru_urun_ac": kb,
                            "beklenen": beklenen,
                            "bugun_acilis": va,
                            "fark": va - beklenen,
                        }
            devir_uyumsuz_var = bool(devir_uyumsuz_kalemleri) or onceki_kapanis_yok

            satirlar.append({
                "sube_id":    sid,
                "sube_adi":   ac_row.get("sube_adi") or sid,
                "tarih":      tarih_str,
                "acilis_ts":  str(ac_row.get("acilis_ts") or ""),
                "kapanis_var": bool(kapanis),
                # Kapanış kaynağı: "kapanis" (gerçek/kesin) | "devir"/"ozet" (geçici yedek) | None (henüz yok)
                "kapanis_kaynak": kapanis_kaynak_map.get(key),
                "kapanis_gercek": kapanis_kaynak_map.get(key) == "kapanis",
                "acilis":     acilis,
                "urun_ac":    urun_ac,
                "kapanis":    kapanis,
                "satilan":    satilan,
                "fark_var":   fark_var,
                "urun_ac_eksik_var": urun_ac_eksik_var,
                "onceki_kapanis_yok": onceki_kapanis_yok,
                "onceki_kapanis_tarihi": _bar_prev_calendar_iso(tarih_str),
                "dun_kapanis": dun_blk,
                "devir_uyumsuz_kalemleri": devir_uyumsuz_kalemleri,
                "devir_farklari": devir_farklari,
                "devir_uyumsuz_var": devir_uyumsuz_var,
            })

        # Evo Grup_Pasta → satılan yanında malzeme etiketi (tek gün sorgularında)
        evo_by_sube: Dict[str, Dict[str, Dict[str, Any]]] = {}
        evo_veri_geldi = False
        evo_mesaj: Optional[str] = None
        evo_canli: Optional[bool] = None
        evo_son_cekim_ts: Optional[str] = None
        if gun_v:
            try:
                from evo_sync import evo_bar_adet_by_sube_id, _hs_web_token_temizle

                if evo_yenile:
                    _hs_web_token_temizle()
                evo_pack = evo_bar_adet_by_sube_id(cur, gun_v)
                evo_by_sube = evo_pack.get("by_sube") or {}
                evo_veri_geldi = bool(evo_pack.get("evo_veri_geldi"))
                evo_mesaj = evo_pack.get("evo_mesaj")
                evo_canli = evo_pack.get("canli")
                evo_son_cekim_ts = evo_pack.get("son_cekim_ts")
            except Exception:
                evo_by_sube = {}
                evo_mesaj = "Evo veri gelmedi — sunucu hatası"

        for row in satirlar:
            evo_bar = evo_by_sube.get(str(row.get("sube_id") or "")) or {}
            row["evo_adet"] = {
                k: round(float(v.get("adet") or 0), 1)
                for k, v in evo_bar.items()
            }
            etiket_ek = "" if evo_canli is not False else " · son çekim"
            row["evo_etiket"] = {
                k: f"Evo · {(v.get('etiket') or k)} · {int(round(float(v.get('adet') or 0)))} ad{etiket_ek}"
                for k, v in evo_bar.items()
                if float(v.get("adet") or 0) > 0
            }
            row["evo_veri_geldi"] = bool(evo_bar)
            row["evo_mesaj"] = (evo_mesaj if evo_bar else (evo_mesaj or "Evo veri gelmedi"))
            row["evo_kaynak"] = "hs_rapor" if evo_bar else None
            row["evo_canli"] = evo_canli
            row["evo_son_cekim_ts"] = evo_son_cekim_ts

        satirlar.sort(key=lambda x: (x["tarih"], x["sube_adi"]), reverse=True)
        return {
            "satirlar": satirlar,
            "year_month": ym,
            "gun": gun_v or None,
            "kapanis_fallback": bool(kapanis_fallback),
            "evo_dahil": bool(gun_v),
            "evo_veri_geldi": evo_veri_geldi if gun_v else None,
            "evo_mesaj": evo_mesaj if gun_v and not evo_veri_geldi else None,
            "evo_canli": evo_canli if gun_v else None,
            "evo_son_cekim_ts": evo_son_cekim_ts if gun_v else None,
        }


@router.get("/urun-ac-uyumsuzluklar")
def ops_urun_ac_uyumsuzluklar(
    gun: Optional[str] = None,
    year_month: Optional[str] = None,
    sube_id: Optional[str] = None,
    limit: int = Query(500, ge=1, le=2000),
):
    """
    Karşılıksız ürün açma uyarıları (sube_operasyon_uyari, tip=URUN_AC_UYUMSUZLUK).
    Hub kartlarındaki «Ürün Aç» uyarıları ile aynı kaynak; bar-ozet sayım farkından bağımsızdır.
    """
    lim = max(1, min(2000, int(limit)))
    gun_v = (gun or "").strip()
    ym = _coerce_year_month(year_month) if (year_month or "").strip() else (
        gun_v[:7] if len(gun_v) >= 7 else _coerce_year_month(None)
    )
    sid = (sube_id or "").strip() or None

    with db() as (conn, cur):
        params: list = []
        where = ["u.tip = 'URUN_AC_UYUMSUZLUK'"]
        if sid:
            where.append("u.sube_id = %s")
            params.append(sid)
        if gun_v:
            where.append("u.tarih = NULLIF(%s, '')::date")
            params.append(gun_v)
        else:
            where.append("to_char(u.tarih, 'YYYY-MM') = %s")
            params.append(ym)
        params.append(lim)
        cur.execute(
            f"""
            SELECT u.id, u.sube_id, s.ad AS sube_adi, u.tarih::text AS tarih,
                   u.kalem_kodu,
                   COALESCE(NULLIF(TRIM(ds.kalem_adi), ''), u.kalem_kodu) AS kalem_adi,
                   u.mesaj, u.detay, u.olusturma
            FROM sube_operasyon_uyari u
            JOIN subeler s ON s.id = u.sube_id
            LEFT JOIN sube_depo_stok ds
                   ON ds.sube_id = u.sube_id AND ds.kalem_kodu = u.kalem_kodu
            WHERE {' AND '.join(where)}
            ORDER BY u.tarih DESC, s.ad ASC, u.olusturma DESC
            LIMIT %s
            """,
            params,
        )
        satirlar: List[Dict[str, Any]] = []
        for r in cur.fetchall():
            d = dict(r)
            if d.get("olusturma"):
                d["olusturma"] = str(d["olusturma"])
            detay_raw = d.get("detay")
            if isinstance(detay_raw, str):
                try:
                    detay_raw = json.loads(detay_raw)
                except Exception:
                    detay_raw = {}
            if not isinstance(detay_raw, dict):
                detay_raw = {}
            d["detay"] = detay_raw
            d["eksik_miktar"] = int(detay_raw.get("eksik_miktar") or 0)
            from operasyon_stok_motor import depo_kalem_gorunen_ad
            fb = str(detay_raw.get("kalem_adi") or detay_raw.get("urun_ad") or d.get("kalem_adi") or "").strip()
            d["kalem_adi"] = depo_kalem_gorunen_ad(
                cur, str(d.get("sube_id") or ""), str(d.get("kalem_kodu") or ""), fb
            )
            satirlar.append(d)

    return {"satirlar": satirlar, "year_month": ym, "gun": gun_v or None}


