def _toptanci_siparis_wa_mesaj(
    tedarikci_ad: Optional[str],
    sube_adi: Optional[str],
    kalemler: List[Dict[str, Any]],
    notu: Optional[str],
) -> str:
    """Tedarikçiye WhatsApp'tan gidecek sipariş listesi metnini üretir."""
    bugun = dt_now_tr().strftime("%d.%m.%Y")
    satirlar = []
    for k in kalemler:
        ad = str(k.get("urun_ad") or "").strip()
        adet = int(k.get("adet") or 0)
        if ad and adet > 0:
            satirlar.append(f"• {ad} × {adet}")
    bas = "🛒 *TULİPİ SİPARİŞ*"
    if tedarikci_ad:
        bas += f"\nTedarikçi: {tedarikci_ad}"
    if sube_adi:
        bas += f"\nŞube: {sube_adi}"
    bas += f"\nTarih: {bugun}\n\n" + "\n".join(satirlar)
    if notu:
        bas += f"\n\n📝 Not: {notu}"
    return bas


def _kanonik_urun_id(cur, kalem_kodu, urun_ad):
    """V2 — kaynakta kanonik kimlik. Sipariş satırı için siparis_urun.id'yi çöz:
    (1) kalem_kodu zaten kanonik UUID mi (siparis_urun'da var) → onu;
    (2) ada göre eşleş (kanonik öncelikli) → onu;
    (3) çözülemezse None (gerçekten katalog-dışı/yeni ürün → teslim-al ozel__'e düşer).
    Çözümü kaynağa taşır; teslim-al dedektiflik yapmaz, urun_id'yi direkt okur."""
    kk = str(kalem_kodu or "").strip()
    if kk:
        try:
            cur.execute("SELECT 1 FROM siparis_urun WHERE id::text=%s LIMIT 1", (kk,))
            if cur.fetchone():
                return kk
        except Exception:
            pass
    ad = str(urun_ad or "").strip()
    if ad:
        try:
            cur.execute(
                "SELECT id::text AS id FROM siparis_urun WHERE lower(btrim(ad))=lower(btrim(%s)) "
                "ORDER BY (depo_stok_kalem_kodu IS NULL) DESC LIMIT 1",
                (ad,),
            )
            r = cur.fetchone()
            if r:
                return str(dict(r)["id"])
        except Exception:
            pass
    return None


@router.post("/siparis/toptanciya-yolla")
def ops_siparis_toptanciya_yolla(body: OpsSiparisToptanciyaYollaBody):
    tid = (body.talep_id or "").strip()
    if not tid:
        raise HTTPException(400, "talep_id zorunlu")
    kalemler_in = body.kalemler or []
    kalemler: List[Dict[str, Any]] = []
    for k in kalemler_in:
        ad = str(k.urun_ad or "").strip()
        adet = max(0, int(k.adet or 0))
        if not ad or adet <= 0:
            continue
        kalemler.append(
            {
                "urun_ad": ad,
                "adet": adet,
                "kalem_kodu": (str(k.kalem_kodu or "").strip() or None),
                "kategori_kod": (str(k.kategori_kod or "").strip() or None),
            }
        )
    if not kalemler:
        raise HTTPException(400, "En az bir geçerli kalem girilmeli")
    tedarikci_id = (body.tedarikci_id or "").strip() or None
    tedarikci_ad = (body.tedarikci_ad or "").strip() or None
    tedarikci_tel: Optional[str] = None
    notu = (body.not_aciklama or "").strip() or None
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT id, sube_id, durum, kalemler
            FROM siparis_talep
            WHERE id=%s
            FOR UPDATE
            """,
            (tid,),
        )
        tr = cur.fetchone()
        if not tr:
            raise HTTPException(404, "Sipariş talebi bulunamadı")
        t = dict(tr)
        if str(t.get("durum") or "") not in ("bekliyor", "hazirlaniyor", "gonderildi"):
            raise HTTPException(409, "Talep toptancı yönlendirmesi için uygun durumda değil")

        # ══════════════════════════════════════════════════════════════════
        # 🛡️ SUNUCU DOĞRULAMASI (Codex denetimi, 2026-08-28)
        # ══════════════════════════════════════════════════════════════════
        # Uç, gelen `kalemler` gövdesini talebe karşı HİÇ doğrulamıyordu:
        # istemci ne yollarsa o yollanıyordu. Fren yalnız ekrandaydı, yani
        # BAYAT bir modal (başka oturum kalemi çoktan yollamışken açık kalmış
        # pencere) aynı malı ikinci kez sipariş edebiliyordu. Ekrandaki
        # kontrol UX'tir; OTORİTE burasıdır.
        # Üç kural: (1) kalem bu talebe ait olmalı, (2) merkez iptal etmiş
        # olmamalı, (3) zaten bir tedarikçiye/depoya çıkmış olmamalı.
        _t_kalemler = t.get("kalemler")
        if isinstance(_t_kalemler, str):
            try:
                _t_kalemler = json.loads(_t_kalemler)
            except Exception:
                _t_kalemler = []
        if not isinstance(_t_kalemler, list):
            _t_kalemler = []
        # ⚠️ Kiyas _norm_ad_tr ile (Codex denetimi, 2026-08-30): duz
        # .lower() Turkce buyuk I'yi bozuyor ve ic bosluk farkini
        # goremiyordu — "FILTRE  KAHVE" mesru kalemi elenebiliyordu.
        _talep_adlari = {
            _norm_ad_tr(str((_i or {}).get("urun_ad") or ""))
            for _i in _t_kalemler if isinstance(_i, dict)
        } - {""}
        _iptal_adlari = {
            _norm_ad_tr(str((_i or {}).get("urun_ad") or ""))
            for _i in _t_kalemler if isinstance(_i, dict) and _i.get("iptal")
        } - {""}

        # Zaten çıkmış olanlar: toptancı + depo (stok_yolda).
        # ⚠️ Sorgu düşerse İSTİSNA YUTULMAZ — sessizce "hiç çıkmamış"
        #    varsaymak, aynı malı ikinci kez sipariş etmek demektir.
        _cikmis_adlar: set = set()
        # Depoya atanmış ama henüz yola çıkmamışlar AYRI tutulur — reddetme
        # sebebi doğru yazılsın: "zaten yollanmış" ile "depoya atanmış" farklı
        # şeylerdir ve kullanıcı ikincisinde depo atamasını geri alabilir.
        _depoya_atanmis: set = set()
        try:
            cur.execute(
                "SELECT kalemler FROM toptanci_siparis "
                "WHERE talep_id = %s AND durum <> 'iptal'",
                (tid,),
            )
            for _cr in cur.fetchall() or []:
                _ck = dict(_cr).get("kalemler") or []
                if isinstance(_ck, str):
                    try:
                        _ck = json.loads(_ck)
                    except Exception:
                        _ck = []
                for _ci in _ck:
                    _cn = _norm_ad_tr(str((_ci or {}).get("urun_ad") or ""))
                    if _cn:
                        _cikmis_adlar.add(_cn)
            ensure_stok_yolda_columns(cur)
            cur.execute(
                # Kolon adı `siparis_talep_id` (database.py:4152) — şemadan.
                "SELECT kalem_adi FROM stok_yolda "
                "WHERE siparis_talep_id = %s AND COALESCE(sevk_adet, 0) > 0",
                (tid,),
            )
            for _sr in cur.fetchall() or []:
                _sn = _norm_ad_tr(str(dict(_sr).get("kalem_adi") or ""))
                if _sn:
                    _cikmis_adlar.add(_sn)
            # ══════════════════════════════════════════════════════════════
            # 🚧 DEPOYA ATANMIŞ AMA HENÜZ YOLA ÇIKMAMIŞ KALEM (Codex, 2026-08-31)
            # ══════════════════════════════════════════════════════════════
            # `stok_yolda` satırı ancak «Yola çıkar» basılınca doğar. Merkez bir
            # kalemi depoya yönlendirip depocu henüz hazırlık aşamasındayken o
            # kalem hiçbir kontrolde "çıkmış" görünmüyordu — aynı kalem AYNI
            # ANDA toptancıya da yollanabiliyordu. Sonuç: mal iki kanaldan
            # gelir, iki fatura doğar, stok iki kez artar.
            # Depo atamasının izi `siparis_talep.kalem_durumlari`dır; oradaki
            # üç değer sevk DIŞIDIR ve engellemez:
            #   depoya_yonlendirilmedi · toptanciya_gitti · merkez_iptal
            cur.execute(
                "SELECT kalem_durumlari FROM siparis_talep WHERE id = %s", (tid,))
            _kd_row = cur.fetchone()
            _kd = (dict(_kd_row).get("kalem_durumlari") if _kd_row else None) or []
            if isinstance(_kd, str):
                try:
                    _kd = json.loads(_kd)
                except Exception:  # noqa: BLE001
                    _kd = []
            _SEVK_DISI = {"depoya_yonlendirilmedi", "toptanciya_gitti", "merkez_iptal"}
            for _ki in (_kd or []):
                if not isinstance(_ki, dict):
                    continue
                _kdur = str(_ki.get("durum") or "").strip().lower()
                _ksebep = str(_ki.get("_sevk_disi_sebep") or "").strip().lower()
                if _kdur in _SEVK_DISI or _ksebep in _SEVK_DISI:
                    continue
                _kn = _norm_ad_tr(str(_ki.get("urun_ad") or ""))
                if _kn and _kn not in _cikmis_adlar:
                    _depoya_atanmis.add(_kn)
        except Exception as _e:
            raise HTTPException(
                503,
                "Gönderim kontrolü yapılamadı — toptancıya yollama güvenli "
                "değil (aynı mal iki kez sipariş edilebilir).",
            ) from _e

        _red: List[str] = []
        _gecerli: List[Dict[str, Any]] = []
        for _k in kalemler:
            _n = _norm_ad_tr(str(_k.get("urun_ad") or ""))
            if _talep_adlari and _n not in _talep_adlari:
                _red.append(f"{_k.get('urun_ad')} (bu siparişte yok)")
            elif _n in _iptal_adlari:
                _red.append(f"{_k.get('urun_ad')} (merkez iptal etti)")
            elif _n in _cikmis_adlar:
                _red.append(f"{_k.get('urun_ad')} (zaten yollanmış)")
            elif _n in _depoya_atanmis:
                _red.append(
                    f"{_k.get('urun_ad')} (depoya atanmış, henüz yola çıkmadı — "
                    "toptancıya da yollanırsa mal iki kanaldan gelir; önce depo "
                    "atamasını geri alın)")
            else:
                _gecerli.append(_k)
        if not _gecerli:
            raise HTTPException(
                409,
                "Yollanacak kalem kalmadı — " + ("; ".join(_red) if _red else "seçim boş")
                + ". Ekranı yenileyip tekrar deneyin.",
            )
        # ⚠️ SESSİZ ELEME YASAK: elenen kalemler yanıtta ADIYLA döner; ekran
        #    bunu kullanıcıya yazar. Sessizce atılsaydı sahip "hepsini
        #    yolladım" sanırdı.
        _elenen_adlar = list(_red)
        kalemler = _gecerli

        defter_sube = str(t.get("sube_id") or "").strip() or _ops_sube_anchor(cur)

        # ── Tedarikçiyi çöz: id verilmişse DB'den ad+telefon al. WhatsApp ile
        #    sipariş gönderebilmek için telefon ZORUNLU — yoksa gönderimi blokla.
        if tedarikci_id:
            cur.execute(
                "SELECT id, ad, telefon FROM tedarikciler WHERE id=%s AND aktif=TRUE",
                (tedarikci_id,),
            )
            ted_row = cur.fetchone()
            if not ted_row:
                raise HTTPException(404, "Seçilen tedarikçi bulunamadı veya pasif")
            ted = dict(ted_row)
            tedarikci_ad = str(ted.get("ad") or "").strip() or tedarikci_ad
            tedarikci_tel = str(ted.get("telefon") or "").strip() or None
            if not tedarikci_tel:
                raise HTTPException(
                    400,
                    f"'{tedarikci_ad or 'Tedarikçi'}' için telefon numarası eksik. "
                    "WhatsApp ile sipariş gönderebilmek için önce Tedarikçiler ekranından numara ekleyin.",
                )

        # Şube adı (WhatsApp mesajı için)
        sube_adi = None
        if defter_sube:
            cur.execute("SELECT ad FROM subeler WHERE id=%s", (defter_sube,))
            _sr = cur.fetchone()
            if _sr:
                sube_adi = str(dict(_sr).get("ad") or "").strip() or None

        # ── V2: KAYNAKTA KANONİK KİMLİK — her kaleme urun_id damgala. Böylece teslim-al
        #    (sube_panel teslim payload'ı urun_id'yi geçirince) direkt kanonik okur,
        #    ozel__ dedektifliğine gerek kalmaz. Çözülemeyen = katalog-dışı → urun_id None
        #    (teslim-al'daki fallback'ler emniyet ağı olarak DURUYOR, additive).
        for _k in kalemler:
            _k["urun_id"] = _kanonik_urun_id(cur, _k.get("kalem_kodu"), _k.get("urun_ad"))

        # ── toptanci_siparis (procurement_line): bu tedarikçiye giden gönderim ──
        ts_id = str(uuid.uuid4())
        cur.execute(
            """
            INSERT INTO toptanci_siparis
                (id, talep_id, sube_id, tedarikci_id, tedarikci_ad, tedarikci_tel,
                 kalemler, not_aciklama, durum)
            VALUES (%s, %s, %s, %s, %s, %s, %s::jsonb, %s, 'gonderildi')
            """,
            (
                ts_id, tid, defter_sube, tedarikci_id, tedarikci_ad, tedarikci_tel,
                json.dumps(kalemler, ensure_ascii=False), notu,
            ),
        )

        # ── WhatsApp: telefon varsa sipariş listesini tedarikçiye gönder ──
        # Toplu gönderimde (wa_gonder=False) per-talep göndermeyiz; Cep tek birleşik
        # mesaj açar (N ayrı mesaj/kota tüketimi olmasın).
        wa_sonuc: Optional[Dict[str, Any]] = None
        if tedarikci_tel and body.wa_gonder:
            mesaj = _toptanci_siparis_wa_mesaj(tedarikci_ad, sube_adi, kalemler, notu)
            try:
                from whatsapp_bildirim import whatsapp_gonder_numara
                wa_sonuc = whatsapp_gonder_numara(tedarikci_tel, mesaj)
            except Exception as e:  # gönderim hatası kaydı engellemez
                wa_sonuc = {"basarili": False, "mesaj_id": None, "chat_id": "", "hata": str(e)[:120]}
            cur.execute(
                """
                UPDATE toptanci_siparis
                SET wa_gonderim_ts = NOW(), wa_mesaj_id = %s, wa_chat_id = %s, wa_durum = %s
                WHERE id = %s
                """,
                (
                    wa_sonuc.get("mesaj_id"),
                    wa_sonuc.get("chat_id"),
                    ("gonderildi" if wa_sonuc.get("basarili") else "hata"),
                    ts_id,
                ),
            )

        # ── operasyon_defter (eski toptancı teslim feed'i korunur) ──
        payload = {
            "talep_id": tid,
            "toptanci_siparis_id": ts_id,
            "tedarikci_id": tedarikci_id,
            "tedarikci_ad": tedarikci_ad,
            "kalemler": kalemler,
            "not_aciklama": notu,
            "wa_basarili": bool(wa_sonuc and wa_sonuc.get("basarili")),
        }
        operasyon_defter_ekle(
            cur,
            defter_sube,
            "SIPARIS_TOPTANCI_YONLENDIRME",
            "TOPTANCI_SIPARIS_JSON:" + json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
            bildirim_saati=dt_now_tr().strftime("%H:%M:%S"),
            ref_event_id=tid,
        )

        # ── merkez_karar_kalemleri = TÜM tedarikçilerin AGGREGATE'i (split fix) ──
        # Tek talep birden fazla tedarikçiye bölünebildiği için N2, tüm
        # toptanci_siparis satırlarının toplamıdır; tek gönderim onu ezmez.
        cur.execute("SELECT kalemler FROM toptanci_siparis WHERE talep_id=%s", (tid,))
        _agg: Dict[str, Dict[str, Any]] = {}
        _sira: List[str] = []
        for _row in cur.fetchall():
            _kl = dict(_row).get("kalemler") or []
            if isinstance(_kl, str):
                try:
                    _kl = json.loads(_kl)
                except Exception:
                    _kl = []
            for _k in _kl:
                _ad = str(_k.get("urun_ad") or "").strip()
                if not _ad:
                    continue
                # ⚠️ Anahtar tek merkezden (2026-08-31): aşağıdaki _orig_map ile
                # KIYASLANIYOR; ikisi aynı normalleştiriciyi kullanmazsa
                # "FİLTRE KAHVE" ile "Filtre Kahve" ayrı ürün sanılır ve
                # gönderilmiş kalem "kalan" görünür (ya da tersi).
                _key = ad_anahtar(_ad)
                if _key not in _agg:
                    _agg[_key] = {
                        "urun_ad": _ad,
                        "adet": 0,
                        "kalem_kodu": _k.get("kalem_kodu"),
                        "kategori_kod": _k.get("kategori_kod"),
                    }
                    _sira.append(_key)
                _agg[_key]["adet"] += int(_k.get("adet") or 0)
        merkez_agg = [_agg[k] for k in _sira]

        # ── KALAN hesabı: N1 (orijinal talep) − dağıtılan (toptanci_siparis) ──
        # Kısmi gönderimde talep KAPANMAZ; gönderilmeyen kalemler kuyrukta kalsın.
        # N1 asla ezilmez; kalan türetilir. (split-back / veri kaybı fix)
        # GÜVENLİK AĞI: bu hesap beklenmedik veriyle patlarsa gönderim ÇÖKMESİN —
        # eski güvenli davranışa (tam_gonderildi=True → talebi kapat) düş, sebebi logla.
        # KALAN = hiç gönderilmemiş ÜRÜNLER (kalem bazında coverage), miktar farkı
        # DEĞİL. Merkez miktarı override edebilir (N2 = nihai karar); 10 isteyip 6
        # gönderince "4 kaldı" denmez — ürün gönderildiyse tamamdır. Kalan yalnızca
        # hiçbir tedarikçiye atanmamış ürünlerdir (örn. A gitti, B atanmadı → B kalan).
        kalan_adet = 0
        tam_gonderildi = True
        try:
            _orig = t.get("kalemler") or []
            if isinstance(_orig, str):
                try:
                    _orig = json.loads(_orig)
                except Exception:
                    _orig = []
            _orig_map: Dict[str, int] = {}
            for _o in (_orig or []):
                if not isinstance(_o, dict):
                    continue
                _oad = ad_anahtar(_o.get("urun_ad"))  # _agg ile AYNI anahtar
                if _oad:
                    _orig_map[_oad] = _orig_map.get(_oad, 0) + max(0, int(_o.get("adet") or 0))
            _dispatched_set = set(_agg.keys())  # dağıtılmış ürün adları (lower)
            _kalan_urunler = [ad for ad in _orig_map if ad not in _dispatched_set]
            kalan_adet = sum(_orig_map[ad] for ad in _kalan_urunler)
            # N1'de hiç kalem yoksa (eski/boş talep) kalan'ı bilemeyiz → tam say.
            tam_gonderildi = (not _orig_map) or (len(_kalan_urunler) == 0)
        except Exception as _kalan_hata:
            # ⚠️ YÖN DEĞİŞTİ (Codex denetimi, 2026-08-31): eskiden hata olunca
            # tam_gonderildi=True'ya düşülüyordu ve talep KAPANIYORDU. Bu
            # "güvenli" değil, en tehlikeli yöndü: hesap patladığında hangi
            # kalemin yönlendirilmediğini BİLMİYORUZ demektir — o bilinmezliği
            # "hepsi gönderildi" diye yorumlamak sahte yeşildir ve
            # yönlendirilmemiş kalemler kuyruktan sessizce kaybolur.
            # Artık AÇIK bırakıyoruz: açık talep görünür ve düzeltilebilir,
            # yanlış kapanmış talep görünmez. (HATA ≠ BOŞ)
            log.exception("toptanciya-yolla kalan hesabı hatası talep=%s: %s", tid, _kalan_hata)
            kalan_adet = 0
            tam_gonderildi = False

        sevk_notu = notu
        if tedarikci_ad:
            ek = f"Toptancı: {tedarikci_ad}"
            sevk_notu = f"{ek}. {sevk_notu}" if sevk_notu else ek
        if tam_gonderildi:
            cur.execute(
                """
                UPDATE siparis_talep
                SET durum = 'gonderildi',
                    sevkiyat_durumu = 'toptanciya_yonlendirildi',
                    sevkiyat_durum = 'toptanciya_yonlendirildi',
                    sevkiyat_notu = COALESCE(NULLIF(TRIM(%s), ''), sevkiyat_notu),
                    sevkiyat_ts = COALESCE(sevkiyat_ts, NOW()),
                    merkez_karar_kalemleri = %s::jsonb
                WHERE id = %s
                """,
                (sevk_notu, json.dumps(merkez_agg, ensure_ascii=False), tid),
            )
        else:
            # Kısmi: talep 'bekliyor' kalır (kuyrukta), sevkiyat_durumu DEĞİŞMEZ.
            # Sadece N2 aggregate + not güncellenir; gönderilen kısım toptanci_siparis'te.
            cur.execute(
                """
                UPDATE siparis_talep
                SET durum = 'bekliyor',
                    sevkiyat_notu = COALESCE(NULLIF(TRIM(%s), ''), sevkiyat_notu),
                    merkez_karar_kalemleri = %s::jsonb
                WHERE id = %s
                """,
                (sevk_notu, json.dumps(merkez_agg, ensure_ascii=False), tid),
            )
        audit(cur, "siparis_talep", tid, "OPS_SIPARIS_TOPTANCIYA_YOLLA")
    return {
        "success": True,
        "talep_id": tid,
        "toptanci_siparis_id": ts_id,
        "kalem_sayisi": len(kalemler),
        "toplam_adet": sum(int(k.get("adet") or 0) for k in kalemler),
        "durum": ("gonderildi" if tam_gonderildi else "bekliyor"),
        "tam_gonderildi": tam_gonderildi,
        # Sunucu doğrulamasının ELEDİĞİ kalemler adıyla + gerekçesiyle döner.
        "elenen_kalemler": _elenen_adlar,
        "kalan_adet": kalan_adet,
        "sevkiyat_durumu": ("toptanciya_yonlendirildi" if tam_gonderildi else None),
        "wa_basarili": bool(wa_sonuc and wa_sonuc.get("basarili")),
        "wa_hata": (wa_sonuc.get("hata") if wa_sonuc else None),
    }


@router.post("/siparis/{talep_id}/toptanci-geri-al")
def ops_siparis_toptanci_geri_al(talep_id: str, toptanci_siparis_id: Optional[str] = None):
    """
    Toptancı gönderimini geri alır → kalemler merkez kuyruğuna döner.

    🔧 ONARIM (Fable denetimi, 2026-08-29) — üç kusur birden vardı:

    1. **Geri alma KENDİNİ İPTAL EDİYORDU.** Uç `toptanci_siparis` satırlarına
       DOKUNMUYOR, yalnız `operasyon_defter`i siliyordu. Kule ise "dağıtılmış"
       hesabını `toptanci_siparis WHERE durum <> 'iptal'`den türetiyor. Yani
       geri alınan talep "tamamı dağıtılmış ama bekliyor" görünüyor ve kulenin
       SELF-HEAL'i onu ilk yenilemede tekrar `gonderildi`ye çekiyordu.
       → Satırlar artık gerçekten `durum='iptal'` yapılıyor.

    2. **KISMİ GÖNDERİM GERİ ALINAMIYORDU.** Kapı
       `sevkiyat_durumu == 'toptanciya_yonlendirildi'` istiyordu; kısmi
       gönderimde bu alan DEĞİŞMİYOR (talep 'bekliyor' kalıyor) → her kısmi
       yönlendirme 400 alıyordu. → Kapı artık "iptal edilecek bir toptancı
       gönderimi VAR MI" diye soruyor.

    3. **HEP-VEYA-HİÇTİ.** Bir talepte 5 tedarikçiye gönderim varken biri
       yanlışsa hepsini geri almak gerekiyordu. → `toptanci_siparis_id`
       verilirse YALNIZ o gönderim geri alınır.

    ⚠️ TESLİM ALINMIŞ gönderim geri ALINMAZ: mal gelmişse "hiç gönderilmedi"
       demek kaydı gerçekle çelişkiye sokar.
    """
    tid = (talep_id or "").strip()
    if not tid:
        raise HTTPException(400, "talep_id zorunlu")
    hedef_ts = (toptanci_siparis_id or "").strip() or None
    with db() as (conn, cur):
        cur.execute(
            "SELECT id, durum, sevkiyat_durumu FROM siparis_talep WHERE id = %s FOR UPDATE",
            (tid,),
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Sipariş bulunamadı")

        # Geri alınabilir gönderimler: iptal olmamış VE teslim alınmamış.
        _p: List[Any] = [tid]
        _ek = ""
        if hedef_ts:
            _ek = " AND id = %s"
            _p.append(hedef_ts)
        cur.execute(
            "SELECT id, tedarikci_ad, durum FROM toptanci_siparis "
            "WHERE talep_id = %s AND durum <> 'iptal'" + _ek,
            tuple(_p),
        )
        gonderimler = [dict(r) for r in (cur.fetchall() or [])]
        if not gonderimler:
            raise HTTPException(
                400,
                "Geri alınacak toptancı gönderimi yok — bu sipariş toptancıya "
                "yönlendirilmemiş veya gönderim zaten iptal edilmiş.",
            )
        teslim = [g for g in gonderimler if str(g.get("durum") or "") == "teslim_alindi"]
        if teslim:
            raise HTTPException(
                409,
                "Teslim alınmış gönderim geri alınamaz: "
                + ", ".join(str(g.get("tedarikci_ad") or "—") for g in teslim)
                + ". Mal geldiyse kaydı 'hiç gönderilmedi' yapmak izi bozar.",
            )

        iptal_ids = [str(g["id"]) for g in gonderimler]
        # ⛔ ASIL ONARIM: satırlar gerçekten iptal edilir, yoksa kule bunları
        #    "dağıtılmış" saymaya devam eder ve self-heal geri almayı bozar.
        cur.execute(
            "UPDATE toptanci_siparis SET durum = 'iptal' WHERE id = ANY(%s)",
            (iptal_ids,),
        )

        # Talebi kuyruğa döndür — YALNIZ başka açık gönderim kalmadıysa.
        cur.execute(
            "SELECT COUNT(*)::int AS n FROM toptanci_siparis "
            "WHERE talep_id = %s AND durum <> 'iptal'",
            (tid,),
        )
        kalan_gonderim = int((cur.fetchone() or {}).get("n") or 0)
        if kalan_gonderim == 0:
            cur.execute(
                """
                UPDATE siparis_talep
                   SET durum            = 'bekliyor',
                       sevkiyat_durumu  = 'bekliyor',
                       sevkiyat_durum   = 'bekliyor',
                       sevkiyat_notu    = NULL,
                       sevkiyat_ts      = NULL
                 WHERE id = %s
                """,
                (tid,),
            )
        else:
            # Kısmi geri alma: talep zaten 'bekliyor' olabilir; durumu ZORLAMA.
            # Diğer tedarikçiye giden kısım hâlâ yolda.
            cur.execute(
                "UPDATE siparis_talep SET durum = 'bekliyor' WHERE id = %s AND durum <> 'teslim_edildi'",
                (tid,),
            )

        # Toptancı defter kayıtlarını da temizle — listeden kalksın.
        # ⚠️ Tek gönderim geri alındıysa defter SİLİNMEZ: diğer gönderimlerin
        #    izi duruyor, hepsini silmek onların kaydını da yok ederdi.
        if kalan_gonderim == 0:
            cur.execute(
                """
                DELETE FROM operasyon_defter
                 WHERE etiket = 'SIPARIS_TOPTANCI_YONLENDIRME'
                   AND ref_event_id = %s
                """,
                (tid,),
            )
        audit(cur, "siparis_talep", tid, "OPS_SIPARIS_TOPTANCI_GERI_AL")
    return {
        "ok": True,
        "talep_id": tid,
        "iptal_edilen_gonderim": len(iptal_ids),
        "iptal_edilen_tedarikciler": [str(g.get("tedarikci_ad") or "—") for g in gonderimler],
        "kalan_acik_gonderim": kalan_gonderim,
        "yeni_durum": "bekliyor",
    }


# ── ÖĞRENEN TOPTANCI ÖNERİSİ (Cep Sipariş Kulesi Faz 2) ─────────────────────
# Ürün→toptancı eşleşmesini ÖĞRENİR (toptanci_siparis geçmişi) + elle tercih EZER.
# Koda gömülmez (kullanıcı: "yeni toptancı eklendikçe değişebiliyor"). Öneri-only.
def _ensure_urun_tercih(cur) -> None:
    cur.execute("""
        CREATE TABLE IF NOT EXISTS urun_toptanci_tercih (
            urun_ad_norm  TEXT PRIMARY KEY,
            urun_ad       TEXT,
            tedarikci_id  TEXT,
            tedarikci_ad  TEXT,
            guncelleme    TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    """)


@router.get("/siparis/toptanci-oneri")
def ops_siparis_toptanci_oneri(gun: int = Query(180, ge=7, le=730)):
    """Her ürün için önerilen toptancı: elle tercih varsa O (kaynak='elle', oran=1),
    yoksa geçmişte en sık gittiği toptancı (kaynak='gecmis', oran=n/toplam)."""
    oneriler: Dict[str, Any] = {}
    with db() as (conn, cur):
        _ensure_urun_tercih(cur)
        cur.execute(
            """
            WITH gecmis AS (
                SELECT lower(btrim(k->>'urun_ad')) AS urun_norm,
                       max(k->>'urun_ad') AS urun_ad,
                       ts.tedarikci_id, ts.tedarikci_ad, count(*) AS n
                FROM toptanci_siparis ts
                CROSS JOIN LATERAL jsonb_array_elements(ts.kalemler) k
                WHERE ts.durum <> 'iptal' AND ts.tedarikci_id IS NOT NULL
                  AND ts.olusturma >= now() - (%s * interval '1 day')
                  AND btrim(coalesce(k->>'urun_ad','')) <> ''
                GROUP BY 1, ts.tedarikci_id, ts.tedarikci_ad
            ),
            toplam AS (SELECT urun_norm, sum(n) AS topn FROM gecmis GROUP BY 1)
            SELECT DISTINCT ON (g.urun_norm)
                   g.urun_norm, g.urun_ad, g.tedarikci_id, g.tedarikci_ad, g.n, t.topn
            FROM gecmis g JOIN toplam t USING (urun_norm)
            ORDER BY g.urun_norm, g.n DESC
            """,
            (int(gun),),
        )
        for r in cur.fetchall() or []:
            d = dict(r)
            topn = float(d.get("topn") or 0) or 1.0
            oneriler[d["urun_norm"]] = {
                "urun_ad": d.get("urun_ad"),
                "tedarikci_id": d.get("tedarikci_id"),
                "tedarikci_ad": d.get("tedarikci_ad"),
                "oran": round(float(d.get("n") or 0) / topn, 2),
                "n": int(d.get("n") or 0),
                "kaynak": "gecmis",
            }
        # Elle tercih EZER
        cur.execute("SELECT urun_ad_norm, urun_ad, tedarikci_id, tedarikci_ad FROM urun_toptanci_tercih")
        for r in cur.fetchall() or []:
            d = dict(r)
            if not d.get("tedarikci_id"):
                continue
            oneriler[d["urun_ad_norm"]] = {
                "urun_ad": d.get("urun_ad"),
                "tedarikci_id": d.get("tedarikci_id"),
                "tedarikci_ad": d.get("tedarikci_ad"),
                "oran": 1.0, "n": None, "kaynak": "elle",
            }
    return {"oneriler": oneriler}


class OpsToptanciTercihBody(BaseModel):
    urun_ad: str
    tedarikci_id: Optional[str] = None
    tedarikci_ad: Optional[str] = None


@router.post("/siparis/toptanci-tercih")
def ops_siparis_toptanci_tercih(body: OpsToptanciTercihBody):
    """Bir ürünün varsayılan toptancısını elle ayarla/düzelt (boş tedarikci_id = temizle)."""
    ad = (body.urun_ad or "").strip()
    if not ad:
        raise HTTPException(400, "urun_ad zorunlu")
    norm = ad.lower()
    tid = (body.tedarikci_id or "").strip() or None
    with db() as (conn, cur):
        _ensure_urun_tercih(cur)
        if not tid:
            cur.execute("DELETE FROM urun_toptanci_tercih WHERE urun_ad_norm=%s", (norm,))
            return {"ok": True, "silindi": True, "urun_ad": ad}
        cur.execute(
            """
            INSERT INTO urun_toptanci_tercih (urun_ad_norm, urun_ad, tedarikci_id, tedarikci_ad, guncelleme)
            VALUES (%s,%s,%s,%s,NOW())
            ON CONFLICT (urun_ad_norm) DO UPDATE
              SET urun_ad=EXCLUDED.urun_ad, tedarikci_id=EXCLUDED.tedarikci_id,
                  tedarikci_ad=EXCLUDED.tedarikci_ad, guncelleme=NOW()
            """,
            (norm, ad, tid, (body.tedarikci_ad or "").strip() or None),
        )
    return {"ok": True, "urun_ad": ad, "tedarikci_id": tid}


@router.post("/siparis/toptanci-siparis/{ts_id}/iptal")
def ops_toptanci_siparis_iptal(ts_id: str):
    """Tek bir toptancı gönderimini iptal eder (örn. çift tıkta oluşan mükerrer kayıt).
    durum='iptal' → şube paneli kabul etmez, öğrenen öneri/geçmiş bunu saymaz.
    operasyon_defter (hash-zincir) DOKUNULMAZ — sadece durum işaretlenir."""
    sid = (ts_id or "").strip()
    if not sid:
        raise HTTPException(400, "toptanci_siparis_id zorunlu")
    kapatildi = False
    kuyruga_dondu = False
    with db() as (conn, cur):
        cur.execute("SELECT id, talep_id, durum FROM toptanci_siparis WHERE id=%s", (sid,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Toptancı siparişi bulunamadı")
        tid = str(dict(row).get("talep_id") or "")
        if str(dict(row).get("durum") or "") != "iptal":
            cur.execute("UPDATE toptanci_siparis SET durum='iptal' WHERE id=%s", (sid,))
            audit(cur, "toptanci_siparis", sid, "OPS_TOPTANCI_SIPARIS_IPTAL")

        # Mükerrer iptal sonrası TALEP TAMAMLANMA RE-CHECK: bekleyen gönderim kalmadı +
        # en az bir teslim_alindi + tüm N1 ürünleri dağıtıldı → talebi 'teslim_edildi' kapat.
        # (Mükerrer 'gonderildi' kaydı kabul anında tamamlanmayı bloke etmişti.)
        if tid:
            cur.execute("SELECT durum, kalemler FROM siparis_talep WHERE id=%s", (tid,))
            trow = cur.fetchone()
            if trow:
                td = dict(trow)
                if str(td.get("durum") or "") not in ("teslim_edildi", "iptal"):
                    cur.execute(
                        "SELECT durum, kalemler FROM toptanci_siparis WHERE talep_id=%s AND durum<>'iptal'",
                        (tid,),
                    )
                    ts_rows = [dict(r) for r in (cur.fetchall() or [])]
                    bekleyen = sum(1 for x in ts_rows if str(x.get("durum") or "") == "gonderildi")
                    teslim = sum(1 for x in ts_rows if str(x.get("durum") or "") == "teslim_alindi")

                    def _adlar(j):
                        if isinstance(j, str):
                            try:
                                j = json.loads(j)
                            except Exception:
                                j = []
                        return {str((k or {}).get("urun_ad") or "").strip().lower()
                                for k in (j or []) if (k or {}).get("urun_ad")}
                    n1 = _adlar(td.get("kalemler"))
                    disp: set = set()
                    for x in ts_rows:
                        disp |= _adlar(x.get("kalemler"))
                    if bekleyen == 0 and teslim > 0 and not (n1 - disp):
                        cur.execute(
                            """UPDATE siparis_talep
                               SET durum='teslim_edildi',
                                   kabul_durum=COALESCE(NULLIF(kabul_durum,''),'kabul_tam'),
                                   kabul_ts=COALESCE(kabul_ts, NOW())
                               WHERE id=%s AND durum NOT IN ('teslim_edildi','iptal')""",
                            (tid,),
                        )
                        kapatildi = cur.rowcount > 0
                    # ══════════════════════════════════════════════════════
                    # 🧟 ZOMBİ TALEP ÖNLEME (canlı ölçüm, 2026-08-29)
                    # ══════════════════════════════════════════════════════
                    # Yukarıdaki dal `teslim > 0` istiyor: en az bir gönderim
                    # TESLİM ALINMIŞ olmalı. Hiç teslim alınmadan TÜM
                    # gönderimler iptal edilirse HİÇBİR dal çalışmıyordu ve
                    # talep `durum='gonderildi'` / 'toptanciya_yonlendirildi'
                    # olarak ASILI KALIYORDU. Sonuç bir kilitlenme:
                    #   · merkez ekranı "toptancıda bekliyor" der (mal yolda sanılır)
                    #   · şube bekleyen listesi yalnız 'gonderildi' kayıtları
                    #     gösterir; iptal olanı göstermez → ŞUBE KABUL EDEMEZ
                    #   · kimse kapatamaz → mutabakat asla tamamlanmaz
                    # Canlı ölçüm: 8 "toptancı bekliyor" siparişinin 7'si bu
                    # durumdaydı, en eskisi 11 günlük (6'sı TEMA).
                    # ⚠️ Talep İPTAL EDİLMEZ, KUYRUĞA DÖNER: şube bu malı hâlâ
                    #    istiyor. Merkez yeniden yönlendirebilsin veya bilerek
                    #    iptal etsin — karar sahibinde kalsın.
                    elif bekleyen == 0 and teslim == 0:
                        cur.execute(
                            """UPDATE siparis_talep
                               SET durum='bekliyor',
                                   sevkiyat_durumu='bekliyor',
                                   sevkiyat_durum='bekliyor',
                                   sevkiyat_ts=NULL
                               WHERE id=%s AND durum NOT IN ('teslim_edildi','iptal')""",
                            (tid,),
                        )
                        if cur.rowcount > 0:
                            kuyruga_dondu = True
                            audit(cur, "siparis_talep", tid,
                                  "OPS_TALEP_KUYRUGA_DONDU_TOPTANCI_IPTAL")
    return {
        "ok": True, "ts_id": sid, "durum": "iptal",
        "talep_tamamlandi": kapatildi,
        # Ekran "iptal ettim, sipariş ne oldu" sorusunu sorabilsin diye.
        "talep_kuyruga_dondu": kuyruga_dondu,
    }


# ── MERKEZ TEST SİPARİŞ TEMİZLİĞİ ────────────────────────────────────────────
# Telefondan/merkezden verilen DENEME siparişlerini (personel_ad='MERKEZ') sahip
# kendisi temizleyebilir. Stok geri alma DAHİL tam silme. GUARD: sadece MERKEZ
# talepleri (gerçek personel siparişleri ASLA buradan silinemez). İzole — kaldırmak
# = bu iki endpoint'i sil.

@router.get("/siparis/merkez-liste")
def ops_siparis_merkez_liste(limit: int = 100):
    """Merkez/telefondan verilen siparişleri listeler (temizlik aracı için)."""
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT st.id AS talep_id, st.durum AS talep_durum, st.sevkiyat_durumu,
                   st.olusturma, s.ad AS sube_adi,
                   ts.id AS ts_id, ts.tedarikci_ad, ts.durum AS ts_durum, ts.kalemler
            FROM siparis_talep st
            LEFT JOIN subeler s ON s.id = st.sube_id
            LEFT JOIN toptanci_siparis ts ON ts.talep_id = st.id
            WHERE UPPER(COALESCE(st.personel_ad,'')) = 'MERKEZ'
            ORDER BY st.olusturma DESC
            LIMIT %s
            """,
            (max(1, min(int(limit or 100), 300)),),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    out = []
    for r in rows:
        kal = r.get("kalemler")
        if isinstance(kal, str):
            try:
                kal = json.loads(kal)
            except Exception:
                kal = []
        ozet = ", ".join(
            f"{int((k or {}).get('adet') or 0)} {(k or {}).get('urun_ad') or ''}".strip()
            for k in (kal or [])[:6] if isinstance(k, dict)
        )
        teslim = (str(r.get("ts_durum") or "") == "teslim_alindi"
                  or str(r.get("talep_durum") or "") == "teslim_edildi")
        iptalli = str(r.get("ts_durum") or "") == "iptal"
        out.append({
            "talep_id": r.get("talep_id"),
            "ts_id": r.get("ts_id"),
            "sube_adi": r.get("sube_adi"),
            "tedarikci_ad": r.get("tedarikci_ad"),
            "kalem_ozet": ozet,
            "talep_durum": r.get("talep_durum"),
            "ts_durum": r.get("ts_durum"),
            "teslim_alindi": teslim,
            "iptalli": iptalli,
            "olusturma": str(r.get("olusturma") or ""),
        })
    return {"toplam": len(out), "siparisler": out}


@router.post("/siparis/merkez-test-temizle")
def ops_siparis_merkez_test_temizle(body: dict):
    """MERKEZ (deneme) siparişini tamamen siler. stok_geri_al=True (vars.) ise teslim
    alınmış siparişin eklediği stok da Tema deposundan düşülür (URUN_SEVK defterinden
    simetrik). siparis_talep silinince toptanci_siparis CASCADE düşer; belge_talep +
    stok_yolda elle temizlenir. GUARD: yalnızca personel_ad='MERKEZ'."""
    tid = str((body or {}).get("talep_id") or "").strip()
    stok_geri_al = bool((body or {}).get("stok_geri_al", True))
    if not tid:
        raise HTTPException(400, "talep_id zorunlu")

    from operasyon_stok_motor import depo_kalem_kodu_resolve, sube_depo_stok_depo_cikis_dus
    from operasyon_defter import operasyon_defter_ekle

    geri_alinan: list = []
    with db() as (conn, cur):
        cur.execute("SELECT id, personel_ad, sube_id FROM siparis_talep WHERE id=%s", (tid,))
        st = cur.fetchone()
        if not st:
            raise HTTPException(404, "Talep bulunamadı")
        st = dict(st)
        if str(st.get("personel_ad") or "").strip().upper() != "MERKEZ":
            raise HTTPException(409, "Sadece MERKEZ (deneme) siparişleri buradan silinebilir.")
        sube_id = st.get("sube_id")

        # 1) Stok geri alma — bu talebe ait URUN_SEVK defter kayıtlarını bul, eklenen stoğu düş
        if stok_geri_al:
            cur.execute(
                "SELECT id, sube_id, aciklama FROM operasyon_defter WHERE etiket='URUN_SEVK' AND aciklama LIKE %s",
                (f"%{tid}%",),
            )
            for dr in (cur.fetchall() or []):
                d = dict(dr)
                acik = str(d.get("aciklama") or "")
                pre = "URUN_SEVK_JSON:"
                if not acik.startswith(pre):
                    continue
                try:
                    obj, _ = json.JSONDecoder().raw_decode(acik[len(pre):])
                except Exception:
                    continue
                if str((obj or {}).get("siparis_talep_id") or "").strip() != tid:
                    continue
                # Zaten geri alınmış mı?
                cur.execute(
                    "SELECT 1 FROM operasyon_defter WHERE etiket='URUN_SEVK_IPTAL' AND ref_event_id=%s LIMIT 1",
                    (d.get("id"),),
                )
                if cur.fetchone():
                    continue
                d_sube = d.get("sube_id") or sube_id
                ozet_kalem: list = []
                for it in ((obj or {}).get("kalemler") or []):
                    if not isinstance(it, dict):
                        continue
                    uad = str(it.get("urun_ad") or "").strip()
                    try:
                        adet_i = max(0, int(it.get("adet") or 0))
                    except Exception:
                        adet_i = 0
                    uid = str(it.get("urun_id") or "").strip()
                    if not uad or adet_i <= 0 or not uid:
                        continue  # urun_id yoksa güvenli ATLA (kanonik olmayan stok riskli)
                    try:
                        depo_kalem = depo_kalem_kodu_resolve(cur, uid, uad)
                    except Exception:
                        depo_kalem = None
                    if not depo_kalem:
                        continue
                    try:
                        sube_depo_stok_depo_cikis_dus(cur, d_sube, depo_kalem, uad, adet_i)
                        geri_alinan.append(f"{adet_i} {uad}")
                        ozet_kalem.append(f"{adet_i} {uad}")
                    except Exception:
                        pass
                # Ters defter izi (hash-zincir korunur — operasyon_defter_ekle ile)
                try:
                    operasyon_defter_ekle(
                        cur, d_sube, "URUN_SEVK_IPTAL",
                        "MERKEZ deneme siparişi silindi — stok geri alındı: "
                        + (", ".join(ozet_kalem[:8]) or "—") + f" | talep {tid}",
                        ref_event_id=d.get("id"),
                    )
                except Exception:
                    pass

        # 2) Bağlı izole kayıtlar (belge_talep FK'sız — elle sil)
        try:
            cur.execute("DELETE FROM belge_talep WHERE talep_id=%s", (tid,))
        except Exception:
            pass
        # 3) Yolda stok satırları
        try:
            cur.execute("DELETE FROM stok_yolda WHERE siparis_talep_id=%s", (tid,))
        except Exception:
            pass
        # 4) Talebi sil → toptanci_siparis ON DELETE CASCADE ile düşer
        cur.execute("DELETE FROM siparis_talep WHERE id=%s", (tid,))
        audit(cur, "siparis_talep", tid, "OPS_MERKEZ_TEST_TEMIZLE")

    return {"ok": True, "talep_id": tid, "stok_geri_alinan": geri_alinan,
            "stok_geri_al": stok_geri_al}


@router.post("/siparis/toptanci-siparis/{ts_id}/whatsapp-yeniden-gonder")
def ops_toptanci_siparis_wa_yeniden(ts_id: str):
    """Daha önce WhatsApp'tan gönderilememiş (wa_durum='hata') bir toptancı
    siparişini tedarikçiye TEKRAR yollar. Başarısız olursa Green API'nin tam
    hatasını döner (anlık hata / kota teşhisi için)."""
    sid = (ts_id or "").strip()
    if not sid:
        raise HTTPException(400, "toptanci_siparis_id zorunlu")
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT ts.id, ts.tedarikci_ad, ts.tedarikci_tel, ts.kalemler,
                   ts.not_aciklama, ts.durum, s.ad AS sube_adi
            FROM toptanci_siparis ts
            LEFT JOIN subeler s ON s.id = ts.sube_id
            WHERE ts.id = %s
            FOR UPDATE OF ts
            """,
            (sid,),
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Toptancı siparişi bulunamadı")
        t = dict(row)
        if str(t.get("durum") or "") == "iptal":
            raise HTTPException(400, "İptal edilmiş sipariş — yeniden gönderilemez")
        tel = str(t.get("tedarikci_tel") or "").strip()
        if not tel:
            raise HTTPException(
                400,
                f"'{t.get('tedarikci_ad') or 'Tedarikçi'}' için telefon yok — "
                "Tedarikçiler ekranından numara ekleyin.",
            )
        kalemler = _td_jliste(t.get("kalemler"))
        mesaj = _toptanci_siparis_wa_mesaj(
            t.get("tedarikci_ad"), t.get("sube_adi"), kalemler, t.get("not_aciklama")
        )
        try:
            from whatsapp_bildirim import whatsapp_gonder_numara
            wa = whatsapp_gonder_numara(tel, mesaj)
        except Exception as e:
            wa = {"basarili": False, "mesaj_id": None, "chat_id": "", "hata": str(e)[:120]}
        cur.execute(
            """
            UPDATE toptanci_siparis
            SET wa_gonderim_ts = NOW(), wa_mesaj_id = %s, wa_chat_id = %s, wa_durum = %s
            WHERE id = %s
            """,
            (
                wa.get("mesaj_id"), wa.get("chat_id"),
                ("gonderildi" if wa.get("basarili") else "hata"), sid,
            ),
        )
    return {
        "ok": bool(wa.get("basarili")),
        "tedarikci_ad": t.get("tedarikci_ad"),
        "telefon": tel,
        "mesaj_id": wa.get("mesaj_id"),
        "hata": wa.get("hata"),
    }


def _td_jliste(v: Any) -> List[Dict[str, Any]]:
    if isinstance(v, list):
        return v
    if isinstance(v, str):
        try:
            x = json.loads(v)
            return x if isinstance(x, list) else []
        except Exception:
            return []
    return []


@router.get("/tedarik-dosyasi")
def ops_tedarik_dosyasi_liste(gun: int = 30, sube_id: Optional[str] = None, limit: int = 100):
    """Tedarik Dosyası INDEX: toptancı zinciri olan siparişler (özet rozetlerle).
    Her satır = bir siparişin tüm hikâyesinin kısa hali (detay ayrı endpoint)."""
    gun_i = max(1, min(180, int(gun or 30)))
    lim = max(1, min(300, int(limit or 100)))
    out: List[Dict[str, Any]] = []
    with db() as (conn, cur):
        try:
            from fatura_api import _ensure_tablolar as _f_ensure
            _f_ensure(cur)
        except Exception:
            pass
        params: List[Any] = [gun_i]
        kos = "t.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')"
        if sube_id:
            kos += " AND t.sube_id=%s"
            params.append(sube_id.strip())
        try:
            cur.execute(
                f"""
                SELECT t.id, s.ad AS sube_adi, t.tarih, t.durum, t.kabul_durum,
                       (SELECT string_agg(DISTINCT ts.tedarikci_ad, ', ')
                          FROM toptanci_siparis ts WHERE ts.talep_id=t.id) AS tedarikciler,
                       (SELECT count(*) FROM tedarikci_fatura f
                          WHERE f.siparis_talep_id=t.id) AS fatura_say
                FROM siparis_talep t JOIN subeler s ON s.id=t.sube_id
                WHERE {kos}
                  AND EXISTS (SELECT 1 FROM toptanci_siparis ts WHERE ts.talep_id=t.id)
                ORDER BY t.olusturma DESC NULLS LAST
                LIMIT %s
                """,
                tuple(params + [lim]),
            )
            rows = cur.fetchall() or []
        except Exception:
            rows = []
        for r in rows:
            d = dict(r)
            out.append({
                "talep_id": str(d.get("id")),
                "sube_adi": str(d.get("sube_adi") or ""),
                "tarih": str(d.get("tarih") or ""),
                "durum": str(d.get("durum") or ""),
                "kabul_durum": str(d.get("kabul_durum") or ""),
                "tedarikciler": str(d.get("tedarikciler") or "—"),
                "fatura_say": int(d.get("fatura_say") or 0),
            })
    return {"dosyalar": out, "toplam": len(out)}


@router.get("/tedarik-dosyasi/{talep_id}")
def ops_tedarik_dosyasi_detay(talep_id: str):
    """Tek siparişin TÜM zinciri tek yerde: N1 talep · N2 toptancı siparişleri ·
    kabul farkı (N3↔N4) · fatura(lar) + foto + OCR fiyat/zam."""
    tid = (talep_id or "").strip()
    if not tid:
        raise HTTPException(400, "talep_id zorunlu")
    with db() as (conn, cur):
        try:
            from fatura_api import _ensure_tablolar as _f_ensure
            _f_ensure(cur)
        except Exception:
            pass
        cur.execute(
            """
            SELECT t.id, t.sube_id, s.ad AS sube_adi, t.tarih, t.durum, t.kabul_durum,
                   t.kalemler, t.kabul_ts, t.kabul_personel_ad
            FROM siparis_talep t JOIN subeler s ON s.id=t.sube_id
            WHERE t.id=%s
            """,
            (tid,),
        )
        tr = cur.fetchone()
        if not tr:
            raise HTTPException(404, "Sipariş bulunamadı")
        t = dict(tr)
        n1 = [
            {"urun_ad": str(k.get("urun_ad") or ""), "adet": int(k.get("adet") or 0)}
            for k in _td_jliste(t.get("kalemler"))
            if isinstance(k, dict) and str(k.get("urun_ad") or "").strip()
        ]
        # N2: toptancı siparişleri (tedarikçi başına)
        cur.execute(
            """
            SELECT id, tedarikci_ad, kalemler, durum, wa_durum, wa_gonderim_ts, teslim_ts
            FROM toptanci_siparis WHERE talep_id=%s ORDER BY olusturma
            """,
            (tid,),
        )
        n2 = []
        for r in cur.fetchall() or []:
            d = dict(r)
            n2.append({
                "id": str(d.get("id")),
                "tedarikci_ad": str(d.get("tedarikci_ad") or "—"),
                "kalemler": [
                    {"urun_ad": str(k.get("urun_ad") or ""), "adet": int(k.get("adet") or 0)}
                    for k in _td_jliste(d.get("kalemler"))
                    if isinstance(k, dict) and str(k.get("urun_ad") or "").strip()
                ],
                "durum": str(d.get("durum") or ""),
                "wa_gonderildi": (str(d.get("wa_durum") or "") == "gonderildi"),
                "teslim_alindi": bool(d.get("teslim_ts")),
            })
        # Kabul farkı (N3↔N4): TOPTANCI_KABUL_FARKI uyarısından
        kabul_farklar: List[Dict[str, Any]] = []
        try:
            cur.execute(
                """
                SELECT detay_json FROM sube_operasyon_uyari
                WHERE tip='TOPTANCI_KABUL_FARKI'
                  AND detay_json->>'siparis_talep_id'=%s
                ORDER BY tarih DESC
                """,
                (tid,),
            )
            for r in cur.fetchall() or []:
                dj = dict(r).get("detay_json")
                if isinstance(dj, str):
                    try:
                        dj = json.loads(dj)
                    except Exception:
                        dj = {}
                if isinstance(dj, dict):
                    kabul_farklar.extend(dj.get("uyusmazlik_satirlar") or [])
        except Exception:
            kabul_farklar = []
        # N3: fatura(lar) + OCR kalem + foto var mı
        faturalar = []
        try:
            cur.execute(
                """
                SELECT id, tedarikci_ad, fatura_tarih, toplam_tutar, durum,
                       (foto IS NOT NULL) AS foto_var
                FROM tedarikci_fatura WHERE siparis_talep_id=%s ORDER BY olusturma DESC
                """,
                (tid,),
            )
            for fr in cur.fetchall() or []:
                f = dict(fr)
                fid = str(f.get("id"))
                cur.execute(
                    """
                    SELECT ocr_ad, adet, birim_fiyat, eslesen_stok_kodu
                    FROM tedarikci_fatura_kalem WHERE fatura_id=%s ORDER BY sira
                    """,
                    (fid,),
                )
                fk = [
                    {
                        "ocr_ad": kd.get("ocr_ad"),
                        "adet": kd.get("adet"),
                        "birim_fiyat": kd.get("birim_fiyat"),
                        "eslesen_stok_kodu": kd.get("eslesen_stok_kodu"),
                    }
                    for kd in (dict(x) for x in (cur.fetchall() or []))
                ]
                faturalar.append({
                    "id": fid,
                    "tedarikci_ad": str(f.get("tedarikci_ad") or "—"),
                    "fatura_tarih": str(f.get("fatura_tarih") or ""),
                    "toplam_tutar": f.get("toplam_tutar"),
                    "durum": str(f.get("durum") or ""),
                    "foto_var": bool(f.get("foto_var")),
                    "kalemler": fk,
                })
        except Exception:
            faturalar = []
    return {
        "talep_id": tid,
        "sube_adi": str(t.get("sube_adi") or ""),
        "tarih": str(t.get("tarih") or ""),
        "durum": str(t.get("durum") or ""),
        "kabul_durum": str(t.get("kabul_durum") or ""),
        "kabul_ts": str(t.get("kabul_ts") or ""),
        "n1_talep": n1,
        "n2_siparisler": n2,
        "kabul_farklar": kabul_farklar,
        "faturalar": faturalar,
    }


def _toptanci_liste_tarih_araligi(
    donem: Optional[str],
    gun: int,
    tarih: Optional[str],
) -> Tuple[Optional[date], Optional[date], int, str]:
    """(tarih_bas, tarih_bit, gun_etiket, donem_norm) — tek gün için bas=bit."""
    bugun = bugun_tr()
    d = (donem or "").strip().lower()
    if not d:
        gun_i = max(1, min(120, int(gun or 30)))
        return bugun - timedelta(days=gun_i - 1), bugun, gun_i, f"gun_{gun_i}"

    if d == "bugun":
        return bugun, bugun, 1, "bugun"
    if d == "dun":
        dun = bugun - timedelta(days=1)
        return dun, dun, 1, "dun"
    if d in ("tarih", "ozel"):
        t_raw = (tarih or "").strip()[:10]
        try:
            t = date.fromisoformat(t_raw)
        except ValueError:
            raise HTTPException(400, "Geçerli tarih girin (YYYY-MM-DD)")
        return t, t, 1, "tarih"

    if d.startswith("gun_"):
        try:
            gun_i = max(1, min(120, int(d.split("_", 1)[1])))
        except (IndexError, ValueError):
            gun_i = max(1, min(120, int(gun or 30)))
        return bugun - timedelta(days=gun_i - 1), bugun, gun_i, d

    gun_i = max(1, min(120, int(gun or 30)))
    return bugun - timedelta(days=gun_i - 1), bugun, gun_i, f"gun_{gun_i}"


def _toptanci_kalem_kategori(it: Dict[str, Any]) -> str:
    kategori_kod = str(it.get("kategori_kod") or "").strip()
    if not kategori_kod:
        kk = str(it.get("kalem_kodu") or "").strip()
        if kk.startswith("katalog__") and "__" in kk:
            parts = kk.split("__")
            if len(parts) >= 3:
                kategori_kod = str(parts[1] or "").strip()
    return kategori_kod or "genel"


@router.get("/siparis/toptanci-listesi")
def ops_siparis_toptanci_listesi(
    gun: int = 30,
    limit: int = 800,
    format: str = "json",  # json | csv
    donem: Optional[str] = Query(None, description="bugun | dun | gun_7 | gun_14 | gun_30 | gun_60 | tarih"),
    tarih: Optional[str] = Query(None, description="YYYY-MM-DD — donem=tarih iken"),
    sirala: str = Query("en_son", description="en_son | eski | adet_azalan | urun"),
):
    tarih_bas, tarih_bit, gun_i, donem_norm = _toptanci_liste_tarih_araligi(donem, gun, tarih)
    lim_i = max(1, min(5000, int(limit or 800)))
    sirala_norm = (sirala or "en_son").strip().lower()
    if sirala_norm not in ("en_son", "eski", "adet_azalan", "urun"):
        raise HTTPException(400, "sirala: en_son | eski | adet_azalan | urun")

    with db() as (conn, cur):
        cur.execute(
            """
            SELECT d.id, d.sube_id, s.ad AS sube_adi, d.tarih, d.bildirim_saati,
                   d.olay_ts, d.aciklama
            FROM operasyon_defter d
            LEFT JOIN subeler s ON s.id = d.sube_id
            WHERE d.etiket='SIPARIS_TOPTANCI_YONLENDIRME'
              AND d.tarih >= %s::date
              AND d.tarih <= %s::date
            ORDER BY d.olay_ts DESC NULLS LAST, d.tarih DESC, d.id DESC
            LIMIT %s
            """,
            (tarih_bas, tarih_bit, lim_i),
        )
        rows = [dict(r) for r in cur.fetchall()]

    agregat: Dict[str, Dict[str, Any]] = {}
    gonderimler: List[Dict[str, Any]] = []
    for r in rows:
        payload = _ops_json_prefix_parse(r.get("aciklama"), "TOPTANCI_SIPARIS_JSON:")
        if not payload:
            continue
        kalemler = payload.get("kalemler") if isinstance(payload.get("kalemler"), list) else []
        kalem_satirlari: List[Dict[str, Any]] = []
        toplam_adet_g = 0
        for it in kalemler:
            if not isinstance(it, dict):
                continue
            urun_ad = str(it.get("urun_ad") or "").strip()
            kategori_kod = _toptanci_kalem_kategori(it)
            try:
                adet = max(0, int(it.get("adet") or 0))
            except Exception:
                adet = 0
            if not urun_ad or adet <= 0:
                continue
            kalem_satirlari.append({"urun_ad": urun_ad, "adet": adet, "kategori_kod": kategori_kod})
            toplam_adet_g += adet
            key = f"{kategori_kod}::{urun_ad}"
            if key not in agregat:
                agregat[key] = {
                    "kategori_kod": kategori_kod,
                    "urun_ad": urun_ad,
                    "toplam_adet": 0,
                    "kayit_sayisi": 0,
                    "son_tarih": str(r.get("tarih") or ""),
                }
            agregat[key]["toplam_adet"] += adet
            agregat[key]["kayit_sayisi"] += 1
            trh = str(r.get("tarih") or "")
            if trh and trh > str(agregat[key].get("son_tarih") or ""):
                agregat[key]["son_tarih"] = trh

        if not kalem_satirlari:
            continue
        olay_ts = r.get("olay_ts")
        olay_iso = ""
        if olay_ts is not None:
            try:
                olay_iso = olay_ts.isoformat() if hasattr(olay_ts, "isoformat") else str(olay_ts)
            except Exception:
                olay_iso = str(olay_ts)
        gonderimler.append(
            {
                "id": str(r.get("id") or ""),
                "tarih": str(r.get("tarih") or ""),
                "saat": str(r.get("bildirim_saati") or "")[:8] or None,
                "olay_ts": olay_iso or None,
                "sube_adi": str(r.get("sube_adi") or "").strip() or None,
                "tedarikci_ad": (str(payload.get("tedarikci_ad") or "").strip() or None),
                "not_aciklama": (str(payload.get("not_aciklama") or "").strip() or None),
                "talep_id": (str(payload.get("talep_id") or "").strip() or None),
                "kalem_sayisi": len(kalem_satirlari),
                "toplam_adet": toplam_adet_g,
                "kalemler": kalem_satirlari,
                "kalemler_ozet": " · ".join(
                    f"{k['urun_ad']} ×{k['adet']}" for k in kalem_satirlari[:5]
                )
                + (" …" if len(kalem_satirlari) > 5 else ""),
            }
        )

    if sirala_norm == "eski":
        gonderimler.sort(
            key=lambda x: (str(x.get("tarih") or ""), str(x.get("olay_ts") or ""), str(x.get("id") or "")),
        )
    elif sirala_norm == "adet_azalan":
        gonderimler.sort(
            key=lambda x: (int(x.get("toplam_adet") or 0), str(x.get("olay_ts") or "")),
            reverse=True,
        )
    elif sirala_norm == "urun":
        gonderimler.sort(key=lambda x: (str(x.get("kalemler_ozet") or "").lower(), str(x.get("olay_ts") or "")))
    # en_son: SQL sırası korunur (zaten DESC)

    satirlar = list(agregat.values())
    if sirala_norm == "en_son":
        satirlar.sort(
            key=lambda x: (str(x.get("son_tarih") or ""), str(x.get("urun_ad") or "")),
            reverse=True,
        )
    elif sirala_norm == "eski":
        satirlar.sort(key=lambda x: (str(x.get("son_tarih") or ""), str(x.get("urun_ad") or "")))
    elif sirala_norm == "adet_azalan":
        satirlar.sort(key=lambda x: (-int(x.get("toplam_adet") or 0), str(x.get("urun_ad") or "")))
    else:
        satirlar.sort(key=lambda x: (str(x.get("urun_ad") or "").lower(), str(x.get("kategori_kod") or "")))

    filtre_etiket = {
        "bugun": "Bugün",
        "dun": "Dün",
        "tarih": str(tarih_bas),
    }.get(donem_norm, f"Son {gun_i} gün")
    if donem_norm == "tarih":
        filtre_etiket = str(tarih_bas)

    if format.lower() == "csv":
        sio = io.StringIO()
        wr = csv.writer(sio)
        wr.writerow(["kategori_kod", "urun_ad", "toplam_adet", "kayit_sayisi", "son_tarih"])
        for s in satirlar:
            wr.writerow([s.get("kategori_kod"), s.get("urun_ad"), s.get("toplam_adet"), s.get("kayit_sayisi"), s.get("son_tarih")])
        csv_text = sio.getvalue()
        return Response(
            content="\ufeff" + csv_text,
            media_type="text/csv; charset=utf-8",
            headers={"Content-Disposition": f'attachment; filename="toptanci_siparisleri_{bugun_tr()}.csv"'},
        )

    return {
        "gun": gun_i,
        "donem": donem_norm,
        "tarih_bas": str(tarih_bas),
        "tarih_bit": str(tarih_bit),
        "filtre_etiket": filtre_etiket,
        "sirala": sirala_norm,
        "toplam_kayit": len(gonderimler),
        "toplam_satir": len(satirlar),
        "satirlar": satirlar,
        "gonderimler": gonderimler,
    }


@router.get("/urun-gelis-gecmisi")
def ops_urun_gelis_gecmisi(urun: str, gun: int = Query(365, ge=7, le=730), sube_id: Optional[str] = None):
    """ÜRÜN GELİŞ TAKİBİ (2026-08-16, sahip: "vanilya milkshake toptancıdan geliş
    tarihleri… bunu takip edebilecek bir sistem kurmalıyız").

    Kaynak: toptanci_siparis (tedarikçiye giden gönderim + teslim_ts kabul anı).
    ŞUBELER ARASI SEVKİYAT DAHİL DEĞİL — o ayrı akış (sevkiyat kulesi); burada
    yalnız TOPTANCIDAN gelenler sayılır. Kalem eşleşmesi ad-içerir (LIKE);
    miktar anahtarı kayıtlarda 'adet' ya da 'miktar' olabilir → ikisi de okunur.

    Dönüş: gelisler (teslim alınmış, tarih desc) + bekleyenler (gönderildi,
    teslim yok) + istatistik (adet, ilk/son geliş, ortalama aralık gün,
    şube ve tedarikçi kırılımı). Ortalama aralık FARKLI GÜNLER üzerinden
    hesaplanır (aynı güne iki teslim aralığı 0 gün diye ortalamayı ezmesin).
    """
    q = (urun or "").strip()
    if len(q) < 2:
        raise HTTPException(400, "urun zorunlu (en az 2 karakter)")
    gun_i = max(7, min(730, int(gun or 365)))
    sid = (sube_id or "").strip() or None
    with db() as (conn, cur):
        params: list = [gun_i, f"%{q.lower()}%"]
        kos = ""
        if sid:
            kos = "AND ts.sube_id = %s"
            params.append(sid)
        cur.execute(
            f"""
            SELECT ts.id, ts.sube_id, COALESCE(s.ad, '—') AS sube_adi,
                   COALESCE(ts.tedarikci_ad, '—') AS tedarikci_ad,
                   ts.durum, COALESCE(ts.kaynak, 'sube') AS kaynak,
                   (ts.teslim_ts AT TIME ZONE 'Europe/Istanbul') AS teslim_ts,
                   (ts.olusturma AT TIME ZONE 'Europe/Istanbul') AS siparis_ts,
                   k->>'urun_ad' AS urun_ad,
                   COALESCE(NULLIF(k->>'adet',''), NULLIF(k->>'miktar','')) AS miktar,
                   COALESCE(k->>'birim','') AS birim
            FROM toptanci_siparis ts
            CROSS JOIN LATERAL jsonb_array_elements(ts.kalemler) k
            LEFT JOIN subeler s ON s.id = ts.sube_id
            WHERE ts.durum <> 'iptal'
              AND ts.olusturma >= now() - (%s * INTERVAL '1 day')
              AND lower(coalesce(k->>'urun_ad','')) LIKE %s
              {kos}
            ORDER BY COALESCE(ts.teslim_ts, ts.olusturma) DESC
            """,
            params,
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]

    gelisler: List[Dict[str, Any]] = []
    bekleyenler: List[Dict[str, Any]] = []
    sube_kirilim: Dict[str, Dict[str, Any]] = {}
    ted_kirilim: Dict[str, int] = {}
    for d in rows:
        kayit = {
            "urun_ad": d.get("urun_ad"),
            "miktar": d.get("miktar"),
            "birim": d.get("birim") or "",
            "sube": d.get("sube_adi"),
            "tedarikci": d.get("tedarikci_ad"),
            "siparis_ts": str(d.get("siparis_ts") or "")[:16].replace("T", " "),
            # sipariş kaynağı: 'sube' = şube ekranından, 'merkez' = patron/cep
            "kaynak": str(d.get("kaynak") or "sube"),
        }
        ts_ = d.get("teslim_ts")
        if ts_ is not None:
            kayit["gelis_ts"] = str(ts_)[:16].replace("T", " ")
            kayit["gelis_tarih"] = str(ts_)[:10]
            gelisler.append(kayit)
            sk = sube_kirilim.setdefault(str(d.get("sube_adi")), {"adet": 0, "son": ""})
            sk["adet"] += 1
            if kayit["gelis_tarih"] > sk["son"]:
                sk["son"] = kayit["gelis_tarih"]
            ted_kirilim[str(d.get("tedarikci_ad"))] = ted_kirilim.get(str(d.get("tedarikci_ad")), 0) + 1
        else:
            kayit["durum"] = str(d.get("durum") or "")
            bekleyenler.append(kayit)

    # Ortalama geliş aralığı — FARKLI teslim günleri üzerinden.
    gunler = sorted({g["gelis_tarih"] for g in gelisler})
    ort_aralik = None
    if len(gunler) >= 2:
        from datetime import date as _d
        farklar = []
        for a, b in zip(gunler, gunler[1:]):
            try:
                farklar.append((_d.fromisoformat(b) - _d.fromisoformat(a)).days)
            except Exception:
                pass
        if farklar:
            ort_aralik = round(sum(farklar) / len(farklar), 1)

    return {
        "sorgu": q,
        "gun": gun_i,
        "kaynak_notu": "toptancı sipariş/kabul kayıtları — şubeler arası sevkiyat DAHİL DEĞİL",
        "gelisler": gelisler,
        "bekleyenler": bekleyenler,
        "istatistik": {
            "gelis_adet": len(gelisler),
            "farkli_gun": len(gunler),
            "ilk_gelis": gunler[0] if gunler else None,
            "son_gelis": gunler[-1] if gunler else None,
            "ortalama_aralik_gun": ort_aralik,
            "sube_kirilim": sube_kirilim,
            "tedarikci_kirilim": ted_kirilim,
        },
    }


@router.get("/toptanci-teslimler")
def ops_toptanci_teslimler(gun: int = 30, sube_id: Optional[str] = None):
    """
    Şubelere tedarikçiden gelen teslimler — operasyon_defter URUN_SEVK kayıtları.
    aciklama alanı 'URUN_SEVK_JSON:{...}' biçiminde; tedarikci + kalem verisi JSON'dan parse edilir.
    Döner: sube bazlı gruplu liste (son 5 teslim detay, toplam sayı, son tarih).
    """
    gun = max(1, min(365, int(gun or 30)))
    sid_filtre = (sube_id or "").strip() or None
    with db() as (conn, cur):
        params: list = [gun]
        sube_kosul = ""
        if sid_filtre:
            sube_kosul = "AND d.sube_id = %s"
            params.append(sid_filtre)
        cur.execute(
            f"""
            SELECT d.sube_id, s.ad AS sube_adi,
                   d.id, d.tarih, d.olay_ts, d.aciklama
            FROM operasyon_defter d
            JOIN subeler s ON s.id = d.sube_id
            WHERE d.etiket = 'URUN_SEVK'
              AND d.tarih >= (CURRENT_DATE - (%s * INTERVAL '1 day'))
              AND d.aciklama LIKE 'URUN_SEVK_JSON:%%'
              {sube_kosul}
            ORDER BY d.olay_ts DESC
            """,
            params,
        )
        rows = cur.fetchall() or []

    subeler_dict: dict = {}
    for r in rows:
        d = dict(r)
        sid = str(d.get("sube_id") or "")
        if not sid:
            continue
        if sid not in subeler_dict:
            # En son teslim: olay_ts ZATEN DESC sıralı geldiği için ilk gelen son'dur
            _olay = str(d.get("olay_ts") or "")[:16].replace("T", " ")
            subeler_dict[sid] = {
                "sube_id": sid,
                "sube_adi": str(d.get("sube_adi") or sid),
                "toplam": 0,
                "son_tarih": str(d.get("tarih") or ""),
                "son_olay_ts": _olay,  # saat dahil — kart başlığında bunu göster
                "teslimler": [],
            }
        aciklama = str(d.get("aciklama") or "")
        payload: dict = {}
        try:
            json_str = aciklama[len("URUN_SEVK_JSON:"):].split(" | ")[0].strip()
            payload = json.loads(json_str)
        except Exception:
            pass
        kalemler_raw = payload.get("kalemler") or []
        delta_raw = payload.get("delta") or {}
        # Kalem listesi: önce açık kalemler, sonra delta'dan standard kalemler
        kalemler_out = []
        for it in (kalemler_raw if isinstance(kalemler_raw, list) else []):
            if not isinstance(it, dict):
                continue
            ad = str(it.get("urun_ad") or it.get("ad") or "").strip()
            adet = max(0, int(it.get("adet") or 0))
            if ad and adet > 0:
                kalemler_out.append({"ad": ad, "adet": adet})
        if not kalemler_out and isinstance(delta_raw, dict):
            for k, v in delta_raw.items():
                try:
                    adet = max(0, int(v or 0))
                except (TypeError, ValueError):
                    adet = 0
                if adet > 0:
                    kalemler_out.append({"ad": str(k), "adet": adet})
        teslim = {
            "id": str(d.get("id") or ""),
            "tarih": str(d.get("tarih") or ""),
            "olay_ts": str(d.get("olay_ts") or "")[:16].replace("T", " "),
            "tedarikci": str(payload.get("tedarikci") or "").strip() or "—",
            "tedarikci_id": str(payload.get("tedarikci_id") or "").strip(),
            "kalemler": kalemler_out,
            "teslim_durumu": str(payload.get("teslim_durumu") or "tam_geldi"),
        }
        subeler_dict[sid]["toplam"] += 1
        if len(subeler_dict[sid]["teslimler"]) < 5:
            subeler_dict[sid]["teslimler"].append(teslim)

    result = sorted(subeler_dict.values(), key=lambda x: x["son_tarih"], reverse=True)
    return {"gun": gun, "toplam_sube": len(result), "subeler": result}


@router.get("/teslim-alimlari")
def ops_teslim_alimlari(gun: int = 14, sube_id: Optional[str] = None, limit: int = 200):
    """Şube 'Ürün Teslim Al' kayıtları — KRONOLOJİK (saat saat) düz feed.
    Sipariş verilmeden gelen (siparişsiz) teslimler de DAHİL; 'siparisli' bayrağı ayırır."""
    gun_i = max(1, min(120, int(gun or 14)))
    lim = max(1, min(500, int(limit or 200)))
    sid = (sube_id or "").strip() or None
    out: List[Dict[str, Any]] = []
    with db() as (conn, cur):
        params: List[Any] = [gun_i]
        kos = ""
        if sid:
            kos = "AND d.sube_id=%s"
            params.append(sid)
        cur.execute(
            f"""
            SELECT d.id, d.sube_id, s.ad AS sube_adi, d.tarih, d.olay_ts,
                   d.aciklama, d.personel_ad
            FROM operasyon_defter d JOIN subeler s ON s.id=d.sube_id
            WHERE d.etiket='URUN_SEVK' AND d.aciklama LIKE 'URUN_SEVK_JSON:%%'
              AND d.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day') {kos}
            ORDER BY d.olay_ts DESC
            LIMIT %s
            """,
            tuple(params + [lim]),
        )
        for r in cur.fetchall() or []:
            d = dict(r)
            payload: Dict[str, Any] = {}
            try:
                js = str(d.get("aciklama") or "")[len("URUN_SEVK_JSON:"):].split(" | ")[0].strip()
                payload = json.loads(js)
            except Exception:
                payload = {}
            kalemler = []
            for it in (payload.get("kalemler") or []):
                if isinstance(it, dict):
                    ad = str(it.get("urun_ad") or it.get("ad") or "").strip()
                    adet = max(0, int(it.get("adet") or 0))
                    if ad and adet > 0:
                        kalemler.append({"ad": ad, "adet": adet})
            out.append({
                "id": str(d.get("id") or ""),
                "tarih": str(d.get("tarih") or ""),
                "olay_ts": str(d.get("olay_ts") or "")[:16].replace("T", " "),
                "sube_adi": str(d.get("sube_adi") or ""),
                "tedarikci": str(payload.get("tedarikci") or "").strip() or "—",
                "kalemler": kalemler,
                "teslim_durumu": str(payload.get("teslim_durumu") or "tam_geldi"),
                "siparisli": bool(str(payload.get("siparis_talep_id") or "").strip()),
                "personel_ad": str(d.get("personel_ad") or "").strip() or None,
            })
    return {"gun": gun_i, "toplam": len(out), "teslimler": out}


@router.get("/tedarikci-guvenilirlik")
def ops_tedarikci_guvenilirlik(gun: int = 60):
    """ÇOK-ŞUBE TEDARİKÇİ PATERNİ (Akıllı Denetim 'görme' bağı): kabul farklarını
    (TOPTANCI_KABUL_FARKI) tedarikçi başına toplar; FARKLI ŞUBE sayısı = iknanın
    anahtarı. >=2 şube → 'tedarikçi paterni' (şube masum); tek şube → belirsiz
    (şube/sayım da olabilir). Tek olaydan suçlama yok (küçük-N)."""
    gun_i = max(7, min(365, int(gun or 60)))
    out: List[Dict[str, Any]] = []
    with db() as (conn, cur):
        try:
            cur.execute(
                """
                SELECT COALESCE(u.detay_json->>'tedarikci_ad','—') AS tedarikci,
                       COALESCE(sb.ad, u.sube_id) AS sube_adi, u.detay_json
                FROM sube_operasyon_uyari u LEFT JOIN subeler sb ON sb.id = u.sube_id
                WHERE u.tip = 'TOPTANCI_KABUL_FARKI'
                  AND u.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
                """,
                (gun_i,),
            )
            rows = [dict(r) for r in (cur.fetchall() or [])]
        except Exception:
            rows = []
        agg: Dict[str, Dict[str, Any]] = {}
        for r in rows:
            ted = str(r.get("tedarikci") or "—").strip() or "—"
            if ted == "—":
                continue
            a = agg.setdefault(ted, {"olay": 0, "subeler": set(), "eksik": 0, "fazla": 0})
            a["olay"] += 1
            a["subeler"].add(str(r.get("sube_adi") or "?"))
            dj = r.get("detay_json")
            if isinstance(dj, str):
                try:
                    dj = json.loads(dj)
                except Exception:
                    dj = {}
            if isinstance(dj, dict):
                for srow in (dj.get("uyusmazlik_satirlar") or []):
                    try:
                        f = int(srow.get("fark") or 0)
                    except Exception:
                        f = 0
                    if f < 0:
                        a["eksik"] += -f
                    elif f > 0:
                        a["fazla"] += f
        for ted, a in agg.items():
            sube_n = len(a["subeler"])
            out.append({
                "tedarikci": ted,
                "olay_sayisi": a["olay"],
                "sube_sayisi": sube_n,
                "subeler": sorted(a["subeler"]),
                "eksik_toplam": a["eksik"],
                "fazla_toplam": a["fazla"],
                # 'görme': >=2 şube → tedarikçi paterni; tek şube → belirsiz
                "sonuc": ("tedarikci_paterni" if sube_n >= 2 else "tek_sube"),
            })
        out.sort(key=lambda x: (-x["sube_sayisi"], -x["olay_sayisi"]))
    return {"gun": gun_i, "tedarikciler": out}


@router.get("/subeler/depolar")
def ops_subeler_depolar():
    """
    Sevkiyat hazırlık / Stok Disiplin «hedef depo» seçimi.
    Önceden yalnızca sube_tipi=depo/karma/… idi; mağaza panelleri çoğunlukla `normal`
    olduğu için liste boş kalıyordu. Tüm aktif şubeler döner; sıralama önce klasik depo tipleri.
    """
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT id, ad, sube_tipi, aktif
            FROM subeler
            WHERE aktif=TRUE
            ORDER BY
              CASE COALESCE(NULLIF(TRIM(sube_tipi), ''), 'normal')
                WHEN 'depo' THEN 0
                WHEN 'sevkiyat' THEN 1
                WHEN 'merkez' THEN 2
                WHEN 'karma' THEN 3
                WHEN 'normal' THEN 4
                ELSE 5
              END,
              ad
            """
        )
        rows = []
        for r in cur.fetchall():
            d = dict(r)
            st = str(d.get("sube_tipi") or "normal")
            if st == "sevkiyat":
                st = "depo"
            elif st == "merkez":
                st = "karma"
            d["sube_tipi"] = st
            rows.append(d)
    return {"satirlar": rows}


@router.get("/siparis/sevkiyat-subeler-ozet")
def ops_siparis_sevkiyat_subeler_ozet(gun: int = 90):
    """
    Aktif şubeler için (hedef depo olarak atanan) sevkiyat taleplerinin durum özeti.
    Merkez «Sevkiyat Hazırlama» ekranında şube bazlı yük / tamamlanan takibi için.
    """
    gun_sayi = max(1, min(365, int(gun or 90)))
    expr = sevkiyat_durumu_sql_expr("t")
    with db() as (conn, cur):
        cur.execute(
            f"""
            WITH agg AS (
                SELECT
                    COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)::text AS depo_id,
                    COUNT(*)::int AS toplam,
                    COUNT(*) FILTER (
                        WHERE ({expr}) IN ('depoda_hazirlaniyor', 'kismi_hazirlandi', 'hazirlaniyor')
                    )::int AS hazirlikta,
                    COUNT(*) FILTER (WHERE ({expr}) = 'gonderildi')::int AS gonderildi,
                    COUNT(*) FILTER (WHERE ({expr}) = 'teslim_edildi')::int AS teslim_edildi,
                    MAX(t.tarih)::text AS son_talep_tarih
                FROM siparis_talep t
                WHERE COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id) IS NOT NULL
                  AND t.tarih >= (CURRENT_DATE - (%s::int * INTERVAL '1 day'))
                GROUP BY COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)
            )
            SELECT s.id::text AS depo_sube_id,
                   s.ad AS depo_sube_adi,
                   COALESCE(NULLIF(TRIM(s.sube_tipi), ''), 'normal') AS sube_tipi,
                   COALESCE(a.toplam, 0)::int AS toplam,
                   COALESCE(a.hazirlikta, 0)::int AS hazirlikta,
                   COALESCE(a.gonderildi, 0)::int AS gonderildi,
                   COALESCE(a.teslim_edildi, 0)::int AS teslim_edildi,
                   a.son_talep_tarih
            FROM subeler s
            LEFT JOIN agg a ON a.depo_id = s.id::text
            WHERE s.aktif = TRUE
            ORDER BY
              CASE WHEN COALESCE(a.toplam, 0) > 0 THEN 0 ELSE 1 END,
              COALESCE(a.hazirlikta, 0) DESC,
              (COALESCE(a.gonderildi, 0) + COALESCE(a.teslim_edildi, 0)) DESC,
              s.ad
            """,
            (gun_sayi,),
        )
        satirlar = [dict(r) for r in (cur.fetchall() or [])]
    return {"gun_sayi": gun_sayi, "satirlar": satirlar}


@router.get("/vade-disiplini")
def ops_vade_disiplini(gun: int = 90):
    """
    SALT-OKUR DUYU 5/6 (2026-07-29): VADE DİSİPLİNİ — ödenmiş planlarda vade
    tarihi ↔ gerçek ödeme tarihi farkı. Ham veri ZATEN kayıtlı (odeme_plani
    tarih + odeme_tarihi); bu uç yalnız türetir. Koç Finans vakası tam bu kör
    noktadandı: gecikme DESENİ görünmüyordu.
    Not: tedarikçi bazlı kırılım v1'de yok — plan satırında yapılandırılmış
    tedarikçi kimliği taşınmıyor (açıklama serbest metin, uydurma gruplanmaz).
    """
    g = max(7, min(365, int(gun or 90)))
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT tarih, odeme_tarihi, odenecek_tutar, aciklama, kaynak_tablo
            FROM odeme_plani
            WHERE durum = 'odendi' AND odeme_tarihi IS NOT NULL AND tarih IS NOT NULL
              AND odeme_tarihi >= CURRENT_DATE - (%s * INTERVAL '1 day')
            ORDER BY odeme_tarihi DESC
            LIMIT 800
            """,
            (g,),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    gecikmeler = []
    en_gecler = []
    erken = zamaninda = hafif = gec = 0
    for r in rows:
        try:
            fark = (r["odeme_tarihi"] - r["tarih"]).days
        except (TypeError, AttributeError):
            continue
        gecikmeler.append(fark)
        if fark < 0:
            erken += 1
        elif fark == 0:
            zamaninda += 1
        elif fark <= 3:
            hafif += 1
        else:
            gec += 1
            en_gecler.append({
                "aciklama": str(r.get("aciklama") or "")[:70],
                "vade": str(r.get("tarih") or ""),
                "odeme": str(r.get("odeme_tarihi") or ""),
                "gecikme_gun": fark,
                "tutar": float(r.get("odenecek_tutar") or 0),
                "kaynak": r.get("kaynak_tablo"),
            })
    en_gecler.sort(key=lambda x: -x["gecikme_gun"])
    return {
        "kesit_gun": g,
        "odenen_plan": len(gecikmeler),
        "ort_gecikme_gun": round(sum(gecikmeler) / len(gecikmeler), 1) if gecikmeler else None,
        "erken": erken, "zamaninda": zamaninda, "hafif_gec": hafif, "gec": gec,
        "gec_orani_yuzde": round(gec / len(gecikmeler) * 100, 1) if gecikmeler else None,
        "en_gecler": en_gecler[:8],
        "not": "GÖZLEMDİR: plan vadesi ↔ gerçek ödeme günü. Negatif=erken. "
               "Tedarikçi kırılımı v1'de yok (plan satırında yapılandırılmış "
               "kimlik taşınmıyor — uydurma gruplanmaz).",
    }


# ─── DUYU 3/6: BULGU YAŞAM DÖNGÜSÜ (2026-07-29) ──────────────────────────────
# Motor bulgularına insan kararı işareti: append-only defter (UPDATE/DELETE ucu
# YOK). Yanlış alarm oranı ve çözüm süresi ancak bu işaretlerle ölçülebilir —
# motorun isabetini ölçmeden motor öğrenemezdi (kör nokta kapanıyor).
def _ensure_bulgu_izi(cur):
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS duyu_bulgu_izi (
            id         TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
            bulgu_ref  TEXT NOT NULL,           -- truth:{sube_id}:{tarih}:{ana_tani}
            kaynak     TEXT NOT NULL DEFAULT 'truth',
            karar      TEXT NOT NULL CHECK (karar IN ('goruldu','cozuldu','yanlis_alarm')),
            not_metin  TEXT,
            olusturma  TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
        """
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_bulgu_izi_ref ON duyu_bulgu_izi (bulgu_ref, olusturma DESC)"
    )
    # DUYU 4/6 (öneri akıbeti): 'uygulandi' kararı eklendi — CHECK idempotent tazelenir
    # ⚠️ 'ertelendi' EKLENDİ (2026-08-26): defter yalnız KABUL edilen öneriyi
    # öğreniyordu. "Uyguladım" ve "yanlış alarm" vardı ama "gördüm, şimdi değil"
    # YOKTU. Bu asimetri iki şeyi birden bozuyordu:
    #   1) Öneri-only doktrini yarım kalıyordu — sistem önerir, insan karar
    #      verir; ama kararın "hayır/sonra" hâli hiçbir yere yazılamıyordu.
    #   2) Aynı öneri her sabah yeniden önüne geliyordu ve SUSTURULAMIYORDU —
    #      kapanamayan alarm, uyarı bütçesi doktrininin ihlali.
    # Yeni sistem KURULMADI: defter zaten append-only ve "son satır geçerli";
    # ertelemenin ihtiyaç duyduğu şeklin tamamı hazırdı, eksik olan tek şey
    # bu enum değeriydi.
    cur.execute("ALTER TABLE duyu_bulgu_izi DROP CONSTRAINT IF EXISTS duyu_bulgu_izi_karar_check")
    cur.execute(
        "ALTER TABLE duyu_bulgu_izi ADD CONSTRAINT duyu_bulgu_izi_karar_check "
        "CHECK (karar IN ('goruldu','cozuldu','yanlis_alarm','uygulandi','ertelendi'))"
    )


@router.post("/bulgu-izi")
def ops_bulgu_izi_yaz(body: dict = None):
    """İnsan kararı işareti (append-only): {bulgu_ref, karar, not_metin?}.
    Karar: goruldu | cozuldu | yanlis_alarm | uygulandi | ertelendi.
    Silme/güncelleme YOK — fikir değişirse yeni satır atılır, son satır geçerli.

    ⚠️ 'ertelendi' bir SUSTURMA DEĞİL, bir KARAR kaydıdır: öneri kaybolmaz,
    "sahip gördü ve şimdi değil dedi" bilgisi deftere yazılır. Sistemin
    öğrenmesi için "hayır"lar da "evet"ler kadar gereklidir."""
    body = body or {}
    ref = str(body.get("bulgu_ref") or "").strip()
    karar = str(body.get("karar") or "").strip()
    if not ref or karar not in ("goruldu", "cozuldu", "yanlis_alarm", "uygulandi", "ertelendi"):
        raise HTTPException(
            400, "bulgu_ref + karar (goruldu|cozuldu|yanlis_alarm|uygulandi|ertelendi) zorunlu")
    notm = (str(body.get("not_metin") or "").strip() or None)
    with db() as (conn, cur):
        _ensure_bulgu_izi(cur)
        cur.execute(
            "INSERT INTO duyu_bulgu_izi (bulgu_ref, karar, not_metin) VALUES (%s,%s,%s) RETURNING id",
            (ref, karar, notm),
        )
        rid = (cur.fetchone() or {}).get("id")
    return {"ok": True, "id": rid}


@router.get("/bulgu-izi/ozet")
def ops_bulgu_izi_ozet(gun: int = 30):
    """SALT-OKUR: işaret defteri özeti — bulgu başına SON karar geçerli.
    Çözüm süresi: bulgu_ref içindeki tarihten (gece 00:30 doğum varsayımı)
    'cozuldu' işaretine kadar geçen saat — varsayım etikette açık."""
    g = max(1, min(365, int(gun or 30)))
    with db() as (conn, cur):
        _ensure_bulgu_izi(cur)
        cur.execute(
            """
            SELECT DISTINCT ON (bulgu_ref) bulgu_ref, karar, olusturma
            FROM duyu_bulgu_izi
            WHERE olusturma >= NOW() - (%s * INTERVAL '1 day')
            ORDER BY bulgu_ref, olusturma DESC
            """,
            (g,),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    sayilar = {"goruldu": 0, "cozuldu": 0, "yanlis_alarm": 0, "uygulandi": 0}
    cozum_saatleri = []
    isaretli_refler = []
    for r in rows:
        sayilar[r["karar"]] = sayilar.get(r["karar"], 0) + 1
        isaretli_refler.append({"ref": r["bulgu_ref"], "karar": r["karar"]})
        if r["karar"] == "cozuldu":
            # ref: truth:{sube}:{YYYY-MM-DD}:{tani} → doğum ≈ tarih 00:30
            try:
                parcalar = str(r["bulgu_ref"]).split(":")
                tarih_s = next(p for p in parcalar if len(p) == 10 and p[4] == "-")
                from datetime import datetime, timezone, timedelta
                dogum = datetime.fromisoformat(tarih_s).replace(
                    hour=0, minute=30, tzinfo=timezone(timedelta(hours=3)))
                saat = (r["olusturma"] - dogum).total_seconds() / 3600.0
                if 0 <= saat <= 24 * 30:
                    cozum_saatleri.append(saat)
            except (StopIteration, ValueError, TypeError):
                pass
    kapali = sayilar["cozuldu"] + sayilar["yanlis_alarm"]
    return {
        "kesit_gun": g,
        "isaretli_bulgu": len(rows),
        "goruldu": sayilar["goruldu"],
        "cozulen": sayilar["cozuldu"],
        "yanlis_alarm": sayilar["yanlis_alarm"],
        "uygulanan": sayilar["uygulandi"],
        "yanlis_alarm_orani_yuzde": round(sayilar["yanlis_alarm"] / kapali * 100, 1) if kapali else None,
        "ort_cozum_saat": round(sum(cozum_saatleri) / len(cozum_saatleri), 1) if cozum_saatleri else None,
        "isaretli_refler": isaretli_refler[:200],
        "not": "Bulgu başına SON karar geçerli (append-only). Çözüm süresi gece "
               "00:30 doğum VARSAYIMIYLA hesaplanır — yaklaşıktır.",
    }


@router.get("/para-yolda")
def ops_para_yolda(gun: int = 14):
    """
    SALT-OKUR DUYU 2/6 (2026-07-29): PARA YOLDA — gün sonu kapanışı yapılmış
    (sube_operasyon_event KAPANIS, cevap_ts dolu) ama gun_sonu KASA TESLİMİ
    henüz kaydedilmemiş şube-günler + kapanış→teslim ortalama süresi.
    Ham veri ZATEN kayıtlı (kapanış cevap_ts / kasa_sayim / devir + kasa_teslim
    olusturma) — bu uç yalnız türetir, hiçbir şey yazmaz.
    """
    g = max(2, min(90, int(gun or 14)))
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT e.sube_id::text AS sube_id, s.ad AS sube_adi, e.tarih,
                   e.cevap_ts, e.kasa_sayim, e.teslim, e.devir
            FROM sube_operasyon_event e
            JOIN subeler s ON s.id = e.sube_id
            WHERE e.tip = 'KAPANIS' AND e.durum = 'tamamlandi'
              AND e.cevap_ts IS NOT NULL
              AND e.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
            ORDER BY e.cevap_ts
            """,
            (g,),
        )
        kapanislar = [dict(r) for r in (cur.fetchall() or [])]
        cur.execute(
            """
            SELECT sube_id::text AS sube_id, tarih, tutar, olusturma
            FROM kasa_teslim
            WHERE teslim_turu = 'gun_sonu'
              AND tarih >= CURRENT_DATE - ((%s + 2) * INTERVAL '1 day')
            ORDER BY olusturma
            """,
            (g,),
        )
        teslimler = [dict(r) for r in (cur.fetchall() or [])]

    kullanildi = set()
    sureler = []
    bekleyenler = []
    eslesen = 0
    from datetime import datetime, timezone
    simdi = datetime.now(timezone.utc)

    # ⚠️ TZ TUZAĞI (2026-08-07 denetimi) — SESSİZ SIFIR EŞLEŞME:
    # `cevap_ts` (sube_operasyon_event) saat dilimi BİLGİSİZ (naive) gelebiliyor,
    # `kasa_teslim.olusturma` ise timestamptz (aware). Python'da naive ile aware
    # datetime karşılaştırması TypeError atar; alttaki `except TypeError: continue`
    # bunu YUTUYORDU → hiçbir teslim hiçbir kapanışa bağlanamıyordu.
    # CANLI SONUÇ: 25 kapanış · 129 teslim kaydı (766.214 ₺) varken "0 eşleşen,
    # 25 gecikmiş, 92.650 ₺ yolda" yazıyordu — para teslim edilmiş olduğu hâlde
    # ekran "teslim edilmedi" diyordu. Sahte alarmın en pahalı türü.
    # ÇÖZÜM: karşılaştırmadan ÖNCE iki tarafı da aware'a çek (tek yardımcı).
    def _aware(d):
        if d is None:
            return None
        try:
            return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
        except AttributeError:
            return None

    for k in kapanislar:
        kts = _aware(k.get("cevap_ts"))
        es = None
        for i, t in enumerate(teslimler):
            if i in kullanildi or t["sube_id"] != k["sube_id"]:
                continue
            tts = _aware(t.get("olusturma"))
            try:
                if tts and kts and tts >= kts and (tts - kts).total_seconds() <= 3 * 86400:
                    es = (i, t)
                    break
            except TypeError:
                continue
        if es:
            kullanildi.add(es[0])
            eslesen += 1
            try:
                saat = (_aware(es[1]["olusturma"]) - kts).total_seconds() / 3600.0
                if 0 <= saat <= 72:
                    sureler.append(round(saat, 1))
            except TypeError:
                pass
        else:
            try:
                kref = kts if kts.tzinfo else kts.replace(tzinfo=timezone.utc)
                gecen = round((simdi - kref).total_seconds() / 3600.0, 1)
            except Exception:
                gecen = None
            beklenen = None
            try:
                if k.get("teslim") is not None:
                    beklenen = float(k["teslim"])
                elif k.get("kasa_sayim") is not None:
                    beklenen = max(0.0, float(k["kasa_sayim"]) - float(k.get("devir") or 0))
            except (TypeError, ValueError):
                beklenen = None
            bekleyenler.append({
                "sube": k.get("sube_adi"),
                "tarih": str(k.get("tarih") or ""),
                "kapanis_saat": str(kts or "")[11:16],
                "gecen_saat": gecen,
                # ertesi gün öğlene kadar teslim olağan — 18 saati aşan gecikmiştir
                "gecikmis": bool(gecen is not None and gecen > 18),
                "beklenen_tutar": beklenen,
            })

    def _ort(xs):
        return round(sum(xs) / len(xs), 1) if xs else None

    def _medyan(xs):
        if not xs:
            return None
        ss = sorted(xs)
        n = len(ss)
        return round(ss[n // 2] if n % 2 else (ss[n // 2 - 1] + ss[n // 2]) / 2, 1)

    bekleyenler.sort(key=lambda x: -(x.get("gecen_saat") or 0))
    return {
        "kesit_gun": g,
        "kapanis_adet": len(kapanislar),
        "eslesen_adet": eslesen,
        "bekleyen_adet": len(bekleyenler),
        "gecikmis_adet": sum(1 for b in bekleyenler if b["gecikmis"]),
        "ort_teslim_saat": _ort(sureler),
        "medyan_teslim_saat": _medyan(sureler),
        "bekleyenler": bekleyenler[:20],
        "not": "GÖZLEMDİR: kapanış cevap_ts ↔ gun_sonu teslim olusturma eşlemesi. "
               "Ertesi gün öğlene kadar teslim olağandır; 18 saati aşan 'gecikmiş' "
               "sayılır. Yazma yok — hüküm insanın.",
    }


@router.get("/siparis/sevkiyat-hiz")
def ops_siparis_sevkiyat_hiz(gun: int = 30):
    """
    SALT-OKUR DUYU (2026-07-29, sahip: 'ölçebilir halde olup ölçmediğimiz'):
    SEVKİYAT HIZI — siparis_talep'te ZATEN duran zaman damgalarından türetilir
    (olusturma → tahsis_ts → sevkiyat_ts → kabul_ts). Hiçbir şey yazmaz.
    Cevapladığı soru: 'talepten teslime kaç saat; hangi depo yavaş?'
    """
    g = max(1, min(365, int(gun or 30)))
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT t.id, s.ad AS sube_adi,
                   COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)::text AS depo_id,
                   d.ad AS depo_adi,
                   t.olusturma, t.tahsis_ts, t.sevkiyat_ts, t.kabul_ts
            FROM siparis_talep t
            JOIN subeler s ON s.id = t.sube_id
            LEFT JOIN subeler d ON d.id = COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)
            WHERE t.kabul_ts IS NOT NULL AND t.olusturma IS NOT NULL
              AND t.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
            ORDER BY t.kabul_ts DESC
            LIMIT 300
            """,
            (g,),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]

    def _saat(a, b):
        try:
            if a and b:
                v = (b - a).total_seconds() / 3600.0
                return round(v, 1) if 0 <= v <= 24 * 30 else None  # negatif/absürt damga elenir
        except Exception:
            return None
        return None

    toplamlar = []
    hazirliklar = []
    yollar = []
    depo_map = {}
    son = []
    for r in rows:
        top = _saat(r.get("olusturma"), r.get("kabul_ts"))
        haz = _saat(r.get("tahsis_ts") or r.get("olusturma"), r.get("sevkiyat_ts"))
        yol = _saat(r.get("sevkiyat_ts"), r.get("kabul_ts"))
        if top is None:
            continue
        toplamlar.append(top)
        if haz is not None:
            hazirliklar.append(haz)
        if yol is not None:
            yollar.append(yol)
        dk = r.get("depo_id") or "-"
        dm = depo_map.setdefault(dk, {"depo_adi": r.get("depo_adi") or "—", "n": 0, "toplam": 0.0})
        dm["n"] += 1
        dm["toplam"] += top
        if len(son) < 10:
            son.append({
                "sube": r.get("sube_adi"), "depo": r.get("depo_adi") or "—",
                "toplam_saat": top, "hazirlik_saat": haz, "yol_saat": yol,
                "kabul": str(r.get("kabul_ts") or "")[:16],
            })

    def _ort(xs):
        return round(sum(xs) / len(xs), 1) if xs else None

    def _medyan(xs):
        if not xs:
            return None
        ss = sorted(xs)
        n = len(ss)
        return round(ss[n // 2] if n % 2 else (ss[n // 2 - 1] + ss[n // 2]) / 2, 1)

    depolar = [
        {"depo_adi": v["depo_adi"], "teslim": v["n"], "ort_saat": round(v["toplam"] / v["n"], 1)}
        for v in depo_map.values() if v["n"] > 0
    ]
    depolar.sort(key=lambda x: -x["ort_saat"])
    return {
        "kesit_gun": g,
        "teslim_adet": len(toplamlar),
        "ort_saat": _ort(toplamlar),
        "medyan_saat": _medyan(toplamlar),
        "hazirlik_ort_saat": _ort(hazirliklar),
        "yol_ort_saat": _ort(yollar),
        "depolar": depolar,
        "son_teslimler": son,
        "not": "GÖZLEMDİR: mevcut zaman damgalarından türetilir; damgası eksik "
               "kayıt hesaba girmez (dürüst boşluk). Yazma yok.",
    }


@router.get("/siparis/sevkiyat-listesi")
def ops_siparis_sevkiyat_listesi(
    sevkiyat_sube_id: Optional[str] = None,
    durum: str = "hazirlaniyor",
    gun: int = 7,
):
    gun_sayi = max(1, min(365, int(gun or 7)))
    sid = (sevkiyat_sube_id or "").strip() or None
    durum_f = (durum or "hazirlaniyor").strip().lower()
    if durum_f == "all":
        durum_f = "all"
    elif durum_f not in ("hazirlaniyor", "depoda_hazirlaniyor", "kismi_hazirlandi", "gonderildi", "teslim_edildi"):
        raise HTTPException(400, "durum: hazirlaniyor | depoda_hazirlaniyor | kismi_hazirlandi | gonderildi | teslim_edildi | all")
    with db() as (conn, cur):
        qp: List[Any] = [gun_sayi]
        q = f"""
            SELECT t.id, t.sube_id, s.ad AS sube_adi, t.tarih, t.durum,
                   t.personel_id, t.personel_ad, t.bildirim_saati, t.not_aciklama,
                   t.kalemler,
                   COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id) AS hedef_depo_sube_id,
                   ss.ad AS hedef_depo_sube_adi,
                   {SD_T} AS sevkiyat_durumu,
                   COALESCE(NULLIF(TRIM(t.sevkiyat_notu), ''), t.sevkiyat_notlari) AS sevkiyat_notu,
                   t.kalem_durumlari, t.olusturma, t.sevkiyat_ts, t.sevkiyat_personel_ad,
                   COALESCE(t.kalem_surum, 0) AS kalem_surum
            FROM siparis_talep t
            JOIN subeler s ON s.id = t.sube_id
            LEFT JOIN subeler ss ON ss.id = COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)
            WHERE t.tarih >= (CURRENT_DATE - (%s * INTERVAL '1 day'))
              AND COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id) IS NOT NULL
        """
        if sid:
            q += " AND COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)=%s"
            qp.append(sid)
        if durum_f != "all":
            if durum_f == "hazirlaniyor":
                q += f" AND {sevkiyat_durumu_sql_expr('t')} IN ('depoda_hazirlaniyor', 'kismi_hazirlandi', 'hazirlaniyor')"
            else:
                q += f" AND {sevkiyat_durumu_sql_expr('t')}=%s"
                qp.append(durum_f)
        liste_limit = 500 if gun_sayi <= 120 else 400
        q += f" ORDER BY t.tarih DESC, t.olusturma DESC NULLS LAST, t.id LIMIT {liste_limit}"
        cur.execute(q, qp)
        rows: List[Dict[str, Any]] = []
        for r in cur.fetchall():
            d = dict(r)
            d["sevkiyat_sube_id"] = d.get("hedef_depo_sube_id")
            d["sevkiyat_sube_adi"] = d.get("hedef_depo_sube_adi")
            d["sevkiyat_durum"] = d.get("sevkiyat_durumu")
            d["sevkiyat_notlari"] = d.get("sevkiyat_notu")
            for k in ("tarih", "olusturma"):
                if d.get(k):
                    d[k] = str(d[k])
            if d.get("sevkiyat_ts"):
                d["sevkiyat_ts"] = str(d["sevkiyat_ts"])
            for k in ("kalemler", "kalem_durumlari"):
                v = d.get(k)
                if isinstance(v, str):
                    try:
                        v = json.loads(v)
                    except Exception:
                        v = []
                if not isinstance(v, list):
                    v = []
                d[k] = v
            # ══════════════════════════════════════════════════════════════
            # 📉 KAYNAK DEPODA STOK VAR MI (canli olcum, 2026-08-30)
            # ══════════════════════════════════════════════════════════════
            # Olcum: 59 stok alarminin 55'i TEMA kaynakli. TEMA sistemde
            # SIFIR gorunen mali fiziksel olarak gonderiyor (Redbull TEMA=0
            # iken 72 adet sevk edilmis). Cikista dusulecek sey bulunamiyor,
            # alici depo artiyor -> STOK SISIYOR.
            # Kok neden kodda degil KAYITTA: TEMA'ya gelen mallarin GIRISI
            # kaydedilmemis (7 zombi siparisin hepsi TEMA'ydi — mal geldi,
            # kabul edilemedi, giris hic olusmadi).
            # Bu blok ONLEYICI: depocu sevk etmeden ONCE "sistemde stok yok"
            # uyarisini gorsun. Sevki ENGELLEMEZ — mal fiziksel olarak
            # oradaysa gonderilmeli; ama korlemesine gonderilmemeli.
            try:
                _dsid = str(d.get("hedef_depo_sube_id") or "").strip()
                _kodlar = []
                for _it in (d.get("kalemler") or []):
                    if not isinstance(_it, dict):
                        continue
                    for _c in (str(_it.get("kalem_kodu") or "").strip(),
                               str(_it.get("urun_id") or "").strip(),
                               str(_it.get("urun_ad") or "").strip()):
                        if _c and _c not in _kodlar:
                            _kodlar.append(_c)
                _kaynak_stok = {}
                if _dsid and _kodlar:
                    # ⚠️ SIRA HAYATİ (2026-08-31, Fable denetimi): stok sonucu ARAYA
                    # başka sorgu girmeden HEMEN okunmalı. Aynı cursor'da ikinci
                    # execute() birincinin sonucunu düşürür; önceki sürümde birim
                    # sorgusu araya giriyordu ve alttaki fetchall() tükenmiş birim
                    # sonucundan BOŞ liste alıyordu. Sonuç: _kaynak_stok HER ZAMAN
                    # boş → sevk ekranı depoda 100 adet varken bile her kaleme
                    # "sistemde stok kaydı yok, stok şişer" kırmızısı basıyordu.
                    # Yani uyarı gerçeği değil, kendi hatasını gösteriyordu.
                    cur.execute(
                        "SELECT kalem_kodu, COALESCE(mevcut_adet, 0) AS m "
                        "FROM sube_depo_stok WHERE sube_id = %s AND kalem_kodu = ANY(%s)",
                        (_dsid, _kodlar),
                    )
                    for _sr in cur.fetchall() or []:
                        _sd2 = dict(_sr)
                        _kaynak_stok[str(_sd2.get("kalem_kodu") or "")] = int(_sd2.get("m") or 0)

                    _birim_map = {}
                    try:
                        # 📏 Kalemin birimi — depocu "3 ne?" diye sormasin.
                        cur.execute(
                            "SELECT id, ad, birim, koli_ic_adet FROM siparis_urun "
                            "WHERE id = ANY(%s) OR LOWER(TRIM(ad)) = ANY(%s)",
                            (_kodlar, [k.lower().strip() for k in _kodlar]),
                        )
                        for _br in cur.fetchall() or []:
                            _b = dict(_br)
                            for _key in (str(_b.get("id") or ""), str(_b.get("ad") or "").lower().strip()):
                                if _key:
                                    _birim_map[_key] = (_b.get("birim"), _b.get("koli_ic_adet"))
                    except Exception:
                        _birim_map = {}
                for _it in (d.get("kalemler") or []):
                    if not isinstance(_it, dict):
                        continue
                    _bulundu = None
                    for _c in (str(_it.get("kalem_kodu") or "").strip(),
                               str(_it.get("urun_id") or "").strip(),
                               str(_it.get("urun_ad") or "").strip()):
                        if _c and _c in _kaynak_stok:
                            _bulundu = _kaynak_stok[_c]
                            break
                    # ⚠️ None = KAYIT YOK (0 adet var DEGIL) — ekran ayirsin.
                    _it["kaynak_depo_mevcut"] = _bulundu
                    _it["kaynak_depo_kayit_var"] = _bulundu is not None
                    # 📏 Birim: BOS ise None kalir — ekran "birim
                    # belirtilmemis" der, sessizce "adet" VARSAYMAZ.
                    _bi = None
                    for _c in (str(_it.get("urun_id") or "").strip(),
                               str(_it.get("urun_ad") or "").lower().strip()):
                        if _c and _c in _birim_map:
                            _bi = _birim_map[_c]; break
                    _it["birim"] = (_bi[0] if _bi else None) or None
                    _it["koli_ic_adet"] = (_bi[1] if _bi else None) or None
            except Exception:
                logger.warning("sevkiyat-listesi: kaynak depo stok okumasi yapilamadi")
            rows.append(d)
    return {
        "satirlar": rows,
        "durum": durum_f,
        "hedef_depo_sube_id": sid,
        "sevkiyat_sube_id": sid,
        "gun_sayi": gun_sayi,
        "liste_limit": liste_limit,
    }


@router.get("/siparis/depo-bekleyen")
def ops_siparis_depo_bekleyen(sube_id: str, gun: int = 15):
    sid = (sube_id or "").strip()
    if not sid:
        raise HTTPException(400, "sube_id zorunlu")
    gun_sayi = max(1, min(60, int(gun or 15)))
    with db() as (conn, cur):
        cur.execute(
            f"""
            SELECT t.id, t.sube_id, s.ad AS sube_adi, t.tarih, t.durum,
                   t.kalemler, t.kalem_durumlari,
                   {SD_T} AS sevkiyat_durumu,
                   COALESCE(NULLIF(TRIM(t.sevkiyat_notu), ''), t.sevkiyat_notlari) AS sevkiyat_notu,
                   t.olusturma
            FROM siparis_talep t
            JOIN subeler s ON s.id = t.sube_id
            WHERE COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)=%s
              AND t.tarih >= (CURRENT_DATE - (%s * INTERVAL '1 day'))
              AND {SD_T} IN ('depoda_hazirlaniyor', 'kismi_hazirlandi')
            ORDER BY t.tarih DESC, t.olusturma DESC NULLS LAST, t.id
            """,
            (sid, gun_sayi),
        )
        rows: List[Dict[str, Any]] = []
        for r in cur.fetchall():
            d = dict(r)
            for k in ("tarih", "olusturma"):
                if d.get(k):
                    d[k] = str(d[k])
            for k in ("kalemler", "kalem_durumlari"):
                v = d.get(k)
                if isinstance(v, str):
                    try:
                        v = json.loads(v)
                    except Exception:
                        v = []
                if not isinstance(v, list):
                    v = []
                d[k] = v
            rows.append(d)
    return {"satirlar": rows, "sube_id": sid, "gun_sayi": gun_sayi}


@router.get("/siparis/depo-sevkiyat-raporlari")
def ops_siparis_depo_sevkiyat_raporlari(
    gun: int = 21,
    limit: int = 40,
    hedef_depo_sube_id: Optional[str] = None,
):
    """Depo şubesinin işlediği kalem bazlı özet raporlar (isten / gönderilen / yok). Sevkiyat Hazırlama ekranından tarihsel takip."""
    gun_i = max(1, min(365, int(gun or 21)))
    lim = max(1, min(200, int(limit or 40)))
    hid = (hedef_depo_sube_id or "").strip() or None
    with db() as (conn, cur):
        qp: List[Any] = [gun_i]
        q_where_hid = ""
        if hid:
            q_where_hid = " AND COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)=%s"
            qp.append(hid)
        qp.append(lim)
        cur.execute(
            f"""
            SELECT t.id, t.sube_id, s.ad AS talep_sube_adi, t.tarih, t.durum,
                   {SD_T} AS sevkiyat_durumu,
                   COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id) AS hedef_depo_sube_id,
                   hd.ad AS hedef_depo_adi,
                   t.depo_sevkiyat_rapor_metni, t.depo_sevkiyat_rapor_ts,
                   t.depo_sevkiyat_rapor_uyari,
                   COALESCE(NULLIF(TRIM(t.sevkiyat_personel_ad), ''), '') AS depo_personel_ad
            FROM siparis_talep t
            JOIN subeler s ON s.id = t.sube_id
            LEFT JOIN subeler hd ON hd.id = COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)
            WHERE t.depo_sevkiyat_rapor_metni IS NOT NULL
              AND TRIM(t.depo_sevkiyat_rapor_metni) <> ''
              AND t.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
            {q_where_hid}
            ORDER BY t.depo_sevkiyat_rapor_ts DESC NULLS LAST, t.olusturma DESC NULLS LAST
            LIMIT %s
            """,
            tuple(qp),
        )
        raporlar: List[Dict[str, Any]] = []
        for r in cur.fetchall() or []:
            d = dict(r)
            if d.get("tarih"):
                d["tarih"] = str(d["tarih"])
            if d.get("depo_sevkiyat_rapor_ts"):
                d["depo_sevkiyat_rapor_ts"] = str(d["depo_sevkiyat_rapor_ts"])
            d["id"] = str(d.get("id") or "")
            raporlar.append(d)
    return {"gun": gun_i, "limit": lim, "hedef_depo_sube_id": hid, "raporlar": raporlar}


@router.get("/siparis/sevkiyat-uyumsuzluklar")
def ops_siparis_sevkiyat_uyumsuzluklar(gun: int = 30, limit: int = 100):
    """Sevk ve kabul adedi farklı olan satırlar (merkez çözüm ekranı)."""
    gun_i = max(1, min(120, int(gun or 30)))
    lim = max(1, min(300, int(limit or 100)))
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT
                y.id AS stok_yolda_id,
                y.siparis_talep_id,
                y.sube_id AS hedef_sube_id,
                hs.ad AS hedef_sube_adi,
                y.kalem_kodu,
                y.kalem_adi,
                COALESCE(y.sevk_adet, 0) AS sevk_adet,
                COALESCE(y.kabul_adet, 0) AS kabul_adet,
                y.durum,
                y.sevk_ts,
                y.kabul_ts,
                t.tarih,
                t.durum AS siparis_durum,
                COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id) AS kaynak_depo_sube_id,
                ks.ad AS kaynak_depo_sube_adi
            FROM stok_yolda y
            LEFT JOIN siparis_talep t ON t.id = y.siparis_talep_id
            LEFT JOIN subeler hs ON hs.id = y.sube_id
            LEFT JOIN subeler ks ON ks.id = COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)
            WHERE (t.tarih IS NULL OR t.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day'))
              AND COALESCE(y.sevk_adet, 0) <> COALESCE(y.kabul_adet, 0)
              AND y.durum IN ('kabul_uyusmazlik', 'kabul_edildi', 'yolda')
            ORDER BY t.tarih DESC NULLS LAST, y.sevk_ts DESC NULLS LAST
            LIMIT %s
            """,
            (gun_i, lim),
        )
        rows = [dict(r) for r in (cur.fetchall() or [])]
    for d in rows:
        if d.get("sevk_ts"):
            d["sevk_ts"] = str(d["sevk_ts"])
        if d.get("kabul_ts"):
            d["kabul_ts"] = str(d["kabul_ts"])
        if d.get("tarih"):
            d["tarih"] = str(d["tarih"])
        d["fark_adet"] = int(d.get("sevk_adet") or 0) - int(d.get("kabul_adet") or 0)
        d["siparis_iptal"] = (str(d.get("siparis_durum") or "").lower() == "iptal")
        d["kabul_yok"] = d.get("kabul_ts") is None
    return {"gun": gun_i, "limit": lim, "satirlar": rows}


@router.post("/siparis/sevkiyat-uyumsuzluk-coz")
def ops_siparis_sevkiyat_uyumsuzluk_coz(body: OpsSevkiyatUyumsuzlukCozBody):
    """
    Merkezden uyumsuz sevkiyat satırını tek adede uzlaştırır:
    - kaynak depo sevk adedi uzlaşır (gerekirse iade/ek düşüm),
    - hedef şube kabul adedi uzlaşır (gerekirse giriş/çıkış),
    - stok_yolda satırı uzlaşma durumuna geçer.
    """
    yid = (body.stok_yolda_id or "").strip()
    if not yid:
        raise HTTPException(400, "stok_yolda_id zorunlu")
    cozum = max(0, int(body.cozum_adet or 0))
    notu = (body.notu or "").strip() or None

    with db() as (conn, cur):
        # LEFT JOIN: siparis_talep silinmiş/iptal olsa bile stok_yolda satırı çözülebilsin
        cur.execute(
            """
            SELECT
                y.id,
                y.siparis_talep_id,
                y.sube_id AS hedef_sube_id,
                y.kalem_kodu,
                y.kalem_adi,
                COALESCE(y.sevk_adet, 0) AS sevk_adet,
                COALESCE(y.kabul_adet, 0) AS kabul_adet,
                COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id) AS kaynak_depo_sube_id,
                t.durum AS siparis_durum
            FROM stok_yolda y
            LEFT JOIN siparis_talep t ON t.id = y.siparis_talep_id
            WHERE y.id = %s
            FOR UPDATE OF y
            """,
            (yid,),
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Uyumsuz sevkiyat satırı bulunamadı")
        r = dict(row)
        kk = str(r.get("kalem_kodu") or "").strip()
        ka = str(r.get("kalem_adi") or kk).strip() or kk
        hedef_sid = str(r.get("hedef_sube_id") or "").strip()
        kaynak_sid = str(r.get("kaynak_depo_sube_id") or "").strip()
        onceki_sevk = int(r.get("sevk_adet") or 0)
        onceki_kabul = int(r.get("kabul_adet") or 0)

        # Kaynak depoda sevk düzeltmesi: çözüm adedine göre farkı geri ekle / ek düş.
        kaynak_delta = cozum - onceki_sevk
        if kaynak_sid and kk and kaynak_delta != 0:
            kaynak_onceki = _stok_onceki_adet(cur, kaynak_sid, kk)
            if kaynak_delta > 0:
                # daha fazla sevk kabul edildi: kaynak depodan ek düş.
                cur.execute(
                    """
                    UPDATE sube_depo_stok
                    SET mevcut_adet = GREATEST(0, COALESCE(mevcut_adet, 0) - %s),
                        guncelleme = NOW()
                    WHERE sube_id=%s AND kalem_kodu=%s
                    """,
                    (kaynak_delta, kaynak_sid, kk),
                )
                _stok_hareket_yaz(
                    cur, sube_id=kaynak_sid, kalem_kodu=kk, kalem_adi=ka,
                    hareket_turu="SEVK_CIKIS", miktar=-float(kaynak_delta),
                    onceki_miktar=kaynak_onceki,
                    sonraki_miktar=max(0.0, kaynak_onceki - kaynak_delta),
                    kaynak_tip="sevkiyat", kaynak_id=str(yid),
                    aciklama=f"Sevkiyat uzlaşma — {ka} x{kaynak_delta} kaynak depodan çıkış",
                )
            else:
                # daha az sevk uzlaşıldı: kaynak depoya iade ekle.
                cur.execute(
                    """
                    INSERT INTO sube_depo_stok
                        (id, sube_id, kalem_kodu, kalem_adi, mevcut_adet)
                    VALUES (%s, %s, %s, %s, %s)
                    ON CONFLICT (sube_id, kalem_kodu) DO UPDATE
                    SET mevcut_adet = COALESCE(sube_depo_stok.mevcut_adet, 0) + EXCLUDED.mevcut_adet,
                        kalem_adi = COALESCE(NULLIF(EXCLUDED.kalem_adi, ''), sube_depo_stok.kalem_adi),
                        guncelleme = NOW()
                    """,
                    (str(uuid.uuid4()), kaynak_sid, kk, ka, abs(kaynak_delta)),
                )
                _stok_hareket_yaz(
                    cur, sube_id=kaynak_sid, kalem_kodu=kk, kalem_adi=ka,
                    hareket_turu="SEVK_UZLASMA", miktar=float(abs(kaynak_delta)),
                    onceki_miktar=kaynak_onceki,
                    sonraki_miktar=kaynak_onceki + abs(kaynak_delta),
                    kaynak_tip="sevkiyat", kaynak_id=str(yid),
                    aciklama=f"Sevkiyat uzlaşma iadesi — {ka} x{abs(kaynak_delta)} geri döndü",
                )

        # Hedef şubede kabul düzeltmesi: çözüm adedine göre giriş / geri düşüm.
        hedef_delta = cozum - onceki_kabul
        if hedef_sid and kk and hedef_delta != 0:
            hedef_onceki = _stok_onceki_adet(cur, hedef_sid, kk)
            if hedef_delta > 0:
                cur.execute(
                    """
                    INSERT INTO sube_depo_stok
                        (id, sube_id, kalem_kodu, kalem_adi, mevcut_adet)
                    VALUES (%s, %s, %s, %s, %s)
                    ON CONFLICT (sube_id, kalem_kodu) DO UPDATE
                    SET mevcut_adet = COALESCE(sube_depo_stok.mevcut_adet, 0) + EXCLUDED.mevcut_adet,
                        kalem_adi = COALESCE(NULLIF(EXCLUDED.kalem_adi, ''), sube_depo_stok.kalem_adi),
                        guncelleme = NOW()
                    """,
                    (str(uuid.uuid4()), hedef_sid, kk, ka, hedef_delta),
                )
                _stok_hareket_yaz(
                    cur, sube_id=hedef_sid, kalem_kodu=kk, kalem_adi=ka,
                    hareket_turu="SEVK_GIRIS", miktar=float(hedef_delta),
                    onceki_miktar=hedef_onceki,
                    sonraki_miktar=hedef_onceki + hedef_delta,
                    kaynak_tip="sevkiyat", kaynak_id=str(yid),
                    aciklama=f"Sevkiyat kabulü — {ka} x{hedef_delta} şubeye giriş",
                )
            else:
                cur.execute(
                    """
                    UPDATE sube_depo_stok
                    SET mevcut_adet = GREATEST(0, COALESCE(mevcut_adet, 0) - %s),
                        guncelleme = NOW()
                    WHERE sube_id=%s AND kalem_kodu=%s
                    """,
                    (abs(hedef_delta), hedef_sid, kk),
                )
                _stok_hareket_yaz(
                    cur, sube_id=hedef_sid, kalem_kodu=kk, kalem_adi=ka,
                    hareket_turu="SEVK_UZLASMA", miktar=-float(abs(hedef_delta)),
                    onceki_miktar=hedef_onceki,
                    sonraki_miktar=max(0.0, hedef_onceki - abs(hedef_delta)),
                    kaynak_tip="sevkiyat", kaynak_id=str(yid),
                    aciklama=f"Sevkiyat uzlaşma düzeltme — {ka} x{abs(hedef_delta)} geri alındı",
                )

        cur.execute(
            """
            UPDATE stok_yolda
            SET sevk_adet = %s,
                kabul_adet = %s,
                durum = 'uzlasildi',
                kabul_ts = COALESCE(kabul_ts, NOW())
            WHERE id = %s
            """,
            (cozum, cozum, yid),
        )
        cur.execute(
            """
            SELECT COUNT(*)
            FROM stok_yolda
            WHERE siparis_talep_id=%s
              AND kabul_ts IS NOT NULL
              AND COALESCE(sevk_adet, 0) <> COALESCE(kabul_adet, 0)
              AND durum <> 'uzlasildi'
            """,
            (str(r.get("siparis_talep_id") or ""),),
        )
        kalan_uyumsuz = _fetch_int_count(cur)
        if kalan_uyumsuz <= 0:
            cur.execute(
                """
                UPDATE siparis_talep
                SET sevkiyat_durumu='teslim_edildi',
                    sevkiyat_durum='teslim_edildi',
                    durum='teslim_edildi'
                WHERE id=%s
                """,
                (str(r.get("siparis_talep_id") or ""),),
            )

        aciklama = (
            f"Sevkiyat uyumsuzluk uzlaştırıldı — yolda_id={yid} kalem={kk} "
            f"sevk:{onceki_sevk} kabul:{onceki_kabul} -> cozum:{cozum}"
            + (f" | not={notu}" if notu else "")
        )
        try:
            defter_sube = kaynak_sid or hedef_sid or _ops_sube_anchor(cur)
            operasyon_defter_ekle(
                cur,
                defter_sube,
                "OPS_SEVKIYAT_UYUSMAZLIK_COZ",
                aciklama[:900],
                bildirim_saati=dt_now_tr().strftime("%H:%M:%S"),
            )
        except Exception:
            pass
        # NOT: conn.commit() kaldırıldı — db() context manager başarılı çıkışta
        # otomatik commit yapar; buradaki explicit commit çift commit riskine yol açıyordu.

    return {
        "success": True,
        "stok_yolda_id": yid,
        "onceki_sevk_adet": onceki_sevk,
        "onceki_kabul_adet": onceki_kabul,
        "cozum_adet": cozum,
    }


class OpsTalepTahsisUyumsuzlukCozBody(BaseModel):
    """Sipariş↔Sevk (talep↔tahsis) uyumsuzluğunu uzlaştırır.
    cozum_adet: hem talep_adet hem tahsis_adet bu değere eşitlenir."""
    talep_id:   str
    urun_id:    str
    cozum_adet: int = 0
    notu:       Optional[str] = None


@router.post("/siparis/talep-tahsis-uyumsuzluk-coz")
def ops_siparis_talep_tahsis_uyumsuzluk_coz(body: OpsTalepTahsisUyumsuzlukCozBody):
    """
    Sipariş (talep) ile sevk/tahsis arasındaki uyumsuzluğu manuel uzlaştırır.

    Aksiyon:
      - siparis_talep.kalemler içinde urun_id'ye karşılık gelen kalemin
        istenen_adet'i cozum_adet'e güncellenir.
      - siparis_talep.kalem_durumlari içinde aynı kalemin tahsis_adet'i ve
        talep_adet'i cozum_adet'e güncellenir, durum='tam' + uzlasildi=True.
      - operasyon_defter'e audit log yazılır.
    """
    log = logging.getLogger(__name__)
    tid = (body.talep_id or "").strip()
    uid = (body.urun_id or "").strip()
    cozum = max(0, int(body.cozum_adet or 0))
    notu = (body.notu or "").strip() or None
    if not tid or not uid:
        raise HTTPException(400, "talep_id ve urun_id zorunlu")

    with db() as (conn, cur):
        cur.execute(
            """
            SELECT id, sube_id::text AS sube_id, kalemler, kalem_durumlari
            FROM siparis_talep
            WHERE id=%s
            FOR UPDATE
            """,
            (tid,),
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Sipariş talebi bulunamadı")
        r = dict(row)

        # Kalemler JSON parse
        kalemler = r.get("kalemler")
        if isinstance(kalemler, str):
            try:
                kalemler = json.loads(kalemler)
            except Exception:
                kalemler = []
        if not isinstance(kalemler, list):
            kalemler = []

        kalem_durumlari = r.get("kalem_durumlari")
        if isinstance(kalem_durumlari, str):
            try:
                kalem_durumlari = json.loads(kalem_durumlari)
            except Exception:
                kalem_durumlari = []
        if not isinstance(kalem_durumlari, list):
            kalem_durumlari = []

        # Eski değerler
        eski_istenen = 0
        kalem_adi = uid
        kalem_bulundu = False
        for k in kalemler:
            if not isinstance(k, dict):
                continue
            if str(k.get("urun_id") or "") == uid:
                eski_istenen = int(k.get("adet") or k.get("istenen_adet") or 0)
                kalem_adi = str(k.get("urun_ad") or k.get("ad") or uid)
                k["adet"] = cozum
                k["istenen_adet"] = cozum
                kalem_bulundu = True
                break

        eski_tahsis = 0
        durum_bulundu = False
        ts_now = dt_now_tr().isoformat()
        for kd in kalem_durumlari:
            if not isinstance(kd, dict):
                continue
            kk = str(kd.get("kalem_kodu") or kd.get("urun_id") or "")
            if kk == uid:
                eski_tahsis = int(kd.get("tahsis_adet") or 0)
                kd["talep_adet"] = cozum
                kd["tahsis_adet"] = cozum
                kd["durum"] = "tam"
                kd["uzlasildi"] = True
                kd["uzlasma_notu"] = notu
                kd["uzlasma_ts"] = ts_now
                durum_bulundu = True
                break
        if not durum_bulundu:
            kalem_durumlari.append({
                "kalem_kodu": uid,
                "urun_id": uid,
                "kalem_adi": kalem_adi,
                "talep_adet": cozum,
                "tahsis_adet": cozum,
                "durum": "tam",
                "uzlasildi": True,
                "uzlasma_notu": notu,
                "uzlasma_ts": ts_now,
            })

        if not kalem_bulundu and not durum_bulundu:
            raise HTTPException(404, f"Kalem bulunamadı: {uid}")

        cur.execute(
            """
            UPDATE siparis_talep
            SET kalemler=%s::jsonb,
                kalem_durumlari=%s::jsonb,
                -- 🔒 Bayat pencere kilidi
                kalem_surum = COALESCE(kalem_surum, 0) + 1,
                guncelleme=NOW()
            WHERE id=%s
            """,
            (
                json.dumps(kalemler, ensure_ascii=False),
                json.dumps(kalem_durumlari, ensure_ascii=False),
                tid,
            ),
        )

        # Audit log
        try:
            sube_sid = r.get("sube_id") or _ops_sube_anchor(cur)
            aciklama = (
                f"Sipariş-Tahsis uzlaşma | talep={tid} | kalem={kalem_adi}({uid}) | "
                f"istenen: {eski_istenen}→{cozum} | tahsis: {eski_tahsis}→{cozum}"
                + (f" | not={notu}" if notu else "")
            )
            operasyon_defter_ekle(
                cur,
                sube_sid,
                "OPS_SIPARIS_TAHSIS_UZLASMA",
                aciklama[:900],
                bildirim_saati=dt_now_tr().strftime("%H:%M:%S"),
            )
        except Exception:
            pass

    log.info("siparis-tahsis-uzlasma talep=%s urun=%s eski_istenen=%d eski_tahsis=%d cozum=%d",
             tid, uid, eski_istenen, eski_tahsis, cozum)

    return {
        "success": True,
        "talep_id": tid,
        "urun_id": uid,
        "kalem_adi": kalem_adi,
        "onceki_talep_adet": eski_istenen,
        "onceki_tahsis_adet": eski_tahsis,
        "cozum_adet": cozum,
    }


@router.post("/siparis/sevkiyat-guncelle")
def ops_siparis_sevkiyat_guncelle(body: OpsSiparisSevkiyatGuncelleBody):
    tid = (body.talep_id or "").strip()
    sevk_sid = (body.hedef_depo_sube_id or body.sevkiyat_sube_id or "").strip()
    if not tid or not sevk_sid:
        raise HTTPException(400, "talep_id ve hedef_depo_sube_id zorunlu")
    pin = (body.pin or "").strip()
    if pin and (len(pin) != 4 or not pin.isdigit()):
        raise HTTPException(400, "pin 4 haneli sayı olmalı")
    durumlar, bekleyen_var, kismi_var = sevkiyat_kalem_durumlari_normalize(body.kalem_durumlari)
    notu = (body.sevkiyat_notu or body.not_aciklama or "").strip() or None
    with db() as (conn, cur):
        ensure_stok_yolda_columns(cur)
        defter_sube = _ops_defter_sube_sevkiyat_hedef(sevk_sid, cur)
        return siparis_sevkiyat_kalem_guncelle_execute(
            cur,
            talep_id=tid,
            hedef_depo_sube_id=sevk_sid,
            durumlar=durumlar,
            bekleyen_var=bekleyen_var,
            kismi_var=kismi_var,
            notu=notu,
            personel_ad=(body.personel_ad or "").strip() or None,
            gonderildi=bool(body.gonderildi),
            defter_sube_id=defter_sube,
            beklenen_surum=body.kalem_surum,
        )


class OpsSiparisOzelIslemBody(BaseModel):
    talep_id: str
    islem: str  # katalog | tek_sefer | red
    not_aciklama: Optional[str] = None


@router.post("/siparis/ozel-islem")
def ops_siparis_ozel_islem(body: OpsSiparisOzelIslemBody):
    """
    bekliyor talep için:
    - katalog: ürünü kataloga ekle, talep onaylandi
    - tek_sefer: kataloga eklemeden siparis_talep satırı (tek seferlik sipariş)
    - red: reddedildi
    """
    tid = (body.talep_id or "").strip()
    islem = (body.islem or "").strip().lower()
    if islem not in ("katalog", "tek_sefer", "red"):
        raise HTTPException(400, "islem: katalog | tek_sefer | red")
    notu = (body.not_aciklama or "").strip() or None

    with db() as (conn, cur):
        cur.execute(
            "SELECT * FROM siparis_ozel_talep WHERE id=%s FOR UPDATE",
            (tid,),
        )
        raw = cur.fetchone()
        if not raw:
            raise HTTPException(404, "Talep bulunamadı")
        rd = dict(raw)
        if (rd.get("durum") or "") != "bekliyor":
            raise HTTPException(409, "Talep artık bekleyen durumda değil")
        sube_id = str(rd["sube_id"])
        saat = dt_now_tr().strftime("%H:%M:%S")
        from operasyon_defter import operasyon_defter_ekle

        if islem == "red":
            cur.execute(
                """
                UPDATE siparis_ozel_talep
                SET durum='reddedildi', islem_ts=NOW(), onaylayan_not=%s
                WHERE id=%s
                """,
                (notu, tid),
            )
            urun_adi = rd.get("urun_adi") or "—"
            red_mesaj = f"Özel ürün talebi reddedildi — {urun_adi}"
            if notu:
                red_mesaj += f" | Neden: {notu}"
            operasyon_defter_ekle(
                cur,
                sube_id,
                "SIPARIS_OZEL_RED",
                red_mesaj,
                bildirim_saati=saat,
            )
            # Şube uyarı listesine de bildirim düşür
            try:
                cur.execute(
                    """
                    INSERT INTO sube_operasyon_uyari
                        (id, sube_id, tarih, tip, seviye, mesaj)
                    VALUES (%s, %s, CURRENT_DATE, 'SIPARIS_RED', 'uyari', %s)
                    """,
                    (str(uuid.uuid4()), sube_id, red_mesaj),
                )
            except Exception:
                pass
            return {"success": True, "durum": "reddedildi"}

        if islem == "katalog":
            rur = _siparis_urun_insert(cur, str(rd["kategori_kod"]), str(rd["urun_adi"]))
            uid = str(rur["id"])
            audit(cur, "siparis_urun", uid, "OZEL_ONAY_KATALOG")
            cur.execute(
                """
                UPDATE siparis_ozel_talep
                SET durum='onaylandi', olusturulan_urun_id=%s,
                    islem_ts=NOW(), onaylayan_not=%s
                WHERE id=%s
                """,
                (uid, notu, tid),
            )
            operasyon_defter_ekle(
                cur,
                sube_id,
                "SIPARIS_OZEL_KATALOG",
                f"Özel talep kataloga alındı — {rd.get('urun_adi')} → ürün_id={uid}",
                bildirim_saati=saat,
            )
            return {"success": True, "durum": "onaylandi", "urun_id": uid, "urun_ad": rur.get("ad")}

        # tek_sefer
        stid = str(uuid.uuid4())
        adet = max(1, int(rd.get("adet") or 1))
        kalem = [
            {
                "kategori_id": str(rd["kategori_kod"]),
                "urun_id": f"ozel_{tid[:10]}",
                "urun_ad": str(rd["urun_adi"]),
                "adet": adet,
                "ozel_tek_sefer": True,
            }
        ]
        not_st = (
            f"Tek seferlik sipariş (özel talep {tid})"
            + (f" | {notu}" if notu else "")
        )
        cur.execute(
            """
            INSERT INTO siparis_talep
                (id, sube_id, tarih, durum, personel_id, personel_ad, bildirim_saati, not_aciklama, kalemler)
            VALUES (%s, %s, CURRENT_DATE, 'bekliyor', NULL, 'MERKEZ_TEK_SEFER', %s, %s, %s::jsonb)
            """,
            (stid, sube_id, saat, not_st, json.dumps(kalem, ensure_ascii=False)),
        )
        audit(cur, "siparis_talep", stid, "SIPARIS_TEK_SEFER")
        cur.execute(
            """
            UPDATE siparis_ozel_talep
            SET durum='tek_sefer', iliskili_talep_id=%s, islem_ts=NOW(), onaylayan_not=%s
            WHERE id=%s
            """,
            (stid, notu, tid),
        )
        operasyon_defter_ekle(
            cur,
            sube_id,
            "SIPARIS_OZEL_TEK_SEFER",
            f"Özel talep tek seferlik siparişe çevrildi — talep={tid} siparis_talep={stid}",
            bildirim_saati=saat,
        )
    return {"success": True, "durum": "tek_sefer", "siparis_talep_id": stid}


@router.get("/panel-ozet")
def ops_panel_ozet():
    """Operasyon merkezi modül kartları için hafif sayısal özet."""
    bugun = str(bugun_tr())
    with db() as (conn, cur):
        return _ops_panel_ozet_from_cur(cur, bugun)


@router.get("/hub-ozet")
def ops_hub_ozet(skip_alarms: bool = Query(False, description="True ise yalnızca sayılar; alarm satırları atlanır (proxy zaman aşımına karşı).")):
    """Hub sayıları + operasyon alarm satırları (tek istek, panel-ozet ile uyumlu)."""
    bugun = str(bugun_tr())
    log = logging.getLogger(__name__)
    try:
        with db() as (conn, cur):
            try:
                _siparis_gonderilmedi_kapat(cur)
            except Exception:
                log.exception("hub-ozet: gonderilmedi_kapat")
                try:
                    conn.rollback()
                except Exception:
                    pass
            try:
                oz = _ops_panel_ozet_from_cur(cur, bugun)
            except Exception:
                log.exception("hub-ozet: panel_ozet_from_cur")
                # Deadlock vb. sonrası txn aborted kalır; rollback olmadan sonraki SQL patlar (InFailedSqlTransaction)
                try:
                    conn.rollback()
                except Exception:
                    pass
                oz = _hub_ozet_fallback_panel()
            if skip_alarms:
                oz["alarm_satirlari"] = []
            else:
                try:
                    tum = _hub_alarm_satirlari(cur, ozet=oz)
                    # Operasyon Merkezi «gelen sipariş» kartı: yalnızca bekleyen katalog talepleri
                    oz["alarm_satirlari"] = [
                        a for a in tum if (a.get("tip") or "") == "siparis_merkez_bekliyor"
                    ]
                except Exception:
                    log.exception("hub-ozet: alarm_satirlari hesaplanamadi")
                    try:
                        conn.rollback()
                    except Exception:
                        pass
                    oz["alarm_satirlari"] = []
            return oz
    except Exception:
        # DATABASE_URL yok, pool hatası veya bağlantı reddi — arayüz tamamen kırılmasın
        log.exception("hub-ozet: veritabani veya kritik hata")
        out = _hub_ozet_fallback_panel()
        out["alarm_satirlari"] = []
        return out


@router.get("/siparis/gecmis")
def ops_siparis_gecmis(
    gun: int = Query(90, ge=1, le=730, description="Kaç gün geriye"),
    sube_arama: Optional[str] = Query(None, description="Şube adı veya ID (kısmi eşleşme)"),
    durum: Optional[str] = Query(None, description="bekliyor | teslim_edildi | iptal | gonderilmedi"),
    limit: int = Query(200, ge=1, le=1000),
):
    """
    Tüm sipariş geçmişi — bekliyor, teslim edildi, iptal ve gönderilmedi dahil.
    sube_arama: şube adı (kısmi) veya tam sube_id ile çalışır.
    ozet: seçili şube + gün filtresi uygulanır, durum filtresi uygulanmaz (tüm durumları göster).
    """
    arama = (sube_arama or "").strip() or None
    dur = (durum or "").strip() or None
    gun_sayi = max(1, min(730, int(gun or 90)))

    valid_durumlar = {
        "bekliyor",
        "hazirlaniyor",
        "gonderildi",
        "teslim_edildi",
        "iptal",
        "gonderilmedi",
    }
    if dur and dur not in valid_durumlar:
        dur = None

    with db() as (conn, cur):
        # Şube filtresi: ad ile ara (ILIKE) veya tam ID eşleşmesi
        sube_kosul = ""
        sube_qp_ana: List[Any] = []
        sube_qp_ozet: List[Any] = []
        if arama:
            sube_kosul = " AND (LOWER(s.ad) LIKE LOWER(%s) OR t.sube_id = %s)"
            like_val = f"%{arama}%"
            sube_qp_ana = [like_val, arama]
            sube_qp_ozet = [like_val, arama]

        # Ana sorgu (durum filtresi dahil)
        qp: List[Any] = [gun_sayi] + sube_qp_ana
        q = f"""
            SELECT
                t.id, t.sube_id, s.ad AS sube_adi,
                t.tarih, t.durum, t.olusturma,
                t.personel_id, t.personel_ad,
                t.not_aciklama, t.kalemler,
                t.gonderilmedi_ts,
                t.sevkiyat_ts,
                t.tahsis_yapan_ad,
                COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id) AS hedef_depo_sube_id,
                ss.ad AS hedef_depo_sube_adi
            FROM siparis_talep t
            JOIN subeler s ON s.id = t.sube_id
            LEFT JOIN subeler ss ON ss.id = COALESCE(t.hedef_depo_sube_id, t.sevkiyat_sube_id)
            WHERE t.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
            {sube_kosul}
        """
        if dur:
            q += " AND t.durum = %s"
            qp.append(dur)
        q += " ORDER BY t.tarih DESC, t.olusturma DESC LIMIT %s"
        qp.append(limit)

        cur.execute(q, qp)
        satirlar = []
        for row in cur.fetchall():
            d = dict(row)
            for k in ("tarih", "olusturma", "gonderilmedi_ts", "sevkiyat_ts"):
                if d.get(k):
                    d[k] = str(d[k])
            kalemler = d.get("kalemler") or []
            if isinstance(kalemler, str):
                try:
                    kalemler = json.loads(kalemler)
                except Exception:
                    kalemler = []
            d["kalemler"] = kalemler if isinstance(kalemler, list) else []
            d["kalem_adet_toplam"] = sum(
                max(0, int((it or {}).get("adet") or 0))
                for it in d["kalemler"] if isinstance(it, dict)
            )
            satirlar.append(d)

        # Özet: şube + gün filtresi uygulanır, durum filtresi UYGULANMAZ
        # → Kullanıcı "Zafer" filtrelediğinde sadece o şubenin durum dağılımını görür
        ozet_qp: List[Any] = [gun_sayi] + sube_qp_ozet
        ozet_kosul = f"WHERE tarih >= CURRENT_DATE - (%s * INTERVAL '1 day'){sube_kosul.replace('s.ad', 'subeler.ad').replace('t.sube_id', 'siparis_talep.sube_id')}"
        cur.execute(
            f"""
            SELECT durum, COUNT(*)::int AS adet
            FROM siparis_talep
            JOIN subeler ON subeler.id = siparis_talep.sube_id
            {ozet_kosul}
            GROUP BY durum
            """,
            ozet_qp,
        )
        ozet = {r["durum"]: r["adet"] for r in (cur.fetchall() or [])}

    return {
        "gun": gun_sayi,
        "sube_arama": arama,
        "durum_filtre": dur,
        "toplam": len(satirlar),
        "ozet": ozet,
        "satirlar": satirlar,
    }


@router.post("/siparis/gecmis/{talep_id}/yeniden-ac")
def ops_siparis_yeniden_ac(talep_id: str):
    """
    'gonderilmedi' statüsündeki siparişi tekrar 'bekliyor'a alır.
    gonderilmedi_ts temizlenir; sipariş kuyruğa döner.
    """
    tid = (talep_id or "").strip()
    if not tid:
        raise HTTPException(400, "talep_id boş olamaz")
    with db() as (conn, cur):
        cur.execute(
            "SELECT id, sube_id, durum FROM siparis_talep WHERE id = %s",
            (tid,),
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Sipariş bulunamadı")
        if row["durum"] != "gonderilmedi":
            raise HTTPException(400, f"Sadece 'gonderilmedi' siparişler yeniden açılabilir (mevcut: {row['durum']})")
        cur.execute(
            """
            UPDATE siparis_talep
            SET durum           = 'bekliyor',
                gonderilmedi_ts = NULL,
                tarih           = CURRENT_DATE
            WHERE id = %s
            """,
            (tid,),
        )
    return {"ok": True, "talep_id": tid}


