class FiyatZamGecersizBody(BaseModel):
    id: str
    neden: str


@router.post("/fiyat-zam-alarmlari/gecersiz")
def ops_fiyat_zam_gecersiz(body: FiyatZamGecersizBody):
    """Yanlış doğmuş alarmı damgalayarak düşürür (SİLMEZ — kayıt + neden kalır).

    Kullanım: birim/ambalaj uyuşmazlığı gibi veri hatasından doğan alarm
    (OREO 32'li koli vakası: 4,75→149,78 '%3.053' — koli çarpanıyla gerçek
    değişim eşik altı). Neden zorunlu: iz olmadan hüküm yok.
    """
    aid = (body.id or "").strip()
    neden = (body.neden or "").strip()
    if not aid:
        raise HTTPException(400, "id zorunlu")
    if len(neden) < 5:
        raise HTTPException(400, "neden zorunlu (en az 5 karakter) — geçersizlik gerekçesiz damgalanamaz")
    with db() as (conn, cur):
        _fza_gecersiz_kolonlari(cur)
        cur.execute(
            "UPDATE fiyat_zam_alarmi SET gecersiz=TRUE, gecersiz_neden=%s WHERE id=%s",
            (neden, aid),
        )
        if cur.rowcount == 0:
            raise HTTPException(404, "Alarm kaydı bulunamadı — listeyi yenileyin")
    return {"ok": True}


@router.get("/maliyet/stok-kalemleri")
def ops_maliyet_stok_kalemleri():
    """
    Depo stok kataloğundaki (sube_depo_stok) tüm kalem kodu/adlarını tekilleştirip döner —
    Maliyet sekmesinde fatura kalemlerini gerçek depo kalemleriyle eşleştirmek için
    arama/öneri listesi olarak kullanılır. Bir kalem_kodu birden fazla şubede farklı
    adla geçiyorsa en sık kullanılan adı seçer.
    """
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT kalem_kodu,
                   (array_agg(kalem_adi ORDER BY kalem_adi))[1] AS kalem_adi,
                   COUNT(*) AS sube_sayisi
            FROM sube_depo_stok
            WHERE kalem_kodu IS NOT NULL AND kalem_kodu != ''
            GROUP BY kalem_kodu
            ORDER BY kalem_adi
            """
        )
        rows = [dict(r) for r in cur.fetchall()]

    # Emekli/jenerik kodlar — fatura eşleştirme listesinden GİZLE (ürün kalem-kaleme
    # ayrıştırıldı; jenerik havuz kodu artık seçilmemeli). kahve_paket: kahve türlere bölündü.
    _EMEKLI_DEPO_KODLAR = {"kahve_paket"}
    rows = [r for r in rows if str(r.get("kalem_kodu") or "") not in _EMEKLI_DEPO_KODLAR]

    # Legacy 'ozel__' yedek kalemleri TEKİLLEŞTİR: aynı adda kanonik (ozel__ olmayan,
    # genelde UUID kodlu, çok-şubeli) bir kalem varsa, ozel__ kopyayı eşleştirme
    # listesinden DÜŞ. Kök sebep: sube_panel urun_id eksikken ozel__<ad> uydururdu
    # (artık olmamalı). Bu sadece GÖRÜNÜM tekilleştirmesi — stok verisine dokunmaz.
    kanonik_adlar = {
        str(r.get("kalem_adi") or "").strip().lower()
        for r in rows
        if not str(r.get("kalem_kodu") or "").startswith("ozel__")
    }
    temiz = [
        r for r in rows
        if not (
            str(r.get("kalem_kodu") or "").startswith("ozel__")
            and str(r.get("kalem_adi") or "").strip().lower() in kanonik_adlar
        )
    ]
    gizlenen = len(rows) - len(temiz)
    return {"kalemler": temiz, "toplam": len(temiz), "gizlenen_kopya": gizlenen}


@router.get("/maliyet/depo-saglik")
def ops_depo_saglik():
    """SALT-OKUR depo mekanizması sağlık taraması — hiçbir şeyi değiştirmez.
    Stok düşüş hatası (kalem_kodu uyumsuzluğu / P2), hayalet stok (P1), fazla-rezerve,
    takılı sevkiyat ve öksüz (orphan) kod sayılarını döner. Depo düşüş/bağlantı
    hatalarının CANLI durumunu ölçmek için."""
    out: Dict[str, Any] = {}

    def _sorgu(label: str, sql: str, params: tuple = ()):  # SAVEPOINT'li güvenli tekil sorgu
        try:
            cur.execute("SAVEPOINT sp_ds")
            cur.execute(sql, params)
            r = cur.fetchone()
            cur.execute("RELEASE SAVEPOINT sp_ds")
            return dict(r) if r else {}
        except Exception as e:
            try:
                cur.execute("ROLLBACK TO SAVEPOINT sp_ds"); cur.execute("RELEASE SAVEPOINT sp_ds")
            except Exception:
                pass
            return {"_hata": str(e)[:80]}

    with db() as (conn, cur):
        out["stok_dusme_hatasi"] = _sorgu(
            "sdh", "SELECT COUNT(*) AS adet, MAX(tarih)::text AS son FROM sube_operasyon_uyari WHERE tip='STOK_DUSME_HATASI'")
        out["hayalet_stok"] = _sorgu(
            "hs", "SELECT COUNT(*) AS adet, MAX(tarih)::text AS son FROM sube_operasyon_uyari WHERE tip='HAYALET_STOK'")
        out["fazla_rezerve"] = _sorgu(
            "fr", "SELECT COUNT(*) AS adet FROM sube_depo_stok WHERE rezerve_adet > mevcut_adet")
        out["yolda_takili"] = _sorgu(
            "yt", "SELECT COUNT(*) AS adet FROM stok_yolda WHERE durum='yolda'")
        out["orphan_kod_yolda"] = _sorgu(
            "ok", """SELECT COUNT(DISTINCT y.kalem_kodu) AS adet FROM stok_yolda y
                     WHERE y.kalem_kodu IS NOT NULL AND y.kalem_kodu <> ''
                       AND NOT EXISTS (SELECT 1 FROM sube_depo_stok d WHERE d.kalem_kodu=y.kalem_kodu)
                       AND NOT EXISTS (SELECT 1 FROM merkez_stok_kart m WHERE m.kalem_kodu=y.kalem_kodu)""")
        # Son 10 stok hata örneği (teşhis için)
        try:
            cur.execute("SAVEPOINT sp_ds2")
            cur.execute(
                """SELECT tip, sube_id, kalem_kodu, mesaj, tarih::text AS tarih
                   FROM sube_operasyon_uyari
                   WHERE tip IN ('STOK_DUSME_HATASI','HAYALET_STOK')
                   ORDER BY tarih DESC, id DESC LIMIT 10""")
            out["ornekler"] = [dict(r) for r in (cur.fetchall() or [])]
            cur.execute("RELEASE SAVEPOINT sp_ds2")
        except Exception:
            try:
                cur.execute("ROLLBACK TO SAVEPOINT sp_ds2"); cur.execute("RELEASE SAVEPOINT sp_ds2")
            except Exception:
                pass
            out["ornekler"] = []
    return out


@router.post("/maliyet/ozel-kopya-temizle")
def ops_maliyet_ozel_kopya_temizle(uygula: bool = Query(False)):
    """Legacy 'ozel__' yedek depo kalemlerini KANONİK (ozel__ olmayan, en çok şubeli)
    ikizine BİRLEŞTİRİR: ozel__ stoğu kanonik satıra eklenir, ozel__ satırı silinir.
    uygula=False → sadece PLAN (kuru çalışma). uygula=True → gerçek merge.
    Aynı adda kanonik kalem YOKSA ozel__ DOKUNULMAZ (veri kaybı olmaz). İdempotent:
    ikinci çalıştırmada birleştirilecek kalmaz. Sadece sube_depo_stok (canlı stok)."""
    from collections import defaultdict
    with db() as (conn, cur):
        cur.execute(
            """
            SELECT id, sube_id, kalem_kodu, kalem_adi, mevcut_adet, rezerve_adet, min_stok
            FROM sube_depo_stok
            """
        )
        rows = [dict(r) for r in cur.fetchall()]

        # kalem_kodu → kaç farklı şube (kanonik seçiminde "en gerçek" için)
        sube_say: Dict[str, set] = defaultdict(set)
        for r in rows:
            sube_say[r["kalem_kodu"]].add(r["sube_id"])
        # ad(lower) → kanonik (kalem_kodu, kalem_adi) : ozel__ olmayan, en çok şubeli
        kanonik: Dict[str, tuple] = {}
        for r in rows:
            kod = str(r["kalem_kodu"] or "")
            if kod.startswith("ozel__"):
                continue
            ad = str(r["kalem_adi"] or "").strip().lower()
            if not ad:
                continue
            cur_best = kanonik.get(ad)
            if cur_best is None or len(sube_say[kod]) > len(sube_say[cur_best[0]]):
                kanonik[ad] = (kod, r["kalem_adi"])

        plan: List[Dict[str, Any]] = []
        for r in rows:
            kod = str(r["kalem_kodu"] or "")
            if not kod.startswith("ozel__"):
                continue
            ad = str(r["kalem_adi"] or "").strip().lower()
            kan = kanonik.get(ad)
            if not kan:
                continue  # kanonik ikiz yok → DOKUNMA
            plan.append({
                "ozel_id": r["id"], "sube_id": r["sube_id"], "ozel_kodu": kod,
                "kalem_adi": r["kalem_adi"], "mevcut_adet": int(r["mevcut_adet"] or 0),
                "rezerve_adet": int(r["rezerve_adet"] or 0), "min_stok": int(r["min_stok"] or 0),
                "kanonik_kodu": kan[0], "kanonik_adi": kan[1],
            })

        if not uygula:
            return {"kuru_calisma": True, "birlestirilecek": len(plan), "plan": plan}

        birlestirilen = 0
        aktarilan_adet = 0
        hata: List[Dict[str, Any]] = []
        for p in plan:
            try:
                cur.execute("SAVEPOINT sp_ozel_merge")
                cur.execute(
                    """
                    INSERT INTO sube_depo_stok
                        (sube_id, kalem_kodu, kalem_adi, mevcut_adet, rezerve_adet, min_stok)
                    VALUES (%s, %s, %s, %s, %s, %s)
                    ON CONFLICT (sube_id, kalem_kodu) DO UPDATE
                      SET mevcut_adet  = sube_depo_stok.mevcut_adet  + EXCLUDED.mevcut_adet,
                          rezerve_adet = sube_depo_stok.rezerve_adet + EXCLUDED.rezerve_adet,
                          guncelleme   = NOW()
                    """,
                    (p["sube_id"], p["kanonik_kodu"], p["kanonik_adi"],
                     p["mevcut_adet"], p["rezerve_adet"], p["min_stok"]),
                )
                cur.execute("DELETE FROM sube_depo_stok WHERE id = %s", (p["ozel_id"],))
                cur.execute("RELEASE SAVEPOINT sp_ozel_merge")
                birlestirilen += 1
                aktarilan_adet += p["mevcut_adet"]
            except Exception as e:
                cur.execute("ROLLBACK TO SAVEPOINT sp_ozel_merge")
                hata.append({"ozel_kodu": p["ozel_kodu"], "sube_id": p["sube_id"], "hata": str(e)[:140]})
        conn.commit()
    return {"uygulandi": True, "birlestirilen": birlestirilen,
            "aktarilan_adet": aktarilan_adet, "hata": hata}


@router.post("/maliyet/alis-fiyat-kaydet")
def ops_maliyet_alis_fiyat_kaydet(body: AlisFiyatBody):
    """Yeni alış fiyatı kaydeder veya günceller."""
    kalem = str(body.kalem_kodu or "").strip()
    if not kalem:
        raise HTTPException(400, "kalem_kodu zorunlu")
    # 🔴 P1 (2026-08-12, Maliyet denetimi): eskiden yalnız `< 0` reddediyordu → 0 TL
    # (boş/bozuk giriş) geçip maliyeti SIFIRLIYORDU (food-cost/marj/P&L sistematik düşük).
    if not (body.birim_maliyet_tl > 0):
        raise HTTPException(400, "birim_maliyet_tl 0'dan büyük olmalı (0/negatif maliyeti sıfırlar)")
    bas = body.gecerli_baslangic or str(date.today())
    with db() as (conn, cur):
        # Manuel giriş = kullanıcı AÇILIŞ birimi fiyatı yazar → katsayı UYGULANMAZ
        new_id = _kaydet_alis_fiyati(cur, kalem, body.kalem_adi, body.birim,
                                      body.birim_maliyet_tl, bas, body.tedarikci,
                                      body.notlar, icerik_uygula=False)
    return {"success": True, "id": new_id, "kalem_kodu": kalem}


@router.delete("/maliyet/alis-fiyat-sil/{fiyat_id}")
def ops_maliyet_alis_fiyat_sil(fiyat_id: str):
    """Tek bir urun_alis_fiyat satırını siler (yanlış/test kaydı düzeltmek için)."""
    with db() as (conn, cur):
        # 🟡 P2 (2026-08-12, Maliyet denetimi): fiyat geçmişi geri dönülmez siliniyordu,
        # audit/iz yoktu. Silinen kaydı audit'e yaz (P&L/KDV incelemesinde kaynak kanıtı).
        cur.execute("SELECT kalem_kodu, birim_maliyet_tl, gecerli_baslangic FROM urun_alis_fiyat WHERE id = %s", (fiyat_id,))
        _eski = cur.fetchone()
        cur.execute("DELETE FROM urun_alis_fiyat WHERE id = %s", (fiyat_id,))
        silindi = cur.rowcount
        if silindi and _eski:
            audit(cur, "urun_alis_fiyat", fiyat_id, "FIYAT_SIL", eski=dict(_eski))
    if not silindi:
        raise HTTPException(404, "Kayıt bulunamadı")
    return {"success": True, "silinen": silindi}


def _medyan(xs: List[float]) -> float:
    s = sorted(xs)
    n = len(s)
    if n == 0:
        return 0.0
    m = n // 2
    return s[m] if n % 2 else (s[m - 1] + s[m]) / 2.0


@router.get("/maliyet/guven-skoru")
def ops_maliyet_guven_skoru(
    gun: int = Query(7, ge=1, le=31),
    sube_id: Optional[str] = Query(None),
):
    """SALT-OKUR Faz 5 — Güven Skoru + Sapma Motoru. Öneri-only: hiçbir veriyi
    DEĞİŞTİRMEZ. Maliyetin ne kadar güvenilir olduğunu (kova başına + genel) ve
    şüpheli sayı/fiyatları (48M/70K plastik bardak olayının kökü) önceden gösterir.

    SAPMA MOTORU iki tip outlier yakalar:
      - FIYAT_OUTLIER: bir kalemin son alış fiyatı, geçmiş medyanının N katı (karamel→bardak)
      - ADET_OUTLIER: bir kalemin bir şubedeki stok adedi, diğer şubelerin medyanının N katı (70583)
    """
    sid = (sube_id or "").strip() or None
    FIYAT_KAT = 5.0      # son fiyat > medyan × 5 → şüpheli (kritik)
    ADET_KAT = 15.0      # bir şube adedi > DİĞER ŞUBELERİN medyanı × 15 → şüpheli (orta)
    ADET_TABAN = 2000    # mutlak taban (küçük sayılarda gürültü olmasın)
    ADET_MED_TABAN = 50  # diğer şubeler bu kalemi anlamlı tutuyorsa kıyasla (farklı alım deseni gürültüsü)
    sapmalar: List[Dict[str, Any]] = []
    kovalar: List[Dict[str, Any]] = []

    with db() as (conn, cur):
        # ── Şube adları (mesajlar için) ──
        sube_ad: Dict[str, str] = {}
        try:
            cur.execute("SELECT id::text AS sid, ad FROM subeler")
            for r in cur.fetchall():
                sube_ad[r["sid"]] = r["ad"]
        except Exception:
            pass

        # ── SAPMA 1: Fiyat outlier (urun_alis_fiyat geçmişi) ──
        try:
            cur.execute(
                """SELECT kalem_kodu, kalem_adi, birim_maliyet_tl, gecerli_baslangic
                   FROM urun_alis_fiyat
                   WHERE birim_maliyet_tl > 0
                   ORDER BY kalem_kodu, gecerli_baslangic ASC"""
            )
            fiyat_grup: Dict[str, List[Tuple[str, str, float]]] = {}
            for r in cur.fetchall():
                d = dict(r)
                fiyat_grup.setdefault(str(d["kalem_kodu"]), []).append(
                    (str(d.get("kalem_adi") or ""), str(d.get("gecerli_baslangic") or ""), float(d.get("birim_maliyet_tl") or 0))
                )
            for kod, lst in fiyat_grup.items():
                if len(lst) < 2:
                    continue
                son_ad, son_tar, son_fiyat = lst[-1]
                gecmis = [f for (_, _, f) in lst[:-1] if f > 0]
                med = _medyan(gecmis)
                if med > 0 and son_fiyat > med * FIYAT_KAT:
                    kat = round(son_fiyat / med, 1)
                    sapmalar.append({
                        "tip": "FIYAT_OUTLIER",
                        "kalem_kodu": kod, "kalem_adi": son_ad,
                        "deger": round(son_fiyat, 2), "beklenen": round(med, 2), "kat": kat,
                        "siddet": "kritik" if kat >= 20 else "orta",
                        "mesaj": f"{son_ad}: son alış {son_fiyat:.2f}₺ = geçmiş medyanın ({med:.2f}₺) {kat}× üstü — yanlış fatura eşleştirmesi olabilir",
                    })
        except Exception:
            pass

        # ── SAPMA 2: Adet outlier (ŞUBE↔ŞUBE stok karşılaştırma — DEPO HARİÇ) ──
        # Hub-spoke: TEMA depo doğası gereği şubelerden çok fazla stok tutar (sevk eder)
        # → depo kıyas dışı, yoksa her depo kalemi yanlış alarm verir. Sadece şubeler
        # birbiriyle kıyaslanır; ADET sapması "orta" (heuristik), "kritik" sadece fiyat.
        depo_subeler: set = set()
        try:
            cur.execute("SELECT id::text AS sid FROM subeler WHERE LOWER(COALESCE(sube_tipi,''))='sevkiyat'")
            depo_subeler = {r["sid"] for r in cur.fetchall()}
            # Yedek tespit: sevkiyatın baskın kaynağı (>=10 talep) da depo sayılır
            cur.execute(
                """SELECT hedef_depo_sube_id AS sid, COUNT(*) AS n FROM siparis_talep
                   WHERE hedef_depo_sube_id IS NOT NULL GROUP BY hedef_depo_sube_id HAVING COUNT(*) >= 10"""
            )
            depo_subeler |= {r["sid"] for r in cur.fetchall() if r.get("sid")}
        except Exception:
            pass
        try:
            cur.execute(
                """SELECT kalem_kodu, kalem_adi, sube_id::text AS sid, mevcut_adet
                   FROM sube_depo_stok WHERE COALESCE(mevcut_adet,0) > 0"""
            )
            adet_grup: Dict[str, List[Tuple[str, str, float]]] = {}
            for r in cur.fetchall():
                d = dict(r)
                sid_r = str(d["sid"])
                if sid_r in depo_subeler:        # DEPO kıyas dışı
                    continue
                adet_grup.setdefault(str(d["kalem_kodu"]), []).append(
                    (sid_r, str(d.get("kalem_adi") or ""), float(d.get("mevcut_adet") or 0))
                )
            for kod, lst in adet_grup.items():
                if len(lst) < 2:                 # en az 2 şube (depo hariç)
                    continue
                for i, (b_sid, b_ad, b_adet) in enumerate(lst):
                    digerleri = [a for j, (_, _, a) in enumerate(lst) if j != i]
                    med = _medyan(digerleri)
                    if (med >= ADET_MED_TABAN and b_adet > med * ADET_KAT and b_adet >= ADET_TABAN):
                        kat = round(b_adet / med, 1)
                        sapmalar.append({
                            "tip": "ADET_OUTLIER",
                            "kalem_kodu": kod, "kalem_adi": b_ad,
                            "sube_id": b_sid, "sube_ad": sube_ad.get(b_sid, b_sid),
                            "deger": int(b_adet), "beklenen": int(med), "kat": kat,
                            "siddet": "orta",
                            "mesaj": f"{b_ad} @ {sube_ad.get(b_sid, b_sid)}: {int(b_adet)} adet = diğer şubelerin medyanının ({int(med)}) {kat}× üstü — sayım hatası olabilir (depo hariç kıyas)",
                        })
        except Exception:
            pass

        sapmalar.sort(key=lambda x: (0 if x.get("siddet") == "kritik" else 1, -float(x.get("kat") or 0)))

        # ── GÜVEN SKORU (kova başına) ──
        aktif_subeler: List[str] = []
        try:
            if sid:
                aktif_subeler = [sid]
            else:
                cur.execute("SELECT id::text AS sid FROM subeler WHERE COALESCE(aktif, TRUE) = TRUE")
                aktif_subeler = [r["sid"] for r in cur.fetchall()]
        except Exception:
            aktif_subeler = [sid] if sid else []
        n_sube = max(1, len(aktif_subeler))
        sube_filt = "AND sube_id::text = %s" if sid else ""

        def _skor_durum(s: float) -> str:
            return "iyi" if s >= 85 else ("orta" if s >= 60 else "zayif")

        # ciro kovası — kapsama (kaç şube-gün ciro var / beklenen)
        ciro_skor = 0.0; ciro_msg = "ciro verisi yok"
        ciro_gun_set: set = set()
        try:
            p = [gun - 1] + ([sid] if sid else [])
            cur.execute(
                f"""SELECT sube_id::text AS sid, tarih::text AS t FROM ciro
                    WHERE tarih >= CURRENT_DATE - (%s || ' days')::interval {sube_filt}""",
                p,
            )
            for r in cur.fetchall():
                ciro_gun_set.add((r["sid"], r["t"]))
            beklenen = n_sube * gun
            kapsama = min(1.0, len(ciro_gun_set) / beklenen) if beklenen else 0.0
            ciro_skor = round(kapsama * 100, 0)
            ciro_msg = f"{len(ciro_gun_set)}/{beklenen} şube-gün ciro girili"
        except Exception:
            pass
        kovalar.append({"kova": "ciro", "baslik": "Ciro", "skor": ciro_skor,
                        "durum": _skor_durum(ciro_skor), "mesaj": ciro_msg})

        # COGS (ürün-aç) kovası — ciro olan günlerde ürün-aç var mı
        cogs_skor = 0.0; cogs_msg = "ürün-aç verisi yok"
        try:
            p = [gun - 1] + ([sid] if sid else [])
            # 🔴 P1 (2026-08-13, EVV-MAL / Codex): ürün-aç defterini okuyan HER sorgu
            # İKİ ETİKETİ de saymalı (defter dersi: URUN_AC + URUN_KULLANIMA_AL —
            # bitince-modu FIX C1'den beri ikinci etiketle yazıyor). Bu okuyucu tek
            # etiketi sayıyordu → bitince-modu şubede maliyet DOĞRUYKEN güven skoru
            # "ciro var ürün-aç yok" diye haksız düşüyordu.
            cur.execute(
                f"""SELECT sube_id::text AS sid, tarih::text AS t FROM operasyon_defter
                    WHERE etiket IN ('URUN_AC','URUN_KULLANIMA_AL')
                      AND tarih >= CURRENT_DATE - (%s || ' days')::interval {sube_filt}""",
                p,
            )
            urunac_set = {(r["sid"], r["t"]) for r in cur.fetchall()}
            ciro_pozitif = ciro_gun_set
            if ciro_pozitif:
                eksik = [g for g in ciro_pozitif if g not in urunac_set]
                oran = 1.0 - (len(eksik) / len(ciro_pozitif))
                cogs_skor = round(oran * 100, 0)
                cogs_msg = (f"{len(eksik)} şube-günde ciro VAR ama ürün-aç YOK (COGS eksik)"
                            if eksik else "ciro olan tüm günlerde ürün-aç bildirimi var")
        except Exception:
            pass
        kovalar.append({"kova": "cogs", "baslik": "Ürün-Aç (COGS)", "skor": cogs_skor,
                        "durum": _skor_durum(cogs_skor), "mesaj": cogs_msg})

        # kira kovası — kaç aktif şubede kira girili
        kira_skor = 0.0; kira_msg = "kira girili değil"
        try:
            cur.execute(
                """SELECT DISTINCT sube_id::text AS sid FROM sabit_giderler
                   WHERE aktif = TRUE AND sube_id IS NOT NULL
                     AND (LOWER(COALESCE(kategori,'')) LIKE %s OR LOWER(COALESCE(gider_adi,'')) LIKE %s)""",
                ('%kira%', '%kira%'),
            )
            kira_subeler = {r["sid"] for r in cur.fetchall()}
            ilgili = set(aktif_subeler)
            var = len(ilgili & kira_subeler)
            kira_skor = round((var / max(1, len(ilgili))) * 100, 0)
            kira_msg = f"{var}/{len(ilgili)} şubede kira girili" + ("" if var == len(ilgili) else " — eksik şubeler kira girmeli")
        except Exception:
            pass
        kovalar.append({"kova": "kira", "baslik": "Kira", "skor": kira_skor,
                        "durum": _skor_durum(kira_skor), "mesaj": kira_msg})

        # faturalar kovası — en güncel kira-dışı sabit giderin yaşı
        fatura_skor = 60.0; fatura_msg = "kira-dışı sabit gider (elektrik/su/gaz) girili değil"
        try:
            cur.execute(
                """SELECT MAX(COALESCE(guncelleme, olusturma)) AS son
                   FROM sabit_giderler WHERE aktif = TRUE
                     AND LOWER(COALESCE(kategori,'')) NOT LIKE %s
                     AND LOWER(COALESCE(gider_adi,'')) NOT LIKE %s""",
                ('%kira%', '%kira%'),
            )
            row = cur.fetchone()
            if row and row.get("son"):
                yas = (datetime.now(row["son"].tzinfo) - row["son"]).days if hasattr(row["son"], "tzinfo") else None
                if yas is None:
                    fatura_skor = 80.0; fatura_msg = "fatura kalemleri girili"
                elif yas <= 45:
                    fatura_skor = 100.0; fatura_msg = f"en güncel fatura {yas} günlük (taze)"
                elif yas <= 90:
                    fatura_skor = 70.0; fatura_msg = f"en güncel fatura {yas} günlük (eskimeye başladı)"
                else:
                    fatura_skor = 40.0; fatura_msg = f"en güncel fatura {yas} günlük (bayat — güncellenmeli)"
        except Exception:
            pass
        kovalar.append({"kova": "faturalar", "baslik": "Faturalar", "skor": fatura_skor,
                        "durum": _skor_durum(fatura_skor), "mesaj": fatura_msg})

        # komisyon kovası — deterministik (oran × ciro), her zaman yüksek
        kom_skor = 100.0
        try:
            cur.execute("SELECT COUNT(*) AS n FROM subeler WHERE COALESCE(pos_oran,0) > 0")
            n_oran = (cur.fetchone() or {}).get("n", 0)
            kom_msg = f"{n_oran} şubede POS komisyon oranı girili (deterministik)"
            if not n_oran:
                kom_skor = 50.0; kom_msg = "POS komisyon oranı girili değil"
        except Exception:
            kom_msg = "komisyon deterministik"
        kovalar.append({"kova": "komisyon", "baslik": "POS/Platform Komisyonu", "skor": kom_skor,
                        "durum": _skor_durum(kom_skor), "mesaj": kom_msg})

        # fire kovası — dönemde fire bildirimi var mı
        fire_skor = 60.0; fire_msg = "dönemde fire/iade bildirimi yok (belirsiz — fire olmuyor olabilir)"
        try:
            p = [gun - 1] + ([sid] if sid else [])
            cur.execute(
                f"""SELECT COUNT(*) AS n FROM sube_fire_bildirim
                    WHERE tarih >= CURRENT_DATE - (%s || ' days')::interval {sube_filt}""",
                p,
            )
            nf = (cur.fetchone() or {}).get("n", 0)
            if nf:
                fire_skor = 100.0; fire_msg = f"dönemde {nf} fire/iade bildirimi kayıtlı"
        except Exception:
            pass
        kovalar.append({"kova": "fire", "baslik": "Fire / İade", "skor": fire_skor,
                        "durum": _skor_durum(fire_skor), "mesaj": fire_msg})

    # ── GENEL SKOR (ağırlıklı) ──
    agirlik = {"ciro": 0.30, "cogs": 0.30, "kira": 0.10, "faturalar": 0.10,
               "komisyon": 0.10, "fire": 0.10}
    genel = 0.0
    for k in kovalar:
        genel += float(k["skor"]) * agirlik.get(k["kova"], 0.0)
    # sapma varsa genel skoru bir miktar düşür (kritik sapma maliyeti güvenilmez yapar)
    kritik_sapma = sum(1 for s in sapmalar if s.get("siddet") == "kritik")
    genel_ham = round(genel, 0)
    # Ceza yumuşak: sadece KRİTİK (fiyat) sapma maliyeti güvenilmez yapar; toplam ceza ≤20
    genel_son = max(0, round(genel - min(20, kritik_sapma * 8), 0))

    return {
        "gun": gun, "sube_id": sid,
        "genel_skor": genel_son,
        "genel_skor_ham": genel_ham,
        "kovalar": kovalar,
        "sapmalar": sapmalar,
        "sapma_sayisi": len(sapmalar),
        "kritik_sapma": kritik_sapma,
        "ozet": (f"{genel_son}/100" + (f" — {len(sapmalar)} şüpheli değer (sapma motoru)" if sapmalar else " — sapma yok")),
    }


@router.get("/maliyet/kalem-tuketim-hesap")
def ops_maliyet_kalem_tuketim_hesap(sube_id: str, kalem_kodu: str, baslangic: str):
    """SALT-OKUR teşhis: bir şubenin bir kalemde, verilen tarihten BUGÜNE kadar
    operasyon_defter URUN_AC toplamını (depodan kullanıma açılan adet) hesaplar.
    'Son sayımdan beri ne kadar tüketildi?' sorusunun cevabı (havuz-birleştirme
    şişmesini gerçek tüketimle ayırmak için)."""
    import json as _json
    sid = (sube_id or "").strip()
    kk = (kalem_kodu or "").strip()
    toplam_urun_ac = 0
    gun_sayisi = 0
    with db() as (conn, cur):
        cur.execute(
            """SELECT aciklama FROM operasyon_defter
               WHERE sube_id=%s AND etiket='URUN_AC' AND tarih >= %s::date
               ORDER BY olay_ts ASC""",
            (sid, baslangic),
        )
        for row in cur.fetchall():
            ac = row.get("aciklama") or ""
            mark = "URUN_AC_JSON:"
            if mark not in ac:
                continue
            try:
                j = _json.loads(ac.split(mark, 1)[1].strip())
            except Exception:
                continue
            d = j.get("delta") if isinstance(j.get("delta"), dict) else j
            try:
                v = int(d.get(kk) or 0)
            except (TypeError, ValueError):
                v = 0
            if v > 0:
                toplam_urun_ac += v
                gun_sayisi += 1
    return {"sube_id": sid, "kalem_kodu": kk, "baslangic": baslangic,
            "toplam_urun_ac": toplam_urun_ac, "kayit_gun": gun_sayisi}


@router.get("/maliyet/eslestirme-liste")
def ops_maliyet_eslestirme_liste(q: str = ""):
    """Fatura kalem eşleştirme hafızasını listeler (salt-okur, teşhis amaçlı).
    q verilirse anahtar/kalem_adi/kalem_kodu içinde arar."""
    with db() as (conn, cur):
        if q:
            like = f"%{q.lower()}%"
            cur.execute(
                """SELECT anahtar, kalem_kodu, kalem_adi, adet, guncelleme
                   FROM fatura_kalem_eslestirme
                   WHERE LOWER(anahtar) LIKE %s OR LOWER(COALESCE(kalem_adi,'')) LIKE %s
                      OR LOWER(COALESCE(kalem_kodu,'')) LIKE %s
                   ORDER BY guncelleme DESC""",
                (like, like, like),
            )
        else:
            cur.execute(
                """SELECT anahtar, kalem_kodu, kalem_adi, adet, guncelleme
                   FROM fatura_kalem_eslestirme ORDER BY guncelleme DESC LIMIT 500"""
            )
        rows = [dict(r) for r in cur.fetchall()]
    return {"satirlar": rows, "toplam": len(rows)}


@router.delete("/maliyet/kalem-temizle/{kalem_kodu}")
def ops_maliyet_kalem_temizle(kalem_kodu: str, stok_fiyat_sifirla: bool = False):
    """
    Bir kalem_kodu'na ait TÜM fiyat geçmişini (urun_alis_fiyat) ve fatura eşleştirme
    hafızasını (fatura_kalem_eslestirme) siler — test/yanlış eşleştirme kayıtlarını
    temizlemek için.

    stok_fiyat_sifirla=True ise AYRICA sube_depo_stok.alis_fiyati_tl alanını da NULL'lar
    (yanlış fiyat stok satırına damgalanmışsa — ozet stok değeri fallback olarak onu
    kullanıyordu → hayalet stok değerini düzeltir). Stok ADETİNE dokunmaz.
    """
    with db() as (conn, cur):
        cur.execute("DELETE FROM urun_alis_fiyat WHERE kalem_kodu = %s", (kalem_kodu,))
        fiyat_silinen = cur.rowcount
        cur.execute("DELETE FROM fatura_kalem_eslestirme WHERE kalem_kodu = %s", (kalem_kodu,))
        esleme_silinen = cur.rowcount
        stok_fiyat_sifirlanan = 0
        if stok_fiyat_sifirla:
            # 🔴 P1 (2026-08-12, Maliyet denetimi): stok-fiyat sıfırlama hatası ESKİDEN
            # yutuluyordu (except: pass) → fiyat geçmişi+eşleşme SİLİNMİŞ ama stok fiyatı
            # kalmış = kısmi temizlik, maliyet izi tutarsız. Hata artık propagate → tüm
            # temizlik tek transaction'da geri alınır (atomik; hepsi ya da hiçbiri).
            cur.execute(
                "UPDATE sube_depo_stok SET alis_fiyati_tl = NULL WHERE kalem_kodu = %s AND alis_fiyati_tl IS NOT NULL",
                (kalem_kodu,),
            )
            stok_fiyat_sifirlanan = cur.rowcount
    return {"success": True, "fiyat_silinen": fiyat_silinen, "esleme_silinen": esleme_silinen,
            "stok_fiyat_sifirlanan": stok_fiyat_sifirlanan}


# ─── Fatura PDF yükleme + kalem eşleştirme ─────────────────────────────────

_FATURA_SAYI_RE = re.compile(r"\d{1,3}(?:[.\s]\d{3})*(?:,\d+)?|\d+(?:[.,]\d+)?")
_FATURA_ATLA_RE = re.compile(
    r"^(ara\s*toplam|genel\s*toplam|toplam|kdv|vergi|fatura\s*no|tarih|"
    r"i[bv]an|m[uü][sş]teri|tedarik[cç]i|sayfa|d[oö]viz|iskonto)\b",
    re.IGNORECASE,
)


def _fatura_sayi_parse(tok: str) -> Optional[float]:
    """TR formatlı sayı ('1.234,50' veya '12,5' veya '12.5') -> float."""
    t = tok.strip().replace(" ", "")
    if not t:
        return None
    if "," in t:
        t = t.replace(".", "").replace(",", ".")
    try:
        return float(t)
    except ValueError:
        return None


def _fatura_anahtar(satir: Dict[str, Any]) -> str:
    """
    Eşleştirme hafızası anahtarı. Tabloda 'Ürün Kodu' kolonu varsa (e-Fatura
    formatlarında genelde olur, örn. 'ST00558') o kullanılır — tedarikçinin
    Türkçe açıklama metni PDF font kodlamasından dolayı bozuk (�) gelebilir,
    ama ürün kodu ASCII olduğu için sağlam ve aynı tedarikçide tekrar edince
    güvenilir bir eşleştirme anahtarı olur. Yoksa açıklama normalize edilir.
    """
    kod = (satir.get("urun_kodu") or "").strip()
    if kod:
        return f"kod:{kod.lower()}"
    a = re.sub(r"\s+", " ", satir.get("aciklama") or "").strip().lower()
    a = re.sub(r"[^a-zçğıöşü0-9 ]", "", a)
    return a[:120]


# Ürün/hammadde kodu gibi görünen hücreler: harf+rakam karışımı, kısa (örn. ST00558)
_FATURA_KOD_RE = re.compile(r"^[A-Za-zÇĞİÖŞÜçğıöşü0-9]{2,12}$")


def _fatura_tablo_basligi_bul(header: List[Optional[str]]) -> Optional[Dict[str, Any]]:
    """
    Bir tablo başlık satırında ürün kodu/açıklama/miktar/birim fiyat kolonlarını bulur.

    Ürün kodu farklı tedarikçilerde / farklı fatura şablonlarında farklı kolonlarda
    olabilir (örn. Sütaş'ın iki ayrı şablonunda aynı ürün kodu bir faturada
    "Mal Hizmet Kodu" kolonunda, diğerinde "Müşteri Stok No" kolonunda gelebilir).
    Bu yüzden TEK bir "kod" kolonu yerine, kod-benzeri tüm kolonları "kod_candidates"
    listesinde topluyoruz; satır işlenirken bunlardan dolu olan ilki kullanılır —
    böylece eşleştirme hafızası (anahtar) iki şablon arasında da tutarlı kalır.
    """
    cols: Dict[str, Any] = {}
    kod_candidates: List[int] = []
    for ci, h in enumerate(header):
        hl = re.sub(r"\s+", " ", (h or "")).strip().lower()
        if not hl:
            continue
        if "kodu" in hl or "stok no" in hl or "mamül no" in hl or "mamul no" in hl or "malzeme no" in hl:
            kod_candidates.append(ci)
        elif ("malzeme" in hl or "a klama" in hl or "ack" in hl or "hizmet" in hl) and "aciklama" not in cols:
            cols["aciklama"] = ci
        elif hl == "miktar" and "miktar" not in cols:
            cols["miktar"] = ci
        elif "birim fiyat" in hl and "fiyat" not in cols:
            cols["fiyat"] = ci
    if kod_candidates:
        cols["kod_candidates"] = kod_candidates
    if "aciklama" in cols and "fiyat" in cols:
        return cols
    return None


def _fatura_satirlari_tablo(pdf_bytes: bytes) -> List[Dict[str, Any]]:
    """e-Fatura tarzı tablolardan (Ürün Kodu / Açıklama / Miktar / Birim Fiyatı) satır çıkarır."""
    import pdfplumber
    out: List[Dict[str, Any]] = []
    with pdfplumber.open(io.BytesIO(pdf_bytes)) as pdf:
        for page in pdf.pages:
            for table in page.extract_tables():
                if len(table) < 2:
                    continue
                cols = None
                header_idx = None
                for i, row in enumerate(table[:3]):
                    cols = _fatura_tablo_basligi_bul(row)
                    if cols:
                        header_idx = i
                        break
                if cols is None:
                    continue
                idxs = [v for k, v in cols.items() if k != "kod_candidates"] + cols.get("kod_candidates", [])
                for row in table[header_idx + 1:]:
                    if not row or len(row) <= max(idxs):
                        continue
                    aciklama_raw = re.sub(r"\s+", " ", (row[cols["aciklama"]] or "")).strip()
                    if len(aciklama_raw) < 3:
                        continue
                    fiyat = _fatura_sayi_parse_tl(row[cols["fiyat"]])
                    if fiyat is None:
                        continue  # "Toplam", "KDV" vb. özet satırları
                    kod = ""
                    for kci in cols.get("kod_candidates", []):
                        kod_raw = (row[kci] or "").strip()
                        if _FATURA_KOD_RE.match(kod_raw):
                            kod = kod_raw
                            break
                    miktar = birim = None
                    if "miktar" in cols:
                        m = re.match(r"\s*([\d.,]+)\s*([A-Za-zÇĞİÖŞÜçğıöşü]*)", row[cols["miktar"]] or "")
                        if m:
                            miktar = _fatura_sayi_parse(m.group(1))
                            birim = (m.group(2) or "").strip().lower() or None
                    out.append({
                        "ham_metin": (f"{kod} " if kod else "") + aciklama_raw,
                        "urun_kodu": kod or None,
                        "aciklama": aciklama_raw,
                        "miktar": miktar,
                        "birim": birim,
                        "tutar": fiyat,  # birim fiyatı
                    })
    return out


def _fatura_sayi_parse_tl(hucre: Optional[str]) -> Optional[float]:
    """'680,00 TL' / '1.680,00 TL' gibi hücrelerden sayıyı çıkarır."""
    if not hucre:
        return None
    m = re.search(r"[\d.,]+", hucre)
    if not m:
        return None
    return _fatura_sayi_parse(m.group(0))


def _fatura_satirlari_satir_bazli(pdf_bytes: bytes) -> List[Dict[str, Any]]:
    """
    Yedek (fallback) yöntem: tablo bulunamazsa satır bazlı genel ayrıştırma.
    Her satırda en az 1 sayı arar; son sayıyı 'tutar' olarak, varsa ondan önceki
    sayıyı 'miktar' olarak alır. Sayılar çıkarılınca kalan metin 'aciklama' olur.
    Not: 'tutar' burada satır toplamı olabilir, birim fiyat olmayabilir —
    kullanıcı düzeltmeli.
    """
    import pdfplumber
    out: List[Dict[str, Any]] = []
    with pdfplumber.open(io.BytesIO(pdf_bytes)) as pdf:
        for page in pdf.pages:
            text = page.extract_text() or ""
            for raw in text.split("\n"):
                line = raw.strip()
                if len(line) < 4:
                    continue
                if _FATURA_ATLA_RE.match(line):
                    continue
                sayilar = _FATURA_SAYI_RE.findall(line)
                if not sayilar:
                    continue
                aciklama = _FATURA_SAYI_RE.sub("", line)
                aciklama = re.sub(r"\s+", " ", aciklama).strip(" -.,:;|")
                if len(aciklama) < 3:
                    continue
                tutar = _fatura_sayi_parse(sayilar[-1])
                miktar = _fatura_sayi_parse(sayilar[-2]) if len(sayilar) >= 2 else None
                if tutar is None:
                    continue
                out.append({
                    "ham_metin": line,
                    "urun_kodu": None,
                    "aciklama": aciklama,
                    "miktar": miktar,
                    "birim": None,
                    "tutar": tutar,
                })
    return out


# METRO Grosmarket fatura satırı: "ART-No Artikel Tanımı Brm.Fiy İçeriği Koli.Fiy Mikt NetTop. KdvKd BrütTop."
# Örn: "0200561 ULUDAĞ LİMONATA 1L ŞEKERLİ 51,900 1 51,90 120 6.228,00 E 6.850,80"
_FATURA_METRO_RE = re.compile(
    r"^\s*(\d{6,8})\s+(.+?)\s+([\d.]+,\d+)\s+(\d+)\s+([\d.]+,\d+)\s+(\d+)\s+([\d.]+,\d+)\s+([A-Z])\s+([\d.]+,\d+)\s*$"
)


def _fatura_satirlari_metro(pdf_bytes: bytes) -> List[Dict[str, Any]]:
    """
    METRO Grosmarket faturaları normal e-Fatura tablo yapısında gelmez; satırlar
    düz metin olarak 'MG EAN ART-No Artikel Tanımı Brm.Fiy İçeriği Koli.Fiy Mikt
    NetTop. KdvKd BrütTop. PROMO SbpK' kolonlarını içerir. Brm.Fiy = tekil ürünün
    KDV'siz birim fiyatı (maliyet için kullanılır), Mikt = sipariş edilen koli/adet
    sayısı.
    """
    import pdfplumber
    out: List[Dict[str, Any]] = []
    with pdfplumber.open(io.BytesIO(pdf_bytes)) as pdf:
        for page in pdf.pages:
            text = page.extract_text() or ""
            for raw in text.split("\n"):
                line = raw.strip()
                m = _FATURA_METRO_RE.match(line)
                if not m:
                    continue
                kod, aciklama, brm_fiy, _icerik, _koli_fiy, mikt, _net_top, _kdv, _brut_top = m.groups()
                aciklama = re.sub(r"\s+", " ", aciklama).strip()
                if len(aciklama) < 3:
                    continue
                fiyat = _fatura_sayi_parse(brm_fiy)
                if fiyat is None:
                    continue
                out.append({
                    "ham_metin": line,
                    "urun_kodu": kod,
                    "aciklama": aciklama,
                    "miktar": _fatura_sayi_parse(mikt),
                    "birim": None,
                    "tutar": fiyat,  # Brm.Fiy: tekil ürün birim fiyatı (KDV hariç)
                })
    return out


# Fatura üzerindeki tarih etiketleri — fatura formatına göre değişebilir
# (Sütaş: "Fatura Tarihi: 09-05-2026", METRO: "Oluşturma Tarihi 26.05.2026 12:45" vb.)
_FATURA_TARIH_RE = re.compile(
    r"(?:Fatura\s*Tarihi|D[uü]zenlenme\s*Tarihi|Olu[sş]turma\s*Tarihi|Fiili\s*Sevk(?:iyat)?\s*Tarihi)"
    r"\s*[:\.]?\s*(\d{2})[.\-](\d{2})[.\-](\d{4})",
    re.IGNORECASE,
)


def _fatura_tarihi_bul(pdf_bytes: bytes) -> Optional[str]:
    """PDF'in ilk sayfasından fatura tarihini (gg.aa.yyyy / gg-aa-yyyy) bulup ISO (yyyy-mm-dd) döner.
    Bulunamazsa None — bu durumda kayıt sırasında bugünün tarihi kullanılır."""
    import pdfplumber
    try:
        with pdfplumber.open(io.BytesIO(pdf_bytes)) as pdf:
            text = (pdf.pages[0].extract_text() or "") if pdf.pages else ""
    except Exception:
        return None
    m = _FATURA_TARIH_RE.search(text)
    if not m:
        return None
    gg, ay, yil = m.groups()
    try:
        return date(int(yil), int(ay), int(gg)).isoformat()
    except ValueError:
        return None


# e-Fatura/e-Arşiv belgelerinde benzersiz işlem numarası (UUID formatında)
_FATURA_ETTN_RE = re.compile(r"ETTN\s*[:\.]?\s*([0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12})")
# "Fatura No: SM22026000264114" / "Fatura ID No: B102026000005741" / "FATURA NUMARASI: 27X2026000000249"
_FATURA_NO_RE = re.compile(r"Fatura\s*(?:ID\s*)?(?:No|Numaras[ıi])\s*[:\.]?\s*([A-Za-z0-9]{6,25})", re.IGNORECASE)


def _fatura_kimlik_bul(pdf_bytes: bytes) -> Dict[str, Optional[str]]:
    """PDF'in ilk sayfasından ETTN ve fatura numarasını bulur — aynı faturanın
    tekrar yüklenip yüklenmediğini anlamak için kullanılır."""
    import pdfplumber
    try:
        with pdfplumber.open(io.BytesIO(pdf_bytes)) as pdf:
            text = (pdf.pages[0].extract_text() or "") if pdf.pages else ""
    except Exception:
        return {"ettn": None, "fatura_no": None}
    ettn_m = _FATURA_ETTN_RE.search(text)
    no_m = _FATURA_NO_RE.search(text)
    return {
        "ettn": ettn_m.group(1) if ettn_m else None,
        "fatura_no": no_m.group(1) if no_m else None,
    }


def _fatura_satirlari_cikar(pdf_bytes: bytes) -> List[Dict[str, Any]]:
    """Önce e-Fatura tablo formatını, sonra METRO formatını dener, bulamazsa satır bazlı yedek yönteme döner."""
    satirlar = _fatura_satirlari_tablo(pdf_bytes)
    if satirlar:
        return satirlar
    satirlar = _fatura_satirlari_metro(pdf_bytes)
    if satirlar:
        return satirlar
    return _fatura_satirlari_satir_bazli(pdf_bytes)


@router.post("/maliyet/fatura-pdf-yukle")
async def ops_maliyet_fatura_pdf_yukle(
    file: UploadFile = File(...),
    tedarikci: Optional[str] = Form(None),
):
    """
    Tedarikçi faturası PDF'i yükler, satır bazlı kalem adaylarını çıkarır.
    Her satır için, daha önce eşleştirilmiş bir stok kalemi varsa (fatura_kalem_eslestirme)
    önerir; ayrıca o kalemin son bilinen fiyatını döner (artış/azalış karşılaştırması için).
    Hiçbir şeyi otomatik kaydetmez — onay /maliyet/fatura-kalem-onayla ile yapılır.
    """
    if not file.filename.lower().endswith(".pdf"):
        raise HTTPException(400, "Sadece PDF dosyası yüklenebilir")
    data = await file.read()
    try:
        satirlar = _fatura_satirlari_cikar(data)
    except Exception as e:
        raise HTTPException(400, f"PDF okunamadı: {e}")

    if not satirlar:
        return {"satirlar": [], "toplam": 0,
                "uyari": "PDF'ten kalem satırı çıkarılamadı. Format desteklenmiyor olabilir — "
                         "satırları aşağıdan elle girebilirsin."}

    fatura_tarihi = _fatura_tarihi_bul(data)
    kimlik = _fatura_kimlik_bul(data)
    ettn = kimlik["ettn"]

    zaten_yuklendi = None
    with db() as (conn, cur):
        _ensure_maliyet_tablolari(cur)

        # Aynı fatura (ETTN ile tanımlı) daha önce yüklenmiş mi?
        if ettn:
            cur.execute("SELECT son_yukleme, yukleme_sayisi FROM fatura_yukleme_log WHERE ettn = %s", (ettn,))
            mevcut = cur.fetchone()
            if mevcut:
                zaten_yuklendi = {
                    "son_yukleme": str(mevcut["son_yukleme"]),
                    "yukleme_sayisi": mevcut["yukleme_sayisi"],
                }
                cur.execute(
                    "UPDATE fatura_yukleme_log SET yukleme_sayisi = yukleme_sayisi + 1, son_yukleme = NOW() WHERE ettn = %s",
                    (ettn,),
                )
            else:
                cur.execute(
                    """
                    INSERT INTO fatura_yukleme_log (ettn, fatura_no, fatura_tarihi, tedarikci, dosya_adi)
                    VALUES (%s, %s, %s, %s, %s)
                    """,
                    (ettn, kimlik["fatura_no"], fatura_tarihi, tedarikci, file.filename),
                )

        for s in satirlar:
            s["fatura_tarihi"] = fatura_tarihi
            anahtar = _fatura_anahtar(s)
            s["anahtar"] = anahtar
            cur.execute(
                "SELECT kalem_kodu, kalem_adi FROM fatura_kalem_eslestirme WHERE anahtar = %s",
                (anahtar,),
            )
            esleme = cur.fetchone()
            if esleme:
                s["onerilen_kalem_kodu"] = esleme["kalem_kodu"]
                s["onerilen_kalem_adi"] = esleme["kalem_adi"]
                # "Önceki fiyat" karşılaştırması bu faturanın TARİHİNDEN ÖNCE geçerli
                # olan fiyatla yapılır — faturalar tarih sırasıyla yüklenmemiş olsa
                # bile artış/azalış doğru yönde görünür (örn. eski tarihli fatura
                # sonradan yüklenirse, ondan daha yeni bir fiyatla kıyaslanmaz).
                if fatura_tarihi:
                    cur.execute(
                        """
                        SELECT birim_maliyet_tl, gecerli_baslangic, birim FROM urun_alis_fiyat
                        WHERE kalem_kodu = %s AND gecerli_baslangic < %s
                        ORDER BY gecerli_baslangic DESC LIMIT 1
                        """,
                        (esleme["kalem_kodu"], fatura_tarihi),
                    )
                else:
                    cur.execute(
                        """
                        SELECT birim_maliyet_tl, gecerli_baslangic, birim FROM urun_alis_fiyat
                        WHERE kalem_kodu = %s ORDER BY gecerli_baslangic DESC LIMIT 1
                        """,
                        (esleme["kalem_kodu"],),
                    )
                onceki = cur.fetchone()
                if onceki:
                    s["onceki_fiyat"] = float(onceki["birim_maliyet_tl"])
                    s["onceki_tarih"] = str(onceki["gecerli_baslangic"])
                    s["birim"] = onceki["birim"]
                else:
                    s["onceki_fiyat"] = None
                    s["onceki_tarih"] = None
            else:
                s["onerilen_kalem_kodu"] = None
                s["onerilen_kalem_adi"] = None
                s["onceki_fiyat"] = None
                s["onceki_tarih"] = None

    return {
        "satirlar": satirlar, "toplam": len(satirlar), "tedarikci": tedarikci,
        "fatura_tarihi": fatura_tarihi, "fatura_no": kimlik["fatura_no"],
        "zaten_yuklendi": zaten_yuklendi,
    }


class FaturaKalemOnaylaBody(BaseModel):
    ham_metin: str
    urun_kodu: Optional[str] = None
    aciklama: Optional[str] = None
    kalem_kodu: str
    kalem_adi: Optional[str] = None
    birim: str = "adet"
    birim_maliyet_tl: float
    tedarikci: Optional[str] = None
    gecerli_baslangic: Optional[str] = None


@router.post("/maliyet/fatura-kalem-onayla")
def ops_maliyet_fatura_kalem_onayla(body: FaturaKalemOnaylaBody):
    """
    Bir fatura satırını onaylar: urun_alis_fiyat'a yeni fiyat kaydı düşer
    (eski fiyat geçmiş olarak korunur) ve fatura_kalem_eslestirme'ye
    'bu satır metni -> bu kalem_kodu' eşleşmesini öğretir/günceller.
    """
    kalem = str(body.kalem_kodu or "").strip()
    if not kalem:
        raise HTTPException(400, "kalem_kodu zorunlu")
    # 🔴 P1 (2026-08-12, Maliyet denetimi): 0 TL onayı maliyeti sıfırlar → 0'dan büyük şart.
    if not (body.birim_maliyet_tl > 0):
        raise HTTPException(400, "birim_maliyet_tl 0'dan büyük olmalı")
    bas = body.gecerli_baslangic or str(date.today())
    anahtar = _fatura_anahtar({"urun_kodu": body.urun_kodu, "aciklama": body.aciklama or body.ham_metin})
    with db() as (conn, cur):
        new_id = _kaydet_alis_fiyati(cur, kalem, body.kalem_adi, body.birim,
                                      body.birim_maliyet_tl, bas, body.tedarikci,
                                      f"PDF'ten onaylandı: {body.ham_metin}")
        if anahtar:
            cur.execute(
                """
                INSERT INTO fatura_kalem_eslestirme (anahtar, kalem_kodu, kalem_adi, adet, guncelleme)
                VALUES (%s, %s, %s, 1, NOW())
                ON CONFLICT (anahtar) DO UPDATE
                    SET kalem_kodu = EXCLUDED.kalem_kodu,
                        kalem_adi  = EXCLUDED.kalem_adi,
                        -- 🔴 P1 (2026-08-12, Maliyet denetimi): re-onay/çift-tık her seferinde
                        -- adet'i şişiriyordu (sahte güven sinyali). Adet YALNIZ eşleşme HEDEFİ
                        -- (kalem_kodu) DEĞİŞİRSE artar — aynı eşleşmeyi tekrar onaylamak inflate etmez.
                        adet       = fatura_kalem_eslestirme.adet
                                     + (CASE WHEN fatura_kalem_eslestirme.kalem_kodu = EXCLUDED.kalem_kodu THEN 0 ELSE 1 END),
                        guncelleme = NOW()
                """,
                (anahtar, kalem, body.kalem_adi or kalem),
            )
    return {"success": True, "id": new_id, "kalem_kodu": kalem}


@router.get("/maliyet/recete-listesi")
def ops_maliyet_recete_listesi():
    """Reçete listesi — KANONİK reçete evreninden türetilmiş maliyet projeksiyonu.

    İKİ EVREN BİRLEŞTİRMESİ (Codex danışmalı, 2026-08-03): sahibin 91 reçetesi
    recete_api evreninde yaşarken bu uç boş `urun_recete` tablosunu okuyor,
    ekran "0 reçete" diyordu. Artık tek kaynak recete_api.maliyet_projeksiyonu
    (Python import — gelecek-ay-yuk deseni); fiyat haritası buradan enjekte
    edilir (dairesel import yok). `urun_recete` OTORİTE DEĞİL — projeksiyon
    boş dönerse eski tabloya düşülür (emniyet ağı, veri kaybı yok)."""
    with db() as (conn, cur):
        _ensure_maliyet_tablolari(cur)
        try:
            from recete_api import maliyet_projeksiyonu
            fiyat = _alis_fiyat_haritasi(cur)
            proj = maliyet_projeksiyonu(cur, fiyat)
            if proj.get("toplam"):
                return proj
        except Exception as e:  # noqa: BLE001 — emniyet ağı: eski yol
            logger.warning("recete projeksiyonu hatasi (eski yola dusuldu): %s", str(e)[:150])
        cur.execute("""
            SELECT urun_id, urun_adi,
                   json_agg(json_build_object(
                       'hammadde_kodu', hammadde_kodu,
                       'hammadde_adi', hammadde_adi,
                       'miktar', miktar,
                       'birim', birim
                   ) ORDER BY hammadde_adi) AS hammaddeler
            FROM urun_recete
            GROUP BY urun_id, urun_adi
            ORDER BY urun_adi
        """)
        rows = [dict(r) for r in cur.fetchall()]
    return {"receteler": rows, "toplam": len(rows), "kaynak": "urun_recete_legacy"}


class ReceteHammadde(BaseModel):
    hammadde_kodu: str
    hammadde_adi: Optional[str] = None
    miktar: float
    birim: str = "adet"


class ReceteBody(BaseModel):
    urun_id: str
    urun_adi: Optional[str] = None
    hammaddeler: List[ReceteHammadde]


@router.post("/maliyet/recete-kaydet")
def ops_maliyet_recete_kaydet(body: ReceteBody):
    """
    Ürün reçetesini kaydeder veya günceller.
    Mevcut reçete satırları silinip yeniden yazılır (tam güncelleme).
    hammaddeler: [{hammadde_kodu, hammadde_adi, miktar, birim}]
    """
    urun = str(body.urun_id or "").strip()
    if not urun:
        raise HTTPException(400, "urun_id zorunlu")
    # 🔴 P1 (2026-08-12, Maliyet denetimi): miktar pozitiflik kontrolü yoktu → 0/negatif
    # miktar BOM maliyetini bozar/tersine çevirir. Kod VE miktar>0 olan satırlar geçerli.
    hammaddeler = [h for h in (body.hammaddeler or [])
                   if str(h.hammadde_kodu or "").strip() and _safe_float(h.miktar) > 0]
    if not hammaddeler:
        raise HTTPException(400, "En az 1 geçerli hammadde satırı gerekli (kod + miktar>0)")
    with db() as (conn, cur):
        _ensure_maliyet_tablolari(cur)
        # Mevcut reçeteyi temizle, yeniden yaz
        cur.execute("DELETE FROM urun_recete WHERE urun_id = %s", (urun,))
        for h in hammaddeler:
            hk = str(h.hammadde_kodu).strip()
            cur.execute(
                """
                INSERT INTO urun_recete (urun_id, urun_adi, hammadde_kodu, hammadde_adi, miktar, birim)
                VALUES (%s, %s, %s, %s, %s, %s)
                ON CONFLICT (urun_id, hammadde_kodu) DO UPDATE
                    SET miktar       = EXCLUDED.miktar,
                        birim        = EXCLUDED.birim,
                        hammadde_adi = EXCLUDED.hammadde_adi,
                        urun_adi     = EXCLUDED.urun_adi
                """,
                (urun, body.urun_adi or urun, hk, h.hammadde_adi or hk,
                 round(float(h.miktar), 4), h.birim),
            )
    return {"success": True, "urun_id": urun, "hammadde_sayisi": len(hammaddeler)}


@router.delete("/maliyet/recete-sil/{urun_id}")
def ops_maliyet_recete_sil(urun_id: str):
    """Bir ürünün tüm reçete satırlarını siler."""
    urun = str(urun_id or "").strip()
    if not urun:
        raise HTTPException(400, "urun_id zorunlu")
    with db() as (conn, cur):
        _ensure_maliyet_tablolari(cur)
        cur.execute("DELETE FROM urun_recete WHERE urun_id = %s", (urun,))
        _n = cur.rowcount
        # 🟡 P2 (2026-08-12, Maliyet denetimi): BOM silme izsizdi — food-cost değişiminin
        # ne zaman/neden olduğu izlenemiyordu. Audit ile iz bırak.
        audit(cur, "urun_recete", urun, "RECETE_SIL", yeni={"silinen_satir": _n})
    return {"success": True, "urun_id": urun, "silinen_satir": _n}


# ─── Geçici Kasa Teşhis Endpoint ────────────────────────────────────────────
@router.get("/kasa-teshis")
def ops_kasa_teshis(
    sube_ad: str = Query("zafer", description="Şube adı içeriği (küçük harf)"),
    tarih: str = Query("2026-05-14", description="YYYY-MM-DD"),
):
    """
    Geçici teşhis endpoint: belirli şube + gün için tüm kasa verilerini gösterir.
    açılış sayım, kapanış sayım, ciro, gider, uyarılar, devir hesabı.
    """
    hedef = date.fromisoformat(tarih)
    with db() as (_, cur):

        # 1. Şube bul
        cur.execute("SELECT id::text, ad FROM subeler WHERE lower(ad) LIKE %s ORDER BY ad", (f"%{sube_ad.lower()}%",))
        subeler_r = [dict(r) for r in cur.fetchall()]

        if not subeler_r:
            return {"hata": f"'{sube_ad}' adında şube bulunamadı", "subeler": []}

        sube_id = subeler_r[0]["id"]
        sube_adi = subeler_r[0]["ad"]

        sonuc = {"sube_id": sube_id, "sube_adi": sube_adi, "tarih": str(hedef)}

        # 2. ACILIS event — kasa_sayim direkt sütun, meta'da değil
        try:
            cur.execute("SAVEPOINT sp_td_acilis")
            cur.execute("""
                SELECT e.id, e.tip, e.tarih, e.durum,
                       e.cevap_ts AT TIME ZONE 'Europe/Istanbul' AS cevap_ts_tr,
                       e.kasa_sayim, e.teslim, e.devir,
                       e.snap_nakit, e.snap_pos, e.snap_online,
                       e.personel_ad, e.meta
                FROM sube_operasyon_event e
                WHERE e.sube_id = %s AND e.tarih = %s AND e.tip = 'ACILIS'
                ORDER BY e.cevap_ts DESC NULLS LAST, e.id DESC
                LIMIT 5
            """, (sube_id, hedef))
            sonuc["acilis_eventler"] = []
            for r in cur.fetchall():
                d = dict(r)
                d["tarih"] = str(d["tarih"])
                d["cevap_ts_tr"] = str(d.get("cevap_ts_tr") or "")
                meta = d.pop("meta", {}) or {}
                if isinstance(meta, str):
                    try: meta = json.loads(meta)
                    except: meta = {}
                d["stok_sayim"] = meta.get("acilis_stok_sayim")
                for k in ("kasa_sayim","teslim","devir","snap_nakit","snap_pos","snap_online"):
                    if d.get(k) is not None: d[k] = float(d[k])
                sonuc["acilis_eventler"].append(d)
            cur.execute("RELEASE SAVEPOINT sp_td_acilis")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_acilis")
            sonuc["acilis_eventler"] = [{"hata": str(ex)}]

        # 3. KAPANIS event — kasa_sayim, teslim, devir direkt sütunlar
        try:
            cur.execute("SAVEPOINT sp_td_kapanis")
            cur.execute("""
                SELECT e.id, e.tip, e.tarih, e.durum,
                       e.cevap_ts AT TIME ZONE 'Europe/Istanbul' AS cevap_ts_tr,
                       e.kasa_sayim, e.teslim, e.devir,
                       e.snap_nakit, e.snap_pos, e.snap_online,
                       e.personel_ad, e.meta
                FROM sube_operasyon_event e
                WHERE e.sube_id = %s AND e.tarih = %s AND e.tip = 'KAPANIS'
                ORDER BY e.cevap_ts DESC NULLS LAST, e.id DESC
                LIMIT 5
            """, (sube_id, hedef))
            sonuc["kapanis_eventler"] = []
            for r in cur.fetchall():
                d = dict(r)
                d["tarih"] = str(d["tarih"])
                d["cevap_ts_tr"] = str(d.get("cevap_ts_tr") or "")
                meta = d.pop("meta", {}) or {}
                if isinstance(meta, str):
                    try: meta = json.loads(meta)
                    except: meta = {}
                d["stok_sayim"] = meta.get("kapanis_stok_sayim")
                for k in ("kasa_sayim","teslim","devir","snap_nakit","snap_pos","snap_online"):
                    if d.get(k) is not None: d[k] = float(d[k])
                sonuc["kapanis_eventler"].append(d)
            cur.execute("RELEASE SAVEPOINT sp_td_kapanis")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_kapanis")
            sonuc["kapanis_eventler"] = [{"hata": str(ex)}]

        # 4. Ciro
        try:
            cur.execute("SAVEPOINT sp_td_ciro")
            cur.execute("""
                SELECT toplam, nakit, pos, online, durum
                FROM ciro WHERE sube_id = %s AND tarih = %s
            """, (sube_id, hedef))
            ciro_r = cur.fetchone()
            sonuc["ciro"] = dict(ciro_r) if ciro_r else None
            if sonuc["ciro"]:
                for k in ("toplam","nakit","pos","online"):
                    if sonuc["ciro"].get(k) is not None:
                        sonuc["ciro"][k] = float(sonuc["ciro"][k])
            cur.execute("RELEASE SAVEPOINT sp_td_ciro")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_ciro")
            sonuc["ciro"] = {"hata": str(ex)}

        # 5. ciro_taslak
        try:
            cur.execute("SAVEPOINT sp_td_taslak")
            cur.execute("""
                SELECT nakit, pos, online, durum, gonderen_ad, olusturma
                FROM ciro_taslak WHERE sube_id = %s AND tarih = %s
                ORDER BY CASE durum WHEN 'onaylandi' THEN 0 ELSE 1 END, olusturma DESC
                LIMIT 3
            """, (sube_id, hedef))
            taslaklari = []
            for r in cur.fetchall():
                d = dict(r)
                d["olusturma"] = str(d.get("olusturma") or "")
                for k in ("nakit","pos","online"):
                    if d.get(k) is not None: d[k] = float(d[k])
                taslaklari.append(d)
            sonuc["ciro_taslak"] = taslaklari
            cur.execute("RELEASE SAVEPOINT sp_td_taslak")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_taslak")
            sonuc["ciro_taslak"] = [{"hata": str(ex)}]

        # 6. Günlük gider (nakit çıkış) — anlik_giderler.sube sütunu kullanır
        try:
            cur.execute("SAVEPOINT sp_td_gider")
            cur.execute("""
                SELECT SUM(tutar) AS toplam_gider, COUNT(*) AS adet
                FROM anlik_giderler
                WHERE sube = %s AND DATE(olusturma AT TIME ZONE 'Europe/Istanbul') = %s
                  AND durum = 'aktif'
            """, (sube_id, hedef))
            gider_r = cur.fetchone()
            sonuc["gunluk_gider"] = {"toplam": float(gider_r["toplam_gider"] or 0), "adet": int(gider_r["adet"] or 0)} if gider_r else None
            cur.execute("RELEASE SAVEPOINT sp_td_gider")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_gider")
            sonuc["gunluk_gider"] = {"hata": str(ex)}

        # 7. Kasa uyarıları
        try:
            cur.execute("SAVEPOINT sp_td_uyari")
            cur.execute("""
                SELECT id, tip, tarih, seviye, fark_tl, beklenen_tl, gercek_tl,
                       mesaj, okundu, olusturma,
                       acilis_personel_ad, kapanis_personel_ad
                FROM sube_operasyon_uyari
                WHERE sube_id = %s AND tarih = %s
                  AND tip IN ('ACILIS_KASA_FARK','KAPANIS_KASA_FARK')
                ORDER BY olusturma DESC
            """, (sube_id, hedef))
            uyarilar = []
            for r in cur.fetchall():
                d = dict(r)
                d["tarih"] = str(d["tarih"])
                d["olusturma"] = str(d.get("olusturma") or "")
                for k in ("fark_tl","beklenen_tl","gercek_tl"):
                    if d.get(k) is not None: d[k] = float(d[k])
                uyarilar.append(d)
            sonuc["kasa_uyarilari"] = uyarilar
            cur.execute("RELEASE SAVEPOINT sp_td_uyari")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_uyari")
            sonuc["kasa_uyarilari"] = [{"hata": str(ex)}]

        # 8. Kasa operasyon kayıtları (kasa_hareketleri)
        try:
            cur.execute("SAVEPOINT sp_td_kasa_har")
            cur.execute("""
                SELECT tip, tutar, aciklama,
                       olusturma AT TIME ZONE 'Europe/Istanbul' AS zaman_tr
                FROM kasa_hareketleri
                WHERE sube_id = %s
                  AND DATE(olusturma AT TIME ZONE 'Europe/Istanbul') = %s
                ORDER BY olusturma
            """, (sube_id, hedef))
            hareketler = []
            for r in cur.fetchall():
                d = dict(r)
                d["zaman_tr"] = str(d.get("zaman_tr") or "")
                if d.get("tutar") is not None: d["tutar"] = float(d["tutar"])
                hareketler.append(d)
            sonuc["kasa_hareketleri"] = hareketler
            cur.execute("RELEASE SAVEPOINT sp_td_kasa_har")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_kasa_har")
            sonuc["kasa_hareketleri"] = [{"hata": str(ex)}]

        # 9. Operasyon defter KASA kayıtları
        try:
            cur.execute("SAVEPOINT sp_td_defter")
            cur.execute("""
                SELECT etiket, aciklama,
                       olay_ts AT TIME ZONE 'Europe/Istanbul' AS zaman_tr
                FROM operasyon_defter
                WHERE sube_id = %s
                  AND DATE(olay_ts AT TIME ZONE 'Europe/Istanbul') = %s
                  AND etiket ILIKE '%KASA%'
                ORDER BY olay_ts
                LIMIT 30
            """, (sube_id, hedef))
            defter = [{"etiket": r["etiket"], "aciklama": str(r["aciklama"] or "")[:200], "zaman": str(r["zaman_tr"] or "")} for r in cur.fetchall()]
            sonuc["operasyon_defter_kasa"] = defter
            cur.execute("RELEASE SAVEPOINT sp_td_defter")
        except Exception as ex:
            cur.execute("ROLLBACK TO SAVEPOINT sp_td_defter")
            sonuc["operasyon_defter_kasa"] = [{"hata": str(ex)}]

        # 10. Devir hesabı — kasa_sayim/teslim/devir direkt sütunlardan
        try:
            ac  = sonuc["acilis_eventler"][0]  if sonuc.get("acilis_eventler")  else {}
            kap = sonuc["kapanis_eventler"][0] if sonuc.get("kapanis_eventler") else {}
            ciro = sonuc.get("ciro") or {}
            taslak_list = sonuc.get("ciro_taslak") or []
            taslak = taslak_list[0] if taslak_list else {}
            gider = sonuc.get("gunluk_gider") or {}

            acilis_kasa    = ac.get("kasa_sayim")   # float veya None
            kapanis_kasa   = kap.get("kasa_sayim")
            kapanis_teslim = kap.get("teslim")
            kapanis_devir  = kap.get("devir")

            # Ciro nakit: onaylı önce, sonra taslak
            ciro_nakit = ciro.get("nakit") if ciro.get("nakit") is not None else taslak.get("nakit")
            gider_toplam = float(gider.get("toplam") or 0)

            if acilis_kasa is not None and ciro_nakit is not None:
                # Kasada olması gereken = açılış deviri + günlük nakit ciro - giderler
                beklenen = round(acilis_kasa + ciro_nakit - gider_toplam, 2)
                # Kasiyer kasayı saydı → teslim + devirde bıraktı
                gercek_toplam = None
                if kapanis_teslim is not None and kapanis_devir is not None:
                    gercek_toplam = round(kapanis_teslim + kapanis_devir, 2)
                elif kapanis_kasa is not None:
                    gercek_toplam = round(kapanis_kasa, 2)

                fark = round(gercek_toplam - beklenen, 2) if gercek_toplam is not None else None
                sonuc["devir_hesabi"] = {
                    "acilis_kasa_sayim":   acilis_kasa,
                    "ciro_nakit":          ciro_nakit,
                    "gunluk_gider":        gider_toplam,
                    "beklenen_kasada":     beklenen,
                    "kapanis_kasa_sayim":  kapanis_kasa,
                    "teslim_edilen":       kapanis_teslim,
                    "devirde_birakilan":   kapanis_devir,
                    "gercek_kasada":       gercek_toplam,
                    "fark_tl":             fark,
                    "aciklama":            "fark = (teslim+devir) - (acilis_kasa + ciro_nakit - gider) | pozitif=fazla, negatif=açık",
                }
            else:
                sonuc["devir_hesabi"] = {
                    "aciklama": "Hesap yapılamadı",
                    "acilis_kasa_sayim": acilis_kasa,
                    "ciro_nakit": ciro_nakit,
                    "eksik": [k for k,v in [("acilis_kasa_sayim", acilis_kasa), ("ciro_nakit", ciro_nakit)] if v is None],
                }
        except Exception as ex:
            sonuc["devir_hesabi"] = {"hata": str(ex)}

    return sonuc


# ─── Food Cost Günlük Hesaplama Motoru ────────────────────────────────────────

def _alis_fiyat_haritasi(cur: Any) -> Dict[str, float]:
    """
    urun_alis_fiyat tablosundan güncel (gecerli_bitis IS NULL veya >= bugün)
    fiyatları döner: {kalem_kodu: birim_maliyet_tl}
    Aynı kalem için birden fazla aktif kayıt varsa en son başlangıç tarihi alınır.
    """
    cur.execute("""
        SELECT DISTINCT ON (kalem_kodu)
               kalem_kodu, birim_maliyet_tl
        FROM urun_alis_fiyat
        WHERE gecerli_bitis IS NULL OR gecerli_bitis >= CURRENT_DATE
        ORDER BY kalem_kodu, gecerli_baslangic DESC
    """)
    return {str(r["kalem_kodu"]): float(r["birim_maliyet_tl"] or 0) for r in cur.fetchall()}


def _depo_alis_fiyat_haritasi(cur: Any) -> Dict[str, float]:
    """
    sube_depo_stok.alis_fiyati_tl — fallback fiyat kaynağı.
    Kalem başına şubeler arası en büyük fiyatı döner (tutarsız kaçının).
    """
    try:
        cur.execute("SAVEPOINT sp_depo_alis_fiyat")
        cur.execute("""
            SELECT kalem_kodu, MAX(alis_fiyati_tl) AS alis_fiyati_tl
            FROM sube_depo_stok
            WHERE alis_fiyati_tl > 0
            GROUP BY kalem_kodu
        """)
        rows = {str(r["kalem_kodu"]): float(r["alis_fiyati_tl"] or 0) for r in cur.fetchall()}
        cur.execute("RELEASE SAVEPOINT sp_depo_alis_fiyat")
        return rows
    except Exception:
        cur.execute("ROLLBACK TO SAVEPOINT sp_depo_alis_fiyat")
        return {}


def _food_cost_hesapla_gun(
    cur: Any,
    tarih_str: str,
    sube_id_filtre: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Belirli bir gün için tüm (veya tek) şubenin food cost hesabını yapar ve
    sube_food_cost_gun tablosuna yazar.

    Algoritma:
      kullanim[k] = acilis_stok[k] + urun_ac[k] - kapanis_stok[k]   (max 0)
      teorik_maliyet = Σ kullanim[k] × alis_fiyati[k]
      stok_degeri_tl = Σ kapanis_stok[k] × alis_fiyati[k]
      food_cost_pct  = teorik_maliyet / ciro_tl  (null if ciro=0)

    Returns: hesaplanan satır listesi (sube başına 1 satır)
    """
    hedef = date.fromisoformat(str(tarih_str)[:10])
    _ensure_maliyet_tablolari(cur)

    # ── 1. Alış fiyatları (önce urun_alis_fiyat, sonra sube_depo_stok fallback) ──
    alis_fiyat = _alis_fiyat_haritasi(cur)
    if not alis_fiyat:
        alis_fiyat = _depo_alis_fiyat_haritasi(cur)
    # BAR_KEYS'deki tüm kalemler için fiyat haritası — 0 ise maliyet hesaplanamaz
    fiyat: Dict[str, float] = {k: alis_fiyat.get(k, 0.0) for k in _BAR_KEYS}

    # ── 2. Şubeleri belirle ──
    sube_filtre = "AND e.sube_id = %s" if sube_id_filtre else ""
    sube_params = [sube_id_filtre] if sube_id_filtre else []

    # ── 3. ACILIS stok sayımları ──
    cur.execute(
        f"""
        SELECT DISTINCT ON (e.sube_id)
               e.sube_id::text, e.meta AS acilis_meta
        FROM sube_operasyon_event e
        WHERE e.tip = 'ACILIS'
          AND e.tarih = %s
          AND e.durum IN ('tamamlandi', 'onaylandi')
          {sube_filtre}
        ORDER BY e.sube_id, e.cevap_ts DESC NULLS LAST, e.id DESC
        """,
        [hedef, *sube_params],
    )
    acilis_rows: Dict[str, Dict[str, int]] = {}
    for r in cur.fetchall():
        sid = str(r["sube_id"])
        acilis_rows[sid] = _bar_stok_from_meta(r.get("acilis_meta"), "acilis_stok_sayim")
    # ⚠️ KANONİK MODEL (2026-08-03): açılış sayımı artık ÖN KOŞUL DEĞİL —
    # para sürücüsü ürün-aç olduğu için gün, ürün-aç/ciro olan her şubede
    # hesaplanır (şube kümesi aşağıda birleştirilir). Sayımlar yalnız
    # stok-değeri BİLGİSİ üretir.

    # ── 4. KAPANIS stok sayımları ──
    kapanis_rows: Dict[str, Dict[str, int]] = {}
    try:
        cur.execute("SAVEPOINT sp_fc_kapanis")
        cur.execute(
            f"""
            SELECT DISTINCT ON (e.sube_id)
                   e.sube_id::text, e.meta AS kapanis_meta
            FROM sube_operasyon_event e
            WHERE e.tip = 'KAPANIS'
              AND e.tarih = %s
              AND e.durum = 'tamamlandi'
              {sube_filtre}
            ORDER BY e.sube_id, e.cevap_ts DESC NULLS LAST, e.id DESC
            """,
            [hedef, *sube_params],
        )
        for r in cur.fetchall():
            sid = str(r["sube_id"])
            kapanis_rows[sid] = _bar_stok_from_meta(r.get("kapanis_meta"), "kapanis_stok_sayim")
        cur.execute("RELEASE SAVEPOINT sp_fc_kapanis")
    except Exception:
        cur.execute("ROLLBACK TO SAVEPOINT sp_fc_kapanis")

    # Fallback: sube_operasyon_ozet.kapanis_stok_json
    if not kapanis_rows:
        try:
            cur.execute("SAVEPOINT sp_fc_ozet_kapanis")
            cur.execute(
                f"""
                SELECT o.sube_id::text, o.kapanis_stok_json
                FROM sube_operasyon_ozet o
                WHERE o.tarih = %s AND o.kapanis_stok_json IS NOT NULL
                {sube_filtre}
                """,
                [hedef, *sube_params],
            )
            for r in cur.fetchall():
                sid = str(r["sube_id"])
                raw = r.get("kapanis_stok_json") or {}
                if isinstance(raw, str):
                    try:
                        import json as _jfc; raw = _jfc.loads(raw)
                    except Exception:
                        raw = {}
                if raw:
                    kapanis_rows[sid] = {k: max(0, int(raw.get(k) or 0)) for k in _BAR_KEYS}
            cur.execute("RELEASE SAVEPOINT sp_fc_ozet_kapanis")
        except Exception:
            cur.execute("ROLLBACK TO SAVEPOINT sp_fc_ozet_kapanis")

    # ── 5. URUN_AC toplamları — BAR kalemleri + TAM-COGS "diğer" kovası ──
    # 🐞 FIX (2026-08-03, sahip talebi "fc %5,7 gerçek COGS değil"):
    # (a) ürün-aç okuyucu ÜÇ KURALI buraya da geldi: iki etiket +
    #     '[BİTTİ]' çift-sayım dışlaması + prefix normalize (REPLACE).
    #     Eski hali yalnız URUN_AC okuyordu → bitince-modunda BAR ürün-açları
    #     da kaçıyordu.
    # (b) Faz-1 sınırı kalktı: BAR-DIŞI ürün-aç kalemleri (espresso, sos,
    #     meyve... UUID/depo kodlu) artık teorik maliyete GİRER — gun-gun
    #     COGS'un "☕ Diğer Ürün-Aç" kovasıyla aynı evren. Fiyat: alış fiyatı
    #     haritası → siparis_urun.birim_fiyat_tl fallback.
    #     Anahtar çözümü kalem_kodu → urun_id → urun_ad(norm) sırasıyla;
    #     urun_ad BAR sayım kalemine eşleniyorsa (bardak vb.) diğer kovasına
    #     GİRMEZ (delta yolu zaten sayar — çift sayım freni).
    urun_ac_map: Dict[str, Dict[str, int]] = {}
    diger_ac_map: Dict[str, Dict[str, int]] = {}   # sid → {kod: adet}
    cur.execute("""
        SELECT id::text, COALESCE(norm_ad,'') AS norm_ad,
               COALESCE(birim_fiyat_tl, 0) AS f,
               COALESCE(depo_stok_kalem_kodu,'') AS depo_kod
        FROM siparis_urun
    """)
    su_fiyat: Dict[str, float] = {}
    su_norm_to_id: Dict[str, str] = {}
    for r in cur.fetchall():
        kid = str(r["id"])
        su_fiyat[kid] = float(r["f"] or 0)
        dk = str(r["depo_kod"] or "").strip()
        if dk and dk not in su_fiyat:
            su_fiyat[dk] = float(r["f"] or 0)
        na = str(r["norm_ad"] or "").strip()
        if na:
            su_norm_to_id[na] = kid
    _fc_dec = json.JSONDecoder()
    cur.execute(
        f"""
        SELECT sube_id::text,
               REPLACE(aciklama, 'URUN_KULLANIMA_AL_JSON:', 'URUN_AC_JSON:') AS aciklama
        FROM operasyon_defter
        WHERE etiket IN ('URUN_AC', 'URUN_KULLANIMA_AL')
          AND NOT (etiket = 'URUN_AC' AND aciklama LIKE %s)
          AND tarih = %s
          {'AND sube_id = %s' if sube_id_filtre else ''}
        """,
        ["%[BİTTİ]%", hedef, *sube_params],
    )
    for r in cur.fetchall():
        sid = str(r["sube_id"])
        ack = r["aciklama"] or ""
        delta = _urun_ac_delta_parse(ack)
        entry = urun_ac_map.setdefault(sid, {k: 0 for k in _BAR_KEYS})
        for k, v in delta.items():
            entry[k] = entry.get(k, 0) + v
        # BAR-dışı kalemler — kod bazında topla
        i = ack.find("URUN_AC_JSON:")
        if i < 0:
            continue
        try:
            j, _ = _fc_dec.raw_decode(ack[i + len("URUN_AC_JSON:"):].strip())
        except Exception:
            continue
        kalemler = j.get("kalemler") if isinstance(j, dict) else None
        if not isinstance(kalemler, list):
            continue
        for k in kalemler:
            if not isinstance(k, dict):
                continue
            uad = str(k.get("urun_ad") or "").strip()
            if uad and _stok_key_from_urun_ad(uad) in _BAR_KEYS:
                continue  # BAR evreninde — delta yolu sayar
            kod = str(k.get("kalem_kodu") or k.get("urun_id") or "").strip()
            if not kod and uad:
                ad_n = re.sub(r'[^a-z0-9]+', '_',
                    uad.lower().replace('ğ','g').replace('ü','u').replace('ş','s')
                    .replace('ı','i').replace('ö','o').replace('ç','c')).strip('_')
                kod = su_norm_to_id.get(ad_n, "")
            if not kod or kod in _BAR_KEYS:
                continue
            try:
                adet = max(0, int(k.get("adet") or 0))
            except (TypeError, ValueError):
                adet = 0
            if adet > 0:
                diger_ac_map.setdefault(sid, {})
                diger_ac_map[sid][kod] = diger_ac_map[sid].get(kod, 0) + adet

    # ── 6. Ciro ──
    cur.execute(
        f"""
        SELECT sube_id::text, toplam AS ciro_tl
        FROM ciro
        WHERE tarih = %s AND durum = 'aktif'
        {'AND sube_id = %s' if sube_id_filtre else ''}
        """,
        [hedef, *sube_params],
    )
    ciro_map: Dict[str, float] = {str(r["sube_id"]): float(r["ciro_tl"] or 0) for r in cur.fetchall()}

    # Fallback: ciro_taslak (onaylı veya bekliyor)
    if not ciro_map:
        try:
            cur.execute(
                f"""
                SELECT DISTINCT ON (sube_id)
                       sube_id::text,
                       (COALESCE(nakit,0) + COALESCE(pos,0) + COALESCE(online,0)) AS ciro_tl
                FROM ciro_taslak
                WHERE tarih = %s AND durum IN ('onaylandi','bekliyor')
                {'AND sube_id = %s' if sube_id_filtre else ''}
                ORDER BY sube_id, CASE durum WHEN 'onaylandi' THEN 0 ELSE 1 END, olusturma DESC
                """,
                [hedef, *sube_params],
            )
            for r in cur.fetchall():
                sid = str(r["sube_id"])
                if sid not in ciro_map:
                    ciro_map[sid] = float(r["ciro_tl"] or 0)
        except Exception:
            pass

    # ── 7. Şube isim haritası ──
    cur.execute("SELECT id::text, ad FROM subeler")
    sube_adlari: Dict[str, str] = {str(r["id"]): str(r["ad"] or "") for r in cur.fetchall()}

    # ── 7b. L2 BEKLENEN maliyet (satış × fiyatlı reçete) — recete_api tek kaynak ──
    teorik_l2: Dict[str, Dict[str, Any]] = {}
    # ⚠️ SAVEPOINT ŞART (2026-08-03 canlı 500 dersi): try/except SQL hatasını
    # yutar ama Postgres transaction'ı ABORTED bırakır — sonraki INSERT
    # "InFailedSqlTransaction" ile patlar. Hata yutulacaksa savepoint'e sarılır.
    try:
        cur.execute("SAVEPOINT sp_fc_l2")
        from recete_api import teorik_maliyet_gun
        t2 = teorik_maliyet_gun(cur, str(hedef), alis_fiyat)
        # 🐞 EŞLEME FIX (2026-08-03): Evo cache anahtarı "Zafer Şubesi" gibi
        # EVO adlarıdır; kaba upper eşleşmesi hiçbirini tutmadı (L2 hep None).
        # Kanonik eşleştirici kullanılır — TEMA=Gazze alias'ı da orada.
        from evo_sync import evvel_sube_evo_id_eslestir, EVO_SUBE_ID_MAP
        t2subeler = t2.get("subeler") or {}
        for sid2, ad2 in sube_adlari.items():
            try:
                eid = evvel_sube_evo_id_eslestir(str(ad2 or ""))
            except Exception:  # noqa: BLE001
                eid = None
            e_ad = EVO_SUBE_ID_MAP.get(str(eid)) if eid is not None else None
            if e_ad and e_ad in t2subeler:
                teorik_l2[sid2] = t2subeler[e_ad]
        cur.execute("RELEASE SAVEPOINT sp_fc_l2")
    except Exception as e:  # noqa: BLE001 — L2 süs; L1'i düşüremez
        try:
            cur.execute("ROLLBACK TO SAVEPOINT sp_fc_l2")
        except Exception:
            pass
        logger.warning("teorik maliyet (L2) hatasi (yutuldu): %s", str(e)[:120])

    # ── 8. Her şube için hesapla ve yaz ──────────────────────────────────────
    # ⭐ KANONİK MODEL v2 (Codex danışmalı, 2026-08-03 — sahip doktrini):
    #   L1 GERÇEK maliyet  = ÜRÜN-AÇ × fiyat (her kalemde; sayım PARA SÜRMEZ).
    #     Ürün-aç "gerçek maliyet TETİKLEYİCİSİ"dir — fiziksel tüketim ölçümü
    #     değil; bar sayım denklemi operasyon sinyali olarak ayrı ekranda kalır.
    #   L2 BEKLENEN        = satış × reçete (ölçekleme YOK, kapsama % ile).
    #   L3 SAPMA           = L1 − L2 (fire/porsiyon/kayıt sinyali, öneri-only).
    # Eski hibrit (BAR'da açılış+aç−kapanış) definition_version=1 idi; v2 ile
    # SERİ TAMAMEN YENİDEN ÜRETİLİR (aynı kolonda karışık tanım bırakılmaz).
    # Kolon DDL'leri _ensure_maliyet_tablolari'da (savepoint'li) — burada tekrar yok.

    # Şube kümesi: ürün-aç OLAN ∪ ciro OLAN ∪ açılış sayımı OLAN
    tum_subeler = set(acilis_rows) | set(urun_ac_map) | set(diger_ac_map) | set(ciro_map)
    if sube_id_filtre:
        tum_subeler &= {str(sube_id_filtre)}

    sonuclar: List[Dict[str, Any]] = []
    for sid in sorted(tum_subeler):
        acilis  = acilis_rows.get(sid, {})
        kapanis = kapanis_rows.get(sid, {})
        urun_ac = urun_ac_map.get(sid, {k: 0 for k in _BAR_KEYS})
        ciro_tl = ciro_map.get(sid, 0.0)

        # L1 — BAR kalemleri: yalnız ÜRÜN-AÇ (delta) × fiyat
        bar_ac_tl = 0.0
        stok_degeri_tl = 0.0
        for k in _BAR_KEYS:
            fp = fiyat.get(k, 0.0)
            if fp <= 0:
                continue
            bar_ac_tl += max(0, urun_ac.get(k, 0)) * fp
            stok_degeri_tl += kapanis.get(k, 0) * fp   # bilgi — para sürmez

        # L1 — BAR-dışı kova (fiyat: alış → siparis_urun fallback)
        diger_urun_ac_tl = 0.0
        for kod, adet in (diger_ac_map.get(sid) or {}).items():
            fp = alis_fiyat.get(kod) or su_fiyat.get(kod, 0.0)
            if fp > 0:
                diger_urun_ac_tl += adet * fp

        actual_cogs = bar_ac_tl + diger_urun_ac_tl
        l2 = teorik_l2.get(sid) or {}
        teorik_tl = l2.get("teorik_tl")
        variance = (round(actual_cogs - float(teorik_tl), 2)
                    if teorik_tl is not None else None)
        food_cost_pct = round(actual_cogs / ciro_tl, 6) if ciro_tl > 0 else None

        cur.execute(
            """
            INSERT INTO sube_food_cost_gun
                (sube_id, tarih, ciro_tl, teorik_maliyet_tl, gercek_maliyet_tl,
                 food_cost_pct, stok_degeri_tl, diger_urun_ac_tl,
                 actual_open_cogs_tl, theoretical_recipe_cogs_tl,
                 teorik_kapsama_pct, teorik_alt_sinir, variance_tl,
                 definition_version, hesaplama_ts)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 2, NOW())
            ON CONFLICT (sube_id, tarih) DO UPDATE
                SET ciro_tl            = EXCLUDED.ciro_tl,
                    teorik_maliyet_tl  = EXCLUDED.teorik_maliyet_tl,
                    gercek_maliyet_tl  = EXCLUDED.gercek_maliyet_tl,
                    food_cost_pct      = EXCLUDED.food_cost_pct,
                    stok_degeri_tl     = EXCLUDED.stok_degeri_tl,
                    diger_urun_ac_tl   = EXCLUDED.diger_urun_ac_tl,
                    actual_open_cogs_tl = EXCLUDED.actual_open_cogs_tl,
                    theoretical_recipe_cogs_tl = EXCLUDED.theoretical_recipe_cogs_tl,
                    teorik_kapsama_pct = EXCLUDED.teorik_kapsama_pct,
                    teorik_alt_sinir   = EXCLUDED.teorik_alt_sinir,
                    variance_tl        = EXCLUDED.variance_tl,
                    definition_version = 2,
                    hesaplama_ts       = NOW()
            """,
            (sid, hedef,
             round(ciro_tl, 2),
             # legacy kolonlar: teorik_maliyet_tl YANLIŞ ADLI eski para kolonu —
             # eski okuyucular kırılmasın diye L1 yazılır; gercek_maliyet_tl
             # (doğru adlı, bugüne dek hiç doldurulmamıştı) da L1'dir.
             round(actual_cogs, 2), round(actual_cogs, 2),
             food_cost_pct,
             round(stok_degeri_tl, 2),
             round(diger_urun_ac_tl, 2),
             round(actual_cogs, 2),
             (round(float(teorik_tl), 2) if teorik_tl is not None else None),
             l2.get("kapsama_pct"),
             l2.get("alt_sinir"),
             variance),
        )

        sonuclar.append({
            "sube_id":          sid,
            "sube_adi":         sube_adlari.get(sid, sid),
            "tarih":            str(hedef),
            "ciro_tl":          round(ciro_tl, 2),
            "actual_open_cogs_tl": round(actual_cogs, 2),
            "teorik_maliyet_tl": round(actual_cogs, 2),   # geriye uyum
            "diger_urun_ac_tl": round(diger_urun_ac_tl, 2),
            "theoretical_recipe_cogs_tl": (round(float(teorik_tl), 2) if teorik_tl is not None else None),
            "teorik_kapsama_pct": l2.get("kapsama_pct"),
            "teorik_alt_sinir": l2.get("alt_sinir"),
            "variance_tl":      variance,
            "food_cost_pct":    round(food_cost_pct * 100, 2) if food_cost_pct else None,
            "stok_degeri_tl":   round(stok_degeri_tl, 2),
            "kapanis_var":      bool(kapanis),
            "definition_version": 2,
            "fiyatli_kalem_sayisi": sum(1 for k in _BAR_KEYS if fiyat.get(k, 0) > 0),
        })

    return sonuclar


class FoodCostHesaplaBody(BaseModel):
    tarih: Optional[str] = None        # YYYY-MM-DD, boş = bugün
    tarih_bitis: Optional[str] = None  # Aralık için bitiş; boş = tarih ile aynı
    sube_id: Optional[str] = None


@router.post("/maliyet/food-cost-hesapla")
def ops_food_cost_hesapla(body: FoodCostHesaplaBody = None):
    """
    Food cost hesaplama motoru — manuel veya otomatik tetikleyici.

    Verilen tarih aralığı için:
      1. Açılış/kapanış stok sayımlarından günlük tüketim hesaplar
      2. Alış fiyatlarıyla çarpar → teorik maliyet
      3. Ciro ile böler → food cost %
      4. sube_food_cost_gun tablosuna yazar (UPSERT)

    body: { tarih, tarih_bitis, sube_id }  — hepsi opsiyonel
    """
    body = body or FoodCostHesaplaBody()
    bas_str = (body.tarih or str(date.today()))[:10]
    bit_str = (body.tarih_bitis or bas_str)[:10]
    bas = date.fromisoformat(bas_str)
    bit = date.fromisoformat(bit_str)
    if (bit - bas).days > 90:
        raise HTTPException(400, "Aralık 90 günü geçemez")

    gun_listesi = []
    d = bas
    while d <= bit:
        gun_listesi.append(d)
        d += timedelta(days=1)

    with db() as (conn, cur):
        _ensure_maliyet_tablolari(cur)
        # Alış fiyatı var mı kontrol
        cur.execute("SELECT COUNT(*) AS n FROM urun_alis_fiyat WHERE gecerli_bitis IS NULL OR gecerli_bitis >= CURRENT_DATE")
        alis_fiyat_sayisi = int((cur.fetchone() or {}).get("n") or 0)

        tum_sonuclar = []
        for gun in gun_listesi:
            satirlar = _food_cost_hesapla_gun(cur, str(gun), body.sube_id)
            tum_sonuclar.extend(satirlar)

    return {
        "success": True,
        "hesaplanan_gun": len(gun_listesi),
        "hesaplanan_satir": len(tum_sonuclar),
        "alis_fiyat_sayisi": alis_fiyat_sayisi,
        "uyari": None if alis_fiyat_sayisi > 0 else "Alış fiyatı girilmemiş — teorik maliyet sıfır hesaplandı",
        "satirlar": tum_sonuclar,
    }


@router.get("/stok-hareketleri")
def ops_stok_hareketleri(
    gun: int = Query(30, ge=1, le=365),
    sube_id: Optional[str] = Query(None),
    kalem_kodu: Optional[str] = Query(None),
    hareket_turu: Optional[str] = Query(None),
    limit: int = Query(200, ge=1, le=2000),
):
    """
    Stok hareket defteri — append-only tarihsel kayıtlar.
    Filtreler: sube_id, kalem_kodu, hareket_turu (virgülle ayrılmış), gun.
    Kullanım: Operasyon Merkezi → Envanter → Stok Hareketi sekmesi.
    """
    with db() as (conn, cur):
        _ensure_stok_hareket_tablosu(cur)
        conds = ["zaman >= NOW() - (%s || ' days')::interval"]
        params: list = [gun]
        if sube_id:
            conds.append("sube_id = %s")
            params.append(sube_id.strip())
        if kalem_kodu:
            conds.append("kalem_kodu = %s")
            params.append(kalem_kodu.strip())
        if hareket_turu:
            turler = [t.strip().upper() for t in hareket_turu.split(",") if t.strip()]
            if turler:
                conds.append(f"hareket_turu = ANY(%s)")
                params.append(turler)
        where = " AND ".join(conds)
        cur.execute(
            f"""
            SELECT
                h.id,
                h.zaman AT TIME ZONE 'Europe/Istanbul' AS zaman,
                h.sube_id,
                COALESCE(s.ad, h.sube_id) AS sube_ad,
                h.kalem_kodu,
                h.kalem_adi,
                h.hareket_turu,
                h.miktar,
                h.onceki_miktar,
                h.sonraki_miktar,
                h.kaynak_tip,
                h.kaynak_id,
                h.kaynak_belge_no,
                h.personel_id,
                h.personel_ad,
                h.aciklama,
                h.onay_durumu
            FROM sube_depo_stok_hareket h
            LEFT JOIN subeler s ON s.id = h.sube_id
            WHERE {where}
            ORDER BY h.zaman DESC
            LIMIT %s
            """,
            params + [limit],
        )
        rows = []
        for r in cur.fetchall():
            d = dict(r)
            if d.get("zaman"):
                d["zaman"] = d["zaman"].isoformat()
            rows.append(d)

        # Özet: hareket_turu bazında adet ve toplam giriş/çıkış
        cur.execute(
            f"""
            SELECT
                hareket_turu,
                COUNT(*) AS adet,
                SUM(CASE WHEN miktar > 0 THEN miktar ELSE 0 END) AS toplam_giris,
                SUM(CASE WHEN miktar < 0 THEN ABS(miktar) ELSE 0 END) AS toplam_cikis
            FROM sube_depo_stok_hareket h
            WHERE {where}
            GROUP BY hareket_turu
            ORDER BY adet DESC
            """,
            params,
        )
        ozet = [dict(r) for r in cur.fetchall()]

        # Şube bazında özet
        cur.execute(
            f"""
            SELECT
                h.sube_id,
                COALESCE(s.ad, h.sube_id) AS sube_ad,
                COUNT(*) AS hareket_adet,
                SUM(CASE WHEN miktar > 0 THEN miktar ELSE 0 END) AS toplam_giris,
                SUM(CASE WHEN miktar < 0 THEN ABS(miktar) ELSE 0 END) AS toplam_cikis
            FROM sube_depo_stok_hareket h
            LEFT JOIN subeler s ON s.id = h.sube_id
            WHERE {where}
            GROUP BY h.sube_id, s.ad
            ORDER BY hareket_adet DESC
            """,
            params,
        )
        sube_ozet = [dict(r) for r in cur.fetchall()]

    return {
        "gun": gun,
        "toplam": len(rows),
        "satirlar": rows,
        "tur_ozet": ozet,
        "sube_ozet": sube_ozet,
    }


@router.get("/v2/depo-ozet")
def ops_v2_depo_ozet(gun: int = Query(30, ge=1, le=365)):
    """
    Tüm aktif şubelerin depo stoğu — pivot özet + son N gün harcama.
    UI: Operasyon Merkezi → "📊 Depo Genel Bakış" sekmesi.

    Dönen veri:
      - subeler: [{id, ad}, ...]
      - urunler: tüm kalem kodları — şube bazında mevcut, değer (TL), harcama
      - urunler_katalog_aktif: yalnızca siparis_urun (aktif) katalog ürünleri; her satırda
        ``subeler[şube_id].mevcut`` ile şube deposundaki adet (yoksa 0)
      - ozet: toplam stok değeri, toplam harcama, kritik/sıfır kalem sayıları,
              şube başına özetler

    Harcama kaynağı: operasyon_defter URUN_AC_JSON kalemler array'i
    (yeni dinamik katalog — siparis_urun.id bazlı).
    """
    bugun = bugun_tr()
    bas = bugun - timedelta(days=max(1, gun) - 1)

    with db() as (conn, cur):
        _ensure_sube_depo_alis_fiyati_col(cur)

        cur.execute("SELECT id, ad FROM subeler WHERE aktif=TRUE ORDER BY ad")
        subeler = [{"id": str(r["id"]), "ad": r["ad"]} for r in cur.fetchall()]
        sube_ids = [s["id"] for s in subeler]
        if not sube_ids:
            return {
                "gun": gun, "tarih_baslangic": str(bas), "tarih_bitis": str(bugun),
                "subeler": [], "urunler": [], "urunler_katalog_aktif": [],
                "ozet": {"toplam_stok_deger": 0, "toplam_harcama_deger": 0,
                         "kritik_kalem_sayisi": 0, "sifir_kalem_sayisi": 0,
                         "urun_sayisi": 0, "sube_basi": {}},
            }

        # Tüm depo stokları
        cur.execute("""
            SELECT sube_id, kalem_kodu, kalem_adi, mevcut_adet, min_stok,
                   COALESCE(alis_fiyati_tl, 0) AS birim_fiyat
            FROM sube_depo_stok
            WHERE sube_id = ANY(%s)
        """, (sube_ids,))
        stok_rows = cur.fetchall()

        # Katalog fiyatları (siparis_urun) — sube_depo_stok'ta birim_fiyat 0 ise fallback
        cur.execute("""
            SELECT su.id, su.ad, su.norm_ad, COALESCE(su.birim_fiyat_tl, 0) AS f,
                   sk.kod AS kategori_kod, sk.ad AS kategori_ad,
                   COALESCE(su.aktif, TRUE) AS aktif,
                   su.depo_stok_kalem_kodu
            FROM siparis_urun su
            LEFT JOIN siparis_kategori sk ON sk.id = su.kategori_id
        """)
        global_fiyat = {}
        urun_meta = {}
        # norm_ad → uuid ve uuid → norm_ad çift yönlü harita (tüketim eşleştirmesi için)
        norm_to_uuid: Dict[str, str] = {}
        uuid_to_norm: Dict[str, str] = {}
        uuid_to_depo: Dict[str, str] = {}   # UUID → fiziksel havuz kodu (bardak_buyuk…)
        for r in cur.fetchall():
            kid = str(r["id"])
            meta_entry = {
                "ad": r["ad"],
                "kategori_kod": r.get("kategori_kod") or "",
                "kategori_ad": r.get("kategori_ad") or "",
                "aktif": bool(r.get("aktif")) if r.get("aktif") is not None else True,
            }
            global_fiyat[kid] = float(r["f"] or 0)
            urun_meta[kid] = meta_entry
            # norm_ad varsa haritaya ekle
            norm_ad = str(r.get("norm_ad") or "").strip() if r.get("norm_ad") else ""
            if not norm_ad:
                # norm_ad kolonu boşsa ad'dan türet (eski kayıtlar için fallback)
                norm_ad = re.sub(r'[^a-z0-9]+', '_',
                    str(r["ad"]).lower()
                    .replace('ğ','g').replace('ü','u').replace('ş','s')
                    .replace('ı','i').replace('ö','o').replace('ç','c')
                ).strip('_')
            if norm_ad:
                norm_to_uuid[norm_ad] = kid
                uuid_to_norm[kid] = norm_ad
                if norm_ad not in urun_meta:
                    urun_meta[norm_ad] = meta_entry
            # Fiziksel havuz kodları (bardak_buyuk, kahve_paket vb.) için de eşleştir
            depo_kod = str(r.get("depo_stok_kalem_kodu") or "").strip()
            if depo_kod and depo_kod not in urun_meta:
                global_fiyat[depo_kod] = float(r["f"] or 0)
                urun_meta[depo_kod] = meta_entry
            # 🔗 UUID → FİZİKSEL HAVUZ KODU (2026-08-08, sahip: "14oz açılımı 0
            # olması neredeyse imkânsız"). Stok hareketleri kanonik çözücüden
            # (operasyon_stok_motor.depo_kalem_kodu_resolve) geçip SABİT koda
            # yazılıyor; bu okuma ise JSON'daki `urun_id`yi (UUID) doğrudan
            # anahtar yapıyordu → aynı ürün İKİ KARTA bölünüyordu:
            #   bardak_buyuk : stok 33.754 · harcanan 0   (sahte "200 günlük stok")
            #   <uuid>       : stok 0      · harcanan 303 (sahte "hiç stok yok")
            # 7 kalemde bu bölünme vardı (14oz/8oz/Plastik Bardak, Su, Redbull,
            # Cookie, Z Peçete) ve sipariş önerisini de yanlış besliyordu.
            if depo_kod:
                uuid_to_depo[kid] = depo_kod

        # Son N gün ürün-aç olayları — kalem_kodu bazında topla.
        # 🐞 FIX (2026-08-03, canlı denetim "30g harcanan 0₺" vakası): sorgu yalnız
        # URUN_AC okuyordu; FIX C1'den (2026-07-06) beri bitince-modu ürünler
        # URUN_KULLANIMA_AL etiketiyle yazılıyor → depo harcaması HEP 0 görünüyordu.
        # gun-gun COGS okumasıyla AYNI desen: iki etiket + '[BİTTİ]' çift-sayım
        # dışlaması + prefix normalize (REPLACE).
        cur.execute("""
            SELECT sube_id,
                   REPLACE(aciklama, 'URUN_KULLANIMA_AL_JSON:', 'URUN_AC_JSON:') AS aciklama
            FROM operasyon_defter
            WHERE etiket IN ('URUN_AC', 'URUN_KULLANIMA_AL')
              AND NOT (etiket = 'URUN_AC' AND aciklama LIKE %s)
              AND tarih BETWEEN %s AND %s
              AND sube_id = ANY(%s)
        """, ("%[BİTTİ]%", bas, bugun, sube_ids))

        # harcama[sid][kod] = adet — kod her zaman UUID veya havuz kodu (normalize edilmiş)
        # 🐞 FIX-2 (2026-08-03, aynı vaka): bitince-modu payload'ı kalemleri
        # `urun_id`/`urun_ad` anahtarıyla yazar (sube_panel:4028), `kalem_kodu`
        # YOK — parse yalnız kalem_kodu aradığı için satırlar atlanıyordu.
        # Ayrıca not-eki JSON'un hemen ardına eklenebiliyor → json.loads yerine
        # raw_decode (recete_api deseniyle aynı).
        _dec = json.JSONDecoder()
        harcama: Dict[str, Dict[str, int]] = {sid: {} for sid in sube_ids}
        for row in cur.fetchall():
            ack = row.get("aciklama") or ""
            i = ack.find("URUN_AC_JSON:")
            if i < 0:
                continue
            try:
                j, _ = _dec.raw_decode(ack[i + len("URUN_AC_JSON:"):].strip())
            except Exception:
                continue
            kalemler = j.get("kalemler") if isinstance(j, dict) else None
            if not isinstance(kalemler, list):
                continue
            sid = str(row["sube_id"])
            for k in kalemler:
                if not isinstance(k, dict):
                    continue
                kod = str(k.get("kalem_kodu") or k.get("urun_id") or "").strip()
                if not kod:
                    # son çare: ürün adından norm eşleşmesi (eski kayıtlar)
                    ad_n = re.sub(r'[^a-z0-9]+', '_',
                        str(k.get("urun_ad") or "").lower()
                        .replace('ğ','g').replace('ü','u').replace('ş','s')
                        .replace('ı','i').replace('ö','o').replace('ç','c')).strip('_')
                    kod = norm_to_uuid.get(ad_n, "")
                if not kod:
                    continue
                # norm_ad olarak geldiyse UUID'ye çevir (eski kayıtlar uyumluluğu)
                if kod in norm_to_uuid:
                    kod = norm_to_uuid[kod]
                # 🔗 UUID → fiziksel havuz kodu: stok hangi kartta duruyorsa
                # tüketim de ORAYA yazılmalı. Eşleme tanımlı değilse UUID kalır
                # (ürün gerçekten ayrı bir kalemdir ya da eşleme sahibi bekliyor).
                if kod in uuid_to_depo:
                    kod = uuid_to_depo[kod]
                try:
                    adet = int(k.get("adet") or 0)
                except (TypeError, ValueError):
                    adet = 0
                if adet > 0:
                    harcama.setdefault(sid, {})
                    harcama[sid][kod] = harcama[sid].get(kod, 0) + adet

        # Pivot oluştur
        def _bos_sube_blok():
            return {sid: {"mevcut": 0, "deger": 0.0, "harcanan": 0,
                          "harcanan_deger": 0.0, "min_stok": 0} for sid in sube_ids}

        pivot: Dict[str, dict] = {}

        def _ensure(kod: str, ad_fallback: str = "", fiyat_fallback: float = 0.0):
            if kod in pivot:
                return pivot[kod]
            meta = urun_meta.get(kod, {})
            pivot[kod] = {
                "kalem_kodu": kod,
                "kalem_adi": ad_fallback or meta.get("ad") or kod,
                "kategori_kod": meta.get("kategori_kod", ""),
                "kategori_ad": meta.get("kategori_ad", ""),
                "birim_fiyat": float(fiyat_fallback or global_fiyat.get(kod, 0.0)),
                "min_stok_max": 0,
                "subeler": _bos_sube_blok(),
                "toplam_adet": 0,
                "toplam_deger": 0.0,
                "toplam_harcanan": 0,
                "toplam_harcanan_deger": 0.0,
            }
            return pivot[kod]

        for r in stok_rows:
            kod = str(r["kalem_kodu"])
            sid = str(r["sube_id"])
            mevcut = int(r["mevcut_adet"] or 0)
            min_s = int(r["min_stok"] or 0)
            row_fiyat = float(r["birim_fiyat"] or 0)
            p = _ensure(kod, r["kalem_adi"] or "", row_fiyat or global_fiyat.get(kod, 0.0))
            # Şube bazlı fiyatı pivot fiyatı olarak güncel tut (max)
            if row_fiyat > p["birim_fiyat"]:
                p["birim_fiyat"] = row_fiyat
            fiyat = p["birim_fiyat"]
            deger = mevcut * fiyat
            p["subeler"].setdefault(sid, {"mevcut": 0, "deger": 0.0, "harcanan": 0,
                                          "harcanan_deger": 0.0, "min_stok": 0})
            p["subeler"][sid]["mevcut"] = mevcut
            p["subeler"][sid]["min_stok"] = min_s
            p["subeler"][sid]["deger"] = round(deger, 2)
            p["toplam_adet"] += mevcut
            p["toplam_deger"] += deger
            if min_s > p["min_stok_max"]:
                p["min_stok_max"] = min_s

        # Harcama bilgisini ekle
        for sid, kod_map in harcama.items():
            for kod, adet in kod_map.items():
                p = _ensure(kod)
                fiyat = p["birim_fiyat"]
                deger = adet * fiyat
                p["subeler"].setdefault(sid, {"mevcut": 0, "deger": 0.0, "harcanan": 0,
                                              "harcanan_deger": 0.0, "min_stok": 0})
                p["subeler"][sid]["harcanan"] = adet
                p["subeler"][sid]["harcanan_deger"] = round(deger, 2)
                p["toplam_harcanan"] += adet
                p["toplam_harcanan_deger"] += deger

        # Yuvarla + sırala (toplam değer azalan)
        for p in pivot.values():
            p["toplam_deger"] = round(p["toplam_deger"], 2)
            p["toplam_harcanan_deger"] = round(p["toplam_harcanan_deger"], 2)

        urunler = sorted(pivot.values(),
                         key=lambda x: (-x["toplam_deger"], -x["toplam_adet"], x["kalem_adi"]))

        # Aktif sipariş kataloğu ürünleri — tüm şubelerde mevcut adet (stokta hiç yoksa 0)
        katalog_aktif_ids = {
            kid for kid, m in urun_meta.items() if m.get("aktif", True)
        }
        for kid in katalog_aktif_ids:
            m = urun_meta[kid]
            _ensure(kid, str(m.get("ad") or kid), float(global_fiyat.get(kid, 0.0)))
        urunler_katalog_aktif = sorted(
            [p for p in pivot.values() if str(p.get("kalem_kodu") or "") in katalog_aktif_ids],
            key=lambda x: (
                (x.get("kategori_ad") or x.get("kategori_kod") or "").lower(),
                (x.get("kalem_adi") or x.get("kalem_kodu") or "").lower(),
            ),
        )

        # Özet
        sube_ozet = {sid: {"stok_deger": 0.0, "harcama_deger": 0.0,
                           "kritik": 0, "sifir": 0} for sid in sube_ids}
        toplam_stok = 0.0
        toplam_harcama = 0.0
        for p in urunler:
            kk = str(p.get("kategori_kod") or "")
            ka = str(p.get("kategori_ad") or "")
            kad = str(p.get("kalem_adi") or "")
            kod = str(p.get("kalem_kodu") or "")
            for sid, sd in p["subeler"].items():
                if sid not in sube_ozet:
                    continue
                sube_ozet[sid]["stok_deger"] += sd["deger"]
                sube_ozet[sid]["harcama_deger"] += sd["harcanan_deger"]
                try:
                    m = int(sd["mevcut"] or 0)
                except (TypeError, ValueError):
                    m = 0
                if m <= 0:
                    sube_ozet[sid]["sifir"] += 1
                elif _depo_stok_satir_alarm_mu(m, kad, kod, kk, ka):
                    sube_ozet[sid]["kritik"] += 1
            toplam_stok += p["toplam_deger"]
            toplam_harcama += p["toplam_harcanan_deger"]

        kritik_kalem = sum(so["kritik"] for so in sube_ozet.values())
        sifir_kalem = sum(so["sifir"] for so in sube_ozet.values())
        for so in sube_ozet.values():
            so["stok_deger"] = round(so["stok_deger"], 2)
            so["harcama_deger"] = round(so["harcama_deger"], 2)

        return {
            "gun": gun,
            "tarih_baslangic": str(bas),
            "tarih_bitis": str(bugun),
            "subeler": subeler,
            "urunler": urunler,
            "urunler_katalog_aktif": urunler_katalog_aktif,
            "ozet": {
                "toplam_stok_deger": round(toplam_stok, 2),
                "toplam_harcama_deger": round(toplam_harcama, 2),
                "kritik_kalem_sayisi": kritik_kalem,
                "sifir_kalem_sayisi": sifir_kalem,
                "urun_sayisi": len(urunler),
                "sube_basi": sube_ozet,
            },
        }


@router.get("/v2/urun-ac-akis")
def ops_v2_urun_ac_akis(
    tarih: Optional[str] = Query(None, description="YYYY-MM-DD"),
    limit: int = Query(80, ge=1, le=300),
):
    """
    Şubelerde «ürün aç» (URUN_AC) hareketlerini gün bazında listeler.
    Varsayılan tarih: bugün.
    """
    hedef_tarih = (tarih or str(bugun_tr())).strip()
    try:
        hedef_tarih = str(datetime.strptime(hedef_tarih, "%Y-%m-%d").date())
    except ValueError:
        raise HTTPException(400, "tarih formatı YYYY-MM-DD olmalı")

    try:
        with db() as (conn, cur):
            cur.execute(
                """
                SELECT column_name
                FROM information_schema.columns
                WHERE table_schema = 'public' AND table_name = 'operasyon_defter'
                """
            )
            cols = {str(r.get("column_name") or "") for r in (cur.fetchall() or [])}
            has_bildirim = "bildirim_saati" in cols
            has_personel_ad = "personel_ad" in cols
            has_personel_id = "personel_id" in cols
            has_olusturma = "olusturma" in cols

            select_personel_id = "d.personel_id" if has_personel_id else "NULL::text AS personel_id"
            select_personel_ad = "d.personel_ad" if has_personel_ad else "NULL::text AS personel_ad"
            select_bildirim = "d.bildirim_saati" if has_bildirim else "NULL::text AS bildirim_saati"
            select_olusturma = "d.olusturma" if has_olusturma else "NULL::timestamp AS olusturma"
            order_expr = "d.olusturma DESC NULLS LAST" if has_olusturma else "d.id DESC"

            cur.execute(
                f"""
                SELECT
                    d.id,
                    d.sube_id,
                    COALESCE(s.ad, d.sube_id) AS sube_adi,
                    d.tarih,
                    {select_bildirim},
                    {select_personel_id},
                    {select_personel_ad},
                    {select_olusturma},
                    d.aciklama
                FROM operasyon_defter d
                LEFT JOIN subeler s ON s.id = d.sube_id
                WHERE d.etiket = 'URUN_AC'
                  AND d.tarih = %s::date
                ORDER BY {order_expr}, d.id DESC
                LIMIT %s
                """,
                (hedef_tarih, limit),
            )
            rows = cur.fetchall() or []
    except Exception as e:
        logger.exception("ops_v2_urun_ac_akis hata: %s", e)
        return {
            "tarih": hedef_tarih,
            "toplam_islem": 0,
            "toplam_adet": 0,
            "kayitlar": [],
            "son_guncelleme": str(dt_now_tr()),
        }

    kayitlar: List[Dict[str, Any]] = []
    toplam_adet = 0
    for r in rows:
        payload = _urun_ac_payload_parse(str(r.get("aciklama") or ""))
        delta_raw = payload.get("delta") if isinstance(payload.get("delta"), dict) else {}
        kalemler_raw = payload.get("kalemler") if isinstance(payload.get("kalemler"), list) else []

        # NOT: Şube paneli aynı kalemi HEM delta HEM kalemler alanına yazar
        # (bkz. sube_panel.py:3000 — depo iki kez düşmesin diye). Toplama
        # yaparken çift sayımı önlemek için ad bazında max(delta, kalemler)
        # mantığı kullanılır (bar-ozet/_urun_ac_delta_parse ile tutarlı).
        delta_map: Dict[str, int] = {}
        for k, v in delta_raw.items():
            try:
                adet = max(0, int(v or 0))
            except (TypeError, ValueError):
                adet = 0
            if adet <= 0:
                continue
            ad = urun_ac_gorunen_ad(k)
            delta_map[ad] = delta_map.get(ad, 0) + adet

        kalemler_map: Dict[str, int] = {}
        for it in kalemler_raw:
            if not isinstance(it, dict):
                continue
            raw_ad = (
                str(it.get("urun_ad") or "").strip()
                or str(it.get("kalem_adi") or "").strip()
                or str(it.get("kalem_kodu") or "").strip()
            )
            if not raw_ad:
                continue
            try:
                adet = max(0, int(it.get("adet") or 0))
            except (TypeError, ValueError):
                adet = 0
            if adet <= 0:
                continue
            ad = urun_ac_gorunen_ad(raw_ad)
            kalemler_map[ad] = kalemler_map.get(ad, 0) + adet

        # Birleştir: aynı ad varsa max al (çift sayım engellenir),
        # sadece birinde varsa onu al.
        urun_map: Dict[str, int] = {}
        for ad in set(delta_map.keys()) | set(kalemler_map.keys()):
            urun_map[ad] = max(int(delta_map.get(ad, 0)), int(kalemler_map.get(ad, 0)))

        urunler = [{"urun_ad": ad, "adet": int(adet)} for ad, adet in urun_map.items()]
        urunler.sort(key=lambda x: (-int(x.get("adet") or 0), str(x.get("urun_ad") or "")))
        adet_toplam = sum(int(u.get("adet") or 0) for u in urunler)
        toplam_adet += adet_toplam

        kayitlar.append(
            {
                "id": r.get("id"),
                "sube_id": r.get("sube_id"),
                "sube_adi": r.get("sube_adi"),
                "tarih": str(r.get("tarih") or hedef_tarih),
                "saat": str(r.get("bildirim_saati") or "")[:8],
                "personel_id": r.get("personel_id"),
                "personel_ad": r.get("personel_ad"),
                "olusturma": str(r.get("olusturma") or ""),
                "adet_toplam": int(adet_toplam),
                "urunler": urunler,
            }
        )

    return {
        "tarih": hedef_tarih,
        "toplam_islem": len(kayitlar),
        "toplam_adet": int(toplam_adet),
        "kayitlar": kayitlar,
        "son_guncelleme": str(dt_now_tr()),
    }


# ── Sipariş Kuyruğu: bekleyen siparişler + stok etki bilgisi ─────

@router.get("/v2/bekleyen-siparisler")
def ops_v2_bekleyen_siparisler(
    gun: int = Query(7, ge=1, le=30),
    aday_depo: Optional[str] = Query(
        None,
        description="Henüz hedef depo ATANMAMIŞ taleplerde stok hesabının "
                    "yapılacağı ADAY depo şube id'si.",
    ),
):
    """
    Merkez paneli için bekleyen sipariş kuyruğu.
    Her sipariş için:
      - Şubenin deposunda bu ürün var mı? (sube_depo_stok)
      - Gönderirsek merkezde ne kalır? (merkez_stok_kart)
      - Davranış uyarısı tetiklendi mi? (sube_operasyon_uyari)

    🔀 `aday_depo` (sahip isteği, 2026-08-28): "sipariş geldiğinde her ürünün
    TEMA şubesinde ne kadar olduğu parantezde yazmalı — depodan sayıyı
    yollayabilecek miyim görmeliyim." Hedef depo ATANANA KADAR
    `hedef_depo_mevcut` null geliyordu, çünkü stok hesabı yalnız ATANMIŞ depo
    için yapılıyordu. Yani karar verilmeden önce karar için gereken sayı yoktu.
    Aday depo verilirse o depo üzerinden hesaplanır; hesabın HANGİ depodan
    yapıldığı `stok_hesap_kaynagi` ile zaten dönüyor (yanlış depoya bakarak
    karar verilmesin).
    """
    with db() as (conn, cur):
        cur.execute("""
            SELECT st.id, st.sube_id, s.ad AS sube_adi,
                   st.tarih, st.olusturma, st.personel_id, st.personel_ad,
                   st.not_aciklama, st.kalemler,
                   COALESCE(st.hedef_depo_sube_id, st.sevkiyat_sube_id) AS hedef_depo_sube_id,
                   st.tahsis_kaynak_depo_sube_id,
                   NULLIF(TRIM(st.operasyon_yonlendirme_talimati), '') AS operasyon_yonlendirme_talimati
            FROM siparis_talep st
            JOIN subeler s ON s.id = st.sube_id
            WHERE st.durum = 'bekliyor'
              AND st.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
            ORDER BY st.olusturma ASC NULLS LAST, st.id
        """, (gun,))
        talepler = cur.fetchall() or []
        merkez_map = merkez_stok_kart_haritasi(cur)
        # Şube id → ad. Ad UYDURULMAZ, tablodan okunur; bulunamayan id için
        # None döner ve ekran sayıyı depo adı OLMADAN yazar (yanlış ad yazmaz).
        _depo_ad_haritasi: Dict[str, str] = {}
        try:
            cur.execute("SELECT id, ad FROM subeler")
            for _sr in cur.fetchall() or []:
                _sd = dict(_sr)
                _sid = str(_sd.get("id") or "").strip()
                if _sid:
                    _depo_ad_haritasi[_sid] = str(_sd.get("ad") or "").strip()
        except Exception:
            _depo_ad_haritasi = {}

        # Aday depo verilmediyse: SON KULLANILAN depoyu bul. Uydurma değil,
        # ÖLÇÜM — geçmiş atamaların çoğunluğu. Bulunamazsa aday YOK ve ekran
        # eskisi gibi "hedef depo atanmadı" der (sahte sayı üretilmez).
        # ⚠️ ŞUBE BAZLI (Codex denetimi, 2026-08-28): önceki sürüm ŞİRKET
        #    GENELİ çoğunluğu alıyordu. Bir şube alışkanlıkla başka bir
        #    depodan besleniyorsa ekran onun için YANLIŞ deponun sayısını
        #    gösteriyordu. Önce o şubenin kendi geçmişi, yoksa genel.
        # ⚠️ BERABERLİK DETERMİNİSTİK: `ORDER BY n DESC, d ASC` — ikinci
        #    anahtar olmadan eşitlikte sonuç fiziksel satır sırasına göre
        #    oynuyor, aynı ekran her yenilemede farklı depo gösterebiliyordu.
        _aday_istek = (aday_depo or "").strip() or None
        _sube_aday: Dict[str, str] = {}
        _genel_aday: Optional[str] = None
        if not _aday_istek:
            try:
                cur.execute(
                    """
                    SELECT sube_id,
                           COALESCE(hedef_depo_sube_id, sevkiyat_sube_id) AS d,
                           COUNT(*) AS n
                    FROM siparis_talep
                    WHERE COALESCE(hedef_depo_sube_id, sevkiyat_sube_id) IS NOT NULL
                      AND tarih >= CURRENT_DATE - INTERVAL '90 day'
                    GROUP BY 1, 2
                    ORDER BY sube_id, n DESC, d ASC
                    """
                )
                for _ar in cur.fetchall() or []:
                    _a = dict(_ar)
                    _sid = str(_a.get("sube_id") or "").strip()
                    _d = str(_a.get("d") or "").strip()
                    # ORDER BY sayesinde her şubenin İLK satırı en çoğu
                    if _sid and _d and _sid not in _sube_aday:
                        _sube_aday[_sid] = _d
                cur.execute(
                    """
                    SELECT COALESCE(hedef_depo_sube_id, sevkiyat_sube_id) AS d,
                           COUNT(*) AS n
                    FROM siparis_talep
                    WHERE COALESCE(hedef_depo_sube_id, sevkiyat_sube_id) IS NOT NULL
                      AND tarih >= CURRENT_DATE - INTERVAL '90 day'
                    GROUP BY 1 ORDER BY n DESC, d ASC LIMIT 1
                    """
                )
                _gr = cur.fetchone()
                if _gr:
                    _genel_aday = str(dict(_gr).get("d") or "").strip() or None
            except Exception:
                _sube_aday = {}
                _genel_aday = None

        sonuc = []
        for talep in talepler:
            tid = talep.get("id")
            sube_id = talep.get("sube_id")
            kalemler = talep.get("kalemler") or []
            if isinstance(kalemler, str):
                try:
                    kalemler = json.loads(kalemler)
                except Exception:
                    kalemler = []
            if not isinstance(kalemler, list):
                kalemler = []

            # Atanmış depo varsa O esastır; yoksa adaya düşülür. Aday, atanmışın
            # yerine GEÇMEZ — yoksa ekran gerçekte kullanılmayacak bir deponun
            # sayısını gösterir.
            hedef_v2 = str(talep.get("hedef_depo_sube_id") or "").strip() or None
            # Aday sırası: istek > BU ŞUBENİN geçmişi > şirket geneli.
            _aday = _aday_istek or _sube_aday.get(str(sube_id or "")) or _genel_aday
            _aday_kaynak = (
                "istek" if _aday_istek
                else ("gecmis_sube" if _sube_aday.get(str(sube_id or ""))
                      else ("gecmis_genel" if _genel_aday else None))
            )
            if not hedef_v2:
                hedef_v2 = _aday
            fl, davranis = _enrich_kalemler_ve_davranis(
                cur,
                sube_id=str(sube_id or ""),
                kalemler=kalemler,
                merkez_map=merkez_map,
                hedef_depo_sube_id=hedef_v2,
                talep_id=str(tid or ""),
            )

            kalem_detay: List[Dict[str, Any]] = []
            for it in kalemler:
                if not isinstance(it, dict):
                    continue
                kk = str(it.get("kalem_kodu") or "").strip()
                urun_ad = str(it.get("urun_ad") or kk or "")
                ist = max(0, int(it.get("adet") or 0))
                kalem_detay.append({
                    "kalem_kodu": kk,
                    "urun_ad": urun_ad,
                    "istenen_adet": ist,
                    "merkez_mevcut": int(it.get("merkez_mevcut", -1)),
                    "merkez_rezerve": int(it.get("merkez_rezerve") or 0),
                    "merkez_min_stok": int(it.get("merkez_min_stok") or 0),
                    "kaynak_kullanilabilir": it.get("kaynak_kullanilabilir"),
                    "kalan_gonderince": it.get("kalan_gonderince"),
                    "alarm_merkez": bool(it.get("alarm_merkez")),
                    "merkez_barem_risk": bool(it.get("merkez_barem_risk")),
                    # ⚠️ `or 0` KULLANILMAZ: None = "şube deposunda kayıt yok"
                    #    demek; 0'a çevirmek "0 adet var" iddiası olur ve
                    #    motorda yapılan ayrımı burada geri bozardı.
                    "sube_depo_mevcut": (
                        int(it["sube_depo_mevcut"])
                        if it.get("sube_depo_mevcut") is not None else None
                    ),
                    "sube_depo_kayit_var": bool(it.get("sube_depo_kayit_var")),
                    # 🪞 Ad katalogda birden fazla urune denk geliyorsa okunan
                    # sayi IKISINDEN BIRININ sayisidir, toplam DEGILDIR.
                    "kimlik_belirsiz": bool(it.get("kimlik_belirsiz")),
                    "sube_zaten_var": bool(it.get("sube_zaten_var")),
                    "gonderim_kaynagi": it.get("gonderim_kaynagi"),
                    "hedef_depo_mevcut": it.get("hedef_depo_mevcut"),
                    "hedef_depo_rezerve": it.get("hedef_depo_rezerve"),
                    "hedef_depo_min_stok": it.get("hedef_depo_min_stok"),
                })

            cn_v2 = siparis_cift_gonderim_bilgi_notu(
                cur,
                talep_id=str(tid),
                sube_id=str(sube_id or ""),
                kalemler=kalemler,
                olusturma=talep.get("olusturma"),
            )
            row_v2: Dict[str, Any] = {
                "id": tid,
                "sube_id": sube_id,
                "sube_adi": talep.get("sube_adi"),
                "tarih": str(talep.get("tarih") or ""),
                "olusturma": str(talep.get("olusturma") or ""),
                "personel_id": talep.get("personel_id"),
                "personel_ad": talep.get("personel_ad"),
                "not_aciklama": talep.get("not_aciklama"),
                "kalemler": kalem_detay,
                "davranis_uyarilari": davranis,
                "stok_alarm_var": fl["stok_alarm_var"],
                "barem_risk_var": fl["barem_risk_var"],
                "gereksiz_var": fl["gereksiz_var"],
                "merkez_kayit_eksik_var": fl["merkez_kayit_eksik_var"],
                "uyari_var": (
                    len(davranis) > 0
                    or fl["barem_risk_var"]
                    or fl["merkez_kayit_eksik_var"]
                    or fl["stok_alarm_var"]
                    or fl["gereksiz_var"]
                ),
                "stok_hesap_kaynagi": fl.get("stok_hesap_kaynagi"),
                "hedef_depo_sube_id": fl.get("hedef_depo_sube_id"),
                "operasyon_yonlendirme_talimati": talep.get("operasyon_yonlendirme_talimati"),
                "tahsis_kaynak_depo_sube_id": talep.get("tahsis_kaynak_depo_sube_id"),
                # Sayının HANGİ deponun sayısı olduğu ADIYLA döner — ekran
                # "(TEMA: 12)" yazabilsin diye. Atanmış mı aday mı ayrımı da
                # verilir: aday sayı bir TAHMİN değil ama bir KARAR da değil.
                "stok_depo_adi": _depo_ad_haritasi.get(str(hedef_v2 or "")) or None,
                "stok_depo_atanmis": bool(
                    str(talep.get("hedef_depo_sube_id") or "").strip()
                ),
                # Aday nereden geldi: istek mi, gecmis olcumu mu. Ekran
                # "TEMA (son sevkiyatlarin deposu)" diyebilsin diye.
                "stok_depo_kaynagi": (
                    "atanmis"
                    if str(talep.get("hedef_depo_sube_id") or "").strip()
                    else _aday_kaynak
                ),
            }
            if cn_v2:
                row_v2["cift_siparis_bilgi_notu"] = cn_v2
                row_v2["uyari_var"] = True
            sonuc.append(row_v2)

    return {"siparisler": sonuc, "toplam": len(sonuc)}


# ─────────────────────────────────────────────────────────────
# SİPARİŞ BİRLEŞTİRME  (merkez kuyruğu çoklu seçim)
# ─────────────────────────────────────────────────────────────

class OpsSiparisBirlestirBody(BaseModel):
    talep_idler: List[str]          # en az 2 talep id
    not_aciklama: Optional[str] = None  # isteğe bağlı merkez notu


@router.post("/siparis/birlestir")
def ops_siparis_birlestir(body: OpsSiparisBirlestirBody):
    """
    Merkez kuyruğundaki 2+ bekleyen siparişi birleştirir.

    Kurallar:
    - Tüm talepler aynı sube_id'den olmalı
    - Tüm talepler durum='bekliyor' ve henüz depoya yönlendirilmemiş olmalı
      (hedef_depo_sube_id IS NULL)
    - Aynı urun_id → adet toplanır; urun_id yoksa urun_ad.lower() eşleşir
    - Eski talepler durum='iptal' yapılır, not olarak yeni id yazılır
    - Yeni birleşik siparis_talep kaydı döner
    """
    log = logging.getLogger(__name__)
    idler = [str(x).strip() for x in (body.talep_idler or []) if str(x).strip()]
    if len(idler) < 2:
        raise HTTPException(400, "En az 2 sipariş seçilmeli")
    if len(idler) > 20:
        raise HTTPException(400, "En fazla 20 sipariş birleştirilebilir")

    with db() as (conn, cur):
        # Kilitle ve veri çek
        placeholders = ",".join(["%s"] * len(idler))
        cur.execute(
            f"""
            SELECT id, sube_id, durum, kalemler,
                   COALESCE(hedef_depo_sube_id, sevkiyat_sube_id) AS hedef_depo_sube_id
            FROM siparis_talep
            WHERE id IN ({placeholders})
            FOR UPDATE
            """,
            tuple(idler),
        )
        rows = cur.fetchall() or []
        bulunan_idler = {str(r["id"]) for r in rows}
        eksik = set(idler) - bulunan_idler
        if eksik:
            raise HTTPException(404, f"Bulunamayan talep(ler): {', '.join(sorted(eksik))}")

        # Validasyon
        sube_id_set = {str(r["sube_id"] or "") for r in rows}
        if len(sube_id_set) > 1:
            raise HTTPException(400, "Birleştirilecek siparişler aynı şubeden olmalı")

        for r in rows:
            if str(r.get("durum") or "") != "bekliyor":
                raise HTTPException(
                    400,
                    f"Talep #{str(r['id'])[:8]} birleştirilemez — durumu: {r.get('durum')}"
                )
            hedef = str(r.get("hedef_depo_sube_id") or "").strip()
            if hedef:
                raise HTTPException(
                    400,
                    f"Talep #{str(r['id'])[:8]} zaten depoya yönlendirilmiş ({hedef}) — birleştirilemez"
                )

        sube_id = sube_id_set.pop()

        # Şube adını al
        cur.execute("SELECT ad FROM subeler WHERE id=%s", (sube_id,))
        sr = cur.fetchone()
        sube_adi = str(sr["ad"]) if sr else sube_id

        # Kalemleri birleştir
        # Öncelik: urun_id (varsa), yoksa urun_ad.lower()
        bilesim: Dict[str, Dict] = {}  # anahtar → kalem dict
        for r in rows:
            kalemler_raw = r.get("kalemler") or []
            if isinstance(kalemler_raw, str):
                try:
                    kalemler_raw = json.loads(kalemler_raw)
                except Exception:
                    kalemler_raw = []
            if not isinstance(kalemler_raw, list):
                kalemler_raw = []

            for k in kalemler_raw:
                if not isinstance(k, dict):
                    continue
                # ⛔ MERKEZ İPTALİ BİRLEŞTİRMEDE DİRİLMEZ (Fable denetimi,
                # 2026-08-28): birleştirme kalemleri yalnız `adet > 0` şartıyla
                # kopyalıyordu; `iptal` bayrağını ne kontrol ediyor ne de yeni
                # siparişe taşıyordu. Merkezin geri çevirdiği kalem, iki sipariş
                # birleştirilince İŞARETSİZ ve CANLI olarak yeniden doğuyordu.
                if k.get("iptal"):
                    continue
                adet = max(0, int(k.get("adet") or k.get("istenen_adet") or 0))
                if adet <= 0:
                    continue

                uid = str(k.get("urun_id") or "").strip()
                urun_ad = str(k.get("urun_ad") or k.get("kalem_kodu") or "").strip()
                kalem_kodu = str(k.get("kalem_kodu") or "").strip()

                # Anahtar seç
                anahtar = uid if uid else urun_ad.lower()
                if not anahtar:
                    continue

                if anahtar in bilesim:
                    bilesim[anahtar]["adet"] += adet
                else:
                    bilesim[anahtar] = {
                        "urun_id": uid or None,
                        "urun_ad": urun_ad,
                        "kalem_kodu": kalem_kodu or None,
                        "adet": adet,
                        "kategori_kod": str(k.get("kategori_kod") or k.get("kategori") or "").strip() or None,
                    }

        kalem_listesi = list(bilesim.values())
        if not kalem_listesi:
            raise HTTPException(400, "Birleştirilecek siparişlerde geçerli kalem bulunamadı")

        # Yeni birleşik sipariş oluştur
        yeni_id = str(uuid.uuid4())
        orijinal_idler_str = ", ".join(f"#{str(i)[:8]}" for i in idler)
        birlestir_notu = (body.not_aciklama or "").strip() or None
        sistem_notu = f"Birleştirildi: {len(idler)} sipariş ({orijinal_idler_str})"
        tam_not = f"{birlestir_notu} | {sistem_notu}" if birlestir_notu else sistem_notu

        cur.execute(
            """
            INSERT INTO siparis_talep
                (id, sube_id, tarih, durum, personel_id, personel_ad,
                 bildirim_saati, not_aciklama, kalemler)
            VALUES (%s, %s, CURRENT_DATE, 'bekliyor', %s, %s, %s, %s, %s::jsonb)
            """,
            (
                yeni_id,
                sube_id,
                "merkez",
                "Merkez — sipariş birleştirme",
                dt_now_tr().strftime("%H:%M:%S"),
                tam_not,
                json.dumps(kalem_listesi, ensure_ascii=False),
            ),
        )

        # Eski siparişleri iptal et
        iptal_notu = f"Birleştirildi → #{yeni_id[:8]}"
        cur.execute(
            f"""
            UPDATE siparis_talep
            SET durum = 'iptal',
                not_aciklama = CASE
                    WHEN not_aciklama IS NOT NULL AND TRIM(not_aciklama) != ''
                    THEN not_aciklama || ' | ' || %s
                    ELSE %s
                END
            WHERE id IN ({placeholders})
            """,
            (iptal_notu, iptal_notu) + tuple(idler),
        )

        conn.commit()
        log.info(
            "siparis_birlestir: sube=%s, yeni=%s, birlesik=%s, kalem=%d",
            sube_id, yeni_id, idler, len(kalem_listesi),
        )

    return {
        "yeni_talep_id": yeni_id,
        "sube_id": sube_id,
        "sube_adi": sube_adi,
        "kalem_sayisi": len(kalem_listesi),
        "birlesik_talep_sayisi": len(idler),
        "kalemler": kalem_listesi,
    }


# ─────────────────────────────────────────────────────────────
# ANALİTİK DASHBOARD  (motor_analitik_olay + siparis_talep)
# ─────────────────────────────────────────────────────────────

@router.get("/analitik-ozet")
def ops_analitik_ozet(gun: int = Query(default=30, ge=1, le=180)):
    """
    Sipariş başarı oranı, ortalama teslim süresi, tedarikçi güvenilirlik özeti.
    Kaynak: siparis_talep tablosu (motor_analitik_olay ileride zenginleştirilebilir).
    """
    with db() as (conn, cur):
        # 1. Sipariş başarı oranı (kabul_edildi / toplam tamamlanmış)
        cur.execute(
            """
            SELECT
                COUNT(*) FILTER (WHERE durum IN ('teslim_edildi','kabul_edildi','tamamlandi')) AS tamamlandi,
                COUNT(*) FILTER (WHERE durum = 'kabul_uyusmazlik') AS uyusmazlik,
                COUNT(*) FILTER (WHERE durum = 'iptal') AS iptal,
                COUNT(*) AS toplam,
                AVG(
                    EXTRACT(EPOCH FROM (guncelleme - olusturma)) / 3600.0
                ) FILTER (WHERE durum IN ('teslim_edildi','kabul_edildi','tamamlandi')) AS ort_sure_saat
            FROM siparis_talep
            WHERE olusturma >= NOW() - (%s * INTERVAL '1 day')
            """,
            (gun,),
        )
        ozet = dict(cur.fetchone() or {})

        # 2. Şube bazlı sipariş performansı (en çok sipariş veren 10 şube)
        cur.execute(
            """
            SELECT s.ad AS sube_adi, st.sube_id,
                   COUNT(*) AS toplam,
                   COUNT(*) FILTER (WHERE st.durum IN ('teslim_edildi','kabul_edildi','tamamlandi')) AS basarili,
                   COUNT(*) FILTER (WHERE st.durum = 'kabul_uyusmazlik') AS uyusmazlik
            FROM siparis_talep st
            LEFT JOIN subeler s ON s.id = st.sube_id
            WHERE st.olusturma >= NOW() - (%s * INTERVAL '1 day')
            GROUP BY st.sube_id, s.ad
            ORDER BY toplam DESC
            LIMIT 10
            """,
            (gun,),
        )
        sube_perf = [dict(r) for r in cur.fetchall()]

        # 3. Günlük sipariş trendi (son gun gün)
        cur.execute(
            """
            SELECT DATE(olusturma AT TIME ZONE 'Europe/Istanbul') AS gun,
                   COUNT(*) AS adet,
                   COUNT(*) FILTER (WHERE durum IN ('teslim_edildi','kabul_edildi','tamamlandi')) AS basarili
            FROM siparis_talep
            WHERE olusturma >= NOW() - (%s * INTERVAL '1 day')
            GROUP BY 1
            ORDER BY 1
            """,
            (gun,),
        )
        trend = [{"gun": str(r["gun"]), "adet": r["adet"], "basarili": r["basarili"]} for r in cur.fetchall()]

        # 4. Tedarikçi güvenilirlik (URUN_SEVK olaylarından)
        cur.execute(
            """
            SELECT
                aciklama,
                COUNT(*) AS teslimat_sayisi,
                tarih
            FROM operasyon_defter
            WHERE etiket = 'URUN_SEVK'
              AND aciklama LIKE 'URUN_SEVK_JSON:%%'
              AND tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
            ORDER BY tarih DESC
            LIMIT 200
            """,
            (gun,),
        )
        tedarikci_map: Dict[str, int] = {}
        for row in cur.fetchall():
            try:
                payload = json.loads(str(row["aciklama"]).removeprefix("URUN_SEVK_JSON:"))
                ad = str(payload.get("tedarikci") or payload.get("tedarikci_ad") or "Bilinmeyen").strip()
                tedarikci_map[ad] = tedarikci_map.get(ad, 0) + 1
            except Exception:
                pass
        tedarikciler = [{"tedarikci": k, "teslimat": v} for k, v in sorted(tedarikci_map.items(), key=lambda x: -x[1])]

        toplam = int(ozet.get("toplam") or 0)
        tamamlandi = int(ozet.get("tamamlandi") or 0)
        basari_oran = round(tamamlandi / toplam * 100, 1) if toplam else 0.0

        return {
            "gun": gun,
            "basari_orani": basari_oran,
            "toplam_siparis": toplam,
            "tamamlandi": tamamlandi,
            "uyusmazlik": int(ozet.get("uyusmazlik") or 0),
            "iptal": int(ozet.get("iptal") or 0),
            "ort_sure_saat": round(float(ozet.get("ort_sure_saat") or 0), 1),
            "sube_performans": sube_perf,
            "gunluk_trend": trend,
            "tedarikciler": tedarikciler,
        }


