# STOK TAHMİN MOTORU
# ─────────────────────────────────────────────────────────────

@router.get("/stok-tahmin")
def ops_stok_tahmin(sube_id: Optional[str] = None, gun: int = Query(default=14, ge=7, le=60)):
    """
    Stok tüketim trendi + 7 günlük tahmin.
    Kaynak: operasyon_defter URUN_AC olayları (fiili tüketim).
    """
    with db() as (conn, cur):
        filtre = "AND od.sube_id = %s" if sube_id else ""
        params_base: list = [gun]
        if sube_id:
            params_base.append(sube_id)

        cur.execute(
            f"""
            SELECT od.sube_id, s.ad AS sube_adi,
                   od.tarih,
                   od.aciklama
            FROM operasyon_defter od
            LEFT JOIN subeler s ON s.id = od.sube_id
            WHERE od.etiket = 'URUN_AC'
              AND od.tarih >= CURRENT_DATE - (%s * INTERVAL '1 day')
              {filtre}
            ORDER BY od.tarih
            """,
            params_base,
        )
        rows = cur.fetchall()

        # Parse aciklama for kalem/adet (format: "... kalemler=[{'urun_ad':X,'adet':N}] ...")
        from collections import defaultdict
        import re as _re
        gun_tuketim: Dict[str, Dict[str, float]] = defaultdict(lambda: defaultdict(float))
        for row in rows:
            acik = str(row["aciklama"] or "")
            tarih = str(row["tarih"] or "")
            # Try JSON payload first
            try:
                m = _re.search(r'\{.*\}', acik)
                if m:
                    payload = json.loads(m.group())
                    for k in payload.get("kalemler", []):
                        ad = str(k.get("urun_ad") or k.get("kalem_kodu") or "?").strip()
                        adet = float(k.get("adet") or 0)
                        gun_tuketim[ad][tarih] += adet
                    continue
            except Exception:
                pass
            # Fallback: parse "×N ürün" style
            for m in _re.finditer(r'([^\d,·]+)[\s×x](\d+)', acik):
                ad = m.group(1).strip().rstrip('·,- ')
                if len(ad) > 2:
                    gun_tuketim[ad][tarih] += float(m.group(2))

        tahminler = []
        import datetime as _dt
        bugun = _dt.date.today()
        for urun_ad, gun_map in list(gun_tuketim.items())[:30]:
            gunler = sorted(gun_map.keys())
            degerler = [gun_map[g] for g in gunler]
            ort_gunluk = sum(degerler) / max(len(gunler), 1)
            # Basit lineer trend
            n = len(degerler)
            if n >= 3:
                son3 = degerler[-3:]
                trend_delta = (son3[-1] - son3[0]) / 2
            else:
                trend_delta = 0.0
            tahmin_7gun = max(0.0, round((ort_gunluk + trend_delta * 0.5) * 7, 1))
            tahminler.append({
                "urun_ad": urun_ad,
                "ort_gunluk_tuketim": round(ort_gunluk, 2),
                "gozlem_gun": len(gunler),
                "tahmin_7gun": tahmin_7gun,
                "trend": "artiyor" if trend_delta > 0.1 else ("dusuyor" if trend_delta < -0.1 else "sabit"),
            })

        tahminler.sort(key=lambda x: -x["tahmin_7gun"])

        # Mevcut depo stoğu (karşılaştırma için)
        stok_map: Dict[str, float] = {}
        if sube_id:
            cur.execute(
                "SELECT kalem_adi, mevcut_adet FROM sube_depo_stok WHERE sube_id=%s",
                (sube_id,),
            )
            for r in cur.fetchall():
                stok_map[str(r["kalem_adi"] or "")] = float(r["mevcut_adet"] or 0)

        for t in tahminler:
            mevcut = stok_map.get(t["urun_ad"])
            if mevcut is not None:
                t["mevcut_stok"] = mevcut
                t["yeterlilik_gun"] = round(mevcut / max(t["ort_gunluk_tuketim"], 0.01), 1)
                t["uyari"] = t["yeterlilik_gun"] < 7

        return {
            "gun": gun,
            "sube_id": sube_id,
            "tahminler": tahminler,
            "guncelleme": str(bugun),
        }


